INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thelbane/Apple-II-Programs/new-content', 'new-content', 'thelbane', 'Apple-II-Programs', 'community', 'new-content thelbane Apple-II-Programs community The new-content skill helps developers create new program posts or blog posts for the Apple II Programs Jekyll site, showcasing Applesoft BASIC programs with source code, screenshots, and descriptions. 新内容技能指导您创建Apple II程序帖子和博客帖子，包括源代码、截图和描述 新規コンテンツスキルは、Apple IIプログラム投稿とブログ投稿の作成を支援します。ソースコード、スクリーンショット、説明書を含みます 새 콘텐츠 기능은 Apple II 프로그램 게시물 및 블로그 게시물의 생성을 지원합니다. 소스 코드, 스크린샷 및 설명을 포함합니다 Crea nuevo contenido para el sitio web de Apple II Programs Jekyll, incluyendo publicaciones de programas y artículos de blog Créez du nouveau contenu pour le site web Apple II Programs Jekyll, y compris des publications de programmes et des articles de blog Erstellen Sie neuen Inhalt für die Apple II Programs Jekyll-Website, einschließlich Programm- und Blogbeiträgen Este skill ajuda a criar novos posts de programas ou blogs para o site Apple II Programs Jekyll, incluindo tipos de conteúdo e configuração rápida Этот скилл помогает создать новые программные или блог-посты для сайта Apple II Programs Jekyll, включая типы контента и быструю настройку هذا المهارة يساعد على إنشاء منشورات جديدة لبرامج أو مدونات لموقع Apple II Programs Jekyll، بما في ذلك أنواع المحتوى والتنصيب السريع how to use new-content new-content setup guide Jekyll site content creation Applesoft BASIC program posts new-content alternative new-content vs Jekyll plugins what is new-content new-content install creating blog posts with new-content 新内容技能 Apple II 程序帖子 博客帖子创建 Jekyll站点 AI工具 程序帖子创建 源代码截图 快速开始创建新内容 Supports creation of program posts with Applesoft BASIC source code Allows for blog post creation with general updates and announcements Utilizes Jekyll site architecture for content management Enables users to add screenshots and descriptions to program posts Provides a quick start guide for users to get started with content creation Includes options for setting custom titles and dates for posts new-content is a skill that guides users through creating new content for the Apple II Programs Jekyll site, including program posts and blog posts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('colmarius/mobcrew/tmux', 'community', 'colmarius', 'mobcrew', 'colmarius/mobcrew', 'tmux', 0, 0, 39, '2026-03-08T01:57:15.415Z', '2026-03-08T02:08:23.642Z', '0e850390b584e5bacc81791d90cc132c0cc75a5b7b2f54c12651079591c88957', '{"id":"colmarius/mobcrew/tmux","name":"tmux","description":{"en":"tmux is a native macOS timer for pair and mob programming sessions, allowing developers to manage background processes using tmux windows. It benefits developers working in collaborative environments.","zh":"tmux 是一个用于管理背景进程的工具，允许您创建新窗口并运行命令","ja":"tmux はバックグラウンドプロセスを管理するためのツールで、新しいウィンドウを作成し、コマンドを実行することができます","ko":"tmux는 백그라운드 프로세스를 관리하는 도구로 새 창을 생성하고 명령을 실행할 수 있습니다","es":"tmux es una herramienta para gestionar procesos en segundo plano en sesiones de programación en pareja. Permite crear ventanas y ejecutar comandos en segundo plano.","fr":"tmux est un outil pour gérer les processus en arrière-plan lors des séances de programmation en binôme. Il permet de créer des fenêtres et d''exécuter des commandes en arrière-plan.","de":"tmux ist ein Tool zur Verwaltung von Hintergrundprozessen bei Pair-Programmierungssitzungen. Es ermöglicht die Erstellung von Fenstern und die Ausführung von Befehlen im Hintergrund.","pt":"O Tmux é uma ferramenta poderosa para gerenciar processos em segundo plano, ideal para programação em paralelo e mob programming.","ru":"Tmux - это мощный инструмент для управления фоновыми процессами, идеальный для моб программирования и параллельного программирования.","ar":"Tmux هو أداة قوية لإدارة العمليات في الخلفية، مثالية لبرمجة الجوال وبرمجة الموب"},"seo":{"title":{"en":"tmux: Background Process Management Setup Guide | AI Agen...","zh":"tmux Setup Guide: 背景进程管理","ja":"tmux ベストプラクティス: バックグラウンドプロセス管理","ko":"tmux 사용 가이드: 백그라운드 프로세스 관리","es":"Guía de configuración de tmux para programación en pareja","fr":"Guide de configuration de tmux pour la programmation en b...","de":"Einrichtungsleitfaden für tmux zur Pair-Programmierung","pt":"Guia de Configuração do Tmux para Programação em Paralelo","ru":"ИИ Агенты: Настройка Tmux для Моб Программирования","ar":"دليل إعداد Tmux لبرمجة الجوال"},"description":{"en":"Discover how to manage background processes with tmux. Learn to verify environment, spawn new windows, and run commands. Get started with tmux today!","zh":"了解如何使用 tmux 管理背景进程，包括验证环境、创建新窗口和运行命令","ja":"tmux を使用してバックグラウンドプロセスを管理する方法を学びます。環境の検証、ウィンドウの作成、コマンドの実行など","ko":"tmux를 사용하여 백그라운드 프로세스를 관리하는 방법을 알아보세요. 환경 확인, 새 창 생성, 명령 실행 등","es":"Aprende a utilizar tmux para gestionar procesos en segundo plano y mejorar tu productividad en sesiones de programación en pareja","fr":"Découvrez comment utiliser tmux pour gérer les processus en arrière-plan et améliorer votre productivité lors des séances de programmation en binôme","de":"Erfahren Sie, wie Sie tmux verwenden, um Hintergrundprozesse zu verwalten und Ihre Produktivität bei Pair-Programmierungssitzungen zu steigern","pt":"Aprenda a usar o Tmux para gerenciar processos em segundo plano e melhorar a produtividade na programação em paralelo","ru":"Узнайте, как использовать Tmux для управления фоновыми процессами и улучшения производительности при моб программировании","ar":"تعلم كيفية استخدام Tmux لإدارة العمليات في الخلفية وتحسين الإنتاجية في برمجة الجوال"},"definition":{"en":"tmux is a terminal multiplexer that enables managing multiple windows and sessions from a single interface, ideal for pair and mob programming.","zh":"tmux 是一个终端复用器，允许您管理多个窗口和会话","ja":"tmux はターミナルマルチプレクサで、複数のウィンドウとセッションを管理できます","ko":"tmux는 터미널 멀티플렉서로 여러 창과 세션을 관리할 수 있습니다","es":"tmux es una herramienta de línea de comandos para gestionar procesos en segundo plano","fr":"tmux est un outil de ligne de commande pour gérer les processus en arrière-plan","de":"tmux ist ein Befehlszeilentool zur Verwaltung von Hintergrundprozessen","pt":"Tmux é um multiplexador de terminal que permite gerenciar várias sessões de terminal em uma única janela","ru":"Tmux - это многоплексор терминала, который позволяет управлять несколькими сессиями терминала в одном окне","ar":"Tmux هو متعدد المضيفين للترميز الذي يسمح بإدارة عدة جلسات الترميز في نافذة واحدة"},"features":{"en":["Manages background processes using tmux windows without blocking the terminal","Verifies environment and checks status with `tmux list-windows` command","Spawns new background processes with `tmux new-window` and `tmux send-keys` commands","Supports detached mode with `-d` option for running processes in the background","Allows naming windows for easy reference with `-n` option"],"zh":["管理背景进程","创建新窗口","运行命令","验证环境","使用 CLI 进行操作","支持多窗口管理"],"ja":["バックグラウンドプロセスを管理","新しいウィンドウを作成","コマンドを実行","環境を検証","CLI を使用して操作","複数ウィンドウを管理"],"ko":["백그라운드 프로세스 관리","새 창 생성","명령 실행","환경 확인","CLI 사용","다중 창 관리"],"es":["Creación de ventanas para procesos en segundo plano","Ejecución de comandos en segundo plano con tmux send-keys","Gestión de procesos en segundo plano con tmux list-windows","Compatibilidad con comandos como npm run dev","Posibilidad de nombrar ventanas para fácil referencia","Capacidad para mantener ventanas desacopladas con la opción -d"],"fr":["Création de fenêtres pour les processus en arrière-plan","Exécution de commandes en arrière-plan avec tmux send-keys","Gestion des processus en arrière-plan avec tmux list-windows","Compatibilité avec des commandes comme npm run dev","Possibilité de nommer des fenêtres pour une référence facile","Capacité à maintenir des fenêtres détachées avec l''option -d"],"de":["Erstellung von Fenstern für Hintergrundprozesse","Ausführung von Befehlen im Hintergrund mit tmux send-keys","Verwaltung von Hintergrundprozessen mit tmux list-windows","Kompatibilität mit Befehlen wie npm run dev","Möglichkeit, Fenster für eine einfache Referenz zu benennen","Fähigkeit, Fenster mit der Option -d zu entkoppeln"],"pt":["Crie janelas de fundo para executar comandos sem bloquear o terminal","Use o comando ''tmux list-windows'' para verificar o status das janelas","Execute comandos em segundo plano com ''tmux new-window'' e ''tmux send-keys''","Nomeie as janelas para fácil referência com ''-n''","Mantenha as janelas desanexadas com ''-d''"],"ru":["Создайте фоновые окна для выполнения команд без блокировки терминала","Используйте команду ''tmux list-windows'' для проверки статуса окон","Выполняйте команды в фоновом режиме с ''tmux new-window'' и ''tmux send-keys''","Назовите окна для легкого обращения с ''-n''","Держите окна отсоединенными с ''-d''"],"ar":["أنشئ نوافذ خلفية لتشغيل الأوامر دون حجب الطرفية","استخدم الأمر ''tmux list-windows'' للتحقق من حالة النوافذ","تشغيل الأوامر في الخلفية مع ''tmux new-window'' و ''tmux send-keys''","اسم النوافذ لسهولة الإشارة إليها مع ''-n''","احتفظ النوافذ غير متصلة مع ''-d''"]},"keywords":{"en":["how to use tmux","tmux alternative","tmux vs screen","tmux install","tmux setup guide","what is tmux","tmux background process management","tmux for pair programming","tmux for mob programming"],"zh":["tmux","背景进程管理","终端复用器","CLI","多窗口管理","环境验证","命令执行","AIエージェント","开发工具"],"ja":["tmux","バックグラウンドプロセス管理","ターミナルマルチプレクサ","CLI","複数ウィンドウ管理","環境検証","コマンド実行","AIエージェント","開発ツール"],"ko":["tmux","백그라운드 프로세스 관리","터미널 멀티플렉서","CLI","다중 창 관리","환경 확인","명령 실행","인공지능 에이전트","개발 도구"],"es":["tmux para programación en pareja","herramientas de línea de comandos para programación","gestión de procesos en segundo plano","tmux send-keys","tmux list-windows","npm run dev","programación en pareja con tmux","mejora de la productividad con tmux"],"fr":["tmux pour la programmation en binôme","outils de ligne de commande pour la programmation","gestion des processus en arrière-plan","tmux send-keys","tmux list-windows","npm run dev","programmation en binôme avec tmux","amélioration de la productivité avec tmux"],"de":["tmux für Pair-Programmierung","Befehlszeilentools für die Programmierung","Verwaltung von Hintergrundprozessen","tmux send-keys","tmux list-windows","npm run dev","Pair-Programmierung mit tmux","Steigerung der Produktivität mit tmux"],"pt":["tmux","programação em paralelo","mob programming","gerenciamento de processos","terminal","comandos em segundo plano","desenvolvimento de software"],"ru":["tmux","моб программирование","параллельное программирование","управление процессами","терминал","команды в фоновом режиме","разработка программного обеспечения","ИИ Агенты"],"ar":["tmux","برمجة الجوال","برمجة الموب","إدارة العمليات","الطرفية","أوامر في الخلفية","تطوير البرمجيات","وكلاء الذكاء الاصطناعي"]}},"owner":"colmarius","repo":"mobcrew","repoPath":"colmarius/mobcrew","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.415Z","topics":[],"category":"community","skillMd":{"name":"tmux","description":"Instructions for using tmux to spawn multiple processes, inspect them, and capture their output. Use when running servers, long-running tasks, or background processes.","bodyPreview":"# tmux\n\nManage background processes using tmux windows without blocking the terminal.\n\n## 1. Verify Environment & Check Status\n\nConfirm tmux is running and list existing windows:\n\n```bash\ntmux list-windows\n```\n\n## 2. Spawn a Background Process\n\nCreate a new tmux window and run a command:\n\n```bash\ntmux new-window -n \"my-server\" -d\ntmux send-keys -t \"my-server\" \"npm run dev\" C-m\n```\n\n- `-n \"my-server\"` names the window for easy reference\n- `-d` keeps it detached (runs in background)\n- `C-m` sends","body":"# tmux\n\nManage background processes using tmux windows without blocking the terminal.\n\n## 1. Verify Environment & Check Status\n\nConfirm tmux is running and list existing windows:\n\n```bash\ntmux list-windows\n```\n\n## 2. Spawn a Background Process\n\nCreate a new tmux window and run a command:\n\n```bash\ntmux new-window -n \"my-server\" -d\ntmux send-keys -t \"my-server\" \"npm run dev\" C-m\n```\n\n- `-n \"my-server\"` names the window for easy reference\n- `-d` keeps it detached (runs in background)\n- `C-m` sends Enter to execute the command\n\n## 3. Inspect Output (Read Logs)\n\n### Visible screen only\n\n```bash\ntmux capture-pane -p -t \"my-server\"\n```\n\n### Full scrollback history\n\n```bash\ntmux capture-pane -p -t \"my-server\" -S -1000\n```\n\n- `-S -1000` captures the last 1000 lines of scrollback\n\n## 4. Interact with the Process\n\n### Send Ctrl+C (interrupt)\n\n```bash\ntmux send-keys -t \"my-server\" C-c\n```\n\n### Kill the window\n\n```bash\ntmux kill-window -t \"my-server\"\n```\n\n## 5. Advanced: Chaining Commands\n\nRun multiple commands in sequence:\n\n```bash\ntmux new-window -n \"build\" -d && \\\ntmux send-keys -t \"build\" \"npm run build && npm run test\" C-m\n```\n\n## Quick Reference\n\n| Action | Command |\n| ------ | ------- |\n| Create window | `tmux new-window -n \"ID\" -d` |\n| Run command | `tmux send-keys -t \"ID\" \"CMD\" C-m` |\n| Read output | `tmux capture-pane -p -t \"ID\"` |\n| Send interrupt | `tmux send-keys -t \"ID\" C-c` |\n| Kill window | `tmux kill-window -t \"ID\"` |\n"},"lastSynced":"2026-03-08T02:08:23.642Z","agentAnalysis":{"suitability":{"en":"Perfect for Terminal-Based Agents needing efficient background process management.","zh":"适合需要高效后台进程管理的基于终端的代理。","ja":"バックグラウンド プロセス管理が効率的なターミナル ベースのエージェントに最適です。","ko":"효율적인 백그라운드 프로세스 관리가 필요한 터미널 기반 에이전트에 적합합니다.","es":"Perfecto para agentes basados en terminal que necesitan una gestión eficiente de procesos en segundo plano.","fr":"Parfait pour les agents basés sur le terminal nécessitant une gestion efficace des processus en arrière-plan.","de":"Perfekt für terminalbasierte Agenten, die eine effiziente Verwaltung von Hintergrundprozessen benötigen.","pt":"Perfeito para Agentes Baseados em Terminal que precisam de gerenciamento eficiente de processos em segundo plano.","ru":"Идеально подходит для Терминальных Агентов, которым требуется эффективное управление фоновыми процессами.","ar":"مثالي لعميل وسيط المترجم الذي يحتاج إلى إدارة الخلفية الفعالة"},"recommendation":{"en":"Empowers agents to manage background processes using tmux windows, enabling seamless execution of commands like ''npm run dev'' without blocking the terminal, utilizing protocols like send-keys and detachment flags like ''-d''.","zh":"赋予代理使用 tmux 窗口管理后台进程的能力，实现命令如 ''npm run dev'' 的无阻塞执行，利用 send-keys 协议和分离标志如 ''-d''。","ja":"tmux ウィンドウを使用してバックグラウンド プロセスを管理するエージェントを強化します。''npm run dev'' のようなコマンドをブロックせずに実行できるようにし、send-keys プロトコルや ''-d'' のようなデタッチ フラグを利用します。","ko":"에이전트가 tmux 창을 사용하여 백그라운드 프로세스를 관리할 수 있도록 해주며, ''npm run dev''와 같은 명령을 터미널을 차단하지 않고 실행할 수 있게 하며, send-keys 프로토콜 및 ''-d''와 같은 분리 플래그를 사용합니다.","es":"Habilita a los agentes a gestionar procesos en segundo plano utilizando ventanas tmux, permitiendo la ejecución sin problemas de comandos como ''npm run dev'' sin bloquear la terminal, utilizando protocolos como send-keys y banderas de desacoplamiento como ''-d''.","fr":"Permet aux agents de gérer les processus en arrière-plan en utilisant des fenêtres tmux, permettant une exécution sans heurts de commandes comme ''npm run dev'' sans bloquer le terminal, en utilisant des protocoles comme send-keys et des drapeaux de détachement comme ''-d''.","de":"Ermöglicht es Agenten, Hintergrundprozesse mithilfe von tmux-Fenstern zu verwalten, wodurch Befehle wie ''npm run dev'' ohne Blockieren des Terminals ausgeführt werden können, unter Verwendung von Protokollen wie send-keys und Trennflags wie ''-d''.","pt":"Habilita os agentes a gerenciar processos em segundo plano usando janelas tmux, permitindo a execução sem interrupção de comandos como ''npm run dev'' sem bloquear o terminal, utilizando protocolos como send-keys e flags de desanexação como ''-d''.","ru":"Наделяет агентов возможностью управлять фоновыми процессами с помощью окон tmux, что позволяет выполнять команды типа ''npm run dev'' без блокировки терминала, используя протоколы типа send-keys и флаги отсоединения типа ''-d''.","ar":"يمكن للوكلاء إدارة العمليات الخلفية باستخدام نوافذ tmux، مما يتيح تنفيذ أوامر مثل ''npm run dev'' بدون حجب Terminal، باستخدام بروتوكولات مثل send-keys وflags مثل ''-d''"},"useCases":{"en":["Automating server startup with detached tmux windows","Managing multiple background processes using named tmux windows","Debugging long-running commands in isolated tmux sessions"],"zh":["使用分离的 tmux 窗口自动启动服务器","使用命名的 tmux 窗口管理多个后台进程","在隔离的 tmux 会话中调试长时间运行的命令"],"ja":["デタッチされた tmux ウィンドウを使用してサーバーを自動起動する","名前付きの tmux ウィンドウを使用して複数のバックグラウンド プロセスを管理する","隔離された tmux セッションで長時間実行されるコマンドをデバッグする"],"ko":["분리된 tmux 창을 사용하여 서버 자동 시작","이름이 지정된 tmux 창을 사용하여 여러 백그라운드 프로세스 관리","분리된 tmux 세션에서 긴 시간 실행되는 명령어 디버깅"],"es":["Automatización del arranque del servidor con ventanas tmux desacopladas","Gestión de varios procesos en segundo plano utilizando ventanas tmux con nombre","Depuración de comandos de larga ejecución en sesiones tmux aisladas"],"fr":["Automatisation du démarrage du serveur avec des fenêtres tmux détachées","Gestion de plusieurs processus en arrière-plan en utilisant des fenêtres tmux nommées","Débogage de commandes à exécution longue dans des sessions tmux isolées"],"de":["Automatisierung des Server-Starts mit abgetrennten tmux-Fenstern","Verwaltung mehrerer Hintergrundprozesse unter Verwendung von benannten tmux-Fenstern","Fehlersuche bei lang laufenden Befehlen in isolierten tmux-Sitzungen"],"pt":["Automatizar a inicialização do servidor com janelas tmux desanexadas","Gerenciar vários processos em segundo plano usando janelas tmux nomeadas","Depurar comandos de longa execução em sessões tmux isoladas"],"ru":["Автоматизировать запуск сервера с отсоединенными окнами tmux","Управлять несколькими фоновыми процессами с помощью именованных окон tmux","Отлаживать долгие команды в изолированных сессиях tmux"],"ar":["توفير تشغيل الخادم التلقائي مع نوافذ tmux منفصلة","إدارة العمليات الخلفية المتعددة باستخدام نوافذ tmux المسمى","تصحيح الأوامر التي تتم تشغيلها لمدة طويلة في جلسات tmux معزولة"]},"limitations":{"en":["Requires tmux installation and configuration","Limited to terminal-based environments","Dependent on command-line interface for send-keys and window management"],"zh":["需要 tmux 安装和配置","仅限于基于终端的环境","依赖于命令行接口用于 send-keys 和窗口管理"],"ja":["tmux のインストールと設定が必要","ターミナル ベースの環境のみ","send-keys とウィンドウ管理のためのコマンドライン インターフェイスに依存"],"ko":["tmux 설치 및 구성 필요","터미널 기반 환경만 해당","send-keys 및 창 관리를 위한 명령줄 인터페이스 의존"],"es":["Requiere instalación y configuración de tmux","Limitado a entornos basados en terminal","Dependiente de la interfaz de línea de comandos para send-keys y gestión de ventanas"],"fr":["Nécessite l''installation et la configuration de tmux","Limité aux environnements basés sur le terminal","Dépendant de l''interface de ligne de commande pour send-keys et la gestion de fenêtres"],"de":["Benötigt tmux-Installation und -Konfiguration","Begrenzt auf terminalbasierte Umgebungen","Abhängig von der Kommandozeilenoberfläche für send-keys und Fensterverwaltung"],"pt":["Requer instalação e configuração do tmux","Limitado a ambientes baseados em terminal","Dependente da interface de linha de comando para send-keys e gerenciamento de janelas"],"ru":["Требует установки и конфигурации tmux","Ограничен терминальными средами","Зависит от командной строки для send-keys и управления окнами"],"ar":["يتطلب تثبيت وتهيئة tmux","محدود بيئات وسيطة المترجم","يعتمد على واجهة سطر الأوامر ل send-keys وإدارة النوافذ"]},"version":4},"contentHash":"0e850390b584e5bacc81791d90cc132c0cc75a5b7b2f54c12651079591c88957","qualityScore":39}');
