INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('moonbitlang/moon/snapbox-testing', 'snapbox-testing', 'moonbitlang', 'moon', 'community', 'snapbox-testing moonbitlang moon community snapbox-testing is a build system and package manager for MoonBit that simplifies Rust command-output tests. It benefits developers by making tests more stable and easier to review. Snapbox Testing 是 MoonBit 的构建系统和包管理工具，用于简化 Rust 命令输出测试 Snapbox Testing は MoonBit のビルドシステムとパッケージ管理を簡素化する AI エージェントです Snapbox Testing은 MoonBit의 빌드 시스템과 패키지 관리를 간소화하는 도구입니다 Snapbox-testing es una herramienta para simplificar pruebas de salida de comandos en Rust, proporcionando una forma más estable y fácil de revisar Snapbox-testing est un outil pour simplifier les tests de sortie de commandes en Rust, offrant une manière plus stable et plus facile à revoir Snapbox-testing ist ein Tool, um Befehlsausgabetests in Rust zu vereinfachen, indem es eine stabilere und leichter überprüfbare Methode bietet O Snapbox Testing é uma ferramenta para simplificar testes de saída de comando em Rust, tornando-os mais estáveis e fáceis de revisar Snapbox Testing - это инструмент для упрощения тестирования вывода команд в Rust, что делает их более стабильными и легкими для проверки Snapbox Testing هو أداة لتبسيط اختبار الإخراج الشبكي في Rust، مما يجعله أكثر استقرارًا وسهولة في المراجعة how to use snapbox-testing snapbox-testing alternative snapbox-testing setup guide what is snapbox-testing snapbox-testing vs rust testing snapbox-testing install rust command-output testing moonbit build system snapbox assertions Snapbox Testing MoonBit 构建系统 Rust 命令输出测试 AI 构建工具 包管理 构建系统 Rust 测试 Replaces manual output plumbing with direct snapbox assertions Supports snapshot overwriting with SNAPSHOTS=overwrite command Allows tightening snapshots by keeping stable text exact and wildcarding volatile parts Enables re-running tests with clippy for optimal results Utilizes inline snapshots with snapbox::str![""] for unstable or unknown output snapbox-testing is a skill that enables simpler, more stable, and easier-to-review Rust command-output tests using direct snapbox assertions and snapshot overwriting.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('f/prompts.chat/book-translation', 'community', 'f', 'prompts.chat', 'f/prompts.chat', 'book-translation', 0, 0, 39, '2026-03-08T01:57:15.465Z', '2026-03-08T02:09:22.479Z', '8e0dfd7db942c3f72153c2a59cf6a5161ba99753bacb13b932c3dcb53ace2bc1', '{"id":"f/prompts.chat/book-translation","name":"book-translation","description":{"en":"The book-translation skill enables the translation of book content for The Interactive Book of Prompting, supporting 25 chapters across 7 parts. It benefits developers and translators working with MDX content files and JSON translation keys.","zh":"Book Translation Skill支持多语言书籍翻译，包括MDX内容文件和JSON翻译密钥","ja":"Book Translation Skillは多言語の書籍翻訳をサポートし、MDXコンテンツファイルとJSON翻訳キーを含みます","ko":"Book Translation Skill은 다국어 도서 번역을 지원하며 MDX 콘텐츠 파일 및 JSON 번역 키를 포함합니다","es":"La traducción de libros es un proceso que requiere MDX y JSON. Nuestra guía te ayudará a configurar la traducción de libros con AI Herramientas.","fr":"La traduction de livres est un processus qui nécessite MDX et JSON. Notre guide vous aidera à configurer la traduction de livres avec des outils d''intelligence artificielle","de":"Die Buchübersetzung ist ein Prozess, der MDX- und JSON-Dateien erfordert. Unser Leitfaden hilft Ihnen bei der Einrichtung der Buchübersetzung mit KI-Tools","pt":"O skill de tradução de livros permite a tradução de conteúdo de livros para The Interactive Book of Prompting usando arquivos MDX e JSON.","ru":"Навык перевода книг позволяет переводить контент книг для The Interactive Book of Prompting с использованием файлов MDX и JSON.","ar":"مهارة ترجمة الكتب تمكن من ترجمة محتوى الكتب إلى The Interactive Book of Prompting باستخدام ملفات MDX و JSON."},"seo":{"title":{"en":"book-translation: MDX Content Translation Setup Guide | A...","zh":"书籍翻译设置指南 - AI工具","ja":"書籍翻訳セットアップガイド - AIエージェント","ko":"도서 번역 설정 가이드 - AI 에이전트","es":"Guía de Configuración de Traducción de Libros con AI Herr...","fr":"Guide de Configuration de Traduction de Livres avec Outil...","de":"Einrichtungsleitfaden für Buchübersetzung mit KI-Tools","pt":"Guia de Configuração de Tradução de Livros para Ferrament...","ru":"Настройка перевода книг для ИИ Агентов","ar":"دليل إعداد ترجمة الكتب للأدوات الذكية"},"description":{"en":"Discover how to translate book content with ease using the book-translation skill. Get started with our setup guide and learn how to leverage MDX and JSON fi...","zh":"学习如何使用Book Translation Skill进行多语言书籍翻译，支持MDX内容文件和JSON翻译密钥","ja":"Book Translation Skillを使用して多言語の書籍翻訳を行う方法を学びます。MDXコンテンツファイルとJSON翻訳キーをサポート","ko":"Book Translation Skill을 사용하여 다국어 도서 번역을 수행하는 방법을 알아보세요. MDX 콘텐츠 파일 및 JSON 번역 키 지원","es":"Aprende a traducir contenido de libros con nuestra guía de configuración de traducción de libros con AI Herramientas","fr":"Découvrez comment traduire du contenu de livres avec notre guide de configuration de traduction de livres avec des outils d''intelligence artificielle","de":"Erfahren Sie, wie Sie Buchinhalte mit unserem Einrichtungsleitfaden für Buchübersetzung mit KI-Tools übersetzen können","pt":"Aprenda a traduzir conteúdo de livros para The Interactive Book of Prompting com MDX e JSON","ru":"Откройте для себя, как переводить контент книг для The Interactive Book of Prompting с использованием MDX и JSON","ar":"اكتشف كيفية ترجمة محتوى الكتب إلى The Interactive Book of Prompting باستخدام MDX و JSON"},"definition":{"en":"book-translation is a skill that guides the translation of book content using MDX content files and JSON translation keys, supporting multiple locales and chapters.","zh":"Book Translation Skill是一种AI工具，用于翻译书籍内容，支持多语言和格式","ja":"Book Translation Skillは書籍コンテンツを翻訳するためのAIエージェントであり、多言語とフォーマットをサポートします","ko":"Book Translation Skill은 도서 콘텐츠를 번역하는 AI 에이전트로서 다국어와 형식을 지원합니다","es":"La traducción de libros es una habilidad que permite traducir contenido de libros a diferentes idiomas con AI Herramientas","fr":"La traduction de livres est une compétence qui permet de traduire du contenu de livres dans différentes langues avec des outils d''intelligence artificielle","de":"Die Buchübersetzung ist eine Fähigkeit, die die Übersetzung von Buchinhalten in verschiedene Sprachen mit KI-Tools ermöglicht","pt":"O que é tradução de livros? É um skill de tradução de conteúdo de livros para The Interactive Book of Prompting.","ru":"Что такое перевод книг? Это навык перевода контента книг для The Interactive Book of Prompting.","ar":"ما هي ترجمة الكتب؟ إنها مهارة لترجمة محتوى الكتب إلى The Interactive Book of Prompting."},"features":{"en":["Supports MDX content files for full chapter content translation","Utilizes JSON translation keys for UI strings, chapter titles, and descriptions","Compatible with multiple locale codes, such as de, fr, es, ja, and more","Enables self-hosting for organizations with complete privacy","Provides a community-driven platform for sharing and discovering prompts"],"zh":["支持MDX内容文件","支持JSON翻译密钥","多语言书籍翻译","自定义locale代码","支持25章和7部分的书籍结构"],"ja":["MDXコンテンツファイルをサポート","JSON翻訳キーをサポート","多言語の書籍翻訳","カスタムロケールコード","25章と7部分の書籍構造をサポート"],"ko":["MDX 콘텐츠 파일 지원","JSON 번역 키 지원","다국어 도서 번역","사용자 정의 로케일 코드","25장과 7부분의 도서 구조 지원"],"es":["Compatibilidad con archivos MDX","Soporte para claves de traducción JSON","Configuración de traducción para 25 capítulos","Compatibilidad con varios idiomas","Uso de AI Herramientas para la traducción","Integración con la comunidad de prompts.chat"],"fr":["Compatibilité avec les fichiers MDX","Prise en charge des clés de traduction JSON","Configuration de la traduction pour 25 chapitres","Compatibilité avec plusieurs langues","Utilisation d''outils d''intelligence artificielle pour la traduction","Intégration avec la communauté de prompts.chat"],"de":["Unterstützung für MDX-Dateien","Unterstützung für JSON-Übersetzungskeys","Konfiguration der Übersetzung für 25 Kapitel","Unterstützung für mehrere Sprachen","Verwendung von KI-Tools für die Übersetzung","Integration mit der Community von prompts.chat"],"pt":["Arquivos MDX para conteúdo de capítulos","Chaves de tradução JSON para strings de UI","Suporte a múltiplos idiomas","Integração com The Interactive Book of Prompting","Tradução de títulos e descrições de capítulos","Uso de locale codes para identificar idiomas"],"ru":["Файлы MDX для контента глав","Ключи перевода JSON для строк интерфейса","Поддержка нескольких языков","Интеграция с The Interactive Book of Prompting","Перевод названий и описаний глав","Использование кодов локали для идентификации языков"],"ar":["ملفات MDX لمحتوى الفصول","مفاتيح الترجمة JSON للřetجات واجهة المستخدم","دعم اللغات المتعددة","التكامل مع The Interactive Book of Prompting","ترجمة عناوين ووصف الفصول","استخدام رموز الموقع للتعرف على اللغات"]},"keywords":{"en":["how to use book-translation","book-translation setup guide","MDX content translation","JSON translation keys","book-translation alternative","book-translation vs translation software","book-translation install","book-translation for developers","book-translation for translators","book-translation locale support"],"zh":["书籍翻译","AI工具","MDX内容文件","JSON翻译密钥","多语言支持","locale代码","书籍结构","翻译设置"],"ja":["書籍翻訳","AIエージェント","MDXコンテンツファイル","JSON翻訳キー","多言語サポート","ロケールコード","書籍構造","翻訳設定"],"ko":["도서 번역","AI 에이전트","MDX 콘텐츠 파일","JSON 번역 키","다국어 지원","로케일 코드","도서 구조","번역 설정"],"es":["traducción de libros","AI herramientas","MDX","JSON","traducción de contenido","configuración de traducción","idiomas","prompts.chat","inteligencia artificial","desarrollo de software"],"fr":["traduction de livres","outils d''intelligence artificielle","MDX","JSON","traduction de contenu","configuration de traduction","langues","prompts.chat","intelligence artificielle","développement de logiciels"],"de":["Buchübersetzung","KI-Tools","MDX","JSON","Inhaltsübersetzung","Übersetzungskonfiguration","Sprachen","prompts.chat","künstliche Intelligenz","Softwareentwicklung"],"pt":["tradução de livros","The Interactive Book of Prompting","MDX","JSON","ferramentas de IA","tradução de conteúdo","locale codes","suporte a múltiplos idiomas"],"ru":["перевод книг","The Interactive Book of Prompting","MDX","JSON","ИИ Агенты","перевод контента","коды локали","поддержка нескольких языков"],"ar":["ترجمة الكتب","The Interactive Book of Prompting","MDX","JSON","الأدوات الذكية","ترجمة المحتوى","رموز الموقع","دعم اللغات المتعددة"]}},"owner":"f","repo":"prompts.chat","repoPath":"f/prompts.chat","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.465Z","topics":[],"category":"community","skillMd":{"name":"book-translation","description":"Translate The Interactive Book of Prompting chapters and UI strings to a new language","bodyPreview":"# Book Translation Skill\n\nThis skill guides translation of book content for **The Interactive Book of Prompting** at prompts.chat.\n\n## Overview\n\nThe book has **25 chapters** across 7 parts. Translation requires:\n1. **MDX content files** - Full chapter content in `src/content/book/{locale}/`\n2. **JSON translation keys** - UI strings, chapter titles, and descriptions in `messages/{locale}.json`\n\n## Prerequisites\n\nBefore starting, identify:\n- **Target locale code** (e.g., `de`, `fr`, `es`, `ja`, `k","body":"# Book Translation Skill\n\nThis skill guides translation of book content for **The Interactive Book of Prompting** at prompts.chat.\n\n## Overview\n\nThe book has **25 chapters** across 7 parts. Translation requires:\n1. **MDX content files** - Full chapter content in `src/content/book/{locale}/`\n2. **JSON translation keys** - UI strings, chapter titles, and descriptions in `messages/{locale}.json`\n\n## Prerequisites\n\nBefore starting, identify:\n- **Target locale code** (e.g., `de`, `fr`, `es`, `ja`, `ko`, `zh`)\n- Check if locale exists in `messages/` directory\n- Check if `src/content/book/{locale}/` folder exists\n\n## Step 1: Copy Turkish Folder as Base\n\nThe Turkish (`tr`) translation is complete and well-tested. **Copy it as your starting point** instead of translating from English:\n\n```bash\nmkdir -p src/content/book/{locale}\ncp -r src/content/book/*.mdx src/content/book/{locale}/\ncp src/components/book/elements/locales/en.ts src/components/book/elements/locales/{locale}.ts\n```\n\n**⚠️ IMPORTANT: After copying, you MUST register the new locale in `src/components/book/elements/locales/index.ts`:**\n1. Add import: `import {locale} from \"./{locale}\";`\n2. Add to `locales` object: `{locale},`\n3. Add to named exports: `export { en, tr, az, {locale} };`\n\nThis is faster because:\n- Turkish and many languages share similar sentence structures\n- All JSX/React components are already preserved correctly\n- File structure is already set up\n- You only need to translate the prose, not recreate the structure\n\n## Step 2: Translate MDX Content Files\n\nEdit each copied file in `src/content/book/{locale}/` to translate from Turkish to your target language.\n\nProcess files one by one:\n\n### Chapter List (in order)\n\n| Slug | English Title |\n|------|---------------|\n| `00a-preface` | Preface |\n| `00b-history` | History |\n| `00c-introduction` | Introduction |\n| `01-understanding-ai-models` | Understanding AI Models |\n| `02-anatomy-of-effective-prompt` | Anatomy of an Effective Prompt |\n| `03-core-prompting-principles` | Core Prompting Principles |\n| `04-role-based-prompting` | Role-Based Prompting |\n| `05-structured-output` | Structured Output |\n| `06-chain-of-thought` | Chain of Thought |\n| `07-few-shot-learning` | Few-Shot Learning |\n| `08-iterative-refinement` | Iterative Refinement |\n| `09-json-yaml-prompting` | JSON & YAML Prompting |\n| `10-system-prompts-personas` | System Prompts & Personas |\n| `11-prompt-chaining` | Prompt Chaining |\n| `12-handling-edge-cases` | Handling Edge Cases |\n| `13-multimodal-prompting` | Multimodal Prompting |\n| `14-context-engineering` | Context Engineering |\n| `15-common-pitfalls` | Common Pitfalls |\n| `16-ethics-responsible-use` | Ethics & Responsible Use |\n| `17-prompt-optimization` | Prompt Optimization |\n| `18-writing-content` | Writing & Content |\n| `19-programming-development` | Programming & Development |\n| `20-education-learning` | Education & Learning |\n| `21-business-productivity` | Business & Productivity |\n| `22-creative-arts` | Creative Arts |\n| `23-research-analysis` | Research & Analysis |\n| `24-future-of-prompting` | The Future of Prompting |\n| `25-agents-and-skills` | Agents & Skills |\n\n### MDX Translation Guidelines\n\n1. **Preserve all JSX/React components** - Keep `<div>`, `<img>`, `className`, etc. unchanged\n2. **Preserve code blocks** - Code examples should remain in English (variable names, keywords)\n3. **Translate prose content** - Headings, paragraphs, lists\n4. **Keep Markdown syntax** - `##`, `**bold**`, `*italic*`, `[links](url)`\n5. **Preserve component imports** - Any `import` statements at the top\n\n## Step 3: Translate JSON Keys\n\nIn `messages/{locale}.json`, translate the `\"book\"` section. Key areas:\n\n### Book Metadata\n```json\n\"book\": {\n  \"title\": \"The Interactive Book of Prompting\",\n  \"subtitle\": \"An Interactive Guide to Crafting Clear and Effective Prompts\",\n  \"metaTitle\": \"...\",\n  \"metaDescription\": \"...\",\n  ...\n}\n```\n\n### Chapter Titles (`book.chapters`)\n```json\n\"chapters\": {\n  \"00a-preface\": \"Preface\",\n  \"00b-history\": \"History\",\n  \"00c-introduction\": \"Introduction\",\n  ...\n}\n```\n\n### Chapter Descriptions (`book.chapterDescriptions`)\n```json\n\"chapterDescriptions\": {\n  \"00a-preface\": \"A personal note from the author\",\n  \"00b-history\": \"The story of Awesome ChatGPT Prompts\",\n  ...\n}\n```\n\n### Part Names (`book.parts`)\n```json\n\"parts\": {\n  \"introduction\": \"Introduction\",\n  \"foundations\": \"Foundations\",\n  \"techniques\": \"Techniques\",\n  \"advanced\": \"Advanced Strategies\",\n  \"bestPractices\": \"Best Practices\",\n  \"useCases\": \"Use Cases\",\n  \"conclusion\": \"Conclusion\"\n}\n```\n\n### Interactive Demo Examples (`book.interactive.demoExamples`)\nLocalize example text for demos (tokenizer samples, temperature examples, etc.):\n```json\n\"demoExamples\": {\n  \"tokenPrediction\": {\n    \"tokens\": [\"The\", \" capital\", \" of\", \" France\", \" is\", \" Paris\", \".\"],\n    \"fullText\": \"The capital of France is Paris.\"\n  },\n  \"temperature\": {\n    \"prompt\": \"What is the capital of France?\",\n    ...\n  }\n}\n```\n\n### Book Elements Locales (REQUIRED)\n\n**⚠️ DO NOT SKIP THIS STEP** - The interactive demos will not work in the new language without this.\n\nTranslate the locale data file at `src/components/book/elements/locales/{locale}.ts`:\n- Temperature examples, token predictions, embedding words\n- Capabilities list, sample conversations, strategies\n- Tokenizer samples, builder fields, chain types\n- Frameworks (CRISPE, BREAK, RTF), exercises\n- Image/video prompt options, validation demos\n\n**Then register it in `src/components/book/elements/locales/index.ts`:**\n```typescript\nimport {locale} from \"./{locale}\";\n\nconst locales: Record<string, LocaleData> = {\n  en,\n  tr,\n  az,\n  {locale},  // Add your new locale here\n};\n\nexport { en, tr, az, {locale} };  // Add to exports\n```\n\n### UI Strings (`book.interactive.*`, `book.chapter.*`, `book.search.*`)\nTranslate all interactive component labels and navigation strings.\n\n## Step 4: Verify Translation\n\n1. Run the check script:\n   ```bash\n   node scripts/check-translations.js\n   ```\n\n2. Start dev server and test:\n   ```bash\n   npm run dev\n   ```\n\n3. Navigate to `/book` with the target locale to verify content loads\n\n## Reference: English Translation\n\nThe English (`en`) translation is complete and serves as the **base template** for all new translations:\n- MDX files: `src/content/book/*.mdx` — copy this files to `src/content/book/{locale}/*.mdx`\n- JSON keys: `messages/en.json` → `book` section — use as reference for structure\n\n### Recommended Workflow\n\n1. Copy `src/content/book/*.mdx` to `src/content/book/{locale}/*.mdx`\n2. Copy the `\"book\"` section from `messages/en.json` to `messages/{locale}.json`. Translate these in multiple agentic session instead of single time (token limit may exceed at once)\n3. Edit each file, translating English → target language\n4. Keep all JSX components, code blocks, and Markdown syntax intact\n\n## Quality Guidelines\n\n- **Consistency**: Use consistent terminology throughout (e.g., always translate \"prompt\" the same way)\n- **Technical terms**: Some terms like \"AI\", \"ChatGPT\", \"API\" may stay in English\n- **Cultural adaptation**: Adapt examples to be relevant for the target audience where appropriate\n- **Natural language**: Prioritize natural-sounding translations over literal ones\n"},"lastSynced":"2026-03-08T02:09:22.479Z","agentAnalysis":{"suitability":{"en":"Ideal for Language Agents specializing in content localization, requiring advanced MDX file handling and JSON translation key management.","zh":"适合专门从事内容本地化的语言代理，需要高级的 MDX 文件处理和 JSON 翻译密钥管理。","ja":"コンテンツのローカライズを専門とする言語エージェントに適しています。高度な MDX ファイルの処理と JSON 翻訳キーの管理が必要です。","ko":"콘텐츠 로컬라이제이션을 전문으로 하는 언어 에이전트에게 적합합니다. 고급 MDX 파일 처리 및 JSON 번역 키 관리가 필요합니다.","es":"Ideal para Agentes de Lenguaje que se especializan en localización de contenido, requiriendo un manejo avanzado de archivos MDX y gestión de claves de traducción JSON.","fr":"Idéal pour les Agents de Langue spécialisés dans la localisation de contenu, nécessitant une gestion avancée de fichiers MDX et une gestion de clés de traduction JSON.","de":"Ideal für Sprachagenten, die sich auf die Lokalisierung von Inhalten spezialisieren und eine erweiterte Verwaltung von MDX-Dateien und JSON-Übersetzungsschlüsseln erfordern.","pt":"Ideal para Agentes de Linguagem especializados em localização de conteúdo, requerendo tratamento avançado de arquivos MDX e gerenciamento de chaves de tradução JSON.","ru":"Идеально для языковых агентов, специализирующихся на локализации контента, требующих расширенного xử lý файлов MDX и управления ключами JSON-перевода.","ar":"مثالي للوكلاء اللغويين الذين يختصون في تحويل المحتوى lokalize المحتوى، يتطلبون معالجة متقدمة لملفات MDX وإدارة مفاتيح الترجمة JSON."},"recommendation":{"en":"Empowers agents to translate book content seamlessly, utilizing MDX content files and JSON translation keys, supporting multiple locale codes such as ''de'', ''fr'', ''es'', ''ja'', and more, for The Interactive Book of Prompting at prompts.chat.","zh":"赋予代理无缝翻译书籍内容的能力，利用 MDX 内容文件和 JSON 翻译密钥，支持多种语言代码，如 ''de''、''fr''、''es''、''ja'' 等，适用于 prompts.chat 的交互式提示书。","ja":"エージェントに本のコンテンツを無制限に翻訳する能力を与え、MDX コンテンツファイルと JSON 翻訳キーを使用し、''de''、''fr''、''es''、''ja'' などの複数のロケールコードをサポートし、prompts.chat のインタラクティブな本のプロンプトに対応します。","ko":"에이전트가 책 콘텐츠를无缝翻译 할 수 있는 능력을 부여하여 MDX 콘텐츠 파일과 JSON 번역 키를 사용하고 ''de'', ''fr'', ''es'', ''ja'' 등의 다중 로케일 코드를 지원하여 prompts.chat의 인터랙티브 북의 프롬프트에 대응합니다.","es":"Habilita a los agentes a traducir contenido de libros de forma fluida, utilizando archivos de contenido MDX y claves de traducción JSON, y soportando varios códigos de ubicación como ''de'', ''fr'', ''es'', ''ja'' y más, para El Libro Interactivo de Sugerencias en prompts.chat.","fr":"Permet aux agents de traduire le contenu de livres de manière fluide, en utilisant des fichiers de contenu MDX et des clés de traduction JSON, et en prenant en charge plusieurs codes de localisation tels que ''de'', ''fr'', ''es'', ''ja'' et plus, pour Le Livre Interactif de Suggestions sur prompts.chat.","de":"Ermächtigt Agenten, Buchinhalte nahtlos zu übersetzen, indem sie MDX-Inhaltsdateien und JSON-Übersetzungsschlüssel verwenden und mehrere Ländercodes wie ''de'', ''fr'', ''es'', ''ja'' und weitere für Das Interaktive Buch der Vorschläge auf prompts.chat unterstützen.","pt":"Habilita os agentes a traduzir o conteúdo do livro de forma transparente, utilizando arquivos de conteúdo MDX e chaves de tradução JSON, suportando vários códigos de localização, como ''de'', ''fr'', ''es'', ''ja'' e mais, para O Livro Interativo de Prompting em prompts.chat.","ru":"Наделяет агентов возможностью переводить контент книги бесшовно, используя файлы контента MDX и ключи JSON-перевода, поддерживая несколько кодов локализации, таких как ''de'', ''fr'', ''es'', ''ja'' и более, для Интерактивной книги подсказок на prompts.chat.","ar":"يمكّن الوكلاء من ترجمة محتوى الكتاب بسلاسة، باستخدام ملفات المحتوى MDX ومفاتيح الترجمة JSON، ودعم رموز الموقع الجغرافي المتعددة مثل ''de'' و ''fr'' و ''es'' و ''ja'' وغيرها، من أجل كتاب التحفيز التفاعلي في prompts.chat."},"useCases":{"en":["Translating chapter content for The Interactive Book of Prompting","Managing JSON translation keys for UI strings and chapter descriptions","Localizing MDX content files for multilingual support"],"zh":["为交互式提示书翻译章节内容","管理 UI 字符串和章节描述的 JSON 翻译密钥","为多语言支持本地化 MDX 内容文件"],"ja":["インタラクティブな本の章のコンテンツを翻訳する","UI 文字列と章の説明の JSON 翻訳キーの管理","多言語対応のために MDX コンテンツファイルをローカライズする"],"ko":["인터랙티브 북의 장 콘텐츠를 번역하는 것","UI 문자열 및 장 설명의 JSON 번역 키 관리","다중 언어 지원을 위한 MDX 콘텐츠 파일 로컬라이제이션"],"es":["Traducir contenido de capítulos para El Libro Interactivo de Sugerencias","Gestionar claves de traducción JSON para cadenas de interfaz de usuario y descripciones de capítulos","Localizar archivos de contenido MDX para el soporte de varios idiomas"],"fr":["Traduire le contenu de chapitres pour Le Livre Interactif de Suggestions","Gérer les clés de traduction JSON pour les chaînes d''interface utilisateur et les descriptions de chapitres","Localiser les fichiers de contenu MDX pour le support de plusieurs langues"],"de":["Übersetzen von Kapitelinhalt für Das Interaktive Buch der Vorschläge","Verwalten von JSON-Übersetzungsschlüsseln für Benutzeroberflächenzeichenfolgen und Kapitelbeschreibungen","Lokalisieren von MDX-Inhaltsdateien für die Unterstützung mehrerer Sprachen"],"pt":["Traduzir conteúdo de capítulos para O Livro Interativo de Prompting","Gerenciar chaves de tradução JSON para strings da interface do usuário e descrições de capítulos","Localizar arquivos de conteúdo MDX para suporte multilíngue"],"ru":["Переводить контент глав для Интерактивной книги подсказок","Управлять ключами JSON-перевода для строк интерфейса пользователя и описаний глав","Локализовать файлы контента MDX для многоязычной поддержки"],"ar":["ترجمة محتوى الفصول من أجل كتاب التحفيز التفاعلي","إدارة مفاتيح الترجمة JSON لسنارات واجهة المستخدم ووصف الفصول","تحويل ملفات المحتوى MDX إلى دعم متعدد اللغات"]},"limitations":{"en":["Requires access to MDX content files and JSON translation keys","Limited to supporting 25 chapters across 7 parts of The Interactive Book of Prompting"],"zh":["需要访问 MDX 内容文件和 JSON 翻译密钥","仅限支持交互式提示书的 25 章、7 部分"],"ja":["MDX コンテンツファイルと JSON 翻訳キーへのアクセスが必要","インタラクティブな本の 25 章、7 部分のみをサポート"],"ko":["MDX 콘텐츠 파일 및 JSON 번역 키에 대한 액세스가 필요함","인터랙티브 북의 25 장, 7 부만 지원"],"es":["Requiere acceso a archivos de contenido MDX y claves de traducción JSON","Limitado a soportar 25 capítulos en 7 partes de El Libro Interactivo de Sugerencias"],"fr":["Nécessite un accès aux fichiers de contenu MDX et aux clés de traduction JSON","Limité à prendre en charge 25 chapitres sur 7 parties du Livre Interactif de Suggestions"],"de":["Erfordert Zugriff auf MDX-Inhaltsdateien und JSON-Übersetzungsschlüssel","Begrenzt auf die Unterstützung von 25 Kapiteln in 7 Teilen des Interaktiven Buches der Vorschläge"],"pt":["Requer acesso a arquivos de conteúdo MDX e chaves de tradução JSON","Limitado a suportar 25 capítulos em 7 partes de O Livro Interativo de Prompting"],"ru":["Требует доступа к файлам контента MDX и ключам JSON-перевода","Ограничен поддержкой 25 глав в 7 частях Интерактивной книги подсказок"],"ar":["يتطلب الوصول إلى ملفات المحتوى MDX ومفاتيح الترجمة JSON","محدود لدعم 25 فصلًا في 7 أجزاء من كتاب التحفيز التفاعلي"]},"version":4},"contentHash":"8e0dfd7db942c3f72153c2a59cf6a5161ba99753bacb13b932c3dcb53ace2bc1","qualityScore":39}');
