INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('f/prompts.chat/book-translation', 'book-translation', 'f', 'prompts.chat', 'community', 'book-translation f prompts.chat community The book-translation skill enables the translation of book content for The Interactive Book of Prompting, supporting 25 chapters across 7 parts. It benefits developers and translators working with MDX content files and JSON translation keys. Book Translation Skill支持多语言书籍翻译，包括MDX内容文件和JSON翻译密钥 Book Translation Skillは多言語の書籍翻訳をサポートし、MDXコンテンツファイルとJSON翻訳キーを含みます Book Translation Skill은 다국어 도서 번역을 지원하며 MDX 콘텐츠 파일 및 JSON 번역 키를 포함합니다 La traducción de libros es un proceso que requiere MDX y JSON. Nuestra guía te ayudará a configurar la traducción de libros con AI Herramientas. La traduction de livres est un processus qui nécessite MDX et JSON. Notre guide vous aidera à configurer la traduction de livres avec des outils d''intelligence artificielle Die Buchübersetzung ist ein Prozess, der MDX- und JSON-Dateien erfordert. Unser Leitfaden hilft Ihnen bei der Einrichtung der Buchübersetzung mit KI-Tools O skill de tradução de livros permite a tradução de conteúdo de livros para The Interactive Book of Prompting usando arquivos MDX e JSON. Навык перевода книг позволяет переводить контент книг для The Interactive Book of Prompting с использованием файлов MDX и JSON. مهارة ترجمة الكتب تمكن من ترجمة محتوى الكتب إلى The Interactive Book of Prompting باستخدام ملفات MDX و JSON. how to use book-translation book-translation setup guide MDX content translation JSON translation keys book-translation alternative book-translation vs translation software book-translation install book-translation for developers book-translation for translators book-translation locale support 书籍翻译 AI工具 MDX内容文件 JSON翻译密钥 多语言支持 locale代码 书籍结构 翻译设置 Supports MDX content files for full chapter content translation Utilizes JSON translation keys for UI strings, chapter titles, and descriptions Compatible with multiple locale codes, such as de, fr, es, ja, and more Enables self-hosting for organizations with complete privacy Provides a community-driven platform for sharing and discovering prompts book-translation is a skill that guides the translation of book content using MDX content files and JSON translation keys, supporting multiple locales and chapters.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Paxeer-Network/Sidiora-Perpetual-Protocol/dev-commands', 'community', 'Paxeer-Network', 'Sidiora-Perpetual-Protocol', 'Paxeer-Network/Sidiora-Perpetual-Protocol', 'dev-commands', 0, 0, 39, '2026-03-08T01:57:15.465Z', '2026-03-08T02:09:24.400Z', '3639301ff37479134f57a0e539321dbad39e3d6745aff256b0bed0b8cf2f4153', '{"id":"Paxeer-Network/Sidiora-Perpetual-Protocol/dev-commands","name":"dev-commands","description":{"en":"dev-commands facilitates development with yarn app commands, supporting desktop and web development servers. It benefits developers by streamlining the development process.","zh":"dev-commands提供了用于Electron和Web开发的命令，包括yarn app:desktop和yarn app:web","ja":"dev-commandsはElectronとWeb開発のためのコマンドを提供します。yarn app:desktopとyarn app:webを使用して開発を開始できます","ko":"dev-commands는 Electron 및 Web 개발을 위한 명령어를 제공합니다. yarn app:desktop 및 yarn app:web를 사용하여 개발을 시작할 수 있습니다","es":"dev-commands es un conjunto de comandos para desarrolladores que permite configurar y ejecutar aplicaciones de escritorio y web con Electron y yarn","fr":"dev-commands est un ensemble de commandes pour les développeurs qui permet de configurer et d''exécuter des applications de bureau et web avec Electron et yarn","de":"dev-commands ist eine Sammlung von Befehlen für Entwickler, die es ermöglicht, Anwendungen von Desktop- und Webanwendungen mit Electron und yarn zu konfigurieren und auszuführen","pt":"O dev-commands é um protocolo de futuros perpétuos sintéticos que suporta ativos RWA, criptomoedas, ações e índices. Os desenvolvedores podem usar comandos como `yarn app:desktop` e `yarn app:web` para criar aplicativos personalizados.","ru":"dev-commands - это синтетический протокол вечных фьючерсов, поддерживающий активы RWA, криптовалюты, акции и индексы. Разработчики могут использовать команды, такие как `yarn app:desktop` и `yarn app:web`, для создания индивидуальных приложений для ИИ Агентов","ar":"dev-commands هو بروتوكول موازنات مستقبلية اصطناعية دائمة يدعم الأصول RWA والعملات المشفرة والأوراق المالية والفهارس. يمكن للمطورين استخدام أوامر مثل `yarn app:desktop` و `yarn app:web` لإنشاء تطبيقات مخصصة للأدوات الذكية"},"seo":{"title":{"en":"dev-commands: Development Setup Guide | AI Agent Skill","zh":"dev-commands 开发命令设置指南","ja":"dev-commands AIエージェント開発コマンドガイド","ko":"dev-commands 개발 명령어 설정 가이드","es":"Guía de configuración de dev-commands para desarrolladores","fr":"Guide de mise en route des dev-commands pour les développ...","de":"Einrichtungsleitfaden für dev-commands für Entwickler","pt":"Guia de Configuração do dev-commands: Desenvolvimento de ...","ru":"Настройка dev-commands: Руководство по разработке приложе...","ar":"دليل إعداد dev-commands: تطوير التطبيقات للأدوات الذكية"},"description":{"en":"Discover how to harness dev-commands for seamless development. Learn to navigate yarn app commands and troubleshoot common issues with our expert guide.","zh":"了解dev-commands的开发命令，包括yarn app:desktop和yarn app:web，用于Electron和Web开发","ja":"dev-commandsの開発コマンドを紹介します。ElectronとWeb開発のためのyarn app:desktopとyarn app:webを使用する方法","ko":"dev-commands 개발 명령어에 대한 정보를 제공합니다. Electron 및 Web 개발을 위한 yarn app:desktop 및 yarn app:web 사용 방법","es":"Aprende a configurar y utilizar dev-commands para desarrollar aplicaciones con tecnologías como Electron y yarn","fr":"Découvrez comment configurer et utiliser dev-commands pour développer des applications avec des technologies comme Electron et yarn","de":"Erfahren Sie, wie Sie dev-commands konfigurieren und verwenden, um Anwendungen mit Technologien wie Electron und yarn zu entwickeln","pt":"Aprenda a configurar o dev-commands para desenvolver aplicativos com comandos personalizados e tecnologias avançadas como Electron e Virtual AMM","ru":"Узнайте, как настроить dev-commands для разработки приложений с помощью индивидуальных команд и передовых технологий, таких как Electron и Virtual AMM, для И...","ar":"استكشف كيفية إعداد dev-commands لتطوير التطبيقات باستخدام أوامر مخصصة وتقنيات متقدمة مثل Electron و Virtual AMM للأدوات الذكية"},"definition":{"en":"dev-commands is a set of development commands for application development, including yarn app:desktop and yarn app:web, for efficient project setup and troubleshooting.","zh":"dev-commands是用于开发的命令集合，包括Electron和Web开发","ja":"dev-commandsは開発用のコマンドの集合であり、ElectronとWeb開発をサポートしています","ko":"dev-commands는 개발을 위한 명령어 모음입니다. Electron 및 Web 개발을 지원합니다","es":"dev-commands es un conjunto de comandos de desarrollo que facilita la creación de aplicaciones","fr":"dev-commands est un ensemble de commandes de développement qui facilite la création d''applications","de":"dev-commands ist eine Sammlung von Entwicklungsbefehlen, die die Erstellung von Anwendungen erleichtert","pt":"O dev-commands é um conjunto de comandos de desenvolvimento para criar aplicativos personalizados com tecnologias avançadas","ru":"dev-commands - это набор команд разработки для создания индивидуальных приложений с помощью передовых технологий для ИИ Агентов","ar":"dev-commands هو مجموعة من أوامر التطوير لإنشاء تطبيقات مخصصة باستخدام تقنيات متقدمة للأدوات الذكية"},"features":{"en":["Starts desktop Electron app development with `yarn app:desktop` command","Supports web development server with `yarn app:web` command","Troubleshoots common issues with `yarn clean && yarn reinstall` command","Provides runtime estimates for development server startup","Adapts to project-specific development needs"],"zh":["支持Electron开发","支持Web开发","使用yarn app:desktop启动Electron应用开发","使用yarn app:web启动Web开发服务器","提供故障排除方法，例如运行yarn clean && yarn reinstall"],"ja":["Electron開発をサポート","Web開発をサポート","yarn app:desktopを使用してElectronアプリ開発を開始","yarn app:webを使用してWeb開発サーバーを開始","トラブルシューティング方法を提供します。例：yarn clean && yarn reinstallを実行"],"ko":["Electron 개발 지원","Web 개발 지원","yarn app:desktop를 사용하여 Electron 애플리케이션 개발 시작","yarn app:web를 사용하여 Web 개발 서버 시작","트러블슈팅 방법 제공, 예: yarn clean && yarn reinstall 실행"],"es":["Soporte para aplicaciones de escritorio con Electron","Compatibilidad con yarn para la gestión de dependencias","Comandos personalizados para la configuración y ejecución de aplicaciones","Opciones de depuración y solución de problemas integradas","Compatibilidad con tecnologías como Virtual AMM y TWAP smoothing"],"fr":["Prise en charge des applications de bureau avec Electron","Compatibilité avec yarn pour la gestion des dépendances","Commandes personnalisées pour la configuration et l''exécution d''applications","Options de débogage et de dépannage intégrées","Compatibilité avec des technologies comme Virtual AMM et TWAP smoothing"],"de":["Unterstützung für Desktop-Anwendungen mit Electron","Kompatibilität mit yarn für die Verwaltung von Abhängigkeiten","Benutzerdefinierte Befehle für die Konfiguration und Ausführung von Anwendungen","Integrierte Debug- und Troubleshooting-Optionen","Kompatibilität mit Technologien wie Virtual AMM und TWAP smoothing"],"pt":["Suporte a ativos RWA, criptomoedas, ações e índices","Comandos personalizados como `yarn app:desktop` e `yarn app:web`","Tecnologias avançadas como Electron e Virtual AMM","Desenvolvimento de aplicativos com per-user on-chain vaults","Suporte a posições long/short com alavancagem de até 1000x"],"ru":["Поддержка активов RWA, криптовалют, акций и индексов","Индивидуальные команды, такие как `yarn app:desktop` и `yarn app:web`","Передовые технологии, такие как Electron и Virtual AMM, для ИИ Агентов","Разработка приложений с пер-user on-chain vaults","Поддержка длинных/коротких позиций с левериджем до 1000x"],"ar":["دعم الأصول RWA والعملات المشفرة والأوراق المالية والفهارس","أوامر مخصصة مثل `yarn app:desktop` و `yarn app:web`","تقنيات متقدمة مثل Electron و Virtual AMM للأدوات الذكية","تطوير التطبيقات مع خزائن على السلسلة لكل مستخدم","دعم المواقف الطويلة/القصيرة مع رافعة مالية تصل إلى 1000x"]},"keywords":{"en":["how to use dev-commands","dev-commands setup guide","yarn app commands","dev-commands alternative","dev-commands vs other development tools","dev-commands install","what is dev-commands","dev-commands troubleshooting","dev-commands for web development","dev-commands for desktop development"],"zh":["dev-commands","Electron开发","Web开发","yarn app:desktop","yarn app:web","开发命令","故障排除"],"ja":["dev-commands","Electron開発","Web開発","yarn app:desktop","yarn app:web","開発コマンド","トラブルシューティング"],"ko":["dev-commands","Electron 개발","Web 개발","yarn app:desktop","yarn app:web","개발 명령어","트러블슈팅"],"es":["dev-commands","desarrollo de aplicaciones","Electron","yarn","Virtual AMM","TWAP smoothing","Herramientas de desarrollo","Entorno de desarrollo","Depuración de aplicaciones"],"fr":["dev-commands","développement d''applications","Electron","yarn","Virtual AMM","TWAP smoothing","Outils de développement","Environnement de développement","Débogage d''applications"],"de":["dev-commands","Anwendungsentwicklung","Electron","yarn","Virtual AMM","TWAP smoothing","Entwicklungstools","Entwicklungsumgebung","Anwendungs-Debugging"],"pt":["dev-commands","desenvolvimento de aplicativos","comandos personalizados","Electron","Virtual AMM","futuros perpétuos sintéticos","ativos RWA","criptomoedas","ações","índices"],"ru":["dev-commands","разработка приложений","индивидуальные команды","Electron","Virtual AMM","вечные фьючерсы","активы RWA","криптовалюты","акции","индексы","ИИ Агенты"],"ar":["dev-commands","تطوير التطبيقات","أوامر مخصصة","Electron","Virtual AMM","الموازنات المستقبلية الاصطناعية","الأصول RWA","العملات المشفرة","الأوراق المالية","الفهارس","الأدوات الذكية"]}},"owner":"Paxeer-Network","repo":"Sidiora-Perpetual-Protocol","repoPath":"Paxeer-Network/Sidiora-Perpetual-Protocol","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.465Z","topics":[],"category":"community","skillMd":{"name":"dev-commands","description":"Development commands for monorepo projects. Use when running dev servers, building apps, linting, testing, or troubleshooting build issues. Triggers on yarn, dev, build, lint, test, desktop, mobile, web, extension, ios, android, compile, bundle.","bodyPreview":"# Development Commands\n\n## Application Development Commands\n\n**PLATFORM-SPECIFIC DEVELOPMENT** (adapt command names to your project):\n- `yarn app:desktop` - Start desktop Electron app development\n  - **Runtime**: 30-60 seconds to start\n  - **Common issues**: Node version conflicts, missing native dependencies\n  - **Troubleshooting**: Run `yarn clean && yarn reinstall` if startup fails\n\n- `yarn app:web` - Start web development server\n  - **Runtime**: 15-30 seconds to start\n  - **Common issues**:","body":"# Development Commands\n\n## Application Development Commands\n\n**PLATFORM-SPECIFIC DEVELOPMENT** (adapt command names to your project):\n- `yarn app:desktop` - Start desktop Electron app development\n  - **Runtime**: 30-60 seconds to start\n  - **Common issues**: Node version conflicts, missing native dependencies\n  - **Troubleshooting**: Run `yarn clean && yarn reinstall` if startup fails\n\n- `yarn app:web` - Start web development server\n  - **Runtime**: 15-30 seconds to start\n  - **Common issues**: Port already in use, webpack/bundler compilation errors\n  - **Troubleshooting**: Kill existing processes on port, check console for specific errors\n\n- `yarn app:ext` - Start browser extension development\n  - **Runtime**: 20-40 seconds to start\n  - **Common issues**: Manifest v3 validation errors, permission issues\n  - **Troubleshooting**: Check extension manifest validity, verify content security policy\n\n- `yarn app:ios` - Start iOS mobile development\n  - **Runtime**: 1-2 minutes (includes Metro bundler)\n  - **Common issues**: Xcode setup, simulator issues, pod install failures\n  - **Prerequisites**: Xcode installed, iOS simulator available\n\n- `yarn app:android` - Start Android mobile development\n  - **Runtime**: 1-2 minutes (includes Metro bundler)\n  - **Common issues**: Android SDK path, emulator setup, gradle build failures\n  - **Prerequisites**: Android Studio, SDK tools, emulator configured\n\n## Build Commands\n\n**PRODUCTION BUILDS** (Use for final validation):\n- `yarn app:desktop:build` - Build desktop app for all platforms\n  - **Runtime**: 5-10 minutes (multi-platform build)\n  - **Output**: Platform-specific installers in `apps/desktop/dist/`\n  - **Common issues**: Code signing, platform-specific dependencies\n\n- `yarn app:ext:build` - Build browser extension\n  - **Runtime**: 2-3 minutes\n  - **Output**: Extension packages in `apps/ext/dist/`\n  - **Common issues**: Manifest validation, content security policy violations\n\n- `yarn app:web:build` - Build web application\n  - **Runtime**: 3-5 minutes\n  - **Output**: Static files in `apps/web/dist/`\n  - **Common issues**: Bundle size limits, missing environment variables\n\n- `yarn app:native-bundle` - Bundle React Native app\n  - **Runtime**: 3-5 minutes\n  - **Common issues**: Native module linking, Metro bundler errors\n\n## Development Tools & Quality Assurance\n\n### Pre-commit Commands (Local Development)\n\n**Use these for fast pre-commit validation:**\n- `yarn lint:staged` - Lint only staged files (fast, recommended for pre-commit)\n- `yarn tsc:staged` - Type check staged files\n\n**Pre-commit workflow:**\n```bash\nyarn lint:staged && yarn tsc:staged && git commit -m \"your message\"\n```\n\n### CI Commands (Full Project Check)\n\n**These run in CI pipeline, not for local pre-commit:**\n- `yarn lint` - **CI ONLY** comprehensive linting\n  - **Expected runtime**: 5-10 minutes\n  - **Zero tolerance**: ALL warnings and errors MUST be fixed\n- `yarn lint:only` - Quick lint check (all files)\n- `yarn tsc:only` - Full TypeScript type check\n- `yarn test` - Test execution\n\n### Other Tools\n\n- `yarn clean` - Clean all build artifacts and node_modules\n- `yarn reinstall` - Full clean install (use when dependency issues occur)\n\n## Testing\n\n- Jest configuration in `jest.config.js`\n- Test setup in `jest-setup.js`\n- Tests located in `__tests__/` or `@tests/` directories within packages\n"},"lastSynced":"2026-03-08T02:09:24.400Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents needing streamlined desktop and web development server management with yarn app commands.","zh":"适合需要简化桌面和Web开发服务器管理的开发代理，支持yarn app命令。","ja":"デスクトップおよびWeb開発サーバーの管理を簡素化する必要がある開発エージェントに適しています。yarn appコマンドを使用します。","ko":"데스크톱 및 웹 개발 서버 관리를 간소화해야 하는 개발 에이전트에게 적합합니다. yarn app 명령을 지원합니다.","es":"Ideal para agentes de desarrollo que necesitan una gestión de servidores de desarrollo de escritorio y web optimizada con comandos de aplicaciones yarn.","fr":"Idéal pour les agents de développement ayant besoin d''une gestion de serveurs de développement de bureau et Web simplifiée avec des commandes d''applications yarn.","de":"Ideal für Entwicklungssagenten, die eine optimierte Verwaltung von Desktop- und Web-Entwicklungsservern mit yarn-App-Befehlen benötigen.","pt":"Ideal para Agentes de Desenvolvimento que necessitam de gerenciamento de servidor de desenvolvimento de desktop e web simplificado com comandos de aplicativo yarn.","ru":"Идеально подходит для агентов разработки, которым необходим упрощенный менеджмент сервера разработки настольных и веб-приложений с помощью команд приложения yarn.","ar":"مثالي لوكلاء التطوير الذين يحتاجون إلى إدارة خادم التطوير على سطح المكتب والويب بسهولة باستخدام أوامر تطبيق يارن."},"recommendation":{"en":"Empowers agents to efficiently manage development workflows using yarn app:desktop and yarn app:web commands, leveraging Electron for desktop applications and optimizing web development server startup times, while troubleshooting common issues like Node version conflicts and missing native dependencies.","zh":"赋予代理高效管理开发工作流的能力，使用yarn app:desktop和yarn app:web命令，利用Electron进行桌面应用开发，并优化Web开发服务器启动时间，同时排除Node版本冲突和缺失的原生依赖等常见问题。","ja":"エージェントが効率的に開発ワークフローを管理できるようにします。yarn app:desktopおよびyarn app:webコマンドを使用し、Electronをデスクトップアプリケーションに、Web開発サーバーの起動時間を最適化します。また、Nodeバージョンの競合や不足しているネイティブ依存関係などの一般的な問題のトラブルシューティングも行います。","ko":"에이전트가 개발 워크플로를 효율적으로 관리할 수 있도록 합니다. yarn app:desktop 및 yarn app:web 명령을 사용하여 Electron을 데스크톱 애플리케이션에 사용하고 웹 개발 서버의 시작 시간을 최적화합니다. 또한 Node 버전 충돌 및缺失한 네이티브 종속성 등 일반적인 문제의 문제 해결도 수행합니다.","es":"Habilita a los agentes a gestionar eficientemente flujos de trabajo de desarrollo utilizando comandos yarn app:desktop y yarn app:web, aprovechando Electron para aplicaciones de escritorio y optimizando los tiempos de inicio del servidor de desarrollo web, mientras se solucionan problemas comunes como conflictos de versión de Node y dependencias nativas que faltan.","fr":"Permet aux agents de gérer efficacement les flux de travail de développement en utilisant les commandes yarn app:desktop et yarn app:web, en exploitant Electron pour les applications de bureau et en optimisant les temps de démarrage du serveur de développement Web, tout en résolvant des problèmes courants tels que les conflits de version de Node et les dépendances natives manquantes.","de":"Ermöglicht es Agenten, Entwicklungswerkflüsse effizient zu verwalten, indem sie yarn-App-Befehle wie yarn app:desktop und yarn app:web verwenden, Electron für Desktop-Anwendungen nutzen und die Startzeit des Web-Entwicklungsservers optimieren, während sie gemeinsame Probleme wie Node-Versionenkonflikte und fehlende native Abhängigkeiten beheben.","pt":"Habilita os agentes a gerenciar fluxos de trabalho de desenvolvimento de forma eficiente usando os comandos yarn app:desktop e yarn app:web, aproveitando o Electron para aplicações de desktop e otimizando os tempos de inicialização do servidor de desenvolvimento da web, além de solucionar problemas comuns como conflitos de versão do Node e dependências nativas ausentes.","ru":"Наделяет агентов возможностью эффективно управлять рабочими процессами разработки с помощью команд yarn app:desktop и yarn app:web, используя Electron для настольных приложений и оптимизируя время запуска веб-сервера разработки, а также решая общие проблемы, такие как конфликты версий Node и отсутствующие родные зависимости.","ar":"يمنح الوكلاء القدرة على إدارة سير عمل التطوير بفعالية باستخدام أوامر يارن تطبيق: سطح المكتب و يارن تطبيق: الويب، واستخدام إلكترون ل تطبيقات سطح المكتب وتحسين أوقات بدء تشغيل خادم التطوير الويب، بالإضافة إلى حل المشاكل الشائعة مثل تحديثات إصدار نود والاعتماديات الأصلية المفقودة."},"useCases":{"en":["Streamlining desktop Electron app development with yarn app:desktop","Accelerating web development server startup with yarn app:web","Troubleshooting startup failures using yarn clean and yarn reinstall"],"zh":["使用yarn app:desktop简化桌面Electron应用开发","使用yarn app:web加速Web开发服务器启动","使用yarn clean和yarn reinstall排除启动失败问题"],"ja":["yarn app:desktopを使用してデスクトップElectronアプリケーションの開発を簡素化する","yarn app:webを使用してWeb開発サーバーの起動を加速する","yarn cleanおよびyarn reinstallを使用して起動失敗の問題をトラブルシューティングする"],"ko":["yarn app:desktop를 사용하여 데스크톱 Electron 애플리케이션 개발을 간소화하는 것","yarn app:web를 사용하여 웹 개발 서버 시작을 가속화하는 것","yarn clean 및 yarn reinstall를 사용하여 시작 실패 문제를 진단하는 것"],"es":["Optimizar el desarrollo de aplicaciones de escritorio Electron con yarn app:desktop","Acelerar el tiempo de inicio del servidor de desarrollo web con yarn app:web","Solucionar fallos de inicio con yarn clean y yarn reinstall"],"fr":["Optimiser le développement d''applications de bureau Electron avec yarn app:desktop","Accélérer le temps de démarrage du serveur de développement Web avec yarn app:web","Résoudre les échecs de démarrage à l''aide de yarn clean et yarn reinstall"],"de":["Desktop-Anwendungen von Electron mit yarn app:desktop optimieren","Web-Entwicklungsserver-Startzeit mit yarn app:web beschleunigen","Startfehler mit yarn clean und yarn reinstall beheben"],"pt":["Simplificando o desenvolvimento de aplicativos Electron de desktop com yarn app:desktop","Acelerando a inicialização do servidor de desenvolvimento da web com yarn app:web","Solucionando falhas de inicialização usando yarn clean e yarn reinstall"],"ru":["Упрощение разработки настольных приложений Electron с помощью yarn app:desktop","Ускорение запуска веб-сервера разработки с помощью yarn app:web","Устранение неисправностей запуска с помощью yarn clean и yarn reinstall"],"ar":["تبسيط تطوير تطبيقات إلكترون لسطح المكتب باستخدام يارن تطبيق: سطح المكتب","تعزيز سرعة بدء تشغيل خادم التطوير الويب باستخدام يارن تطبيق: الويب","معالجة عطال بدء التشغيل باستخدام يارن تنظيف و يارن إعادة التثبيت"]},"limitations":{"en":["Requires yarn installation","Limited to desktop and web development servers","Potential Node version conflicts and missing native dependencies"],"zh":["需要yarn安装","仅限桌面和Web开发服务器","可能存在Node版本冲突和缺失的原生依赖"],"ja":["yarnのインストールが必要","デスクトップおよびWeb開発サーバーに限定される","Nodeバージョンの競合や不足しているネイティブ依存関係が発生する可能性がある"],"ko":["yarn 설치가 필요함","데스크톱 및 웹 개발 서버에만 국한됨","Node 버전 충돌이나 결측된 네이티브 종속성 발생 가능"],"es":["Requiere la instalación de yarn","Limitado a servidores de desarrollo de escritorio y web","Posibles conflictos de versión de Node y dependencias nativas que faltan"],"fr":["Nécessite l''installation de yarn","Limité aux serveurs de développement de bureau et Web","Conflits de version de Node et dépendances natives manquantes possibles"],"de":["Benötigt yarn-Installation","Begrenzt auf Desktop- und Web-Entwicklungsserver","Mögliche Node-Versionenkonflikte und fehlende native Abhängigkeiten"],"pt":["Exige a instalação do yarn","Limitado a servidores de desenvolvimento de desktop e web","Conflitos potenciais de versão do Node e dependências nativas ausentes"],"ru":["Требует установки yarn","Ограничен серверами разработки настольных и веб-приложений","Потенциальные конфликты версий Node и отсутствующие родные зависимости"],"ar":["يتطلب تثبيت يارن","محدود بخوادرمحطات سطح المكتب والويب","تحديثات إصدار نود المحتملة والاعتماديات الأصلية المفقودة"]},"version":4},"contentHash":"3639301ff37479134f57a0e539321dbad39e3d6745aff256b0bed0b8cf2f4153","qualityScore":39}');
