JavaScript فقط","يتطلب إعداد MCP للتكاملات الخارجية","مقتصر على نظام المكتبات المُحمّلة مسبقًا"]},"version":4},"contentHash":"d24415fbe938bc20435c1f6a0f1b4cb8b4e118bf4ba1714d4b3391d54828768b","qualityScore":39}');
