INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DeanMojo/polysmith-mvp/claude-code-guide', 'claude-code-guide', 'DeanMojo', 'polysmith-mvp', 'community', 'claude-code-guide DeanMojo polysmith-mvp community The claude-code-guide skill provides a comprehensive learning resource for developers, covering Claude Code''s core functionality, REPL environment, and development workflows. It benefits developers looking to master Claude Code and improve their development efficiency. Claude Code是一种高级开发工具，提供了从基础到高级的所有核心概念、工具使用、开发工作流和最佳实践 Claude Codeは高級開発ツールであり、基礎から高級までのすべてのコア概念、ツールの使用、開発ワークフロー、ベストプラクティスを提供します Claude Code는 고급 개발 도구로, 기본에서 고급까지 모든 핵심 개념, 도구 사용, 개발 워크플로, 최고의 관행을 제공합니다 Claude Code es una herramienta de desarrollo que ofrece un entorno REPL con soporte para ES6+, async/await y WebAssembly, así como capacidades de visualización con React y Three.js Claude Code est un outil de développement qui propose un environnement REPL avec un support pour ES6+, async/await et WebAssembly, ainsi que des capacités de visualisation avec React et Three.js Claude Code ist ein Entwicklungstool, das eine REPL-Umgebung mit Unterstützung für ES6+, async/await und WebAssembly sowie Visualisierungsfunktionen mit React und Three.js bietet O guia de desenvolvimento avançado do Claude Code cobre conceitos core, REPL, Artifacts e melhores práticas. Руководство по продвинутому разработке Claude Code охватывает основные концепции, REPL, Artifacts и лучшие практики для ИИ Агентов. دليل التطوير المتقدم Claude Code يغطي المفاهيم الأساسية و REPL و Artifacts وأفضل الممارسات لأدوات الذكاء الاصطناعي how to use claude-code-guide claude-code-guide tutorial claude-code-guide vs other development tools claude-code-guide setup guide claude-code-guide install what is claude-code-guide claude-code-guide best practices claude-code-guide advanced development claude-code-guide REPL environment Claude Code 高级开发工具 REPL环境 Artifacts可视化输出 JavaScript运行时环境 ES6+ D3.js MathJS Lodash Papaparse SheetJS Supports JavaScript runtime environment with ES6+ support Provides pre-loaded libraries including D3.js, MathJS, and Lodash Enables async/await, BigInt, and WebAssembly support Offers file reading capabilities via `window.fs.readFile()` Includes Artifacts for visualized output with React and Three.js claude-code-guide is a comprehensive development guide for Claude Code, covering core concepts, tools, and best practices for advanced development and workflow optimization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Vinicius-B-Leite/blcalisteniaV2/create-screens-and-routing', 'community', 'Vinicius-B-Leite', 'blcalisteniaV2', 'Vinicius-B-Leite/blcalisteniaV2', 'create-screens-and-routing', 0, 0, 39, '2026-03-08T01:57:15.476Z', '2026-03-08T02:09:47.865Z', '32dedd07a76ddb724a48a9b9a829f6711648ef5d8efeabf7973d09f5a7f48d25', '{"id":"Vinicius-B-Leite/blcalisteniaV2/create-screens-and-routing","name":"create-screens-and-routing","description":{"en":"The create-screens-and-routing skill guides developers in creating screens and routing configurations using Expo Router and React Native with TypeScript. This skill benefits developers building mobile applications.","zh":"本技能指导使用Expo Router和项目的屏幕/布局模式创建屏幕和路由配置","ja":"このスキルは、Expo Routerとプロジェクトのスクリーン/レイアウトパターンを使用してスクリーンとルーティングを設定する方法を示します","ko":"이 스킬은 Expo Router와 프로젝트의 화면/레이아웃 패턴을 사용하여 화면과 라우팅을 설정하는 방법을 가이드합니다","es":"create-screens-and-routing es una habilidad que guía la creación de pantallas y configuración de rutas con Expo Router y patrones de pantalla/diseño de proyectos","fr":"create-screens-and-routing est une compétence qui guide la création d''écrans et la configuration de routes avec Expo Router et les modèles d''écran/conception de projets","de":"create-screens-and-routing ist eine Fähigkeit, die die Erstellung von Bildschirmen und die Konfiguration von Routen mit Expo Router und Projektscreen-Layout-Mustern anleitet","pt":"Este guia aborda a criação de telas e roteamento com Expo Router, React Native e TypeScript. Aprenda a usar componentes core e ícones para melhorar a experiência do usuário.","ru":"Этот гид посвящен созданию экранов и маршрутизации с помощью Expo Router, React Native и TypeScript. Узнайте, как использовать базовые компоненты и иконки для улучшения пользовательского опыта.","ar":"هذا الدليل يغطي إنشاء الشاشات وتصفية الطرق باستخدام Expo Router و React Native و TypeScript. تعلم كيفية استخدام المكونات الأساسية والأيقونات لتحسين تجربة المستخدم."},"seo":{"title":{"en":"create-screens-and-routing: Expo Router Setup Guide | AI ...","zh":"AI工具：创建屏幕和路由配置Setup Guide","ja":"AIエージェント：スクリーンとルーティングの設定方法","ko":"AI 도구: 화면 및 라우팅 설정 가이드","es":"Guía de configuración para create-screens-and-routing con...","fr":"Configurer les écrans et le routage avec create-screens-a...","de":"Einrichtung von Bildschirmen und Routing mit create-scree...","pt":"Criar Telas e Roteamento com Expo Router - Guia de Config...","ru":"Создание Экранов и Маршрутизации с Expo Router - Настройк...","ar":"إنشاء الشاشات وتصفية الطرق باستخدام Expo Router - دليل ال..."},"description":{"en":"Discover how to create screens and routing configurations with Expo Router and React Native. Learn how to implement file-based routing and more!","zh":"学习使用Expo Router和React Native创建屏幕和路由配置，搭配Stack、Tabs和Safe Area","ja":"Expo RouterとReact Nativeを使用してスクリーンとルーティングを設定する方法を学びましょう","ko":"Expo Router와 React Native를 사용하여 화면과 라우팅을 설정하는 방법을 알아보세요","es":"Aprende a crear pantallas y configurar rutas con create-screens-and-routing y Expo Router para aplicaciones móviles con React Native","fr":"Découvrez comment créer des écrans et configurer les routes avec create-screens-and-routing et Expo Router pour des applications mobiles avec React Native","de":"Erfahren Sie, wie Sie Bildschirme erstellen und Routen konfigurieren mit create-screens-and-routing und Expo Router für mobile Anwendungen mit React Native","pt":"Aprenda a criar telas e configurar roteamento com Expo Router, React Native e TypeScript. Descubra como usar Stack, Tabs e Safe Area para melhorar a experiên...","ru":"Узнайте, как создать экраны и настроить маршрутизацию с помощью Expo Router, React Native и TypeScript. Откройте для себя, как использовать Stack, Tabs и Saf...","ar":"تعرف على كيفية إنشاء الشاشات وتهيئة التصفية باستخدام Expo Router و React Native و TypeScript. اكتشف كيفية استخدام Stack و Tabs و Safe Area لتحسين ت