INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Vinicius-B-Leite/blcalisteniaV2/create-screens-and-routing', 'create-screens-and-routing', 'Vinicius-B-Leite', 'blcalisteniaV2', 'community', 'create-screens-and-routing Vinicius-B-Leite blcalisteniaV2 community The create-screens-and-routing skill guides developers in creating screens and routing configurations using Expo Router and React Native with TypeScript. This skill benefits developers building mobile applications. 本技能指导使用Expo Router和项目的屏幕/布局模式创建屏幕和路由配置 このスキルは、Expo Routerとプロジェクトのスクリーン/レイアウトパターンを使用してスクリーンとルーティングを設定する方法を示します 이 스킬은 Expo Router와 프로젝트의 화면/레이아웃 패턴을 사용하여 화면과 라우팅을 설정하는 방법을 가이드합니다 create-screens-and-routing es una habilidad que guía la creación de pantallas y configuración de rutas con Expo Router y patrones de pantalla/diseño de proyectos create-screens-and-routing est une compétence qui guide la création d''écrans et la configuration de routes avec Expo Router et les modèles d''écran/conception de projets create-screens-and-routing ist eine Fähigkeit, die die Erstellung von Bildschirmen und die Konfiguration von Routen mit Expo Router und Projektscreen-Layout-Mustern anleitet Este guia aborda a criação de telas e roteamento com Expo Router, React Native e TypeScript. Aprenda a usar componentes core e ícones para melhorar a experiência do usuário. Этот гид посвящен созданию экранов и маршрутизации с помощью Expo Router, React Native и TypeScript. Узнайте, как использовать базовые компоненты и иконки для улучшения пользовательского опыта. هذا الدليل يغطي إنشاء الشاشات وتصفية الطرق باستخدام Expo Router و React Native و TypeScript. تعلم كيفية استخدام المكونات الأساسية والأيقونات لتحسين تجربة المستخدم. how to use create-screens-and-routing create-screens-and-routing setup guide Expo Router tutorial React Native routing configuration create-screens-and-routing alternative create-screens-and-routing vs React Navigation install create-screens-and-routing create-screens-and-routing documentation what is create-screens-and-routing AI工具 创建屏幕 路由配置 Expo Router React Native 文件基于路由 Stack Tabs Safe Area Utilizes Expo Router for file-based routing Supports React Native with TypeScript for building mobile applications Includes Stack and Tabs components from expo-router Provides Safe Area via react-native-safe-area-context Enables theme customization via useAppTheme and useStyles Leverages core components from src/ui/components/core/ create-screens-and-routing is a skill that enables developers to create screens and routing configurations using Expo Router, React Native, and TypeScript.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fantasy-cc/credit-card-tracker/update-card-benefits', 'community', 'fantasy-cc', 'credit-card-tracker', 'fantasy-cc/credit-card-tracker', 'update-card-benefits', 0, 0, 39, '2026-03-08T01:57:15.493Z', '2026-03-08T02:10:09.311Z', '0d9a0a38d20143f7ef91ecc93059160dfdb3b1d0bda0764d0773d7b80595a0b4', '{"id":"fantasy-cc/credit-card-tracker/update-card-benefits","name":"update-card-benefits","description":{"en":"The update-card-benefits skill guides you through updating benefits for existing credit cards, ensuring all users see the changes. This 3-step process is crucial for maintaining consistency.","zh":"update-card-benefits技能指导您更新现有信用卡的福利，确保所有用户看到变化","ja":"update-card-benefitsスキルは、既存のクレジットカードの福利を更新します","ko":"update-card-benefits 스킬은 기존 신용카드의福利를 업데이트합니다","es":"Actualiza beneficios de tarjetas en CouponCycle con este proceso de 3 pasos para asegurar que todos los usuarios vean los cambios","fr":"Mettez à jour les avantages des cartes dans CouponCycle avec ce processus de 3 étapes pour vous assurer que tous les utilisateurs voient les modifications","de":"Aktualisieren Sie Kartenleistungen in CouponCycle mit diesem 3-Schritte-Prozess, um sicherzustellen, dass alle Benutzer die Änderungen sehen","pt":"O skill update-card-benefits é um processo de 3 etapas para atualizar benefícios de cartão para todos os usuários, novos e existentes, editando o arquivo prisma/seed.ts","ru":"Навык update-card-benefits представляет собой 3-ступенчатый процесс обновления льгот карт для всех пользователей, новых и существующих, путем редактирования файла prisma/seed.ts","ar":"مهارة update-card-benefits هي عملية من 3 خطوات لتحديث فوائد البطاقة لجميع المستخدمين، الجدد والقائمين، من خلال تحرير ملف prisma/seed.ts"},"seo":{"title":{"en":"update-card-benefits: 3-Step Setup Guide for AI Agents","zh":"更新卡片福利指南 - AIエージェント工具","ja":"Update Card Benefits Setup Guide - AIエージェント","ko":"카드福利 업데이트 가이드 - AI 에이전트 도구","es":"Guía de configuración para actualizar beneficios de tarje...","fr":"Guide d''installation pour mettre à jour les avantages des...","de":"Einrichtungsleitfaden zum Aktualisieren von Kartenleistun...","pt":"Guia de Configuração para Atualizar Benefícios de Cartão ...","ru":"Настройка обновления льгот карт с помощью ИИ Агентов","ar":"دليل الإعداد لتحديث فوائد البطاقة باستخدام أدوات الذكاء ا..."},"description":{"en":"Learn how to update credit card benefits with our 3-step process. Ensure all users see changes. Get started now!","zh":"了解如何使用update-card-benefits技能更新现有信用卡的福利，确保所有用户看到变化","ja":"update-card-benefitsスキルを使用して既存のクレジットカードの福利を更新する方法を学びます","ko":"update-card-benefits 스킬을 사용하여 기존 신용카드의福利를 업데이트하는 방법을 알아보세요","es":"Aprende a actualizar beneficios de tarjetas existentes en CouponCycle con nuestra guía paso a paso para desarrolladores","fr":"Découvrez comment mettre à jour les avantages des cartes existantes dans CouponCycle avec notre guide étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie bestehende Kartenleistungen in CouponCycle mit unserem Schritt-für-Schritt-Leitfaden für Entwickler aktualisieren","pt":"Aprenda a atualizar benefícios de cartão para todos os usuários com o skill update-card-benefits e melhore a experiência do usuário final","ru":"Узнайте, как обновить льготы карт для всех пользователей с помощью навыка update-card-benefits и улучшите опыт конечных пользователей","ar":"تعرف على كيفية تحديث فوائد البطاقة لجميع المستخدمين باستخدام مهارة update-card-benefits وتحسين تجربة المستخدم النهائي"},"definition":{"en":"update-card-benefits is a skill that updates benefits for existing credit cards in CouponCycle, ensuring all users see the changes through a 3-step process.","zh":"update-card-benefits技能是更新现有信用卡福利的3步骤过程","ja":"update-card-benefitsスキルは、既存のクレジットカードの福利を更新するための3ステッププロセスです","ko":"update-card-benefits 스킬은 기존 신용카드의福利를 업데이트하기 위한 3단계 프로세스입니다","es":"La actualización de beneficios de tarjetas es un proceso de 3 pasos que garantiza que todos los usuarios vean los cambios en los beneficios de las tarjetas","fr":"La mise à jour des avantages des cartes est un processus de 3 étapes qui garantit que tous les utilisateurs voient les modifications apportées aux avantages des cartes","de":"Die Aktualisierung von Kartenleistungen ist ein 3-Schritte-Prozess, der sicherstellt, dass alle Benutzer die Änderungen an den Kartenleistungen sehen","pt":"O que é update-card-benefits? É um skill que atualiza benefícios de cartão para todos os usuários, garantindo que as alterações sejam vistas por todos","ru":"Что такое update-card-benefits? Это навык, который обновляет льготы карт для всех пользователей, гарантируя, что изменения будут видны всем","ar":"ما هي مهارة update-card-benefits؟ هي مهارة تحديث فوائد البطاقة لجميع المستخدمين، مما يضمن أن يتم رؤية التغييرات من قبل الجميع"},"features":{"en":["Edits prisma/seed.ts to update benefit structures","Ensures new users see updated benefits when adding cards","Updates existing users'' benefit structures to reflect changes","Follows a recommended 3-step workflow for seamless implementation"],"zh":["3步骤更新福利过程","编辑prisma/seed.ts文件","确保新旧用户都看到变化","更新信用卡福利结构","使用Prisma进行数据更新"],"ja":["3ステップの福利更新プロセス","prisma/seed.tsファイルの編集","新規および既存のユーザーが変更を確認する","クレジットカードの福利構造の更新","Prismaを使用したデータ更新"],"ko":["3단계福利 업데이트 프로세스","prisma/seed.ts 파일 편집","신규 및 기존 사용자가 변경 사항을 확인","신용카드福利 구조 업데이트","Prisma를 사용한 데이터 업데이트"],"es":["Edición del archivo prisma/seed.ts","Actualización de beneficios para tarjetas existentes","Garantía de que todos los usuarios vean los cambios","Proceso de 3 pasos para la actualización","Compatibilidad con usuarios nuevos y existentes","Implementación con tecnologías como Prisma"],"fr":["Édition du fichier prisma/seed.ts","Mise à jour des avantages pour les cartes existantes","Garantie que tous les utilisateurs voient les modifications","Processus de 3 étapes pour la mise à jour","Compatibilité avec les utilisateurs nouveaux et existants","Implémentation avec des technologies comme Prisma"],"de":["Bearbeitung der Datei prisma/seed.ts","Aktualisierung von Leistungen für bestehende Karten","Gewährleistung, dass alle Benutzer die Änderungen sehen","3-Schritte-Prozess für die Aktualisierung","Kompatibilität mit neuen und bestehenden Benutzern","Implementierung mit Technologien wie Prisma"],"pt":["Edição do arquivo prisma/seed.ts","Atualização de benefícios de cartão para todos os usuários","Processo de 3 etapas para garantir a consistência","Compatibilidade com novos e existentes usuários","Melhoria da experiência do usuário final"],"ru":["Редактирование файла prisma/seed.ts","Обновление льгот карт для всех пользователей","3-ступенчатый процесс для обеспечения согласованности","Совместимость с новыми и существующими пользователями","Улучшение опыта конечных пользователей"],"ar":["تحرير ملف prisma/seed.ts","تحديث فوائد البطاقة لجميع المستخدمين","عملية من 3 خطوات لضمان الاتساق","التوافق مع المستخدمين الجدد والقائمين","تحسين تجربة المستخدم النهائي"]},"keywords":{"en":["how to use update-card-benefits","update-card-benefits setup guide","update-card-benefits alternative","update-card-benefits vs CouponCycle","prisma seed ts update benefits","couponcycle update card benefits"],"zh":["更新卡片福利","AIエージェント工具","Prisma","信用卡福利","更新福利结构","更新卡片信息","AI工具","信用卡管理"],"ja":["クレジットカードの福利を更新","AIエージェント","Prisma","クレジットカードの福利","福利構造の更新","クレジットカード情報の更新","AIツール","クレジットカード管理"],"ko":["카드福利 업데이트","AI 에이전트 도구","Prisma","신용카드福利","福利 구조 업데이트","신용카드 정보 업데이트","AI工具","신용카드 관리"],"es":["actualizar beneficios de tarjetas","CouponCycle","prisma/seed.ts","usuarios nuevos y existentes","proceso de 3 pasos","Herramientas de Inteligencia Artificial","desarrollo de software","actualización de beneficios","tarjetas de crédito"],"fr":["mettre à jour les avantages des cartes","CouponCycle","prisma/seed.ts","utilisateurs nouveaux et existants","processus de 3 étapes","Outils d''Intelligence Artificielle","développement de logiciels","mise à jour des avantages","cartes de crédit"],"de":["Kartenleistungen aktualisieren","CouponCycle","prisma/seed.ts","neue und bestehende Benutzer","3-Schritte-Prozess","KI-Tools","Softwareentwicklung","Leistungen aktualisieren","Kreditkarten"],"pt":["update-card-benefits","atualizar benefícios de cartão","prisma/seed.ts","usuários novos e existentes","experiência do usuário final","ferramentas de IA","desenvolvimento de software","programação"],"ru":["update-card-benefits","обновление льгот карт","prisma/seed.ts","новые и существующие пользователи","опыт конечных пользователей","ИИ Агенты","разработка программного обеспечения","программирование"],"ar":["update-card-benefits","تحديث فوائد البطاقة","prisma/seed.ts","مستخدمين جدد وقائمين","تجربة المستخدم النهائي","أدوات الذكاء الاصطناعي","تطوير البرمجيات","البرمجة"]}},"owner":"fantasy-cc","repo":"credit-card-tracker","repoPath":"fantasy-cc/credit-card-tracker","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.493Z","topics":[],"category":"community","skillMd":{"name":"update-card-benefits","description":"Update, add, or remove benefits from existing credit cards in CouponCycle. Use when the user asks to update card benefits, add a new benefit to a card, remove a benefit, change benefit values, or mentions annual fee updates for cards like Amex Platinum, Chase Sapphire Reserve.","bodyPreview":"# Update Card Benefits in CouponCycle\n\nThis skill guides you through updating benefits for existing credit cards. This is a **3-step process** to ensure all users (new and existing) see the changes.\n\n## The Problem\n\nWhen you update benefits in `prisma/seed.ts`:\n- **New users** who add the card will see the changes\n- **Existing users** still have the old benefit structure\n\nThis skill ensures ALL users get the updates.\n\n## Recommended Workflow\n\n### Step 1: Edit the Seed File\n\nEdit `prisma/seed.ts`","body":"# Update Card Benefits in CouponCycle\n\nThis skill guides you through updating benefits for existing credit cards. This is a **3-step process** to ensure all users (new and existing) see the changes.\n\n## The Problem\n\nWhen you update benefits in `prisma/seed.ts`:\n- **New users** who add the card will see the changes\n- **Existing users** still have the old benefit structure\n\nThis skill ensures ALL users get the updates.\n\n## Recommended Workflow\n\n### Step 1: Edit the Seed File\n\nEdit `prisma/seed.ts` to add, remove, or modify benefits:\n\n```typescript\n{\n  name: ''American Express Platinum Card'',\n  issuer: ''American Express'',\n  annualFee: 895, // Update annual fee if changed\n  benefits: [\n    // Add new benefits\n    {\n      description: ''$100 Quarterly Resy Dining Credit'',\n      category: ''Dining'',\n      maxAmount: 100,\n      frequency: BenefitFrequency.QUARTERLY,\n      percentage: 0,\n      cycleAlignment: BenefitCycleAlignment.CALENDAR_FIXED,\n      occurrencesInCycle: 1,\n    },\n    // Keep existing benefits...\n  ],\n}\n```\n\n### Step 2: Update the Template\n\n```bash\nnpx prisma db seed\n```\n\nThis updates the predefined card template for new users.\n\n### Step 3: Run the Unified Update Script\n\n```bash\n# Preview changes (safe - no data modified)\nnode scripts/update-card-benefits.js --card \"Card Name\" --dry-run\n\n# Execute the update (migrates all existing users)\nnode scripts/update-card-benefits.js --card \"Card Name\" --force\n```\n\n## What the Script Does\n\nThe unified script automatically:\n\n1. Verifies the predefined card exists\n2. Finds all existing user cards for that card type\n3. **Smart diff-based migration:**\n   - Adds new benefits (preserves existing statuses)\n   - Updates changed benefits (keeps benefit IDs)\n   - Removes deprecated benefits\n4. Creates benefit status records (makes benefits visible)\n5. Uses transactions (rollback on failure)\n\n## Example Commands\n\n```bash\n# Update Amex Platinum\nnode scripts/update-card-benefits.js \\\n  --card \"American Express Platinum Card\" \\\n  --dry-run\n\n# Update Chase Sapphire Reserve\nnode scripts/update-card-benefits.js \\\n  --card \"Chase Sapphire Reserve\" \\\n  --force\n\n# Update Amex Business Platinum\nnode scripts/update-card-benefits.js \\\n  --card \"American Express Business Platinum Card\" \\\n  --force\n```\n\n## Alternative: Advanced Migration Framework\n\nFor complex migrations involving multiple cards or custom logic:\n\n```bash\n# 1. Create migration definition in scripts/migrate-benefits.js\n\n# 2. Validate migration\nnode scripts/validate-migration.js --migration-id=your-migration\n\n# 3. Preview changes\nnode scripts/migrate-benefits.js --migration-id=your-migration --dry-run\n\n# 4. Execute migration\nnode scripts/migrate-benefits.js --migration-id=your-migration --force\n```\n\n## Common Mistakes to Avoid\n\n### Mistake 1: Only Running Seed\n```bash\nnpx prisma db seed  # Only helps NEW users\n```\n\n### Mistake 2: Forgetting to Run Update Script\nWithout the update script, existing users won''t see the changes.\n\n### Correct Process\n```bash\nnpx prisma db seed  # Update template\nnode scripts/update-card-benefits.js --card \"Card Name\" --force\n```\n\n## Benefit Frequency Reference\n\n| Type | Enum | Description |\n|------|------|-------------|\n| Monthly | `BenefitFrequency.MONTHLY` | Resets every month |\n| Quarterly | `BenefitFrequency.QUARTERLY` | Resets every 3 months |\n| Yearly | `BenefitFrequency.YEARLY` | Resets once per year |\n| One-time | `BenefitFrequency.ONE_TIME` | Never resets |\n\n## Cycle Alignment Reference\n\n| Type | Enum | Description |\n|------|------|-------------|\n| Calendar Fixed | `BenefitCycleAlignment.CALENDAR_FIXED` | Fixed dates (Jan 1, Apr 1, etc.) |\n| Card Anniversary | `BenefitCycleAlignment.CARD_ANNIVERSARY` | Based on card opening date |\n\n## Semi-Annual Benefits Pattern\n\nFor benefits that reset twice a year (Jan-Jun, Jul-Dec), create TWO separate benefits:\n\n```typescript\n// First half: January - June\n{\n  description: ''$300 Hotel Credit (Jan-Jun)'',\n  frequency: BenefitFrequency.YEARLY,\n  cycleAlignment: BenefitCycleAlignment.CALENDAR_FIXED,\n  fixedCycleStartMonth: 1,\n  fixedCycleDurationMonths: 6,\n},\n// Second half: July - December\n{\n  description: ''$300 Hotel Credit (Jul-Dec)'',\n  frequency: BenefitFrequency.YEARLY,\n  cycleAlignment: BenefitCycleAlignment.CALENDAR_FIXED,\n  fixedCycleStartMonth: 7,\n  fixedCycleDurationMonths: 6,\n},\n```\n\n## Troubleshooting\n\n### \"Card not found\" Error\n- Check the exact card name in the database\n- Card names are case-sensitive\n\n### Users Not Seeing Benefits\n- Ensure benefit statuses were created\n- Users may need to refresh their browser\n\n### Migration Failed for Some Users\n- Check error messages in output\n- Re-run the script to retry failed users\n- Individual failures don''t affect other users\n\n## Safety Features\n\n- **Dry Run Mode**: Always test with `--dry-run` first\n- **Transaction Safety**: Changes rollback on failure\n- **Progress Tracking**: See which users were migrated\n- **Preserves Completed Status**: Existing completions are kept\n"},"lastSynced":"2026-03-08T02:10:09.311Z","agentAnalysis":{"suitability":{"en":"Ideal for Maintenance Agents requiring synchronized credit card benefit updates across user bases.","zh":"适合需要在用户群体中同步更新信用卡福利的维护代理。","ja":"ユーザーベース全体でクレジットカードの福利を同期して更新する必要があるメンテナンスエージェントに最適です。","ko":"사용자 기반 전체에서 신용 카드 혜택을 동기화하여 업데이트해야 하는 유지 보수 에이전트에 적합합니다.","es":"Ideal para Agentes de Mantenimiento que requieren actualizaciones de beneficios de tarjetas de crédito sincronizadas en bases de usuarios.","fr":"Idéal pour les Agents de Maintenance nécessitant des mises à jour de bénéfices de cartes de crédit synchronisées sur les bases d''utilisateurs.","de":"Ideal für Wartungsagenten, die synchronisierte Kreditkarten-Benefits-Updates über Benutzerbasen hinweg benötigen.","pt":"Ideal para Agentes de Manutenção que exigem atualizações de benefícios de cartão de crédito sincronizadas em bases de usuários.","ru":"Идеально для агентов обслуживания, требующих синхронизированных обновлений преимуществ кредитных карт в базах пользователей.","ar":"مثالي للوكلاء الصيانة الذين يتطلبون تحديثات مزايا بطاقة الائتمان المزامنة عبر قواعد بيانات المستخدمين."},"recommendation":{"en":"Empowers agents to uniformly update benefits for existing credit cards by editing the prisma/seed.ts file, ensuring consistency for both new and existing users through a 3-step process.","zh":"通过编辑prisma/seed.ts文件，统一更新现有信用卡的福利，确保新旧用户的一致性，通过3步过程。","ja":"prisma/seed.tsファイルを編集して、既存のクレジットカードの福利を統一的に更新し、新規および既存のユーザーに対する一貫性を確保する、3ステップのプロセスを通じて。","ko":"prisma/seed.ts 파일을 편집하여 기존 신용 카드의 혜택을 일관性 있게 업데이트하고, 3단계 프로세스를 통해 새로운 및 기존 사용자에 대한 일관성을 보장합니다.","es":"Habilita a los agentes a actualizar uniformemente los beneficios para tarjetas de crédito existentes editando el archivo prisma/seed.ts, garantizando la consistencia tanto para nuevos como para usuarios existentes a través de un proceso de 3 pasos.","fr":"Permet aux agents de mettre à jour de manière uniforme les bénéfices pour les cartes de crédit existantes en éditant le fichier prisma/seed.ts, assurant ainsi la cohérence à la fois pour les nouveaux et les utilisateurs existants via un processus en 3 étapes.","de":"Ermächtigt Agenten, die Vorteile für bestehende Kreditkarten einheitlich zu aktualisieren, indem sie die Datei prisma/seed.ts bearbeiten, wodurch die Konsistenz sowohl für neue als auch für bestehende Benutzer durch einen 3-Schritt-Prozess sichergestellt wird.","pt":"Habilita os agentes a atualizar uniformemente os benefícios para cartões de crédito existentes editando o arquivo prisma/seed.ts, garantindo consistência para novos e existentes usuários por meio de um processo de 3 etapas.","ru":"Наделяет агентов возможностью единообразно обновлять преимущества для существующих кредитных карт, редактируя файл prisma/seed.ts, обеспечивая последовательность как для новых, так и для существующих пользователей через 3-этапный процесс.","ar":"يمنح الوكلاء القدرة على تح