INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ripgraphics/authorsinfo/state-management-expert', 'state-management-expert', 'ripgraphics', 'authorsinfo', 'community', 'state-management-expert ripgraphics authorsinfo community The state-management-expert skill provides expertise in React state management patterns and libraries, benefiting developers working with complex component issues and performance optimization State Management Expert 是一个专门的 React 状态管理模式和库的专家，帮助开发者优化应用性能 State Management Expert は React 状態管理パターンとライブラリの専門家で、アプリケーションのパフォーマンスを最適化する State Management Expert는 React 상태 관리 패턴 및 라이브러리의 전문가로서 개발자가 애플리케이션 성능을 최적화하는 데 도움을 줍니다 El state-management-expert es un experto en patrones y bibliotecas de manejo de estado en React, como Redux, Zustand y React Query Le state-management-expert est un expert dans les modèles et les bibliothèques de gestion d''état en React, comme Redux, Zustand et React Query Der state-management-expert ist ein Experte für Muster und Bibliotheken zur Zustandsverwaltung in React, wie Redux, Zustand und React Query O State Management Expert é um especialista em padrões e bibliotecas de gestão de estado para React ИИ Агент State Management Expert является экспертом в области паттернов и библиотек управления состоянием для React خبير إدارة الحالة هو خبير في أنماط ومكتبات إدارة الحالة للتفاعل how to use state-management-expert state-management-expert vs Redux state-management-expert setup guide what is state-management-expert state-management-expert alternative React state management patterns state-management-expert install optimizing React performance with state-management-expert State Management Expert React 状态管理 AI 工具 状态管理解决方案 React 性能优化 Redux Zustand Jotai Recoil Recommends specialist experts for React component issues and performance profiling Detects environment setup using bash commands like grep and find Supports state management libraries including Redux, Zustand, Jotai, and Recoil Provides guidance on API data fetching using Rest API and React Query Analyzes package.json files for state management dependencies Identifies store and slice files in project directories state-management-expert is an AI agent skill specializing in React state management, providing recommendations for libraries like Redux, Zustand, and React Query');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ferryhinardi/supertool/new-tool-scaffolder', 'community', 'ferryhinardi', 'supertool', 'ferryhinardi/supertool', 'new-tool-scaffolder', 0, 0, 39, '2026-03-08T01:57:15.502Z', '2026-03-08T02:10:18.951Z', '60e05a98d55889a6ed757ced48ec2a37fb2a710f1f7d23872376e5f71227085c', '{"id":"ferryhinardi/supertool/new-tool-scaffolder","name":"new-tool-scaffolder","description":{"en":"The new-tool-scaffolder skill generates tool structures for Next.js 16 developers, utilizing Panda CSS and Vitest + Playwright. It benefits developers building browser-based tools within the SuperTool toolkit","zh":"new-tool-scaffolder 是一个 Next.js 16 和 React 19 开发工具包，用于创建和管理工具","ja":"new-tool-scaffolder は、AIエージェント開発を容易にする Next.js 16 と React 19 開発ツールキットです","ko":"new-tool-scaffolder는 Next.js 개발을 위한 도구를 생성하고 관리하는 Next.js 16 및 React 19 개발 도구입니다","es":"new-tool-scaffolder es una herramienta para crear herramientas personalizadas en SuperTool, un kit de desarrollo de Next.js 16 con React 19","fr":"new-tool-scaffolder est un outil pour créer des outils personnalisés dans SuperTool, un kit de développement Next.js 16 avec React 19","de":"new-tool-scaffolder ist ein Tool zum Erstellen benutzerdefinierter Tools in SuperTool, einem Next.js 16-Entwicklungstoolkit mit React 19","pt":"O new-tool-scaffolder é uma ferramenta de desenvolvimento para criar ferramentas personalizadas com Next.js 16 e React 19. Utiliza Panda CSS para estilização e Vitest para testes.","ru":"ИИ Агенты: new-tool-scaffolder - это инструмент для разработки индивидуальных инструментов с Next.js 16 и React 19. Использует Panda CSS для стилизации и Vitest для тестирования.","ar":"new-tool-scaffolder هو أداة تطوير لإنشاء أدوات مخصصة مع Next.js 16 و React 19. يستخدم Panda CSS للتنسيق و Vitest للاختبارات"},"seo":{"title":{"en":"new-tool-scaffolder: Next.js Toolkit Setup Guide | AI Age...