INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ferryhinardi/supertool/new-tool-scaffolder', 'new-tool-scaffolder', 'ferryhinardi', 'supertool', 'community', 'new-tool-scaffolder ferryhinardi supertool community The new-tool-scaffolder skill generates tool structures for Next.js 16 developers, utilizing Panda CSS and Vitest + Playwright. It benefits developers building browser-based tools within the SuperTool toolkit new-tool-scaffolder 是一个 Next.js 16 和 React 19 开发工具包，用于创建和管理工具 new-tool-scaffolder は、AIエージェント開発を容易にする Next.js 16 と React 19 開発ツールキットです new-tool-scaffolder는 Next.js 개발을 위한 도구를 생성하고 관리하는 Next.js 16 및 React 19 개발 도구입니다 new-tool-scaffolder es una herramienta para crear herramientas personalizadas en SuperTool, un kit de desarrollo de Next.js 16 con React 19 new-tool-scaffolder est un outil pour créer des outils personnalisés dans SuperTool, un kit de développement Next.js 16 avec React 19 new-tool-scaffolder ist ein Tool zum Erstellen benutzerdefinierter Tools in SuperTool, einem Next.js 16-Entwicklungstoolkit mit React 19 O new-tool-scaffolder é uma ferramenta de desenvolvimento para criar ferramentas personalizadas com Next.js 16 e React 19. Utiliza Panda CSS para estilização e Vitest para testes. ИИ Агенты: new-tool-scaffolder - это инструмент для разработки индивидуальных инструментов с Next.js 16 и React 19. Использует Panda CSS для стилизации и Vitest для тестирования. new-tool-scaffolder هو أداة تطوير لإنشاء أدوات مخصصة مع Next.js 16 و React 19. يستخدم Panda CSS للتنسيق و Vitest للاختبارات how to use new-tool-scaffolder new-tool-scaffolder setup guide new-tool-scaffolder alternative new-tool-scaffolder vs create-next-app new-tool-scaffolder install what is new-tool-scaffolder new-tool-scaffolder documentation new-tool-scaffolder tutorial new-tool-scaffolder and Next.js 16 new-tool-scaffolder with Vitest and Playwright new-tool-scaffolder Next.js 16 React 19 Panda CSS Vitest Playwright Vercel 工具开发 AI开发工具 Generates tool structures under `app/tools/<category>/<tool-slug>/` Utilizes Panda CSS for styling Leverages Vitest + Playwright for testing Supports deployment to Vercel Creates `page.tsx` main tool components with ''use client'' directive Follows Next.js 16 and React 19 standards new-tool-scaffolder is a toolkit for scaffolding new browser-based tools within the SuperTool project, utilizing Next.js 16 and React 19');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('frodeste/rubic2tripletex/convex-migration', 'community', 'frodeste', 'rubic2tripletex', 'frodeste/rubic2tripletex', 'convex-migration', 0, 0, 39, '2026-03-08T01:57:15.509Z', '2026-03-08T02:10:25.150Z', '8f01e252a73a493f99ca7ee51a32e85395bee333053fad5e31ad130ff1a14ab1', '{"id":"frodeste/rubic2tripletex/convex-migration","name":"convex-migration","description":{"en":"The convex-migration skill enables data integration between Rubic and Tripletex by migrating from Drizzle ORM to Convex as the backend database, benefiting developers working with Neon Postgres and Drizzle client.","zh":"Convex Migration 是一个用于将数据集成到 Rubic 和 Tripletex 的存储库，使用 Drizzle ORM 和 Neon Postgres 进行迁移","ja":"Convex Migration は、Rubic と Tripletex のデータを統合するためのリポジトリで、Drizzle ORM と Neon Postgres を使用した移行が含まれています","ko":"Convex Migration은 Rubic 및 Tripletex의 데이터를 통합하기 위한 저장소로 Drizzle ORM 및 Neon Postgres를 사용하여 마이그레이션합니다","es":"El proyecto convex-migration utiliza Drizzle ORM y Neon Postgres para la integración de datos entre Rubic y Tripletex.","fr":"Le projet convex-migration utilise Drizzle ORM et Neon Postgres pour l''intégration de données entre Rubic et Tripletex.","de":"Das Projekt convex-migration verwendet Drizzle ORM und Neon Postgres für die Datenintegration zwischen Rubic und Tripletex.","pt":"O Convex Migration é um projeto que visa migrar a integração de dados entre Rubic e Tripletex de Drizzle ORM para Convex, utilizando Drizzle ORM 0.45.x e Neon Postgres","ru":"Convex Migration - это проект, целью которого является миграция интеграции данных между Rubic и Tripletex с Drizzle ORM на Convex, используя Drizzle ORM 0.45.x и Neon Postgres для ИИ Агентов","ar":"هجرة Convex هو مشروع يهدف إلى هجرة تكامل البيانات بين Rubic و Tripletex من Drizzle ORM إلى Convex، باستخدام Drizzle ORM 0.45.x و Neon Postgres لأدوات الإی الأجنبیة"},"seo":{"title":{"en":"convex-migration: Drizzle ORM to Convex Setup Guide | AI ...","zh":"Convex Migration 设置指南 - 使用 Drizzle ORM 和 Neon Postgres","ja":"Convex Migration セットアップガイド - Drizzle ORM と Neon Postgres を使用","ko":"Convex Migration 설정 가이드 - Drizzle ORM 및 Neon Postgres 사용","es":"Convex Migration Setup Guide: Herramientas de AI para Int...","fr":"Guide de Migration Convex : Outils d''IA pour l''Intégratio...","de":"Convex-Migrations-Setup-Leitfaden: KI-Tools für Dateninte...","pt":"Guia de Migração Convex: Migrando de Drizzle ORM para Convex","ru":"Руководство по миграции Convex: ИИ Агенты для перехода с ...","ar":"دليل هجرة Convex: هجرة من Drizzle ORM إلى Convex باستخدام..."},"description":{"en":"Migrate from Drizzle ORM to Convex with ease. Learn how to integrate Convex as your backend database and discover the benefits of a seamless migration process.","zh":"了解如何使用 Convex Migration 将数据集成到 Rubic 和 Tripletex 中，包括 Drizzle ORM 和 Neon Postgres 的迁移","ja":"Convex Migration を使用して Rubic と Tripletex のデータを統合する方法を学びます。Drizzle ORM と Neon Postgres の移行を含みます","ko":"Convex Migration을 사용하여 Rubic 및 Tripletex의 데이터를 통합하는 방법을 알아보세요. Drizzle ORM 및 Neon Postgres의 마이그레이션 포함","es":"Migre su base de datos a Convex con nuestra guía paso a paso. Aprenda a integrar datos entre Rubic y Tripletex con herramientas de AI.","fr":"Migrez votre base de données vers Convex avec notre guide étape par étape. Découvrez comment intégrer des données entre Rubic et Tripletex avec des outils d''IA.","de":"Wandeln Sie Ihre Datenbank in Convex um, mit unserer Schritt-für-Schritt-Anleitung. Erfahren Sie, wie Sie Daten zwischen Rubic und Tripletex mit KI-Tools int...","pt":"Aprenda a migrar de Drizzle ORM para Convex com este guia passo a passo, incluindo dicas para integração com Neon Postgres e Drizzle Kit","ru":"Узнайте, как перейти с Drizzle ORM на Convex с помощью этого пошагового руководства, включая советы по интеграции с Neon Postgres и Drizzle Kit, для ИИ Агентов","ar":"تعلم كيفية الهجرة من Drizzle ORM إلى Convex باستخدام هذا الدليل الخطوة بخطوة، بما في ذلك نصائح للتكامل مع Neon Postgres و Drizzle Kit لأدوات الإی الأجنبیة"},"definition":{"en":"convex-migration is a repository that facilitates data integration between Rubic and Tripletex by providing a migration guide from Drizzle ORM to Convex.","zh":"Convex Migration 是一个 AIエージェント，用于将数据从 Drizzle ORM 和 Neon Postgres 迁移到 Convex","ja":"Convex Migration は、Drizzle ORM と Neon Postgres から Convex へのデータ移行を可能にする AIエージェントです","ko":"Convex Migration은 Drizzle ORM 및 Neon Postgres에서 Convex로의 데이터 마이그레이션을 가능하게 하는 AI 도구입니다","es":"Convex-migration es un proyecto de integración de datos que utiliza Drizzle ORM y Neon Postgres para migrar a Convex.","fr":"Convex-migration est un projet d''intégration de données qui utilise Drizzle ORM et Neon Postgres pour migrer vers Convex.","de":"Convex-Migration ist ein Datenintegrationsprojekt, das Drizzle ORM und Neon Postgres verwendet, um zu Convex zu migrieren.","pt":"O Convex Migration é um projeto de migração de banco de dados que utiliza Convex como backend","ru":"Convex Migration - это проект миграции базы данных, который использует Convex в качестве бэкенда для ИИ Агентов","ar":"هجرة Convex هو مشروع هجرة قاعدة البيانات الذي يستخدم Convex كخلفية لأدوات الإی الأجنبیة"},"features":{"en":["Migrates from Drizzle ORM 0.45.x to Convex","Supports Neon Postgres serverless database","Utilizes drizzle-kit for migrations","Manages schema with src/db/schema.ts","Integrates with Drizzle client via src/db/client.ts","Handles migrations with src/db/migrations/"],"zh":["使用 Drizzle ORM 0.45.x 进行数据迁移","支持 Neon Postgres 服务器端数据库","包含 4 个表的 schema 定义","使用 Convex 作为后端数据库","支持 enums 和复合主键","包含客户端和迁移脚本"],"ja":["Drizzle ORM 0.45.x を使用したデータ移行","Neon Postgres サーバーレスデータベースのサポート","4 つのテーブルの schema 定義を含む","Convex をバックエンドデータベースとして使用","列挙型と複合主キーをサポート","クライアントと移行スクリプトを含む"],"ko":["Drizzle ORM 0.45.x를 사용한 데이터 마이그레이션","Neon Postgres 서버리스 데이터베이스 지원","4개의 테이블 schema 정의 포함","Convex를 백엔드 데이터베이스로 사용","열거형 및 복합 기본 키 지원","클라이언트 및 마이그레이션 스크립트 포함"],"es":["Utiliza Drizzle ORM 0.45.x con drizzle-kit para migraciones","Soporte para Neon Postgres (servidor sin servidor)","Esquema de base de datos con 4 tablas y claves primarias compuestas","Cliente de Drizzle con conexión a Neon","Migraciones de base de datos con src/db/migrations/"],"fr":["Utilise Drizzle ORM 0.45.x avec drizzle-kit pour les migrations","Prise en charge de Neon Postgres (serveur sans serveur)","Schéma de base de données avec 4 tables et clés primaires composites","Client Drizzle avec connexion à Neon","Migrations de base de données avec src/db/migrations/"],"de":["Verwendet Drizzle ORM 0.45.x mit drizzle-kit für Migrationen","Unterstützung für Neon Postgres (Serverlos)","Datenbankschema mit 4 Tabellen und zusammengesetzten Primärschlüsseln","Drizzle-Client mit Neon-Verbindung","Datenbankmigrationen mit src/db/migrations/"],"pt":["Utiliza Drizzle ORM 0.45.x com Drizzle Kit para migrações","Suporta Neon Postgres como banco de dados","Inclui schema com 4 tabelas e chaves primárias compostas","Fornece client Drizzle com conexão Neon","Oferece migrações em src/db/migrations/"],"ru":["Использует Drizzle ORM 0.45.x с Drizzle Kit для миграций","Поддерживает Neon Postgres в качестве базы данных","Включает схему с 4 таблицами и составными первичными ключами","Предоставляет клиент Drizzle с подключением Neon","Предлагает миграции в src/db/migrations/ для ИИ Агентов"],"ar":["يستخدم Drizzle ORM 0.45.x مع Drizzle Kit لمهام الهجرة","يدعم Neon Postgres كقاعدة بيانات","يضم مخططًا مع 4 جداول ومفاتيح первية مركبة","يقدم عميل Drizzle مع اتصال Neon","يقدم مهام الهجرة في src/db/migrations/ لأدوات الإی الأجنبیة"]},"keywords":{"en":["convex-migration setup guide","drizzle orm to convex migration","neon postgres serverless database","convex backend database","how to use convex-migration","convex-migration vs drizzle orm","convex-migration install","convex-migration tutorial","convex-migration alternative","convex-migration documentation"],"zh":["Convex Migration","Drizzle ORM","Neon Postgres","数据迁移","AIエージェント","Convex 后端数据库","服务器端数据库","schema 定义","enums","复合主键"],"ja":["Convex Migration","Drizzle ORM","Neon Postgres","データ移行","AIエージェント","Convex バックエンドデータベース","サーバーレスデータベース","schema 定義","列挙型","複合主キー"],"ko":["Convex Migration","Drizzle ORM","Neon Postgres","데이터 마이그레이션","AI 도구","Convex 백엔드 데이터베이스","서버리스 데이터베이스","schema 정의","열거형","복합 기본 키"],"es":["convex migration","drizzle orm","neon postgres","integración de datos","migración de base de datos","herramientas de ai","rubix y tripletex","desarrollo de software"],"fr":["convex migration","drizzle orm","neon postgres","intégration de données","migration de base de données","outils d''ia","rubix et tripletex","développement de logiciels"],"de":["convex migration","drizzle orm","neon postgres","datenintegration","datenbankmigration","ki-tools","rubix und tripletex","softwareentwicklung"],"pt":["migração de banco de dados","Drizzle ORM","Convex","Neon Postgres","Drizzle Kit","migração de dados","integração de dados","Rubic","Tripletex"],"ru":["миграция базы данных","Drizzle ORM","Convex","Neon Postgres","Drizzle Kit","миграция данных","интеграция данных","Rubic","Tripletex","ИИ Агенты"],"ar":["هجرة قاعدة البيانات","Drizzle ORM","Convex","Neon Postgres","Drizzle Kit","هجرة البيانات","تكامل البيانات","Rubic","Tripletex","أدوات الإی الأجنبیة"]}},"owner":"frodeste","repo":"rubic2tripletex","repoPath":"frodeste/rubic2tripletex","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.509Z","topics":[],"category":"community","skillMd":{"name":"convex-migration","description":"Guide migration from the current Drizzle ORM / Neon Postgres stack to Convex. Use when the user asks about Convex, migrating the database, replacing Drizzle, or setting up Convex schema, functions, or queries. Provides schema translation, function patterns, and migration considerations specific to this project.","bodyPreview":"# Convex Migration Guide\n\nThis project currently uses **Drizzle ORM + Neon Postgres**. This skill guides migration to **Convex** as the backend database.\n\n## Current Stack (What We''re Migrating From)\n\n- **ORM:** Drizzle ORM 0.45.x with `drizzle-kit` for migrations\n- **Database:** Neon Postgres (serverless)\n- **Schema:** `src/db/schema.ts` -- 4 tables with enums, composite primary keys\n- **Client:** `src/db/client.ts` -- Drizzle client with Neon connection\n- **Migrations:** `src/db/migrations/` -","body":"# Convex Migration Guide\n\nThis project currently uses **Drizzle ORM + Neon Postgres**. This skill guides migration to **Convex** as the backend database.\n\n## Current Stack (What We''re Migrating From)\n\n- **ORM:** Drizzle ORM 0.45.x with `drizzle-kit` for migrations\n- **Database:** Neon Postgres (serverless)\n- **Schema:** `src/db/schema.ts` -- 4 tables with enums, composite primary keys\n- **Client:** `src/db/client.ts` -- Drizzle client with Neon connection\n- **Migrations:** `src/db/migrations/` -- SQL migration files\n\n### Current Tables\n\n| Table | Purpose | Key Fields |\n|-------|---------|------------|\n| `sync_state` | Tracks each sync run | serial PK, sync_type enum, status enum, timestamps |\n| `customer_mapping` | Rubic customerNo -> Tripletex customerId | composite PK (rubic_id, env), hash |\n| `product_mapping` | Rubic productCode -> Tripletex productId | composite PK (rubic_id, env), hash |\n| `invoice_mapping` | Rubic invoiceId -> Tripletex invoiceId | composite PK (rubic_id, env), payment_synced |\n\n### Current Enums\n\n- `sync_type`: `\"customers\" | \"products\" | \"invoices\" | \"payments\"`\n- `sync_status`: `\"running\" | \"success\" | \"failed\"`\n- `tripletex_env`: `\"sandbox\" | \"production\"`\n\n## Convex Equivalents\n\n### Schema Translation\n\nThe current Drizzle schema in `src/db/schema.ts` maps to Convex like this:\n\n```typescript\n// convex/schema.ts\nimport { defineSchema, defineTable } from \"convex/server\";\nimport { syncType, syncStatus, tripletexEnv } from \"./validators\";\n\nexport default defineSchema({\n\tsyncState: defineTable({\n\t\tsyncType: syncType,\n\t\ttripletexEnv: tripletexEnv,\n\t\tlastSyncAt: v.optional(v.number()), // epoch ms\n\t\tstatus: syncStatus,\n\t\terrorMessage: v.optional(v.string()),\n\t\trecordsProcessed: v.number(),\n\t\trecordsFailed: v.number(),\n\t\tstartedAt: v.number(), // epoch ms\n\t\tcompletedAt: v.optional(v.number()),\n\t})\n\t\t.index(\"by_type_and_env\", [\"syncType\", \"tripletexEnv\"])\n\t\t.index(\"by_status\", [\"status\"]),\n\n\tcustomerMapping: defineTable({\n\t\trubicCustomerNo: v.string(),\n\t\ttripletexEnv: tripletexEnv,\n\t\ttripletexCustomerId: v.number(),\n\t\tlastSyncedAt: v.number(),\n\t\thash: v.optional(v.string()),\n\t})\n\t\t.index(\"by_rubic_and_env\", [\"rubicCustomerNo\", \"tripletexEnv\"]),\n\n\tproductMapping: defineTable({\n\t\trubicProductCode: v.string(),\n\t\ttripletexEnv: tripletexEnv,\n\t\ttripletexProductId: v.number(),\n\t\tlastSyncedAt: v.number(),\n\t\thash: v.optional(v.string()),\n\t})\n\t\t.index(\"by_rubic_and_env\", [\"rubicProductCode\", \"tripletexEnv\"]),\n\n\tinvoiceMapping: defineTable({\n\t\trubicInvoiceId: v.number(),\n\t\ttripletexEnv: tripletexEnv,\n\t\trubicInvoiceNumber: v.number(),\n\t\ttripletexInvoiceId: v.number(),\n\t\tlastSyncedAt: v.number(),\n\t\tpaymentSynced: v.boolean(),\n\t})\n\t\t.index(\"by_rubic_and_env\", [\"rubicInvoiceId\", \"tripletexEnv\"]),\n});\n```\n\n### Key Translation Rules\n\n| Drizzle / Postgres | Convex |\n|--------------------|--------|\n| `serial(\"id\").primaryKey()` | Auto-generated `_id` (no serial IDs) |\n| `pgEnum(\"name\", [...])` | `v.union(v.literal(\"a\"), v.literal(\"b\"))` |\n| Composite primary key | `.index(\"name\", [\"field1\", \"field2\"])` + unique enforcement in mutations |\n| `timestamp({ withTimezone: true })` | `v.number()` (epoch ms via `Date.now()`) |\n| `varchar(\"col\", { length: N })` | `v.string()` (no length limits in Convex) |\n| `integer(\"col\")` | `v.number()` |\n| `boolean(\"col\")` | `v.boolean()` |\n| `text(\"col\")` | `v.string()` |\n| `.notNull()` | Field is required by default |\n| `.default(value)` | Set in mutation handler, not in schema |\n| `NULL` / nullable | `v.optional(v.string())` |\n\n### Function Patterns\n\nConvex replaces raw SQL / Drizzle queries with typed functions. Extract shared validators into a `convex/validators.ts` file so they can be reused across schema and functions:\n\n```typescript\n// convex/validators.ts\nimport { v } from \"convex/values\";\n\nexport const syncType = v.union(\n\tv.literal(\"customers\"),\n\tv.literal(\"products\"),\n\tv.literal(\"invoices\"),\n\tv.literal(\"payments\"),\n);\n\nexport const syncStatus = v.union(\n\tv.literal(\"running\"),\n\tv.literal(\"success\"),\n\tv.literal(\"failed\"),\n);\n\nexport const tripletexEnv = v.union(\n\tv.literal(\"sandbox\"),\n\tv.literal(\"production\"),\n);\n```\n\nUse these validators in function args for consistent type safety (not `v.string()`):\n\n**Query (read data):**\n\n```typescript\n// convex/syncState.ts\nimport { query } from \"./_generated/server\";\nimport { syncType, tripletexEnv } from \"./validators\";\n\nexport const getLatest = query({\n\targs: { syncType, tripletexEnv },\n\thandler: async (ctx, args) => {\n\t\treturn await ctx.db\n\t\t\t.query(\"syncState\")\n\t\t\t.withIndex(\"by_type_and_env\", (q) =>\n\t\t\t\tq.eq(\"syncType\", args.syncType).eq(\"tripletexEnv\", args.tripletexEnv),\n\t\t\t)\n\t\t\t.order(\"desc\")\n\t\t\t.first();\n\t},\n});\n```\n\n**Mutation (write data):**\n\n```typescript\n// convex/syncState.ts\nimport { mutation } from \"./_generated/server\";\nimport { syncType, tripletexEnv } from \"./validators\";\n\nexport const startSync = mutation({\n\targs: { syncType, tripletexEnv },\n\thandler: async (ctx, args) => {\n\t\treturn await ctx.db.insert(\"syncState\", {\n\t\t\tsyncType: args.syncType,\n\t\t\ttripletexEnv: args.tripletexEnv,\n\t\t\tstatus: \"running\",\n\t\t\trecordsProcessed: 0,\n\t\t\trecordsFailed: 0,\n\t\t\tstartedAt: Date.now(),\n\t\t});\n\t},\n});\n```\n\n**Action (external API calls):**\n\nSync logic that calls Rubic/Tripletex APIs should use actions, since they can call external services:\n\n```typescript\n// convex/sync.ts\nimport { action } from \"./_generated/server\";\nimport { api } from \"./_generated/api\";\nimport { tripletexEnv } from \"./validators\";\n\nexport const syncCustomers = action({\n\targs: { tripletexEnv },\n\thandler: async (ctx, args) => {\n\t\t// Call external APIs\n\t\tconst customers = await fetchFromRubic();\n\n\t\t// Write to Convex DB via mutations\n\t\tfor (const customer of customers) {\n\t\t\tawait ctx.runMutation(api.customerMapping.upsert, {\n\t\t\t\trubicCustomerNo: customer.customerNo,\n\t\t\t\ttripletexEnv: args.tripletexEnv,\n\t\t\t\t// ...\n\t\t\t});\n\t\t}\n\t},\n});\n```\n\n### Next.js Integration\n\n```typescript\n// In Server Components or Route Handlers\nimport { fetchQuery, fetchMutation } from \"convex/nextjs\";\nimport { api } from \"@/convex/_generated/api\";\n\n// Read\nconst state = await fetchQuery(api.syncState.getLatest, {\n\tsyncType: \"customers\",\n\ttripletexEnv: \"production\",\n});\n\n// Write\nawait fetchMutation(api.syncState.startSync, {\n\tsyncType: \"customers\",\n\ttripletexEnv: \"production\",\n});\n```\n\nRequires `NEXT_PUBLIC_CONVEX_URL` and `CONVEX_URL` environment variables.\n\n## Migration Steps\n\n1. **Install Convex:** `bun add convex` and `npx convex dev` to initialize\n2. **Create schema:** `convex/schema.ts` (see translation above)\n3. **Create functions:** `convex/*.ts` for queries, mutations, actions\n4. **Migrate data:** Write a one-time script to read from Neon and insert into Convex\n5. **Update API routes:** Replace Drizzle queries with Convex function calls\n6. **Update sync logic:** Move `src/sync/` orchestration to Convex actions\n7. **Remove Drizzle:** Remove `drizzle-orm`, `drizzle-kit`, `@neondatabase/serverless`, and `src/db/`\n\n## Key Differences to Keep in Mind\n\n- **No raw SQL** -- all data access is through Convex functions\n- **No migrations** -- schema changes are applied automatically by `npx convex dev` / `npx convex deploy`\n- **No connection pooling** -- Convex handles connections internally\n- **Composite uniqueness** -- enforce in mutation handlers (query by index, check existence), not at schema level\n- **Timestamps** -- use `Date.now()` (epoch ms) instead of SQL `TIMESTAMP WITH TIME ZONE`\n- **Realtime by default** -- Convex queries are reactive; the dashboard would get live sync status updates for free\n\n## Reference\n\n- [Convex Docs](https://docs.convex.dev/)\n- [Convex Schema Docs](https://docs.convex.dev/database/schemas)\n- [Convex Next.js Guide](https://docs.convex.dev/client/nextjs/app-router/)\n- [Convex Functions](https://docs.convex.dev/functions)\n"},"lastSynced":"2026-03-08T02:10:25.150Z","agentAnalysis":{"suitability":{"en":"Perfect for Database Migration Agents needing seamless transitions from Drizzle ORM to Convex with Neon Postgres support.","zh":"非常适合需要从 Drizzle ORM 到 Convex 的无缝过渡的数据库迁移代理，支持 Neon Postgres。","ja":"Drizzle ORM から Convex への無шов移行を必要とするデータベース移行エージェントに最適で、Neon Postgres をサポートしています。","ko":"Drizzle ORM에서 Convex로의無шов 전환을 필요로하는 데이터베이스 마이그레이션 에이전트에 적합하며, Neon Postgres를 지원합니다.","es":"Perfecto para Agentes de Migración de Base de Datos que necesitan transiciones sin problemas de Drizzle ORM a Convex con soporte de Neon Postgres.","fr":"Parfait pour les Agents de Migration de Base de Données nécessitant des transitions sans heurts de Drizzle ORM à Convex avec prise en charge de Neon Postgres.","de":"Perfekt für Datenbank-Migrationsagenten, die einen reibungslosen Übergang von Drizzle ORM zu Convex mit Neon-Postgres-Unterstützung benötigen.","pt":"Perfeito para Agentes de Migração de Banco de Dados que precisam de transições sem interrupções do Drizzle ORM para o Convex com suporte ao Neon Postgres.","ru":"Идеально подходит для агентов миграции баз данных, которым необходимы бесшовные переходы из Drizzle ORM в Convex с поддержкой Neon Postgres.","ar":"مثالي للوكلاء الذين يحتاجون إلى انتقالات دون انقطاع من Drizzle ORM إلى Convex مع دعم Neon Postgres."},"recommendation":{"en":"Empowers agents to migrate database backends from Drizzle ORM to Convex, leveraging Neon Postgres for serverless efficiency and utilizing Convex for enhanced data management capabilities, including schema migrations and client connections.","zh":"赋予代理从 Drizzle ORM 迁移到 Convex 的能力，利用 Neon Postgres 实现无服务器效率，并利用 Convex 实现增强的数据管理能力，包括架构迁移和客户端连接。","ja":"Drizzle ORM から Convex へのデータベースバックエンドの移行を可能にし、Neon Postgres を使用してサーバーレス効率を実現し、Convex を使用してスキーマ移行やクライアント接続などの強化されたデータ管理機能を実現します。","ko":"에이전트가 Drizzle ORM에서 Convex로 데이터베이스 백엔드를 마이그레이션 할 수 있도록 하며, Neon Postgres를 사용하여 서버리스 효율성을 실현하고, Convex를 사용하여 스키마 마이그레이션 및 클라이언트 연결과 같은 강화된 데이터 관리 기능을 제공합니다.","es":"Habilita a los agentes a migrar los backends de bases de datos de Drizzle ORM a Convex, aprovechando Neon Postgres para una eficiencia sin servidor y utilizando Convex para capacidades de gestión de datos mejoradas, incluidas migraciones de esquemas y conexiones de clientes.","fr":"Permet aux agents de migrer les backends de base de données de Drizzle ORM à Convex, en exploitant Neon Postgres pour une efficacité sans serveur et en utilisant Convex pour des capacités de gestion de données améliorées, notamment des migrations de schémas et des connexions clients.","de":"Ermächtigt Agenten, Datenbank-Backends von Drizzle ORM zu Convex zu migrieren, indem Neon Postgres für serverlose Effizienz genutzt und Convex für erweiterte Datenverwaltungsfähigkeiten eingesetzt wird, einschließlich Schemamigrationen und Clientverbindungen.","pt":"Habilita os agentes a migrar backends de banco de dados do Drizzle ORM para o Convex, aproveitando o Neon Postgres para eficiência sem servidor e utilizando o Convex para capacidades de gerenciamento de dados aprimoradas, incluindo migrações de esquema e conexões de cliente.","ru":"Наделяет агентов возможностью мигрировать бэкэнды баз данных из Drizzle ORM в Convex, используя Neon Postgres для серверной эффективности иConvex для улучшенных возможностей управления данными, включая миграции схемы и клиентские подключения.","ar":"يمنح الوكلاء القدرة على نقل خلفيات قواعد البيانات من Drizzle ORM إلى Convex، مستفيدًا من Neon Postgres للكفاءة بدون خادم واستخدام Convex لقدرات إدارة البيانات المحسنة، بما في ذلك هجرات مخطط وقنوات العميل."},"useCases":{"en":["Migrating Drizzle ORM databases to Convex","Integrating Convex with Neon Postgres for serverless database solutions","Updating Drizzle client configurations to work with Convex"],"zh":["从 Drizzle ORM 迁移到 Convex 的数据库","将 Convex 与 Neon Postgres 集成以实现无服务器数据库解决方案","更新 Drizzle 客户端配置以适用于 Convex"],"ja":["Drizzle ORM から Convex へのデータベースの移行","Convex と Neon Postgres を統合してサーバーレスデータベースソリューションを実現","Drizzle クライアントの構成を Convex で使用できるように更新"],"ko":["Drizzle ORM에서 Convex로의 데이터베이스 마이그레이션","Convex와 Neon Postgres를 통합하여 서버리스 데이터베이스 솔루션을 구현","Drizzle 클라이언트 구성 업데이트 Convex에서 사용"],"es":["Migrar bases de datos de Drizzle ORM a Convex","Integrar Convex con Neon Postgres para soluciones de bases de datos sin servidor","Actualizar configuraciones de clientes de Drizzle para que funcionen con Convex"],"fr":["Migrer des bases de données de Drizzle ORM à Convex","Intégrer Convex avec Neon Postgres pour des solutions de bases de données sans serveur","Mettre à jour les configurations de clients de Drizzle pour qu''elles fonctionnent avec Convex"],"de":["Datenbanken von Drizzle ORM zu Convex migrieren","Convex mit Neon Postgres für serverlose Datenbanklösungen integrieren","Drizzle-Client-Konfigurationen aktualisieren, um mit Convex zu funktionieren"],"pt":["Migrar bancos de dados Drizzle ORM para Convex","Integrar Convex com Neon Postgres para soluções de banco de dados sem servidor","Atualizar configurações de cliente Drizzle para funcionar com Convex"],"ru":["Мигрировать базы данных Drizzle ORM в Convex","Интегрировать Convex с Neon Postgres для серверных решений базы данных","Обновлять конфигурации клиента Drizzle для работы с Convex"],"ar":["نقل قواعد البيانات من Drizzle ORM إلى Convex","دمج Convex مع Neon Postgres لحلول قواعد البيانات بدون خادم","تحديث إعدادات العميل Drizzle للعمل مع Convex"]},"limitations":{"en":["Requires existing Drizzle ORM setup with Neon Postgres","Compatibility limited to Convex as the backend database"],"zh":["需要现有的 Drizzle ORM 设置并支持 Neon Postgres","仅限 Convex 作为后端数据库的兼容性"],"ja":["Neon Postgres をサポートする既存の Drizzle ORM 設定が必要","バックエンドデータベースとして Convex だけを使用した場合の互換性に限定"],"ko":["Neon Postgres를 지원하는 기존 Drizzle ORM 설정이 필요","백엔드 데이터베이스로 Convex만 사용한 경우의 호환성에 제한"],"es":["Requiere una configuración existente de Drizzle ORM con Neon Postgres","Compatibilidad limitada a Convex como base de datos de backend"],"fr":["Nécessite une configuration existante de Drizzle ORM avec Neon Postgres","Compatibilité limitée à Convex en tant que base de données de backend"],"de":["Benötigt eine bestehende Drizzle-ORM-Konfiguration mit Neon Postgres","Kompatibilität beschränkt auf Convex als Backend-Datenbank"],"pt":["Requer configuração existente do Drizzle ORM com Neon Postgres","Compatibilidade limitada ao Convex como banco de dados de backend"],"ru":["Требует наличия настроек Drizzle ORM с Neon Postgres","Совместимость ограничена только Convex в качестве базы данных бэкэнда"],"ar":["يتطلب إعدادات موجودة من Drizzle ORM مع Neon Postgres","التوافق محدود ب Convex كقاعدة بيانات خلفية"]},"version":4},"contentHash":"8f01e252a73a493f99ca7ee51a32e85395bee333053fad5e31ad130ff1a14ab1","qualityScore":39}');
