INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('frodeste/rubic2tripletex/convex-migration', 'convex-migration', 'frodeste', 'rubic2tripletex', 'community', 'convex-migration frodeste rubic2tripletex community The convex-migration skill enables data integration between Rubic and Tripletex by migrating from Drizzle ORM to Convex as the backend database, benefiting developers working with Neon Postgres and Drizzle client. Convex Migration 是一个用于将数据集成到 Rubic 和 Tripletex 的存储库，使用 Drizzle ORM 和 Neon Postgres 进行迁移 Convex Migration は、Rubic と Tripletex のデータを統合するためのリポジトリで、Drizzle ORM と Neon Postgres を使用した移行が含まれています Convex Migration은 Rubic 및 Tripletex의 데이터를 통합하기 위한 저장소로 Drizzle ORM 및 Neon Postgres를 사용하여 마이그레이션합니다 El proyecto convex-migration utiliza Drizzle ORM y Neon Postgres para la integración de datos entre Rubic y Tripletex. Le projet convex-migration utilise Drizzle ORM et Neon Postgres pour l''intégration de données entre Rubic et Tripletex. Das Projekt convex-migration verwendet Drizzle ORM und Neon Postgres für die Datenintegration zwischen Rubic und Tripletex. O Convex Migration é um projeto que visa migrar a integração de dados entre Rubic e Tripletex de Drizzle ORM para Convex, utilizando Drizzle ORM 0.45.x e Neon Postgres Convex Migration - это проект, целью которого является миграция интеграции данных между Rubic и Tripletex с Drizzle ORM на Convex, используя Drizzle ORM 0.45.x и Neon Postgres для ИИ Агентов هجرة Convex هو مشروع يهدف إلى هجرة تكامل البيانات بين Rubic و Tripletex من Drizzle ORM إلى Convex، باستخدام Drizzle ORM 0.45.x و Neon Postgres لأدوات الإی الأجنبیة convex-migration setup guide drizzle orm to convex migration neon postgres serverless database convex backend database how to use convex-migration convex-migration vs drizzle orm convex-migration install convex-migration tutorial convex-migration alternative convex-migration documentation Convex Migration Drizzle ORM Neon Postgres 数据迁移 AIエージェント Convex 后端数据库 服务器端数据库 schema 定义 enums 复合主键 Migrates from Drizzle ORM 0.45.x to Convex Supports Neon Postgres serverless database Utilizes drizzle-kit for migrations Manages schema with src/db/schema.ts Integrates with Drizzle client via src/db/client.ts Handles migrations with src/db/migrations/ convex-migration is a repository that facilitates data integration between Rubic and Tripletex by providing a migration guide from Drizzle ORM to Convex.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Nickzhan1001/AI-tools/powershell-windows', 'community', 'Nickzhan1001', 'AI-tools', 'Nickzhan1001/AI-tools', 'powershell-windows', 0, 0, 39, '2026-03-08T01:57:15.515Z', '2026-03-08T02:10:34.043Z', 'e902ee8d16b3fe50d8c53d7612fbfce4c97526ec4d069e7738e14bc9ae3acacb', '{"id":"Nickzhan1001/AI-tools/powershell-windows","name":"powershell-windows","description":{"en":"The powershell-windows skill provides critical patterns and pitfalls for Windows PowerShell, benefiting developers and administrators who want to optimize their scripting skills.","zh":"PowerShell Windows 是一种强大的命令行工具，掌握其语法规则和命令行最佳实践是开发人员的必备技能","ja":"PowerShell Windows は強力なコマンドラインツールであり、その構文ルールとコマンドラインのベストプラクティスをマスターすることは開発者の必須スキルです","ko":"PowerShell Windows는 강력한 명령어 툴로서, 그 구문 규칙과 명령어 최적의 프ラク티스를 마스터하는 것은 개발자의 필수 스킬입니다","es":"PowerShell Windows es una herramienta poderosa para la automatización y administración de sistemas","fr":"PowerShell Windows est un outil puissant pour l''automatisation et l''administration de systèmes","de":"PowerShell Windows ist ein leistungsfähiges Tool für die Automatisierung und Systemadministration","pt":"O PowerShell Windows é uma ferramenta poderosa para automação e gerenciamento de sistemas. Aprenda a usá-la com eficácia","ru":"PowerShell Windows - это мощный инструмент для автоматизации и управления системами. Узнайте, как им пользоваться эффективно","ar":"PowerShell Windows هو أداة قوية لتحكم وتنفيذ الأنظمة. تعرف على كيفية استخدامها بفعالية"},"seo":{"title":{"en":"powershell-windows: Mastering Critical Patterns and Pitfa...","zh":"PowerShell Windows 设置指南：语法规则和命令行最佳实践","ja":"PowerShell Windows のセットアップガイド：コマンドラインのベストプラクティスと AI エージェント","ko":"PowerShell Windows 설치 가이드: 명령어 구문 규칙 및 AI 툴 활용","es":"Guía de configuración de PowerShell Windows","fr":"Meilleures pratiques pour PowerShell Windows","de":"Einrichtungsleitfaden für PowerShell Windows","pt":"Guia de Configuração do PowerShell Windows: Melhores Prát...","ru":"ИИ Агенты для PowerShell Windows: Руководство по Настройке","ar":"دليل إعداد PowerShell Windows: إرشادات وأفضل الممارسات"},"description":{"en":"Unlock expert-level Windows PowerShell skills with critical patterns and pitfalls. Learn how to avoid common mistakes and optimize your scripts today!","zh":"了解 PowerShell Windows 的关键模式和陷阱，掌握语法规则和命令行最佳实践，提高开发效率","ja":"PowerShell Windows の重要なパターンと落とし穴を学び、ガイドラインとベストプラクティスをマスターして、開発効率を向上させる","ko":"PowerShell Windows의 중요 패턴과 함정을 학습하고, 가이드라인과 최적의 프ラク티스를 마스터하여 개발 효율성을 향상시키세요","es":"Aprende a utilizar PowerShell Windows de manera efectiva con nuestros consejos y trucos","fr":"Découvrez les meilleures pratiques pour utiliser PowerShell Windows avec succès","de":"Erfahren Sie, wie Sie PowerShell Windows optimal nutzen können","pt":"Aprenda a configurar e usar o PowerShell Windows com eficácia, seguindo as melhores práticas e padrões críticos","ru":"Узнайте, как настроить и использовать PowerShell Windows эффективно, следуя лучшим практикам и критическим шаблонам","ar":"تعرف على كيفية.config و استخدام PowerShell Windows بفعالية، باتباع الإرشادات وأفضل الممارسات"},"definition":{"en":"powershell-windows is a set of critical patterns and pitfalls for Windows PowerShell, focusing on operator syntax rules and Unicode restrictions.","zh":"PowerShell Windows 是一种为 Windows 操作系统设计的命令行 shell 和脚本语言","ja":"PowerShell Windows は Windows オペレーティングシステム向けのコマンドラインシェルおよびスクリプト言語です","ko":"PowerShell Windows는 윈도우 운영체제를 위한 명령어 셸 및 스크립트 언어입니다","es":"PowerShell Windows es un lenguaje de scripting y shell de comando para la administración de sistemas","fr":"PowerShell Windows est un langage de scripting et un shell de commande pour l''administration de systèmes","de":"PowerShell Windows ist eine Skript-Sprache und ein Kommando-Shell für die Systemadministration","pt":"O que é PowerShell Windows? É uma ferramenta de automação e gerenciamento de sistemas baseada em CLI","ru":"Что такое PowerShell Windows? Это инструмент автоматизации и управления системами на основе CLI","ar":"ما هو PowerShell Windows? هو أداة تحكم وتنفيذ الأنظمة باستخدام واجهة سطر الأوامر"},"features":{"en":["Enforces parentheses requirements for cmdlet calls with logical operators","Avoids Unicode and emoji restrictions in PowerShell scripts","Optimizes script syntax with correct operator usage","Provides examples of correct and incorrect syntax for common pitfalls","Improves script reliability with proper use of parentheses and logical operators"],"zh":["语法规则：逻辑运算符时括号的使用","命令行最佳实践：避免 Unicode 和 Emoji 字符","支持批量操作和脚本编写","集成 Windows 操作系统的功能","提供强大的调试和错误处理机制"],"ja":["構文ルール：論理演算子での括弧の使用","コマンドラインのベストプラクティス：Unicode と Emoji 文字の回避","バッチ処理とスクリプト作成のサポート","Windows オペレーティングシステムの機能との統合","強力なデバッグとエラー処理メカニズムの提供"],"ko":["구문 규칙: 논리 연산자에서의 괄호 사용","명령어 최적의 프ラク티스: 유니코드 및 이모지 문자의 회피","배치 처리 및 스크립트 작성의 지원","윈도우 운영체제의 기능과의 통합","강력한 디버깅 및 에러 처리 메커니즘의 제공"],"es":["Sintaxis de operadores con paréntesis obligatorios","Restricciones de Unicode y emojis","Uso de cmdlets con operadores lógicos","Patrones críticos para la administración de sistemas","Mejores prácticas para la automatización de tareas"],"fr":["Syntaxe des opérateurs avec parenthèses obligatoires","Restrictions d''Unicode et d''emojis","Utilisation de cmdlets avec opérateurs logiques","Modèles critiques pour l''administration de systèmes","Meilleures pratiques pour l''automatisation de tâches"],"de":["Syntaxregeln für Operatoren mit obligatorischen Klammern","Einschränkungen für Unicode und Emojis","Verwendung von Cmdlets mit logischen Operatoren","Kritische Muster für die Systemadministration","Best Practices für die Automatisierung von Aufgaben"],"pt":["Uso de parênteses obrigatórios em chamadas de cmdlets com operadores lógicos","Restrições de Unicode e Emoji no código","Suporte a operadores lógicos avançados","Integração com outros recursos do Windows","Compatibilidade com diferentes versões do Windows"],"ru":["Использование обязательных скобок в вызовах cmdlets с логическими операторами","Ограничения Unicode и Emoji в коде","Поддержка продвинутых логических операторов","Интеграция с другими возможностями Windows","Совместимость с разными версиями Windows"],"ar":["استخدام الأقواس الإلزامية في استدعاءات cmdlets مع مشغل المنطق","قيود Unicode و Emoji في الكود","دعم مشغل المنطق المتقدم","التكامل مع ميزات أخرى في Windows","التوافق مع إصدارات مختلفة من Windows"]},"keywords":{"en":["how to use powershell-windows","powershell-windows best practices","windows powershell scripting guide","powershell-windows vs bash","powershell-windows install and setup","mastering powershell-windows patterns and pitfalls"],"zh":["PowerShell Windows","命令行工具","语法规则","命令行最佳实践","Windows 操作系统","脚本语言","批量操作","调试和错误处理"],"ja":["PowerShell Windows","コマンドラインツール","構文ルール","コマンドラインのベストプラクティス","Windows オペレーティングシステム","スクリプト言語","バッチ処理","デバッグとエラー処理"],"ko":["PowerShell Windows","명령어 툴","구문 규칙","명령어 최적의 프ラク티스","윈도우 운영체제","스크립트 언어","배치 처리","디버깅 및 에러 처리"],"es":["PowerShell Windows","automatización de sistemas","administración de sistemas","lenguaje de scripting","shell de comando","cmdlets","operadores lógicos","Unicode","emojis"],"fr":["PowerShell Windows","automatisation de systèmes","administration de systèmes","langage de scripting","shell de commande","cmdlets","opérateurs logiques","Unicode","emojis"],"de":["PowerShell Windows","Automatisierung von Systemen","Systemadministration","Skript-Sprache","Kommando-Shell","Cmdlets","logische Operatoren","Unicode","Emojis"],"pt":["PowerShell Windows","configuração do PowerShell","melhores práticas do PowerShell","automatização de sistemas","gerenciamento de sistemas","CLI","operadores lógicos","Unicode","Emoji"],"ru":["PowerShell Windows","настройка PowerShell","лучшие практики PowerShell","автоматизация систем","управление системами","CLI","логические операторы","Unicode","Emoji","ИИ Агенты"],"ar":["PowerShell Windows","إعداد PowerShell","إرشادات PowerShell","تحكم وتنفيذ الأنظمة","automatização de sistemas","CLI","مشغل المنطق","Unicode","Emoji","أدوات الذكاء الاصطناعي"]}},"owner":"Nickzhan1001","repo":"AI-tools","repoPath":"Nickzhan1001/AI-tools","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.515Z","topics":[],"category":"community","skillMd":{"name":"powershell-windows","description":"PowerShell Windows patterns. Critical pitfalls, operator syntax, error handling.","bodyPreview":"# PowerShell Windows Patterns\n\n> Critical patterns and pitfalls for Windows PowerShell.\n\n---\n\n## 1. Operator Syntax Rules\n\n### CRITICAL: Parentheses Required\n\n| ❌ Wrong | ✅ Correct |\n|----------|-----------|\n| `if (Test-Path \"a\" -or Test-Path \"b\")` | `if ((Test-Path \"a\") -or (Test-Path \"b\"))` |\n| `if (Get-Item $x -and $y -eq 5)` | `if ((Get-Item $x) -and ($y -eq 5))` |\n\n**Rule:** Each cmdlet call MUST be in parentheses when using logical operators.\n\n---\n\n## 2. Unicode/Emoji Restriction\n\n### CRIT","body":"# PowerShell Windows Patterns\n\n> Critical patterns and pitfalls for Windows PowerShell.\n\n---\n\n## 1. Operator Syntax Rules\n\n### CRITICAL: Parentheses Required\n\n| ❌ Wrong | ✅ Correct |\n|----------|-----------|\n| `if (Test-Path \"a\" -or Test-Path \"b\")` | `if ((Test-Path \"a\") -or (Test-Path \"b\"))` |\n| `if (Get-Item $x -and $y -eq 5)` | `if ((Get-Item $x) -and ($y -eq 5))` |\n\n**Rule:** Each cmdlet call MUST be in parentheses when using logical operators.\n\n---\n\n## 2. Unicode/Emoji Restriction\n\n### CRITICAL: No Unicode in Scripts\n\n| Purpose | ❌ Don''t Use | ✅ Use |\n|---------|-------------|--------|\n| Success | ✅ ✓ | [OK] [+] |\n| Error | ❌ ✗ 🔴 | [!] [X] |\n| Warning | ⚠️ 🟡 | [*] [WARN] |\n| Info | ℹ️ 🔵 | [i] [INFO] |\n| Progress | ⏳ | [...] |\n\n**Rule:** Use ASCII characters only in PowerShell scripts.\n\n---\n\n## 3. Null Check Patterns\n\n### Always Check Before Access\n\n| ❌ Wrong | ✅ Correct |\n|----------|-----------|\n| `$array.Count -gt 0` | `$array -and $array.Count -gt 0` |\n| `$text.Length` | `if ($text) { $text.Length }` |\n\n---\n\n## 4. String Interpolation\n\n### Complex Expressions\n\n| ❌ Wrong | ✅ Correct |\n|----------|-----------|\n| `\"Value: $($obj.prop.sub)\"` | Store in variable first |\n\n**Pattern:**\n```\n$value = $obj.prop.sub\nWrite-Output \"Value: $value\"\n```\n\n---\n\n## 5. Error Handling\n\n### ErrorActionPreference\n\n| Value | Use |\n|-------|-----|\n| Stop | Development (fail fast) |\n| Continue | Production scripts |\n| SilentlyContinue | When errors expected |\n\n### Try/Catch Pattern\n\n- Don''t return inside try block\n- Use finally for cleanup\n- Return after try/catch\n\n---\n\n## 6. File Paths\n\n### Windows Path Rules\n\n| Pattern | Use |\n|---------|-----|\n| Literal path | `C:\\Users\\User\\file.txt` |\n| Variable path | `Join-Path $env:USERPROFILE \"file.txt\"` |\n| Relative | `Join-Path $ScriptDir \"data\"` |\n\n**Rule:** Use Join-Path for cross-platform safety.\n\n---\n\n## 7. Array Operations\n\n### Correct Patterns\n\n| Operation | Syntax |\n|-----------|--------|\n| Empty array | `$array = @()` |\n| Add item | `$array += $item` |\n| ArrayList add | `$list.Add($item) | Out-Null` |\n\n---\n\n## 8. JSON Operations\n\n### CRITICAL: Depth Parameter\n\n| ❌ Wrong | ✅ Correct |\n|----------|-----------|\n| `ConvertTo-Json` | `ConvertTo-Json -Depth 10` |\n\n**Rule:** Always specify `-Depth` for nested objects.\n\n### File Operations\n\n| Operation | Pattern |\n|-----------|---------|\n| Read | `Get-Content \"file.json\" -Raw | ConvertFrom-Json` |\n| Write | `$data | ConvertTo-Json -Depth 10 | Out-File \"file.json\" -Encoding UTF8` |\n\n---\n\n## 9. Common Errors\n\n| Error Message | Cause | Fix |\n|---------------|-------|-----|\n| \"parameter ''or''\" | Missing parentheses | Wrap cmdlets in () |\n| \"Unexpected token\" | Unicode character | Use ASCII only |\n| \"Cannot find property\" | Null object | Check null first |\n| \"Cannot convert\" | Type mismatch | Use .ToString() |\n\n---\n\n## 10. Script Template\n\n```powershell\n# Strict mode\nSet-StrictMode -Version Latest\n$ErrorActionPreference = \"Continue\"\n\n# Paths\n$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path\n\n# Main\ntry {\n    # Logic here\n    Write-Output \"[OK] Done\"\n    exit 0\n}\ncatch {\n    Write-Warning \"Error: $_\"\n    exit 1\n}\n```\n\n---\n\n> **Remember:** PowerShell has unique syntax rules. Parentheses, ASCII-only, and null checks are non-negotiable.\n"},"lastSynced":"2026-03-08T02:10:34.043Z","agentAnalysis":{"suitability":{"en":"Perfect for Windows Administration Agents needing advanced scripting and automation capabilities with PowerShell","zh":"非常适合需要使用PowerShell进行高级脚本编写和自动化的Windows管理代理","ja":"Windows管理エージェントがPowerShellを使用した高度なスクリプト作成と自動化の機能を必要とする場合に最適","ko":"PowerShell을 사용하여 고급 스크립팅 및 자동화를 필요한 Windows 관리 에이전트에 적합","es":"Perfecto para agentes de administración de Windows que necesitan capacidades de scripting y automatización avanzadas con PowerShell","fr":"Parfait pour les agents d''administration Windows nécessitant des capacités de scripting et d''automatisation avancées avec PowerShell","de":"Perfekt für Windows-Administrationsagenten, die erweiterte Skript- und Automatisierungsfunktionen mit PowerShell benötigen","pt":"Perfeito para agentes de administração do Windows que precisam de capacidades avançadas de script e automação com PowerShell","ru":"Идеально подходит для агентов администрирования Windows, которым требуются расширенные возможности скриптинга и автоматизации с помощью PowerShell","ar":"مثالي لعميل إدارة نظام التشغيل Windows الذي يحتاج إلى قدرات برمجة وتنفيذ متقدمة مع PowerShell"},"recommendation":{"en":"Empowers agents to write efficient and error-free PowerShell scripts using critical patterns and pitfalls, including proper operator syntax rules and Unicode/Emoji restrictions, ensuring seamless execution of cmdlets like Test-Path and Get-Item","zh":"使代理能够使用关键模式和陷阱编写高效且无错误的PowerShell脚本，包括正确的运算符语法规则和Unicode/Emoji限制，确保cmdlet如Test-Path和Get-Item的无缝执行","ja":"エージェントが重要なパターンと落とし