INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Nickzhan1001/AI-tools/powershell-windows', 'powershell-windows', 'Nickzhan1001', 'AI-tools', 'community', 'powershell-windows Nickzhan1001 AI-tools community The powershell-windows skill provides critical patterns and pitfalls for Windows PowerShell, benefiting developers and administrators who want to optimize their scripting skills. PowerShell Windows 是一种强大的命令行工具，掌握其语法规则和命令行最佳实践是开发人员的必备技能 PowerShell Windows は強力なコマンドラインツールであり、その構文ルールとコマンドラインのベストプラクティスをマスターすることは開発者の必須スキルです PowerShell Windows는 강력한 명령어 툴로서, 그 구문 규칙과 명령어 최적의 프ラク티스를 마스터하는 것은 개발자의 필수 스킬입니다 PowerShell Windows es una herramienta poderosa para la automatización y administración de sistemas PowerShell Windows est un outil puissant pour l''automatisation et l''administration de systèmes PowerShell Windows ist ein leistungsfähiges Tool für die Automatisierung und Systemadministration O PowerShell Windows é uma ferramenta poderosa para automação e gerenciamento de sistemas. Aprenda a usá-la com eficácia PowerShell Windows - это мощный инструмент для автоматизации и управления системами. Узнайте, как им пользоваться эффективно PowerShell Windows هو أداة قوية لتحكم وتنفيذ الأنظمة. تعرف على كيفية استخدامها بفعالية how to use powershell-windows powershell-windows best practices windows powershell scripting guide powershell-windows vs bash powershell-windows install and setup mastering powershell-windows patterns and pitfalls PowerShell Windows 命令行工具 语法规则 命令行最佳实践 Windows 操作系统 脚本语言 批量操作 调试和错误处理 Enforces parentheses requirements for cmdlet calls with logical operators Avoids Unicode and emoji restrictions in PowerShell scripts Optimizes script syntax with correct operator usage Provides examples of correct and incorrect syntax for common pitfalls Improves script reliability with proper use of parentheses and logical operators powershell-windows is a set of critical patterns and pitfalls for Windows PowerShell, focusing on operator syntax rules and Unicode restrictions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('andreaskelm/pm-brain/pm-brain-workflow', 'community', 'andreaskelm', 'pm-brain', 'andreaskelm/pm-brain', 'pm-brain-workflow', 0, 0, 39, '2026-03-08T01:57:15.517Z', '2026-03-08T02:10:35.893Z', '6ad6609520f03f2d01fc0c6446e60af97b8f9dc06f5657c157a8226a6a69728c', '{"id":"andreaskelm/pm-brain/pm-brain-workflow","name":"pm-brain-workflow","description":{"en":"The pm-brain-workflow skill helps product managers navigate and apply frameworks from the PM Brain repository, following a natural product development flow. It assists in braindumping, structuring thinking, and templating.","zh":"pm-brain-workflow是一种Git版本的产品管理系统，提供框架、指南、模板和游戏手册，帮助您将产品管理理论应用于日常执行","ja":"pm-brain-workflowは、AIエージェントを使用したプロダクト管理のためのフレームワーク、ガイド、テンプレート、プレイブックを提供するGitベースのプロダクト管理システムです","ko":"pm-brain-workflow는 Git 기반의 제품 관리 시스템으로, 프레임워크, 가이드, 템플릿, 플레이북 등을 제공하여 제품 관리 이론을 일상적인 실행에 적용하도록 도와줍니다","es":"pm-brain-workflow es un sistema de gestión de productos versionado con Git que proporciona frameworks, guías, plantillas y libros de juego para bridar la teoría y la ejecución diaria","fr":"pm-brain-workflow est un système de gestion de produits versionné Git qui fournit des frameworks, des guides, des modèles et des livres de jeu pour relier la théorie et l''exécution quotidienne","de":"pm-brain-workflow ist ein Git-versioniertes Produktmanagement-System, das Frameworks, Anleitungen, Vorlagen und Playbooks zur Brücke zwischen Theorie und täglicher Ausführung bietet","pt":"O pm-brain-workflow é um sistema de gerenciamento de produtos baseado em Git que fornece frameworks, guias e templates para ajudar no desenvolvimento de produtos. Ele segue um fluxo de trabalho natural de desenvolvimento de produtos.","ru":"ИИ Агент pm-brain-workflow - это система управления продуктами на основе Git, которая предоставляет фреймворки, руководства и шаблоны для помощи в разработке продуктов. Она следует естественному потоку работы разработки продуктов","ar":"pm-brain-workflow هو نظام إدارة المنتجات القائم على Git الذي يوفر الإطارات و الدلائل و القوالب لمساعدتك في تطوير المنتجات. يتبع نظامًا طبيعيًا لتدفق العمل في تطوير المنتجات"},"seo":{"title":{"en":"pm-brain-workflow: Git-Versioned Product Management Setup...","zh":"pm-brain-workflow.Setup Guide: Git版本产品管理系统","ja":"pm-brain-workflowベストプラクティス: AIエージェントによるプロダクト管理","ko":"pm-brain-workflow 설정 가이드: Git 기반 제품 관리 시스템","es":"Guía de configuración de pm-brain-workflow: Flujo de trab...","fr":"Guide de mise en place de pm-brain-workflow: Système de g...","de":"Einrichtungsleitfaden für pm-brain-workflow: Git-versioni...","pt":"Guia de Configuração do pm-brain-workflow: Fluxo de Traba...","ru":"Настройка ИИ Агента pm-brain-workflow: Система Управления...","ar":"دليل إعداد pm-brain-workflow: نظام إدارة المنتجات المتقدم"},"description":{"en":"Unlock efficient product development with pm-brain-workflow. Discover how to bridge PM theory and execution with Git-versioned frameworks, guides, and templa...","zh":"了解pm-brain-workflow的功能和特点，包括框架、指南、模板和游戏手册，帮助您桥接产品管理理论和日常执行","ja":"pm-brain-workflowの機能と特徴を紹介します。AIエージェントを使用したプロダクト管理のためのフレームワーク、ガイド、テンプレート、プレイブックなど","ko":"pm-brain-workflow의 기능과 특징을 소개합니다. Git 기반의 제품 관리 시스템을 위한 프레임워크, 가이드, 템플릿, 플레이북 등","es":"Descubre cómo pm-brain-workflow te ayuda a navegar y aplicar frameworks de gestión de productos con una secuencia de desarrollo natural","fr":"Découvrez comment pm-brain-workflow vous aide à naviguer et à appliquer des frameworks de gestion de produits avec une séquence de développement naturelle","de":"Erfahren Sie, wie pm-brain-workflow Ihnen hilft, Frameworks für das Produktmanagement zu navigieren und anzuwenden, mit einer natürlichen Entwicklungssequenz","pt":"Aprenda a configurar o pm-brain-workflow, um sistema de gerenciamento de produtos baseado em Git, com frameworks, guias e templates para ajudar no desenvolvi...","ru":"Узнайте, как настроить ИИ Агент pm-brain-workflow, систему управления продуктами на основе Git, с фреймворками, руководствами и шаблонами для помощи в разраб...","ar":"تعرف على كيفية إعداد pm-brain-workflow، نظام إدارة المنتجات القائم على Git، مع الإطارات و الدلائل و القوالب لمساعدتك في تطوير المنتجات"},"definition":{"en":"pm-brain-workflow is a Git-versioned product management system that provides frameworks, guides, templates, and playbooks to bridge product management theory and day-to-day execution.","zh":"pm-brain-workflow是一种Git版本的产品管理系统，提供框架、指南、模板和游戏手册","ja":"pm-brain-workflowは、AIエージェントを使用したプロダクト管理のためのフレームワーク、ガイド、テンプレート、プレイブックを提供するシステムです","ko":"pm-brain-workflow는 Git 기반의 제품 관리 시스템으로, 프레임워크, 가이드, 템플릿, 플레이북 등을 제공합니다","es":"pm-brain-workflow es un agente de IA que proporciona un flujo de trabajo de gestión de productos para ayudar a los desarrolladores a organizar y estructurar su pensamiento","fr":"pm-brain-workflow est un agent IA qui fournit un flux de travail de gestion de produits pour aider les développeurs à organiser et à structurer leur pensée","de":"pm-brain-workflow ist ein KI-Agent, der einen Workflow für das Produktmanagement bereitstellt, um Entwicklern zu helfen, ihre Gedanken zu organisieren und zu strukturieren","pt":"O pm-brain-workflow é um sistema de gerenciamento de produtos que combina teoria e prática para ajudar no desenvolvimento de produtos","ru":"ИИ Агент pm-brain-workflow - это система управления продуктами, которая объединяет теорию и практику для помощи в разработке продуктов","ar":"pm-brain-workflow هو نظام إدارة المنتجات الذي يجمع بين النظرية و التطبيق لمساعدتك في تطوير المنتجات"},"features":{"en":["Braindump feature to get all raw thoughts out","Structure thinking using framework prompts to organize","Apply formal templates after structuring thoughts","Follows a natural product development sequence","Utilizes the PM Brain repository for frameworks and guides","Supports Git-versioned product management systems"],"zh":["框架、指南、模板和游戏手册","Git版本控制","产品管理理论和日常执行的桥接","Braindump、结构化思考和模板应用","自然产品开发流程"],"ja":["フレームワーク、ガイド、テンプレート、プレイブック","Gitベースのバージョン管理","プロダクト管理理論と日常的な実行の橋渡し","ブレインダンプ、構造化思考、テンプレート適用","自然なプロダクト開発フロー"],"ko":["프레임워크, 가이드, 템플릿, 플레이북","Git 기반 버전 관리","제품 관리 이론과 일상적인 실행의 연결","브레인덤프, 구조화된思考, 템플릿 적용","자연적인 제품 개발 과정"],"es":["Braindump para recopilar pensamientos raw","Estructuración del pensamiento con prompts de framework","Aplicación de plantillas formales","Secuencia de desarrollo natural","Integración con Git para versionar el sistema de gestión de productos","Flujo de trabajo de gestión de productos personalizable"],"fr":["Braindump pour collecter les pensées raw","Structuration de la pensée avec des prompts de framework","Application de modèles formels","Séquence de développement naturelle","Intégration avec Git pour versionner le système de gestion de produits","Flux de travail de gestion de produits personnalisable"],"de":["Braindump, um Rohgedanken zu sammeln","Strukturierung des Denkens mit Framework-Prompts","Anwendung formalen Vorlagen","Natürliche Entwicklungssequenz","Integration mit Git, um das Produktmanagement-System zu versionieren","Anpassbarer Workflow für das Produktmanagement"],"pt":["Fluxo de trabalho natural de desenvolvimento de produtos","Frameworks e guias para organizar o pensamento","Templates para ajudar na estruturação de projetos","Sistema baseado em Git para controle de versão","Braindump para registrar ideias e pensamentos","Estrutura de pensamento para organizar e priorizar tarefas"],"ru":["Естественный поток работы разработки продуктов","Фреймворки и руководства для организации мыслей","Шаблоны для помощи в структурировании проектов","Система на основе Git для контроля версий","Брейндамп для регистрации идей и мыслей","Структура мыслей для организации и приоритизации задач"],"ar":["نظام تدفق العمل الطبيعي لتطوير المنتجات","الإطارات و الدلائل لت组织 الأفكار","القوالب لمساعدتك في هيكلة المشاريع","نظام قائم على Git للسيطرة على الإصدارات","برين دامب لتسجيل الأفكار و الأفكار","هيكلة الأفكار لت组织 و تحديد الأولويات لل المهام"]},"keywords":{"en":["how to use pm-brain-workflow","pm-brain-workflow setup guide","pm-brain-workflow alternative","product management workflow","git-versioned product management","pm-brain-workflow install","pm-brain-workflow vs asana","what is pm-brain-workflow","pm-brain-workflow tutorial"],"zh":["pm-brain-workflow","产品管理系统","Git版本控制","AI工具","产品管理理论","日常执行","框架、指南、模板","自然产品开发流程"],"ja":["pm-brain-workflow","プロダクト管理システム","Gitベースのバージョン管理","AIエージェント","プロダクト管理理論","日常的な実行","フレームワーク、ガイド、テンプレート","自然なプロダクト開発フロー"],"ko":["pm-brain-workflow","제품 관리 시스템","Git 기반 버전 관리","AI 도구","제품 관리 이론","일상적인 실행","프레임워크, 가이드, 템플릿","자연적인 제품 개발 과정"],"es":["pm-brain-workflow","gestión de productos","frameworks de gestión de productos","git versionado","flujo de trabajo de gestión de productos","agentes de IA para desarrolladores","herramientas de IA para gestión de productos","desarrollo de productos","organización de pensamiento","estructuración de pensamiento"],"fr":["pm-brain-workflow","gestion de produits","frameworks de gestion de produits","git versionné","flux de travail de gestion de produits","agents IA pour développeurs","outils IA pour gestion de produits","développement de produits","organisation de la pensée","structuration de la pensée"],"de":["pm-brain-workflow","Produktmanagement","Frameworks für das Produktmanagement","Git-versioniert","Workflow für das Produktmanagement","KI-Agenten für Entwickler","KI-Tools für Produktmanagement","Produktentwicklung","Gedankenorganisation","Gedankenstrukturierung"],"pt":["pm-brain-workflow","gerenciamento de produtos","desenvolvimento de produtos","fluxo de trabalho","frameworks","guias","templates","sistema baseado em Git","controle de versão"],"ru":["ИИ Агент pm-brain-workflow","управление продуктами","разработка продуктов","поток работы","фреймворки","руководства","шаблоны","система на основе Git","контроль версий"],"ar":["pm-brain-workflow","نظام إدارة المنتجات","تطوير المنتجات","نظام تدفق العمل","الإطارات","الدلائل","القوالب","نظام قائم على Git","السيطرة على الإصدارات"]}},"owner":"andreaskelm","repo":"pm-brain","repoPath":"andreaskelm/pm-brain","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.517Z","topics":[],"category":"community","skillMd":{"name":"pm-brain-workflow","description":"Guide product managers through PM workflows using the PM Brain framework library. Use when working on product management tasks, braindumping ideas, assessing opportunities, writing PRDs, conducting research, or planning strategy. Supports thinking-first approach before jumping to templates.","bodyPreview":"# PM Brain Workflow Assistant\n\nThis skill helps you navigate and apply product management frameworks from the PM Brain repository following a natural product development flow.\n\n## Core Principle: Think First, Template Later\n\nBefore jumping to templates, help users:\n1. **Braindump** - Get all raw thoughts out\n2. **Structure thinking** - Use framework prompts to organize\n3. **Template** - Only then apply formal templates\n\n## Framework Flow\n\nThe PM Brain follows a natural product development sequen","body":"# PM Brain Workflow Assistant\n\nThis skill helps you navigate and apply product management frameworks from the PM Brain repository following a natural product development flow.\n\n## Core Principle: Think First, Template Later\n\nBefore jumping to templates, help users:\n1. **Braindump** - Get all raw thoughts out\n2. **Structure thinking** - Use framework prompts to organize\n3. **Template** - Only then apply formal templates\n\n## Framework Flow\n\nThe PM Brain follows a natural product development sequence:\n\n```\n2.0 Foundations → 2.1 Strategy → 2.2 Discovery → 2.3 Execution → 2.4 Communication\n(HOW TO THINK)  (WHERE TO GO?)  (WHAT TO BUILD?) (BUILD & SHIP)  (KEEP ALIGNED)\n```\n\n**When user is:**\n- Early/exploring → Point to **2.0 Foundations** and **2.1 Strategy**\n- Has a problem → Guide to **2.2 Discovery**\n- Ready to build → Move to **2.3 Execution**\n- Throughout → Support with **2.4 Communication**\n\n## Quick Framework Locations\n\n### 2.0 Foundations (How to Think)\n- Mental Models: `02-Methods-and-Tools/2.0-Foundations/2.0.1-Mental-Models/`\n- Bias Awareness: `02-Methods-and-Tools/2.0-Foundations/2.0.2-Bias/`\n- Self-Reflection: `02-Methods-and-Tools/2.0-Foundations/2.0.3-Self-Reflection/`\n\n### 2.1 Strategy (Where are we going?)\n- Strategic Foundations: `02-Methods-and-Tools/2.1-Strategy/2.1.1-Strategic-Foundations/`\n- OKRs: `02-Methods-and-Tools/2.1-Strategy/2.1.2-Strategic-Execution/1-OKR/`\n- Roadmaps: `02-Methods-and-Tools/2.1-Strategy/2.1.2-Strategic-Execution/2-Roadmap/`\n- North Star: `02-Methods-and-Tools/2.1-Strategy/2.1.2-Strategic-Execution/3-North-Star/`\n- Prioritization: `02-Methods-and-Tools/2.1-Strategy/2.1.2-Strategic-Execution/4-Prioritization/`\n\n### 2.2 Discovery (What to build?)\n- Research Interviews: `02-Methods-and-Tools/2.2-Discovery/2.2.1-Research-Interviews/`\n- Continuous Discovery: `02-Methods-and-Tools/2.2-Discovery/2.2.2-Continuous-Discovery-Habits/`\n- Jobs-to-be-Done: `02-Methods-and-Tools/2.2-Discovery/2.2.3-Jobs-To-Be-Done/`\n- Opportunity Assessment: `02-Methods-and-Tools/2.2-Discovery/2.2.4-Opportunity-Assessment/`\n- Problem-Solution Space: `02-Methods-and-Tools/2.2-Discovery/2.2.6-Problem-Solution-Space/`\n\n### 2.3 Execution (Build, ship, measure)\n- Daily Rituals: `02-Methods-and-Tools/2.3-Execution/2.3.1-Daily-Execution-And-Rituals/`\n- User Stories: `02-Methods-and-Tools/2.3-Execution/2.3.2-User-Stories/`\n- PRDs: `02-Methods-and-Tools/2.3-Execution/2.3.4-PRD/`\n- Personas: `02-Methods-and-Tools/2.3-Execution/2.3.5-Personas/`\n- Metrics: `02-Methods-and-Tools/2.3-Execution/2.3.6-Metrics/`\n\n### 2.4 Communication (Keep aligned)\n- Newsletters: `02-Methods-and-Tools/2.4-Communication/2.4.1-Newsletter/`\n- One-Pagers: `02-Methods-and-Tools/2.4-Communication/2.4.3-One-Pagers/`\n- Stakeholder Management: `02-Methods-and-Tools/2.4-Communication/2.4.7-Stakeholder-Management/`\n- Saying No: `02-Methods-and-Tools/2.4-Communication/2.4.6-Saying-No/`\n- Politics & organization survival: use the `politics-coach` skill with `01-Company-Context/1.1-Stakeholder-Avatars/` (person-level avatars) and `01-Company-Context/1.2-Organization-Survival/` (system-level politics: power map, alliances, red flags) when stakeholder problems are clearly political, not just about message shape.\n\n## Typical File Patterns\n\nMost framework folders follow this structure:\n- `1-*-framework.md` - Guide explaining the framework\n- `2-*-template.md` - Template to fill out\n- `3-*-evaluation.md` - Assessment criteria\n\n## Braindumping Workflow\n\nWhen a user wants to work on something or is thinking/braindumping (the agent is in **product_sense**): **apply the golden rule from `PRODUCT-SENSE-RULES.md`** (braindump before structure), including the \"braindump sufficient\" checklist. Use prompts from `02-Methods-and-Tools/2.0-Foundations/2.0.1-Mental-Models/6-Product-Sense-Development/2-product-sense-prompts.md` for the relevant context (PRD, prioritization, strategy, research, stuck).\n\n1. **Listen and probe**\n   - Ask if the user has added (or should add) relevant context from [01-Company-Context/](../../../../01-Company-Context/README.md), [03-Research-Artifacts/](../../../../03-Research-Artifacts/README.md), or [04-Initiatives/](../../../../04-Initiatives/README.md); having it in the conversation speeds up thinking.\n   - What''s the core problem or opportunity?\n   - What stage are they at? (ideation, validation, building, shipping)\n   - What constraints exist?\n\n2. **Guide exploration** (do not suggest templates yet)\n   - Use prompts from `2-product-sense-prompts.md` to surface assumptions and blind spots\n   - Ask clarifying questions from the relevant framework\n   - Help organize scattered thoughts only after raw thinking is out\n\n3. **Suggest framework** (only after braindump / when leaving product_sense into execution_mode)\n   - Match their need to the right framework location\n   - Show the framework guide first (1-*-framework.md)\n   - Only then point to the template (2-*-template.md)\n\n## Modes & evals\n\n- **product_sense** → braindump, prompts, no framework until sufficient. **execution_mode** → structure + framework/template (or template-finder path). **meta_reflection** → after substantial conversations: suggest `00-Meta/` (log, forecast, learning), optionally Level 2 checklist ([.cursor/evals/](../../../../.cursor/evals/README.md)), and rule updates (`.cursor/rules/thinking.mdc`). Full routing and states: [ORCHESTRATION.md](../../../../ORCHESTRATION.md).\n- **Signal mode transitions** in natural language when switching (per [AGENTS.md](../../../../AGENTS.md) and [ORCHESTRATION.md](../../../../ORCHESTRATION.md)); e.g. \"We''ve got enough to structure this—here''s the framework that fits…\"\n- **Evals** are a separate workflow, not a conversation mode: Level 1 (artifact quality) lives in `02-Methods-and-Tools/` and the agent uses Quick Quality Checks per `.cursor/rules/evaluation-orchestration.mdc` when creating supported frameworks; Level 2 (agent behavior) lives in [.cursor/evals/](../../../../.cursor/evals/README.md). See ORCHESTRATION.md → Eval Checkpoints. You may suggest the Level 2 checklist in meta_reflection; the user runs evals when they choose.\n\n## Common Scenarios\n\n### \"I have an idea\"\n→ Start with **Discovery** (use `discovery-research` skill):\n- Problem-Solution Space to separate problem from solution\n- Jobs-to-be-Done to understand user needs\n- Opportunity Assessment to evaluate viability\n\n### \"I need to prioritize features\"\n→ Go to **Strategy** (use `strategy-planning` skill):\n- Prioritization frameworks (RICE, Value/Effort, MoSCoW)\n- Strategic Foundations for alignment with goals\n\n### \"I need to write a PRD\"\n→ Check in **Execution**:\n- Before touching templates, ask **2–3 lightweight preflight questions** (why this/why now, know vs guess, who it’s for) and a **context/memory check**, for example:\n  - \"Why this, why now?\"\n  - \"What do you already know vs what are you guessing?\"\n  - \"Who is this primarily for to read and approve?\"\n  - \"Do you want to anchor this in any existing strategy/initiative/research, or keep this PRD self-contained for now?\"\n- PRD templates and guides\n- User Stories for requirements\n- Metrics for success criteria\n\n### \"How do I convince stakeholders?\"\n→ Look in **Communication** (use `stakeholder-management` skill; add `politics-coach` when dynamics are clearly political):\n- One-Pagers for executive summaries\n- Stakeholder Management strategies\n- Saying No frameworks for managing requests\n\n### \"I''m stuck / not sure how to think about this\"\n→ Start with **Foundations**:\n- Mental Models for frameworks\n- Bias awareness for blind spots\n- Self-Reflection for clarity\n\n### \"I''m overwhelmed with requests\"\n→ Treat this as an **overwhelm / paralysis** case:\n- First, acknowledge the feeling and keep cognitive load low.\n- Ask **at most 1–2 gentle questions** to narrow, for example: \"What’s one thing that, if you made a bit of progress on it this week, would make you feel less stuck?\"\n- Help the user choose a **tiny, concrete next step** (e.g. \"open the first onboarding email and jot 3 bullets on what feels off\") instead of introducing mini‑frameworks.\n- Make explicit that **they choose**: \"You choose the smallest step that feels doable; I’ll help you shape it.\"\n\n### \"Am I improving? / How do I track my judgment?\"\n→ Point to **00-Meta**:\n- **Product Judgment Test**: `00-Meta/0.3-Product-Judgment-Test/` – log forecasts (prediction + confidence %) *before* shipping, resolve when data is in, track Weighted Brier Score for calibration\n- Learning log and growth portfolio: `00-Meta/0.1-Learning-Log/`, `00-Meta/0.2-Growth-Portfolio/`\n\n## Response Guidelines\n\n1. **Always cite source paths** - e.g., \"From `02-Methods-and-Tools/2.3-Execution/2.3.4-PRD/2-prd-template.md`\"\n\n2. **Read files before suggesting** - Don''t guess what''s in a framework; read it first\n\n3. **Think → Structure → Template** - Never jump straight to templates\n\n4. **Follow the flow** - Respect the natural progression (Foundations → Strategy → Discovery → Execution → Communication)\n\n5. **Cross-reference related frameworks** - PMs benefit from connecting concepts\n\n6. **Be actionable** - Point to specific next steps, not just information\n\n## Storage Locations\n\n- **Personal practice & evidence**: `00-Meta/` (daily log, learning log, growth portfolio, Product Judgment Test)\n- **Company context**: `01-Company-Context/`\n- **Methods & frameworks**: `02-Methods-and-Tools/`\n- **Research artifacts**: `03-Research-Artifacts/`\n- **Active initiatives**: `04-Initiatives/`\n\n## Example Interactions\n\n**User:** \"I want to assess if we should build a new feature\"\n**Response:**\n1. Ask: What problem does it solve? For whom?\n2. Guide to: `2.2-Discovery/2.2.4-Opportunity-Assessment/`\n3. Read framework guide first, then suggest template\n4. Cross-reference: Problem-Solution Space, JTBD\n\n**User:** \"Help me write a PRD\"\n**Response:**\n1. Before template, ask: What have you learned from discovery? What metrics matter?\n2. Point to: `2.3-Execution/2.3.4-PRD/`\n3. Also reference: User Stories, Personas, Metrics\n\n**User:** \"I''m overwhelmed with requests\"\n**Response:**\n1. Explore the situation\n2. Point to: `2.4-Communication/2.4.6-Saying-No/`\n3. Cross-reference: Prioritization frameworks, Stakeholder Management\n\n## Notes\n\n- This repository is git-versioned - changes are tracked\n- Templates are starting points, not rigid requirements\n- Frameworks are tools for thinking, not bureaucracy\n- The best PMs adapt frameworks to their context\n"},"lastSynced":"2026-03-08T02:10:35.893Z","agentAnalysis":{"suitability":{"en":"Ideal for Product Management Agents requiring structured framework application and templating capabilities.","zh":"适合需要结构化框架应用和模板功能的产品管理代理。","ja":"構造化フレームワークの適用とテンプレーティング機能を必要とする製品管理エージェントに適しています。","ko":"구조화된 프레임워크 적용 및 템플릿 기능을 필요로 하는 제품 관리 에이전트에 적합합니다.","es":"Ideal para agentes de gestión de productos que requieren una aplicación de estructura de framework y capacidades de templating.","fr":"Idéal pour les agents de gestion de produits nécessitant une application de structure de framework et des capacités de templating.","de":"Ideal für Product-Management-Agents, die eine strukturierte Framework-Anwendung und Templating-Fähigkeiten erfordern.","pt":"Ideal para Agentes de Gerenciamento de Produto que exigem aplicação de estrutura de framework e capacidades de modelagem.","ru":"Идеально для агентов по управлению продуктами, требующих структурированного применения фреймворка и возможностей шаблонизации.","ar":"مثالي لعميل إدارة المنتج الذي يتطلب تطبيق إطار العمل المنظم وقدرات القوالب."},"recommendation":{"en":"Empowers agents to navigate product development flows using the PM Brain repository, facilitating braindumping, structuring thinking, and templating with frameworks, following the core principle of think first, template later, utilizing framework prompts and natural product development sequences.","zh":"赋予代理导航产品开发流程的能力，使用PM Brain仓库，促进脑力倾倒、结构化思维和使用框架的模板，遵循先思考、后模板的核心原则，利用框架提示和自然产品开发序列。","ja":"エージェントが製品開発フローをナビゲートする能力を付与し、PM Brainリポジトリを使用して、ブレインダンプ、構造化思考、フレームワークを使用したテンプレーティングを促進し、先に考える、後に行うという基本原則に従い、フレームワークのヒントや自然な製品開発シーケンスを利用する。","ko":"에이전트가 제품 개발 흐름을导航할 수 있는 능력을 부여하며, PM Brain 저장소를 사용하여 뇌내용을 비우고, 구조적인 사고와 프레임워크를 사용한 템플릿을 생성하며, 먼저 생각하고 나중에 템플릿을 사용하는 핵심 원칙을 따르며, 프레임워크 프롬프트와 자연적인 제품 개발 시퀀스를 활용합니다.","es":"Habilita a los agentes a navegar por flujos de desarrollo de productos utilizando el repositorio PM Brain, facilitando el braindumping, la estructuración del pensamiento y el templating con frameworks, siguiendo el principio fundamental de pensar primero y templar después, utilizando promts de framework y secuencias de desarrollo de productos naturales.","fr":"Permet aux agents de naviguer dans les flux de développement de produits en utilisant le référentiel PM Brain, en facilitant le braindumping, la structuration de la pensée et le templating avec des frameworks, en suivant le principe fondamental de penser d''abord, puis de templater plus tard, en utilisant des invites de framework et des séquences de développement de produits naturelles.","de":"Ermächtigt Agenten, Produktentwicklungsflüsse mit dem PM Brain-Repository zu navigieren, indem es Braindumping, Denkstrukturierung und Templating mit Frameworks ermöglicht, wobei das Kernprinzip von „zuerst denken, dann templaten“ befolgt wird, unter Verwendung von Framework-Prompts und natürlichen Produktentwicklungssequenzen.","pt":"Permite que os agentes naveguem por fluxos de desenvolvimento de produtos usando o repositório PM Brain, facilitando a criação de esboços mentais, estruturando o pensamento e modelagem com frameworks, seguindo o princípio fundamental de pensar primeiro e criar modelos posteriormente, utilizando prompts de framework e sequências de desenvolvimento de produtos naturais.","ru":"Наделяет агентов возможностью ориентироваться в потоках разработки продуктов с помощью репозитория PM Brain, облегчая мозговой штурм, структурирование мышления и шаблонизацию с помощью фреймворков, следуя основному принципу думать сначала, а затем создавать шаблоны, используя подсказки фреймворка и естественные последовательности разработки продуктов.","ar":"تمكّن الوكلاء من التنقل في تدفقات تطوير المنتجات باستخدام مستودع PM Brain، ويسهم في تفريغ الأفكار، وتنظيم التفكير، وإنشاء القوالب باستخدام الإطارات، اتباعًا للمبدأ الأساسي للتفكير أولاً ثم إنشاء القوالب فيما بعد، مستخدمًا إشارات الإطار وتسلسلات تطوير المنتجات الطبيعية."},"useCases":{"en":["Braindumping raw thoughts for product development","Structuring thinking using framework prompts","Applying formal templates after organizing thoughts"],"zh":["产品开发的原始想法の腦力倾倒","使用框架提示的结构化思考","组织思想后应用正式模板"],"ja":["製品開発の生の考えのブレインダンプ","フレームワークのヒントを使用した構造化思考","考えをまとめた後に正式なテンプレートを適用"],"ko":["제품 개발을 위한 원시적인 생각을 비우기","프레임워크 프롬프트를 사용한 구조적인 사고","생각을 조직한 후에正式한 템플릿을 적용"],"es":["Volcado de pensamientos crudos para el desarrollo de productos","Estructuración del pensamiento utilizando promts de framework","Aplicación de plantillas formales después de organizar los pensamientos"],"fr":["Déversement de pensées brutes pour le développement de produits","Structuration de la pensée en utilisant des invites de framework","Application de modèles formels après avoir organisé les pensées"],"de":["Braindumping von rohen Gedanken für die Produktentwicklung","Strukturierung des Denkens unter Verwendung von Framework-Prompts","Anwendung formaler Vorlagen nach der Organisation der Gedanken"],"pt":["Criação de esboços mentais de pensamentos brutos para desenvolvimento de produtos","Estruturando o pensamento usando prompts de framework","Aplicação de modelos formais após organizar pensamentos"],"ru":["Мозговой штурм сырых мыслей для разработки продуктов","Структурирование мышления с помощью подсказок фреймворка","Применение формальных шаблонов после организации мыслей"],"ar":["تفريغ الأفكار الخام لتطوير المنتجات","تنظيم التفكير باستخدام إشارات الإطار","تطبيق قوالب رسمية بعد تنظيم الأفكار"]},"limitations":{"en":["Requires access to the PM Brain repository","Follows a specific natural product development sequence"],"zh":["需要访问PM Brain仓库","遵循特定的自然产品开发序列"],"ja":["PM Brainリポジトリへのアクセスが必要","特定の自然な製品開発シーケンスに従う"],"ko":["PM Brain 저장소에 액세스해야 함","특정한 자연적인 제품 개발 시퀀스를 따름"],"es":["Requiere acceso al repositorio PM Brain","Sigue una secuencia de desarrollo de productos natural específica"],"fr":["Nécessite un accès au référentiel PM Brain","Suit une séquence de développement de produits naturelle spécifique"],"de":["Erfordert Zugriff auf das PM Brain-Repository","Befolgt eine spezifische natürliche Produktentwicklungssequenz"],"pt":["Exige acesso ao repositório PM Brain","Segue uma sequência específica de desenvolvimento de produtos natural"],"ru":["Требует доступа к репозиторию PM Brain","Следует определенной естественной последовательности разработки продуктов"],"ar":["يتطلب الوصول إلى مستودع PM Brain","يتبع تسلسلًا محددًا لتطوير المنتجات الطبيعي"]},"version":4},"contentHash":"6ad6609520f03f2d01fc0c6446e60af97b8f9dc06f5657c157a8226a6a69728c","qualityScore":39}');
