INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('intertwine/hive-orchestrator/hive-mcp', 'hive-mcp', 'intertwine', 'hive-orchestrator', 'community', 'hive-mcp intertwine hive-orchestrator community hive-mcp is a vendor-agnostic orchestration OS for autonomous AI agents, enabling human-in-the-loop management through standardized tool interfaces. It benefits developers working with AI agents like Claude, GPT, Gemini, and Grok. Hive-MCP是一种无厂商锁定的编排操作系统，用于自主AI代理的协调和管理 Hive-MCPはベンダーに依存しないオーケストレーションOSであり、自律的なAIエージェントの調整と管理に使用される Hive-MCP는 벤더에 종속되지 않는 오케스트레이션 OS로, 자율적인 인공지능 에이전트의 조정 및 관리에 사용됩니다 Hive MCP es un sistema operativo de orquestación vendor-agnostic para agentes de IA autónomos, que coordina Claude, GPT, Gemini y Grok utilizando archivos Markdown como memoria compartida Hive MCP est un système d''exploitation d''orchestration vendor-agnostic pour les agents d''IA autonomes, qui coordonne Claude, GPT, Gemini et Grok en utilisant des fichiers Markdown comme mémoire partagée Hive MCP ist ein vendor-agnostisches Orchestrierungsbetriebssystem für autonome KI-Agents, das Claude, GPT, Gemini und Grok mithilfe von Markdown-Dateien als gemeinsamer Speicher koordiniert O Hive-MCP é um sistema de orquestração de agentes de IA que permite a coordenação de agentes como Claude, GPT e Gemini usando Markdown como memória compartilhada. Hive-MCP - это система оркестровки ИИ агентов, которая позволяет координировать агентов, такие как Claude, GPT и Gemini, используя Markdown как общую память. Hive-MCP هو نظام تنسيق لأدوات الذكاء الاصطناعي التي تمكن من تنسيق أدوات مثل Claude و GPT و Gemini باستخدام Markdown كذاكرة مشتركة. how to use hive-mcp hive-mcp setup guide hive-mcp alternative hive-mcp vs Claude what is hive-mcp hive-mcp install hive-mcp GitHub Actions MCP protocol AI agent orchestration Markdown file shared memory Hive-MCP AI Engine 自主AI代理 模型上下文协议 Markdown共享内存 GitHub Actions AI工具 自动化编排 Exposes Agent Hive functionality as MCP tools Enables AI agents to programmatically manage projects through standardized tool interfaces Supports coordination of Claude, GPT, Gemini, and Grok using Markdown files Runs on GitHub Actions free tier, enabling Git-native management Provides a standardized way for AI agents to interact with external tools through MCP (Model Context Protocol) Allows for human-in-the-loop management of AI agents hive-mcp is a vendor-agnostic orchestration OS that enables autonomous AI agents to interact with external tools through standardized interfaces, using Markdown files as shared memory.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Matchpoint-AI/matchpoint-github-runners-helm/cross-repo-coordination', 'community', 'Matchpoint-AI', 'matchpoint-github-runners-helm', 'Matchpoint-AI/matchpoint-github-runners-helm', 'cross-repo-coordination', 0, 0, 39, '2026-03-08T01:57:15.580Z', '2026-03-08T02:11:52.697Z', '582ac18099e3dc9c93f104a569daa3bb9603af23fa18497397c12823c73458ee', '{"id":"Matchpoint-AI/matchpoint-github-runners-helm/cross-repo-coordination","name":"cross-repo-coordination","description":{"en":"The cross-repo-coordination skill enables coordinated updates across GitHub repositories using self-hosted runners. It benefits developers working with GitHub Actions workflows in the project-beta ecosystem.","zh":"跨仓库协调技能实现 GitHub Actions Runner Scale Set 的自动化部署和管理，支持 Matchpoint-AI 组织的 Helm Charts","ja":"クロスリポジトリコーディネーションスキルは、GitHub Actions Runner Scale Set の自動化デプロイと管理を実現し、Matchpoint-AI 組織の Helm Charts をサポートします","ko":"크로스 리포지토리 코디네이션 스킬은 GitHub Actions Runner Scale Set의 자동화 배포 및 관리를 구현하며 Matchpoint-AI 조직의 Helm Charts를 지원합니다","es":"La coordinación entre repositorios es crucial para GitHub Actions. Aprende a configurar Helm charts para ARC en Matchpoint-AI","fr":"La coordination entre référentiels est essentielle pour GitHub Actions. Découvrez comment configurer Helm charts pour ARC dans Matchpoint-AI","de":"Die Koordination zwischen Repositorys ist für GitHub Actions entscheidend. Erfahren Sie, wie Sie Helm charts für ARC in Matchpoint-AI konfigurieren","pt":"A coordenação entre repositórios é essencial para atualizações de runners em projetos que usam GitHub Actions. Este guia mostra como configurar com Helm charts.","ru":"Координация между репозиториями необходима для обновления runners в проектах, использующих GitHub Actions. Это руководство показывает, как настроить с помощью Helm charts.","ar":"تنسيق المستودعات ضروري لتحديث التشغيل في المشاريع التي تستخدم GitHub Actions. هذا الدليل يظهر كيفية ضبط الإعدادات باستخدام Helm charts."},"seo":{"title":{"en":"cross-repo-coordination: Helm Charts Setup Guide for AI A...","zh":"跨仓库协调技能：GitHub Actions Runner Scale Set 部署指南","ja":"クロスリポジトリコーディネーションスキル：GitHub Actions Runner Scale Set のデプロ...","ko":"크로스 리포지토리 코디네이션 스킬: GitHub Actions Runner Scale Set 배포 설정...","es":"Guía de configuración para la coordinación entre reposito...","fr":"Guide de mise en place de la coordination entre référenti...","de":"Einrichtungsleitfaden für die Koordination zwischen Repos...","pt":"Guia de Configuração de Coordenação entre Repositórios co...","ru":"Руководство по настройке координации между репозиториями ...","ar":"دليل ضبط تنسيق المستودعات عبر أدوات الذكاء الاصطناعي"},"description":{"en":"Streamline GitHub Actions Runner Scale Set deployments with cross-repo-coordination. Learn how to coordinate updates across repositories with our expert guide.","zh":"了解跨仓库协调技能，实现 GitHub Actions Runner Scale Set 的自动化部署和管理，提高开发效率","ja":"クロスリポジトリコーディネーションスキルを使用して、GitHub Actions Runner Scale Set の自動化デプロイと管理を実現し、開発効率を向上させる","ko":"크로스 리포지토리 코디네이션 스킬을 사용하여 GitHub Actions Runner Scale Set의 자동화 배포 및 관리를 구현하고 개발 효율성을 향상시키세요","es":"Aprende a implementar la coordinación entre repositorios con Helm charts para GitHub Actions Runner Scale Set (ARC) en la organización Matchpoint-AI","fr":"Découvrez comment mettre en place la coordination entre référentiels avec Helm charts pour GitHub Actions Runner Scale Set (ARC) dans l''organisation Matchpoi...","de":"Erfahren Sie, wie Sie die Koordination zwischen Repositorys mit Helm charts für GitHub Actions Runner Scale Set (ARC) in der Organisation Matchpoint-AI imple...","pt":"Aprenda a configurar a coordenação entre repositórios com Helm charts para GitHub Actions Runner Scale Set (ARC) deployments","ru":"Узнайте, как настроить координацию между репозиториями с помощью Helm charts для GitHub Actions Runner Scale Set (ARC) deployments","ar":"تعلم كيفية ضبط تنسيق المستودعات باستخدام Helm charts لتركيبات GitHub Actions Runner Scale Set (ARC)"},"definition":{"en":"cross-repo-coordination is a skill that facilitates coordinated updates across multiple GitHub repositories using Helm charts for GitHub Actions Runner Scale Set deployments.","zh":"跨仓库协调技能是一种实现 GitHub Actions Runner Scale Set 自动化部署和管理的技术","ja":"クロスリポジトリコーディネーションスキルは、GitHub Actions Runner Scale Set の自動化デプロイと管理を実現する技術です","ko":"크로스 리포지토리 코디네이션 스킬은 GitHub Actions Runner Scale Set의 자동화 배포 및 관리를 구현하는 기술입니다","es":"La coordinación entre repositorios es una habilidad que permite la actualización coordinada de runners en múltiples repositorios","fr":"La coordination entre référentiels est une compétence qui permet la mise à jour coordonnée des runners dans plusieurs référentiels","de":"Die Koordination zwischen Repositorys ist eine Fähigkeit, die die koordinierte Aktualisierung von Runnern in mehreren Repositorys ermöglicht","pt":"Coordenação entre repositórios é uma técnica para gerenciar atualizações de runners em múltiplos repositórios","ru":"Координация между репозиториями - это техника для управления обновлениями runners в нескольких репозиториях","ar":"تنسيق المستودعات هو تقنية لإدارة تحديث التشغيل في مستودعات متعددة"},"features":{"en":["Defines runnerScaleSetName using Helm charts","Deploys runners with ArgoCD","Supports GitHub Actions workflows with self-hosted runners","Enables coordinated updates across repositories using the arc-beta-runners label","Integrates with project-beta ecosystem repositories","Utilizes matchpoint-github-runners-helm for runner configuration"],"zh":["支持 GitHub Actions Runner Scale Set 的自动化部署","实现 Matchpoint-AI 组织的 Helm Charts 管理","提供 ArgoCD 部署和管理功能","支持 project-beta 项目的 runner 配置更新","自动化 runnerScaleSetName 的定义和管理","集成多个仓库的工作流协调"],"ja":["GitHub Actions Runner Scale Set の自動化デプロイをサポート","Matchpoint-AI 組織の Helm Charts 管理を実現","ArgoCD デプロイと管理機能を提供","project-beta プロジェクトの runner 構成更新をサポート","runnerScaleSetName の定義と管理を自動化","複数のリポジトリのワークフロー協調を実現"],"ko":["GitHub Actions Runner Scale Set의 자동화 배포를 지원","Matchpoint-AI 조직의 Helm Charts 관리를 구현","ArgoCD 배포 및 관리 기능을 제공","project-beta 프로젝트의 runner 구성 업데이트를 지원","runnerScaleSetName의 정의 및 관리를 자동화","複数의 리포지토리의 워크플로우 협조를 구현"],"es":["Uso de Helm charts para la implementación de runners","Integración con GitHub Actions Runner Scale Set (ARC)","Compatibilidad con la organización Matchpoint-AI","Actualización coordinada de runners en múltiples repositorios","Uso de ArgoCD para la implementación de runners","Soporte para la etiqueta runnerScaleSetName"],"fr":["Utilisation de Helm charts pour la mise en place des runners","Intégration avec GitHub Actions Runner Scale Set (ARC)","Compatibilité avec l''organisation Matchpoint-AI","Mise à jour coordonnée des runners dans plusieurs référentiels","Utilisation d''ArgoCD pour la mise en place des runners","Prise en charge de l''étiquette runnerScaleSetName"],"de":["Verwendung von Helm charts für die Implementierung von Runnern","Integration mit GitHub Actions Runner Scale Set (ARC)","Kompatibilität mit der Organisation Matchpoint-AI","Koordinierte Aktualisierung von Runnern in mehreren Repositorys","Verwendung von ArgoCD für die Implementierung von Runnern","Unterstützung für die Kennzeichnung runnerScaleSetName"],"pt":["Uso de Helm charts para deployments de GitHub Actions Runner Scale Set (ARC)","Coordenação de atualizações de runners em múltiplos repositórios","Integração com ArgoCD para deploy de runners","Suporte a projetos que usam GitHub Actions","Definição de runnerScaleSetName para configuração de runners"],"ru":["Использование Helm charts для deployments GitHub Actions Runner Scale Set (ARC)","Координация обновления runners в нескольких репозиториях","Интеграция с ArgoCD для deploy runners","Поддержка проектов, использующих GitHub Actions","Определение runnerScaleSetName для конфигурации runners"],"ar":["استخدام Helm charts لتركيبات GitHub Actions Runner Scale Set (ARC)","تنسيق تحديث التشغيل في مستودعات متعددة","التكامل مع ArgoCD لنشر التشغيل","دعم المشاريع التي تستخدم GitHub Actions","تحديد runnerScaleSetName لإعداد التشغيل"]},"keywords":{"en":["how to use cross-repo-coordination","cross-repo-coordination setup guide","github actions runner scale set deployments","helm charts for github actions","argocd deployments","cross-repo-coordination vs github actions","cross-repo-coordination install","what is cross-repo-coordination","cross-repo-coordination alternative"],"zh":["跨仓库协调技能","GitHub Actions Runner Scale Set","Matchpoint-AI","Helm Charts","ArgoCD","自动化部署","runner 配置更新","多仓库工作流协调"],"ja":["クロスリポジトリコーディネーションスキル","GitHub Actions Runner Scale Set","Matchpoint-AI","Helm Charts","ArgoCD","自動化デプロイ","runner 構成更新","多リポジトリワークフロー協調"],"ko":["크로스 리포지토리 코디네이션 스킬","GitHub Actions Runner Scale Set","Matchpoint-AI","Helm Charts","ArgoCD","자동화 배포","runner 구성 업데이트","다중 리포지토리 워크플로우 협조"],"es":["coordinación entre repositorios","Helm charts","GitHub Actions","Runner Scale Set","ARC","Matchpoint-AI","ArgoCD","runnerScaleSetName","implementación de runners","actualización coordinada"],"fr":["coordination entre référentiels","Helm charts","GitHub Actions","Runner Scale Set","ARC","Matchpoint-AI","ArgoCD","runnerScaleSetName","mise en place des runners","mise à jour coordonnée"],"de":["Koordination zwischen Repositorys","Helm charts","GitHub Actions","Runner Scale Set","ARC","Matchpoint-AI","ArgoCD","runnerScaleSetName","Implementierung von Runnern","koordinierte Aktualisierung"],"pt":["coordenação entre repositórios","Helm charts","GitHub Actions Runner Scale Set","ArgoCD","GitHub Actions","runnerScaleSetName","deploy de runners","Inteligenzia artificial para desenvolvedores"],"ru":["координация между репозиториями","Helm charts","GitHub Actions Runner Scale Set","ArgoCD","GitHub Actions","runnerScaleSetName","deploy runners","ИИ Агенты для разработчиков"],"ar":["تنسيق المستودعات","Helm charts","تركيبات GitHub Actions Runner Scale Set","ArgoCD","GitHub Actions","runnerScaleSetName","نشر التشغيل","أدوات الذكاء الاصطناعي للمطورين"]}},"owner":"Matchpoint-AI","repo":"matchpoint-github-runners-helm","repoPath":"Matchpoint-AI/matchpoint-github-runners-helm","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.580Z","topics":[],"category":"community","skillMd":{"name":"cross-repo-coordination","description":"Coordinate changes across project-beta repositories when updating runner configurations. Ensures workflow labels match runner scale set names. Use when changing runnerScaleSetName or deploying new runner pools.","bodyPreview":"# Cross-Repository Workflow Coordination Skill\n\n## Overview\n\nGitHub Actions workflows in the project-beta ecosystem use self-hosted runners. When runner configurations change, ALL repositories using those runners need coordinated updates.\n\n## Architecture\n\n```\nmatchpoint-github-runners-helm\n├── Defines runnerScaleSetName: \"arc-beta-runners\"\n└── ArgoCD deploys runners with this label\n\nproject-beta-frontend\nproject-beta-api           } Must use: runs-on: arc-beta-runners\nproject-beta\n```\n\n**Critic","body":"# Cross-Repository Workflow Coordination Skill\n\n## Overview\n\nGitHub Actions workflows in the project-beta ecosystem use self-hosted runners. When runner configurations change, ALL repositories using those runners need coordinated updates.\n\n## Architecture\n\n```\nmatchpoint-github-runners-helm\n├── Defines runnerScaleSetName: \"arc-beta-runners\"\n└── ArgoCD deploys runners with this label\n\nproject-beta-frontend\nproject-beta-api           } Must use: runs-on: arc-beta-runners\nproject-beta\n```\n\n**Critical Rule:** Workflow `runs-on:` MUST EXACTLY match Helm `runnerScaleSetName`\n\n## The Coordination Problem\n\n### Issue #121 Example\n\n**Change:** Update `runnerScaleSetName` from `arc-runners` to `arc-beta-runners`\n\n**Impact:**\n```\nmatchpoint-github-runners-helm\n  ✅ runnerScaleSetName: \"arc-beta-runners\"\n\nproject-beta-frontend (15 workflows)\n  ❌ runs-on: arc-runners  # OLD label - jobs stuck!\n\nproject-beta-api (13 workflows)\n  ❌ runs-on: arc-runners  # OLD label - jobs stuck!\n\nproject-beta (3 workflows)\n  ❌ runs-on: arc-runners  # OLD label - jobs stuck!\n```\n\n**Result:** All CI jobs stuck in \"queued\" state until workflows updated.\n\n## Affected Repositories\n\n| Repository | Workflows | Runner Labels | Priority |\n|------------|-----------|---------------|----------|\n| project-beta-frontend | 15 files | arc-beta-runners | P0 - Blocks deploys |\n| project-beta-api | 13 files | arc-beta-runners | P0 - Blocks deploys |\n| project-beta | 3 files | arc-beta-runners | P0 - Blocks infra |\n\n## Coordination Workflow\n\n### Phase 1: Planning\n\nBefore changing `runnerScaleSetName`, audit all repositories:\n\n```bash\n# Search for current runner label usage\nfor repo in project-beta-frontend project-beta-api project-beta; do\n  echo \"=== $repo ===\"\n  cd /path/to/$repo\n  grep -r \"runs-on:\" .github/workflows/ | grep -v \"ubuntu-latest\" | sort -u\ndone\n```\n\n**Output example:**\n```\n=== project-beta-frontend ===\n.github/workflows/ci.yaml:    runs-on: arc-runners\n.github/workflows/deploy.yaml:    runs-on: arc-runners\n...\n\n=== project-beta-api ===\n.github/workflows/test.yaml:    runs-on: arc-runners\n...\n```\n\n**Document the changes needed:**\n- Count of files per repository\n- Specific workflow files affected\n- Any workflows using different labels\n\n### Phase 2: Create Migration Plan\n\n**Option A: Dual Runner Pools (Zero Downtime)**\n\nDeploy BOTH old and new runner pools during transition:\n\n```yaml\n# matchpoint-github-runners-helm/argocd/applicationset-runners.yaml\ngenerators:\n- list:\n    elements:\n    - name: arc-runners           # OLD - for existing workflows\n      valuesFile: examples/runners-values-old.yaml\n    - name: arc-beta-runners      # NEW - for updated workflows\n      valuesFile: examples/runners-values-new.yaml\n```\n\n**Timeline:**\n1. Deploy both runner pools\n2. Update workflows in all repos (can be done gradually)\n3. Remove old runner pool after all workflows migrated\n\n**Pros:**\n- Zero downtime\n- Safe rollback (revert workflow changes)\n- Can update repos independently\n\n**Cons:**\n- 2x runner costs during migration\n- Need to track which repos migrated\n\n**Option B: Coordinated Single Cutover**\n\nUpdate runner AND all workflows simultaneously:\n\n1. Prepare PRs in ALL repositories (don''t merge)\n2. Merge runner config change\n3. Wait for ArgoCD sync (~3 min)\n4. Merge ALL workflow PRs quickly\n5. Monitor for stuck jobs\n\n**Pros:**\n- No extra runner costs\n- Clean cutover\n\n**Cons:**\n- ~3-5 minute CI outage\n- Requires coordination across repos\n- Risky if issues arise\n\n**Recommended:** Option A for production, Option B for dev/test\n\n### Phase 3: Update Workflows\n\nFor each repository, create a PR that updates ALL workflow files:\n\n```bash\n# Script: update-runner-labels.sh\n#!/bin/bash\n\nOLD_LABEL=\"arc-runners\"\nNEW_LABEL=\"arc-beta-runners\"\nREPO=$1\n\ncd /path/to/$REPO\n\n# Find all workflow files\nWORKFLOWS=$(find .github/workflows -name \"*.ya*ml\")\n\n# Update each file\nfor workflow in $WORKFLOWS; do\n  if grep -q \"runs-on: $OLD_LABEL\" \"$workflow\"; then\n    echo \"Updating: $workflow\"\n    sed -i \"s/runs-on: $OLD_LABEL/runs-on: $NEW_LABEL/g\" \"$workflow\"\n  fi\ndone\n\n# Create PR\ngit checkout -b fix/update-runner-label-to-$NEW_LABEL\ngit add .github/workflows/\ngit commit -m \"ci: Update runner label from $OLD_LABEL to $NEW_LABEL\n\nAligns with runner configuration change in matchpoint-github-runners-helm.\n\nRefs: matchpoint-ai/matchpoint-github-runners-helm#121\"\n\ngit push -u origin fix/update-runner-label-to-$NEW_LABEL\n\ngh pr create \\\n  --title \"ci: Update runner label from $OLD_LABEL to $NEW_LABEL\" \\\n  --body \"Updates all workflows to use the new runner label \\`$NEW_LABEL\\`.\n\n## Context\nmatchpoint-github-runners-helm changed \\`runnerScaleSetName\\` to \\`$NEW_LABEL\\`.\n\n## Changes\n- Updates all \\`.github/workflows/*.yaml\\` files\n- Changes \\`runs-on: $OLD_LABEL\\` → \\`runs-on: $NEW_LABEL\\`\n\n## Testing\n- [ ] Verify workflows use correct runner label\n- [ ] Confirm CI jobs execute (not stuck in queue)\n\nRelated: matchpoint-ai/matchpoint-github-runners-helm#121\"\n```\n\n**Usage:**\n```bash\n./update-runner-labels.sh project-beta-frontend\n./update-runner-labels.sh project-beta-api\n./update-runner-labels.sh project-beta\n```\n\n### Phase 4: Verification\n\nAfter merging workflow updates:\n\n```bash\n# Check that runners are picking up jobs\ngh run list --repo Matchpoint-AI/project-beta-frontend --limit 5\n\n# Verify no jobs stuck in queue\ngh run list --repo Matchpoint-AI/project-beta-frontend --status queued\n\n# Check runner status\ngh api /orgs/Matchpoint-AI/actions/runners --jq ''.runners[] | {name, status, busy, labels: [.labels[].name]}''\n```\n\n**Success criteria:**\n- ✅ No jobs stuck in \"queued\" for > 2 minutes\n- ✅ Jobs transition to \"in_progress\" quickly\n- ✅ Runners show \"busy: true\" when jobs running\n\n## Common Scenarios\n\n### Scenario 1: Adding New Runner Pool\n\n**Example:** Add dedicated runners for frontend with GPU support\n\n**Steps:**\n1. Add runner pool in matchpoint-github-runners-helm:\n   ```yaml\n   # argocd/applicationset-runners.yaml\n   - name: arc-frontend-gpu\n     valuesFile: examples/frontend-gpu-values.yaml\n   ```\n\n2. Update ONLY affected workflows in project-beta-frontend:\n   ```yaml\n   # .github/workflows/e2e-visual-tests.yaml\n   jobs:\n     visual-tests:\n       runs-on: arc-frontend-gpu  # NEW pool\n   ```\n\n3. Keep other workflows on existing pool:\n   ```yaml\n   # .github/workflows/ci.yaml\n   jobs:\n     test:\n       runs-on: arc-beta-runners  # Existing pool\n   ```\n\n**Impact:** Only workflows explicitly updated use new pool\n\n### Scenario 2: Removing Runner Pool\n\n**Example:** Deprecate `arc-runners` in favor of `arc-beta-runners`\n\n**Steps:**\n1. Ensure NO workflows reference old label:\n   ```bash\n   for repo in project-beta-frontend project-beta-api project-beta; do\n     cd /path/to/$repo\n     grep -r \"runs-on: arc-runners\" .github/workflows/ && echo \"❌ Found old label in $repo\"\n   done\n   ```\n\n2. Remove runner pool from matchpoint-github-runners-helm:\n   ```yaml\n   # argocd/applicationset-runners.yaml\n   # Remove the arc-runners entry\n   ```\n\n3. Verify no queued jobs after removal:\n   ```bash\n   gh run list --status queued --limit 20\n   ```\n\n### Scenario 3: Emergency Runner Failover\n\n**Example:** Primary runner pool down, need to switch to backup\n\n**Steps:**\n1. Deploy backup runner pool (if not already deployed):\n   ```bash\n   # Quick deploy via ArgoCD\n   kubectl apply -f argocd/applications/arc-backup-runners.yaml\n   ```\n\n2. Bulk update workflows in critical repo:\n   ```bash\n   # Emergency script\n   find .github/workflows -name \"*.yaml\" -exec sed -i ''s/runs-on: arc-beta-runners/runs-on: arc-backup-runners/g'' {} \\;\n   git add .github/workflows/\n   git commit -m \"EMERGENCY: Switch to backup runners\"\n   git push\n   ```\n\n3. Monitor job execution:\n   ```bash\n   watch -n 5 ''gh run list --limit 10''\n   ```\n\n## Validation Scripts\n\n### Pre-Merge Validation\n\nRun before merging runner configuration changes:\n\n```bash\n#!/bin/bash\n# scripts/validate-runner-labels.sh\n\nset -euo pipefail\n\nRUNNER_LABEL=$1\nREPOS=(\"project-beta-frontend\" \"project-beta-api\" \"project-beta\")\n\necho \"🔍 Checking if workflows use runner label: $RUNNER_LABEL\"\n\nfor repo in \"${REPOS[@]}\"; do\n  echo \"\"\n  echo \"=== $repo ===\"\n\n  if [ ! -d \"../$repo\" ]; then\n    echo \"⚠️  Repository not found: ../$repo\"\n    continue\n  fi\n\n  cd \"../$repo\"\n\n  MATCHES=$(grep -r \"runs-on: $RUNNER_LABEL\" .github/workflows/ 2>/dev/null | wc -l)\n\n  if [ \"$MATCHES\" -gt 0 ]; then\n    echo \"✅ Found $MATCHES workflow jobs using $RUNNER_LABEL\"\n    grep -r \"runs-on: $RUNNER_LABEL\" .github/workflows/ | head -5\n  else\n    echo \"❌ No workflows use $RUNNER_LABEL\"\n  fi\n\n  cd - > /dev/null\ndone\n```\n\n**Usage:**\n```bash\ncd matchpoint-github-runners-helm\n./scripts/validate-runner-labels.sh arc-beta-runners\n```\n\n### Post-Merge Validation\n\nRun after merging workflow updates:\n\n```bash\n#!/bin/bash\n# scripts/verify-ci-not-stuck.sh\n\nset -euo pipefail\n\nREPOS=(\"Matchpoint-AI/project-beta-frontend\" \"Matchpoint-AI/project-beta-api\" \"Matchpoint-AI/project-beta\")\n\necho \"🔍 Checking for stuck CI jobs...\"\n\nfor repo in \"${REPOS[@]}\"; do\n  echo \"\"\n  echo \"=== $repo ===\"\n\n  QUEUED=$(gh run list --repo \"$repo\" --status queued --limit 50 --json databaseId,createdAt,status | jq -r ''.[] | select(.status == \"queued\") | \"\\(.databaseId) - queued since \\(.createdAt)\"'')\n\n  if [ -z \"$QUEUED\" ]; then\n    echo \"✅ No queued jobs\"\n  else\n    echo \"⚠️  Found queued jobs:\"\n    echo \"$QUEUED\"\n\n    # Check if any queued > 5 minutes\n    STUCK=$(echo \"$QUEUED\" | jq -r ''select(now - (.createdAt | fromdateiso8601) > 300)'')\n    if [ -n \"$STUCK\" ]; then\n      echo \"❌ Jobs stuck for > 5 minutes!\"\n    fi\n  fi\ndone\n```\n\n**Usage:**\n```bash\n./scripts/verify-ci-not-stuck.sh\n```\n\n## Troubleshooting\n\n### Error: Jobs Stuck After Runner Change\n\n**Symptom:** CI jobs stuck in \"queued\" after runner label change\n\n**Diagnosis:**\n```bash\n# Check what label runners have\nkubectl get autoscalingrunnerset -A -o jsonpath=''{.items[*].spec.runnerScaleSetName}''\n\n# Check what label workflows use\nfor repo in project-beta-frontend project-beta-api project-beta; do\n  cd ../$repo\n  grep -h \"runs-on:\" .github/workflows/* | sort -u\ndone\n```\n\n**Fix:**\n```bash\n# If mismatch found, update workflows\ncd ../project-beta-frontend\nfind .github/workflows -name \"*.yaml\" -exec sed -i ''s/runs-on: OLD_LABEL/runs-on: NEW_LABEL/g'' {} \\;\ngit commit -am \"fix: Update runner label to match deployed runners\"\ngit push\n```\n\n### Error: Some Repos Updated, Others Not\n\n**Symptom:** CI works in some repos but not others\n\n**Diagnosis:**\n```bash\n# Check each repo''s workflows\nfor repo in project-beta-frontend project-beta-api project-beta; do\n  echo \"=== $repo ===\"\n  cd ../$repo\n  grep -h \"runs-on:\" .github/workflows/* | sort -u\n  cd -\ndone\n```\n\n**Fix:** Update remaining repos using update script\n\n### Error: Runners Deployed But Not Registering\n\n**Symptom:** Runners deployed but GitHub doesn''t show them\n\n**Diagnosis:**\n```bash\n# Check GitHub runners\ngh api /orgs/Matchpoint-AI/actions/runners --jq ''.runners[] | {name, labels: [.labels[].name]}''\n\n# Check Kubernetes runners\nkubectl get pods -n arc-beta-runners -l app.kubernetes.io/component=runner\n```\n\n**Fix:** See [arc-runner-troubleshooting](../arc-runner-troubleshooting/SKILL.md)\n\n## Best Practices\n\n1. **Plan multi-repo changes in advance** - Don''t surprise developers with stuck CI\n2. **Use dual runner pools during migration** - Eliminates downtime\n3. **Communicate changes** - Post in team chat before merging\n4. **Verify in dev first** - Test runner changes in development repo\n5. **Monitor after deployment** - Watch for queued jobs for 30 minutes post-change\n6. **Document runner labels** - Keep README updated with current label names\n7. **Automate validation** - Run validation scripts in CI for runner config changes\n\n## Coordination Checklist\n\nBefore changing `runnerScaleSetName`:\n\n- [ ] Audit all repos for workflow label usage\n- [ ] Document count of files per repo needing updates\n- [ ] Choose migration strategy (dual pool vs cutover)\n- [ ] Prepare PRs for all affected repos\n- [ ] Communicate change timeline to team\n- [ ] Deploy runner config change\n- [ ] Wait for ArgoCD sync (verify runners online)\n- [ ] Merge workflow PRs\n- [ ] Verify CI jobs execute successfully\n- [ ] Monitor for stuck jobs (30 minutes)\n- [ ] Clean up old runner pool (if dual pool strategy)\n\n## Related Skills\n\n- [arc-runner-troubleshooting](../arc-runner-troubleshooting/SKILL.md) - Runner registration issues\n- [argocd-bootstrap](../argocd-bootstrap/SKILL.md) - Runner deployment via ArgoCD\n- [infrastructure-cd](../infrastructure-cd/SKILL.md) - Automated deployment workflow\n\n## Related Issues\n\n- #121 - releaseName/runnerScaleSetName mismatch causing empty labels\n- #123 - Cross-repo label update coordination\n- #112 - CI jobs stuck investigation\n- project-beta-api#798 - Workflow label update\n- project-beta-frontend#886 - CI blocked by label mismatch\n\n## References\n\n- [GitHub Actions: runs-on](https://docs.github.com/en/actions/using-workflows/workflow-syntax-for-github-actions#jobsjob_idruns-on)\n- [ARC: Using Runners in Workflows](https://docs.github.com/en/actions/hosting-your-own-runners/managing-self-hosted-runners-with-actions-runner-controller/using-actions-runner-controller-runners-in-a-workflow)\n"},"lastSynced":"2026-03-08T02:11:52.697Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing automated workflow coordination across GitHub repositories.","zh":"非常适合需要在 GitHub 仓库中自动化工作流协调的 DevOps Agent。","ja":"GitHub リポジトリ全体で自動化されたワークフローを調整する必要がある DevOps エージェントに最適です。","ko":"GitHub 저장소 전반에서 자동화된 워크플로우 조정을 필요로 하는 DevOps 에이전트에게 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan coordinación de flujo de trabajo automatizada en varios repositorios de GitHub.","fr":"Parfait pour les agents DevOps ayant besoin d''une coordination de workflow automatisée à travers plusieurs dépôts GitHub.","de":"Perfekt für DevOps-Agents, die eine automatisierte Workflow-Koordination über mehrere GitHub-Repositories hinweg benötigen.","pt":"Perfeito para Agentes DevOps que necessitam de coordenação de fluxo de trabalho automatizada em repositórios GitHub.","ru":"Идеально подходит для агентов DevOps, которым требуется автоматизированная координация рабочих процессов в репозиториях GitHub.","ar":"مثالي لعميل DevOps الذي يحتاج إلى تنسيق تدفق العمل الآلي عبر مستودعات GitHub."},"recommendation":{"en":"Empowers agents to orchestrate updates across multiple repositories using self-hosted runners, GitHub Actions workflows, and ArgoCD deployments, ensuring seamless coordination and minimizing manual intervention.","zh":"赋予代理人使用自托管运行器、GitHub Actions 工作流和 ArgoCD 部署来跨多个仓库编排更新的能力，确保无缝协调并尽量减少手动干预。","ja":"セルフホステッド ランナー、GitHub Actions ワークフロー、および ArgoCD デプロイを使用して、複数のリポジトリにわたる更新をオーケストレーションできるようにエージェントに権限を付与し、シームレスな調整を保証し、手動介入を最小限に抑えます。","ko":"자체 호스팅 러너, GitHub Actions 워크플로 및 ArgoCD 배포를 사용하여 여러 리포지토리에서 업데이트를 오케스트레이션할 수 있는 에이전트를 강화하여 무중단 조정을 보장하고 수동 개입을 최소화합니다.","es":"Habilita a los agentes a orquestar actualizaciones en varios repositorios utilizando ejecutores autohospedados, flujos de trabajo de GitHub Actions y despliegues de ArgoCD, garantizando una coordinación sin problemas y minimizando la intervención manual.","fr":"Permet aux agents d''orchestrer des mises à jour à travers plusieurs dépôts en utilisant des exécuteurs auto-hébergés, des flux de travail GitHub Actions et des déploiements ArgoCD, assurant une coordination transparente et minimisant l''intervention manuelle.","de":"Ermächtigt Agents, Updates über mehrere Repositories hinweg mithilfe von selbst gehosteten Runnern, GitHub Actions-Workflows und ArgoCD-Deployments zu orchestrieren, wodurch eine nahtlose Koordination sichergestellt und die manuelle Eingreifung minimiert wird.","pt":"Habilita os agentes a orquestrar atualizações em vários repositórios usando executores auto-hospedados, fluxos de trabalho GitHub Actions e implantações ArgoCD, garantindo uma coordenação sem problemas e minimizando a intervenção manual.","ru":"Наделяет агентов возможностью оркестрировать обновления в нескольких репозиториях с помощью само-хостинговых руннеров, рабочих процессов GitHub Actions и развертываний ArgoCD, обеспечивая бесперебойную координацию и минимизируя ручное вмешательство.","ar":"يمكن الوكلاء من تنسيق التحديثات عبر عدة مستودعات باستخدام تشغيلات المضيفين ذاتية الاستضافة و سلاسل عمل GitHub Actions و عمليات نشر ArgoCD، مما يضمن تنسيقًا سلسًا ويقلل من التدخل اليدوي."},"useCases":{"en":["Automating runner configuration updates","Coordinating workflow deployments across repositories","Debugging cross-repository workflow issues"],"zh":["自动化运行器配置更新","跨仓库协调工作流部署","调试跨仓库工作流问题"],"ja":["ランナー構成の更新を自動化する","リポジトリを跨ぐワークフローのデプロイを調整する","リポジトリを跨ぐワークフロー問題をデバッグする"],"ko":["러너 구성 업데이트를 자동화하는 것","리포지토리를跨는 워크플로 배포를 조정하는 것","리포지토리를跨는 워크플로 문제를 디버깅하는 것"],"es":["Automatización de actualizaciones de configuración de ejecutores","Coordinación de despliegues de flujos de trabajo en varios repositorios","Depuración de problemas de flujos de trabajo entre repositorios"],"fr":["Automatisation des mises à jour de configuration d''exécuteurs","Coordination des déploiements de flux de travail à travers plusieurs dépôts","Débogage des problèmes de flux de travail entre dépôts"],"de":["Automatisierung von Runner-Konfigurations-Updates","Koordination von Workflow-Deployments über mehrere Repositories hinweg","Fehlerbehebung bei Workflow-Problemen zwischen Repositories"],"pt":["Automatizar atualizações de configuração de executor","Coordenar implantações de fluxo de trabalho em repositórios","Depurar problemas de fluxo de trabalho entre repositórios"],"ru":["Автоматизировать обновления конфигурации руннера","Координировать развертывания рабочих процессов в репозиториях","Отлаживать проблемы рабочих процессов между репозиториями"],"ar":["تحديث تكوين تشغيل المضيفين تلقائيًا","تنسيق عمليات نشر سلاسل العمل عبر المستودعات","تصحيح مشاكل سلاسل العمل بين المستودعات"]},"limitations":{"en":["Requires self-hosted runners","Limited to GitHub Actions workflows","Dependent on ArgoCD for deployment"],"zh":["需要自托管运行器","仅限 GitHub Actions 工作流","依赖 ArgoCD 进行部署"],"ja":["セルフホステッド ランナーが必要","GitHub Actions ワークフローに限定される","デプロイに Argocd に依存する"],"ko":["자체 호스팅 러너가 필요함","GitHub Actions 워크플로에만 국한됨","배포에 ArgoCD에 의존함"],"es":["Requiere ejecutores autohospedados","Limitado a flujos de trabajo de GitHub Actions","Dependiente de ArgoCD para la implementación"],"fr":["Nécessite des exécuteurs auto-hébergés","Limité aux flux de travail GitHub Actions","Dépendant d''ArgoCD pour le déploiement"],"de":["Erfordert selbst gehostete Runner","Begrenzt auf GitHub Actions-Workflows","Von ArgoCD für das Deployment abhängig"],"pt":["Exige executores auto-hospedados","Limitado a fluxos de trabalho GitHub Actions","Dependente de ArgoCD para implantação"],"ru":["Требует само-хостинговых руннеров","Ограничен рабочими процессами GitHub Actions","Зависит от ArgoCD для развертывания"],"ar":["يتطلب تشغيلات المضيفين ذاتية الاستضافة","محدود بسلاسل عمل GitHub Actions","يعتمد على ArgoCD لنشر"]},"version":4},"contentHash":"582ac18099e3dc9c93f104a569daa3bb9603af23fa18497397c12823c73458ee","qualityScore":39}');
