INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Matchpoint-AI/matchpoint-github-runners-helm/cross-repo-coordination', 'cross-repo-coordination', 'Matchpoint-AI', 'matchpoint-github-runners-helm', 'community', 'cross-repo-coordination Matchpoint-AI matchpoint-github-runners-helm community The cross-repo-coordination skill enables coordinated updates across GitHub repositories using self-hosted runners. It benefits developers working with GitHub Actions workflows in the project-beta ecosystem. 跨仓库协调技能实现 GitHub Actions Runner Scale Set 的自动化部署和管理，支持 Matchpoint-AI 组织的 Helm Charts クロスリポジトリコーディネーションスキルは、GitHub Actions Runner Scale Set の自動化デプロイと管理を実現し、Matchpoint-AI 組織の Helm Charts をサポートします 크로스 리포지토리 코디네이션 스킬은 GitHub Actions Runner Scale Set의 자동화 배포 및 관리를 구현하며 Matchpoint-AI 조직의 Helm Charts를 지원합니다 La coordinación entre repositorios es crucial para GitHub Actions. Aprende a configurar Helm charts para ARC en Matchpoint-AI La coordination entre référentiels est essentielle pour GitHub Actions. Découvrez comment configurer Helm charts pour ARC dans Matchpoint-AI Die Koordination zwischen Repositorys ist für GitHub Actions entscheidend. Erfahren Sie, wie Sie Helm charts für ARC in Matchpoint-AI konfigurieren A coordenação entre repositórios é essencial para atualizações de runners em projetos que usam GitHub Actions. Este guia mostra como configurar com Helm charts. Координация между репозиториями необходима для обновления runners в проектах, использующих GitHub Actions. Это руководство показывает, как настроить с помощью Helm charts. تنسيق المستودعات ضروري لتحديث التشغيل في المشاريع التي تستخدم GitHub Actions. هذا الدليل يظهر كيفية ضبط الإعدادات باستخدام Helm charts. how to use cross-repo-coordination cross-repo-coordination setup guide github actions runner scale set deployments helm charts for github actions argocd deployments cross-repo-coordination vs github actions cross-repo-coordination install what is cross-repo-coordination cross-repo-coordination alternative 跨仓库协调技能 GitHub Actions Runner Scale Set Matchpoint-AI Helm Charts ArgoCD 自动化部署 runner 配置更新 多仓库工作流协调 Defines runnerScaleSetName using Helm charts Deploys runners with ArgoCD Supports GitHub Actions workflows with self-hosted runners Enables coordinated updates across repositories using the arc-beta-runners label Integrates with project-beta ecosystem repositories Utilizes matchpoint-github-runners-helm for runner configuration cross-repo-coordination is a skill that facilitates coordinated updates across multiple GitHub repositories using Helm charts for GitHub Actions Runner Scale Set deployments.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CodeStorm-Hub/stormcomui/tailwind-ecommerce', 'community', 'CodeStorm-Hub', 'stormcomui', 'CodeStorm-Hub/stormcomui', 'tailwind-ecommerce', 0, 0, 39, '2026-03-08T01:57:15.584Z', '2026-03-08T02:11:55.481Z', '00538517542f9fc0beeebd82def7d078d5a10ad7d1141d1fd10f57df20a2163f', '{"id":"CodeStorm-Hub/stormcomui/tailwind-ecommerce","name":"tailwind-ecommerce","description":{"en":"tailwind-ecommerce provides pre-designed UI patterns for ecommerce applications, including product display, cart, checkout, and store navigation. It benefits developers and designers building online stores.","zh":"Tailwind Ecommerce 是一个使用 Tailwind CSS 构建电商 UI 的解决方案，提供产品展示、购物车、结账、订单和商店导航等功能","ja":"Tailwind Ecommerce は、AIエージェントを使用して電商 UI を作成するソリューションです。製品表示、ショッピングカート、チェックアウト、オーダー、ストアナビゲーションなどの機能を提供します","ko":"Tailwind Ecommerce는 Tailwind CSS로 이커머스 UI를 구축하는 솔루션입니다. 제품 표시, 쇼핑 카트, 체크 아웃, 주문, 스토어 네비게이션 등의 기능을 제공합니다","es":"Tailwind Ecommerce ofrece patrones de UI para comercio electrónico con Tailwind CSS, incluyendo tarjetas de producto y carrito","fr":"Tailwind Ecommerce propose des modèles d''UI pour le commerce électronique avec Tailwind CSS, y compris des cartes de produit et panier","de":"Tailwind Ecommerce bietet UI-Muster für E-Commerce mit Tailwind CSS, einschließlich Produktkarten und Warenkorb","pt":"O Tailwind Ecommerce é uma coleção de padrões de interface de usuário para comércio eletrônico, incluindo exibição de produtos, carrinho, checkout e navegação de loja","ru":"ИИ Агенты Tailwind Ecommerce - это коллекция шаблонов интерфейса пользователя для электронной коммерции, включая отображение продуктов, корзину, оформление заказа и навигацию по магазину","ar":"أدوات ذكاء الأعمال.tailwind-ecommerce هي مجموعة من أنماط واجهة المستخدم للتجارة الإلكترونية، بما في ذلك عرض المنتجات و سلة التسوق و الدفع و التنقل في المتجر"},"seo":{"title":{"en":"tailwind-ecommerce: Ecommerce UI Setup Guide | AI Agent S...","zh":"Tailwind Ecommerce 集成指南 - 使用 Tailwind CSS 搭建电商 UI","ja":"Tailwind Ecommerce セットアップガイド - AIエージェントによる電商 UI 作成","ko":"Tailwind Ecommerce 설정 가이드 - Tailwind CSS로 이커머스 UI 구축","es":"Guía de configuración de Tailwind Ecommerce para UI de co...","fr":"Guide de mise en place de Tailwind Ecommerce pour l''UI de...","de":"Einrichtungsanleitung für Tailwind Ecommerce zur UI von E...","pt":"Guia de Configuração do Tailwind Ecommerce","ru":"Настройка Инструментов ИИ Агентов для Tailwind Ecommerce","ar":"دليل إعداد أدوات ذكاء الأعمال.tailwind-ecommerce"},"description":{"en":"Unlock efficient ecommerce UI development with tailwind-ecommerce. Learn how to implement product display patterns, cart, and checkout functionality with eas...","zh":"了解如何使用 Tailwind CSS 构建电商 UI，包括产品展示、购物车、结账、订单和商店导航等功能","ja":"AIエージェントを使用して電商 UI を作成する方法を学びましょう。製品表示、ショッピングカート、チェックアウト、オーダー、ストアナビゲーションなど","ko":"Tailwind CSS로 이커머스 UI를 구축하는 방법을 알아보세요. 제품 표시, 쇼핑 카트, 체크 아웃, 주문, 스토어 네비게이션 등","es":"Aprende a crear patrones de UI de comercio electrónico con Tailwind CSS, incluyendo tarjetas de producto, carrito y pago","fr":"Découvrez comment créer des modèles d''UI de commerce électronique avec Tailwind CSS, y compris des cartes de produit, panier et paiement","de":"Erfahren Sie, wie Sie UI-Muster für E-Commerce mit Tailwind CSS erstellen, einschließlich Produktkarten, Warenkorb und Zahlung","pt":"Aprenda a criar interfaces de usuário de comércio eletrônico personalizadas com o Tailwind CSS e padrões de exibição de produtos","ru":"Мастер-skills для создания индивидуальных интерфейсов электронной коммерции с помощью Tailwind CSS и шаблонов отображения продуктов","ar":"تعلم كيفية إنشاء واجهات مستخدم خاصة بالتجارة الإلكترونية باستخدام Tailwind CSS و أنماط عرض المنتجات"},"definition":{"en":"tailwind-ecommerce is a set of reusable UI components and patterns built with Tailwind CSS, designed to streamline ecommerce development","zh":"Tailwind Ecommerce 是一个使用 Tailwind CSS 构建电商 UI 的解决方案","ja":"Tailwind Ecommerce は、AIエージェントを使用して電商 UI を作成するソリューションです","ko":"Tailwind Ecommerce는 Tailwind CSS로 이커머스 UI를 구축하는 솔루션입니다","es":"Tailwind Ecommerce es un conjunto de patrones de UI para comercio electrónico basados en Tailwind CSS","fr":"Tailwind Ecommerce est un ensemble de modèles d''UI pour le commerce électronique basés sur Tailwind CSS","de":"Tailwind Ecommerce ist eine Sammlung von UI-Mustern für E-Commerce auf Basis von Tailwind CSS","pt":"O que é Tailwind Ecommerce? É uma coleção de padrões de interface de usuário para comércio eletrônico","ru":"Что такое ИИ Агенты Tailwind Ecommerce? Это коллекция шаблонов интерфейса пользователя для электронной коммерции","ar":"ما هي أدوات ذكاء الأعمال.tailwind-ecommerce؟ هي مجموعة من أنماط واجهة المستخدم للتجارة الإلكترونية"},"features":{"en":["Generates product display patterns using aspect-ratio classes (e.g., `aspect-[3/4]`) and text styling","Supports card variants with key classes like `rounded-lg`, `border`, and `bg-white` for customizable product listings","Includes horizontal card layout using `flex` for responsive and adaptable product displays","Provides patterns for cart, checkout, orders, and store navigation using Tailwind CSS utility classes","Enables customization of product listings with price, rating, and badge elements"],"zh":["产品展示卡片变体（Simple grid card、Card with details、Horizontal card）","使用 Tailwind CSS 构建电商 UI","提供购物车、结账、订单和商店导航等功能","支持自定义 UI 组件","兼容多种设备和浏览器"],"ja":["製品表示カードバリエーション（Simple grid card、Card with details、Horizontal card）","AIエージェントを使用して電商 UI を作成","ショッピングカート、チェックアウト、オーダー、ストアナビゲーションなどの機能を提供","カスタム UI コンポーネントをサポート","複数のデバイスとブラウザに対応"],"ko":["제품 표시 카드 변형（Simple grid card、Card with details、Horizontal card）","Tailwind CSS로 이커머스 UI를 구축","쇼핑 카트, 체크 아웃, 주문, 스토어 네비게이션 등의 기능을 제공","커스텀 UI 컴포넌트를 지원","複数의 디바이스와 브라우저에 대응"],"es":["Patrones de tarjetas de producto con variantes simples y detalladas","Diseño de carrito y pago con Tailwind CSS","Navegación de tienda y patrones de orden","Utilización de clases como `aspect-[3/4]` y `rounded-lg` para diseño personalizado","Compatibilidad con diferentes dispositivos y tamaños de pantalla"],"fr":["Modèles de cartes de produit avec des variantes simples et détaillées","Conception de panier et paiement avec Tailwind CSS","Navigation de boutique et modèles de commande","Utilisation de classes comme `aspect-[3/4]` et `rounded-lg` pour personnaliser le design","Compatibilité avec différents appareils et tailles d''écran"],"de":["Produktkarten-Muster mit einfachen und detaillierten Varianten","Warenkorb- und Zahlungsdesign mit Tailwind CSS","Store-Navigation und Bestellmuster","Verwendung von Klassen wie `aspect-[3/4]` und `rounded-lg` für individualisierten Design","Kompatibilität mit verschiedenen Geräten und Bildschirmgrößen"],"pt":["Padrões de exibição de produtos personalizados","Carrinho e checkout personalizados","Navegação de loja responsiva","Integração com Tailwind CSS","Componentes de interface de usuário reutilizáveis"],"ru":["Индивидуальные шаблоны отображения продуктов","Персонализированная корзина и оформление заказа","Адаптивная навигация по магазину","Интеграция с Tailwind CSS","Переиспользуемые компоненты интерфейса пользователя"],"ar":["أنماط عرض منتجات مخصصة","سلة تسوق و دفع مخصصين","تنقل متجر مستجيب","دمج مع Tailwind CSS","مكونات واجهة المستخدم قابلة لإعادة الاستخدام"]},"keywords":{"en":["how to use tailwind-ecommerce","tailwind-ecommerce setup guide","tailwind-ecommerce vs bootstrap","tailwind-ecommerce install","what is tailwind-ecommerce","tailwind-ecommerce alternative","tailwind-ecommerce tutorial","tailwind-ecommerce documentation","tailwind-ecommerce examples"],"zh":["Tailwind Ecommerce","Tailwind CSS","电商 UI","产品展示","购物车","结账","订单","商店导航","AIエージェント"],"ja":["Tailwind Ecommerce","Tailwind CSS","電商 UI","製品表示","ショッピングカート","チェックアウト","オーダー","ストアナビゲーション","AIエージェント"],"ko":["Tailwind Ecommerce","Tailwind CSS","이커머스 UI","제품 표시","쇼핑 카트","체크 아웃","주문","스토어 네비게이션","AI 에이전트"],"es":["Tailwind Ecommerce","UI de comercio electrónico","patrones de tarjetas de producto","carrito y pago","navegación de tienda","Tailwind CSS","diseño personalizado","compatibilidad con dispositivos"],"fr":["Tailwind Ecommerce","UI de commerce électronique","modèles de cartes de produit","panier et paiement","navigation de boutique","Tailwind CSS","conception personnalisée","compatibilité avec les appareils"],"de":["Tailwind Ecommerce","UI von E-Commerce","Produktkarten-Muster","Warenkorb und Zahlung","Store-Navigation","Tailwind CSS","individualisierten Design","Kompatibilität mit Geräten"],"pt":["tailwind ecommerce","comércio eletrônico","interface de usuário","padrões de exibição de produtos","carrinho e checkout","navegação de loja","tailwind css"],"ru":["ИИ Агенты Tailwind Ecommerce","электронная коммерция","интерфейс пользователя","шаблоны отображения продуктов","корзина и оформление заказа","навигация по магазину","tailwind css"],"ar":["أدوات ذكاء الأعمال.tailwind-ecommerce","التجارة الإلكترونية","واجهة المستخدم","أنماط عرض المنتجات","سلة التسوق و الدفع","التنقل في المتجر","tailwind css"]}},"owner":"CodeStorm-Hub","repo":"stormcomui","repoPath":"CodeStorm-Hub/stormcomui","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.584Z","topics":[],"category":"community","skillMd":{"name":"tailwind-ecommerce","description":"Use when building ecommerce interfaces, product pages, shopping carts, checkout flows, order management, or store navigation with Tailwind CSS. Covers product cards, product lists, product detail pages, category filters, shopping cart, checkout forms, order summaries, order history, pricing displays, promo sections, reviews, ratings, store navigation, category previews, inventory badges, wishlist buttons, compare features.","bodyPreview":"# Ecommerce UI with Tailwind CSS\n\nPatterns for product display, cart, checkout, orders, and store navigation.\n\n---\n\n## 1. Product Display Patterns\n\n### Card Variants\n\n| Variant | Key Classes | Use Case |\n|---------|-------------|----------|\n| Simple grid card | `aspect-[3/4] w-full object-cover` + text below image | Category pages, minimal listings |\n| Card with details | `rounded-lg border bg-white shadow-sm` + price, rating, badge | Product listings, search results |\n| Horizontal card | `flex","body":"# Ecommerce UI with Tailwind CSS\n\nPatterns for product display, cart, checkout, orders, and store navigation.\n\n---\n\n## 1. Product Display Patterns\n\n### Card Variants\n\n| Variant | Key Classes | Use Case |\n|---------|-------------|----------|\n| Simple grid card | `aspect-[3/4] w-full object-cover` + text below image | Category pages, minimal listings |\n| Card with details | `rounded-lg border bg-white shadow-sm` + price, rating, badge | Product listings, search results |\n| Horizontal card | `flex flex-row gap-4` + image left, details right | Cart items, wishlists, comparisons |\n| Quick view overlay | `group relative` + `opacity-0 group-hover:opacity-100` overlay CTA | Browse-and-add flows |\n| Featured card | `col-span-2 row-span-2` + larger image | Homepage hero products |\n\n### Image Handling\n\n| Concern | Pattern | Classes |\n|---------|---------|---------|\n| Aspect ratio | Fixed ratio container | `aspect-square`, `aspect-[3/4]`, `aspect-[4/3]` |\n| Fill behavior | Cover without distortion | `object-cover w-full h-full` |\n| Responsive sizing | Fluid width, fixed aspect | `w-full` on container, aspect ratio on `<img>` |\n| Placeholder | Background color fallback | `bg-gray-100` on container |\n| Hover zoom | Scale on group hover | `transition-transform duration-300 group-hover:scale-105` |\n| Lazy loading | Native attribute | `loading=\"lazy\"` on `<img>` |\n\n### Price Display\n\n| Scenario | Pattern |\n|----------|---------|\n| Regular price | `<span class=\"text-lg font-semibold text-gray-900\">$49.99</span>` |\n| Sale price | Original: `line-through text-gray-500 text-sm` / Sale: `text-lg font-semibold text-red-600` |\n| Price range | `From $29.99` with `text-sm text-gray-500` prefix |\n| Currency symbol | Keep symbol adjacent, no wrapping: `whitespace-nowrap` |\n\n### Rating Display\n\n| Element | Classes |\n|---------|---------|\n| Star icon (filled) | `size-4 text-yellow-400 fill-current` |\n| Star icon (empty) | `size-4 text-gray-300 fill-current` |\n| Half star | Clip filled star at 50% with `overflow-hidden w-2` wrapper |\n| Review count | `text-sm text-gray-500 ml-1` next to stars |\n| Container | `flex items-center gap-0.5` |\n\n---\n\n## 2. Product List Layouts\n\n### Responsive Grid\n\n```html\n<div class=\"grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4\">\n  <!-- Product cards -->\n</div>\n```\n\n### Layout Patterns\n\n| Layout | Classes | When to Use |\n|--------|---------|-------------|\n| Grid (default) | `grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6` | Category pages, search results |\n| Two-column wide | `grid grid-cols-1 md:grid-cols-2 gap-8` | Featured products, comparisons |\n| List view | `flex flex-col divide-y` with horizontal cards | Detail-heavy browsing |\n| Masonry-style | `columns-2 lg:columns-3 gap-4` | Visual-heavy catalogs |\n\n### Loading and Pagination\n\n| Pattern | Implementation |\n|---------|---------------|\n| Skeleton card | `animate-pulse` with `bg-gray-200 rounded` blocks matching card layout |\n| Skeleton image | `aspect-[3/4] bg-gray-200 rounded-lg animate-pulse` |\n| Skeleton text | `h-4 bg-gray-200 rounded w-3/4 animate-pulse` |\n| Load more button | `w-full py-3 border rounded-lg text-center` below grid |\n| Pagination | `flex items-center gap-2` with numbered buttons, active: `bg-indigo-600 text-white` |\n| Infinite scroll | Intersection observer on sentinel div at grid end |\n| Empty state | `text-center py-16` with icon, heading, and CTA |\n\n---\n\n## 3. Category and Filtering\n\n### Sidebar Filter Panel (Desktop)\n\n| Element | Classes |\n|---------|---------|\n| Panel container | `w-64 shrink-0 hidden lg:block` |\n| Filter group | `border-b py-4` with heading + options |\n| Group heading | `font-medium text-sm text-gray-900 mb-3` |\n| Checkbox + label | `flex items-center gap-2 text-sm text-gray-600` |\n| Color swatch | `size-6 rounded-full border-2` + `ring-2 ring-offset-2 ring-indigo-500` when active |\n| Price range | Two `input[type=number]` with `w-20` in a `flex gap-2 items-center` row |\n| Apply button | `w-full mt-3 py-2 bg-indigo-600 text-white rounded-lg text-sm` |\n\n### Mobile Filter (Slide-out Dialog)\n\n| Element | Classes |\n|---------|---------|\n| Trigger button | `lg:hidden flex items-center gap-2 border rounded-lg px-4 py-2` |\n| Backdrop | `fixed inset-0 bg-black/25 z-40` |\n| Panel | `fixed inset-y-0 right-0 w-full max-w-sm bg-white z-50 overflow-y-auto` |\n| Header | `flex items-center justify-between px-4 py-3 border-b` |\n| Footer | `sticky bottom-0 bg-white border-t px-4 py-3` with Apply/Clear buttons |\n\n### Active Filters and Sorting\n\n| Element | Classes |\n|---------|---------|\n| Filter chip | `inline-flex items-center gap-1 rounded-full bg-gray-100 px-3 py-1 text-sm` |\n| Remove button | `size-4 text-gray-400 hover:text-gray-600` (X icon inside chip) |\n| Clear all link | `text-sm text-indigo-600 hover:text-indigo-800` |\n| Sort dropdown | `select` or custom dropdown, `text-sm border rounded-lg px-3 py-2` |\n| Result count | `text-sm text-gray-500` (e.g., \"128 products\") |\n| Filter count badge | `size-5 rounded-full bg-indigo-600 text-white text-xs flex items-center justify-center` |\n\n---\n\n## 4. Shopping Cart\n\n### Cart Item Row\n\n```html\n<div class=\"flex gap-4 py-4 border-b\">\n  <img class=\"size-20 rounded-lg object-cover shrink-0\" src=\"...\" alt=\"...\" />\n  <div class=\"flex flex-1 flex-col justify-between\">\n    <div class=\"flex justify-between\">\n      <div>\n        <h3 class=\"text-sm font-medium text-gray-900\">Product Name</h3>\n        <p class=\"mt-1 text-sm text-gray-500\">Color / Size</p>\n      </div>\n      <p class=\"text-sm font-medium text-gray-900\">$49.99</p>\n    </div>\n    <div class=\"flex items-center justify-between\">\n      <!-- Quantity selector -->\n      <div class=\"flex items-center rounded-lg border\">\n        <button class=\"px-3 py-1 text-gray-600\">-</button>\n        <span class=\"px-3 py-1 border-x text-sm\">1</span>\n        <button class=\"px-3 py-1 text-gray-600\">+</button>\n      </div>\n      <button class=\"text-sm text-red-600 hover:text-red-800\">Remove</button>\n    </div>\n  </div>\n</div>\n```\n\n### Cart Sections\n\n| Section | Classes | Content |\n|---------|---------|---------|\n| Cart list | `divide-y` | Cart item rows |\n| Summary panel | `rounded-lg bg-gray-50 p-6 lg:w-80 lg:shrink-0` | Subtotal, shipping, tax, total |\n| Summary row | `flex justify-between text-sm text-gray-600 py-2` | Label + amount |\n| Total row | `flex justify-between text-base font-semibold text-gray-900 border-t pt-4 mt-4` | Total label + amount |\n| Checkout CTA | `w-full mt-6 py-3 bg-indigo-600 text-white rounded-lg font-medium` | \"Proceed to Checkout\" |\n| Continue shopping | `text-sm text-indigo-600 hover:text-indigo-800 mt-4 text-center block` | Link back |\n\n### Cart States\n\n| State | Pattern |\n|-------|---------|\n| Empty cart | `text-center py-16` with cart icon, \"Your cart is empty\" heading, shop CTA |\n| Mini cart / drawer | `fixed inset-y-0 right-0 w-full max-w-md bg-white shadow-xl z-50` |\n| Cart badge | `absolute -top-2 -right-2 size-5 rounded-full bg-indigo-600 text-white text-xs flex items-center justify-center` |\n| Updating state | `opacity-50 pointer-events-none` on item row during async update |\n\n---\n\n## 5. Checkout Flow\n\n### Progress Indicator\n\n| Step State | Classes |\n|------------|---------|\n| Completed | `size-8 rounded-full bg-indigo-600 text-white` with check icon |\n| Current | `size-8 rounded-full border-2 border-indigo-600 text-indigo-600` |\n| Upcoming | `size-8 rounded-full border-2 border-gray-300 text-gray-400` |\n| Connector (done) | `h-0.5 w-full bg-indigo-600` between circles |\n| Connector (pending) | `h-0.5 w-full bg-gray-300` between circles |\n| Container | `flex items-center justify-between max-w-lg mx-auto mb-8` |\n\n### Form Layout\n\n| Section | Structure |\n|---------|-----------|\n| Two-column layout | `grid grid-cols-1 lg:grid-cols-5 gap-8` (3 cols form + 2 cols summary) |\n| Field group | `space-y-4` container |\n| Two-field row | `grid grid-cols-2 gap-4` (first/last name, city/zip) |\n| Full-width field | `col-span-2` or standalone |\n| Label | `block text-sm font-medium text-gray-700 mb-1` |\n| Input | `w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500` |\n| Error input | `border-red-500 focus:border-red-500 focus:ring-red-500` |\n| Error message | `text-sm text-red-600 mt-1` |\n\n### Payment Fields\n\n| Element | Pattern |\n|---------|---------|\n| Card number | Full-width input with card icon right-aligned |\n| Expiry + CVC | `grid grid-cols-2 gap-4` side by side |\n| Card group | `rounded-lg border divide-y` wrapping all card fields as one visual unit |\n| Saved cards | Radio group: `flex items-center gap-3 p-4 border rounded-lg` per card |\n| Security note | `flex items-center gap-2 text-sm text-gray-500` with lock icon |\n\n### Checkout Patterns\n\n| Pattern | Implementation |\n|---------|---------------|\n| Guest vs account | Toggle or tabs at top: `flex rounded-lg border` with two options |\n| Order review | Summary card: item thumbnails, quantities, line totals in `bg-gray-50 rounded-lg p-6` |\n| Place order CTA | `w-full py-3 bg-indigo-600 text-white rounded-lg font-medium text-lg` |\n| Terms checkbox | `flex items-start gap-2` with checkbox and label text |\n| Loading on submit | Button with `opacity-75 cursor-not-allowed` + spinner icon |\n\n---\n\n## 6. Order Management\n\n### Order History Table\n\n| Viewport | Pattern |\n|----------|---------|\n| Desktop | Standard `<table>` with columns: Order #, Date, Status, Total, Actions |\n| Mobile | Stacked cards: `divide-y` with each order as a `flex flex-col gap-2 py-4` block |\n| Table header | `text-left text-sm font-medium text-gray-500 pb-3 border-b` |\n| Table cell | `py-4 text-sm text-gray-900` |\n\n### Order Status Badges\n\n| Status | Classes |\n|--------|---------|\n| Pending | `bg-yellow-100 text-yellow-800 rounded-full px-2.5 py-0.5 text-xs font-medium` |\n| Processing | `bg-blue-100 text-blue-800 rounded-full px-2.5 py-0.5 text-xs font-medium` |\n| Shipped | `bg-indigo-100 text-indigo-800 rounded-full px-2.5 py-0.5 text-xs font-medium` |\n| Delivered | `bg-green-100 text-green-800 rounded-full px-2.5 py-0.5 text-xs font-medium` |\n| Cancelled | `bg-red-100 text-red-800 rounded-full px-2.5 py-0.5 text-xs font-medium` |\n| Refunded | `bg-gray-100 text-gray-800 rounded-full px-2.5 py-0.5 text-xs font-medium` |\n\n### Order Detail Page\n\n| Section | Pattern |\n|---------|---------|\n| Status timeline | Vertical: `relative pl-8 space-y-6` with `absolute left-0` circles and connecting line |\n| Timeline dot (done) | `size-4 rounded-full bg-indigo-600` |\n| Timeline dot (current) | `size-4 rounded-full border-2 border-indigo-600 bg-white` |\n| Timeline line | `absolute left-2 top-4 bottom-0 w-0.5 bg-gray-200` |\n| Items list | Horizontal cards with image, name, qty, price |\n| Totals section | Same pattern as cart summary |\n| Shipping address | `bg-gray-50 rounded-lg p-4` card |\n| Invoice layout | `max-w-2xl mx-auto` with logo header, address block, items table, totals |\n\n---\n\n## 7. Pricing and Promotions\n\n### Price Patterns\n\n| Pattern | Implementation |\n|---------|---------------|\n| Original + sale | `<span class=\"line-through text-gray-500 text-sm\">$99.99</span> <span class=\"text-lg font-semibold text-red-600\">$49.99</span>` |\n| Save amount | `<span class=\"text-sm text-green-600 font-medium\">Save $50.00 (50%)</span>` |\n| Per-unit price | `<span class=\"text-xs text-gray-500\">$2.50/oz</span>` below main price |\n\n### Discount Badge (on Product Image)\n\n```html\n<div class=\"relative\">\n  <img class=\"aspect-[3/4] w-full rounded-lg object-cover\" src=\"...\" alt=\"...\" />\n  <span class=\"absolute top-2 left-2 rounded-full bg-red-600 px-2.5 py-0.5 text-xs font-semibold text-white\">\n    -50%\n  </span>\n</div>\n```\n\n### Pricing Tier Cards\n\n| Element | Classes |\n|---------|---------|\n| Card container | `rounded-xl border p-6 text-center` |\n| Featured card | `border-indigo-600 ring-2 ring-indigo-600 relative` with \"Popular\" badge |\n| Price | `text-4xl font-bold text-gray-900` |\n| Period | `text-sm text-gray-500` (e.g., \"/month\") |\n| Feature list | `space-y-3 text-sm text-gray-600` with check icons |\n| CTA button | `w-full mt-6 py-2.5 rounded-lg font-medium` |\n\n### Promo and Incentive Sections\n\n| Pattern | Classes |\n|---------|---------|\n| Full-width banner | `bg-indigo-600 text-white py-3 text-center text-sm font-medium` |\n| Dismissable banner | Add `flex items-center justify-between px-4` with close button |\n| Trust icons row | `grid grid-cols-2 md:grid-cols-4 gap-6 py-8 text-center` |\n| Trust icon item | `flex flex-col items-center gap-2 text-sm text-gray-600` with icon above |\n| Coupon input | `flex` with `flex-1 rounded-l-lg border px-3 py-2` input + `rounded-r-lg bg-gray-900 text-white px-4 py-2` button |\n\n---\n\n## 8. Store Navigation\n\n### Store Header\n\n| Element | Classes |\n|---------|---------|\n| Header bar | `sticky top-0 z-30 bg-white border-b` |\n| Inner layout | `flex items-center justify-between h-16 px-4 max-w-7xl mx-auto` |\n| Logo | `shrink-0` |\n| Search bar | `flex-1 max-w-lg mx-8 hidden md:block` with `rounded-full bg-gray-100 px-4 py-2` |\n| Icon group | `flex items-center gap-4` for account, wishlist, cart icons |\n| Cart icon + badge | `relative` button with `absolute -top-1.5 -right-1.5` badge |\n\n### Mega Menu\n\n| Element | Classes |\n|---------|---------|\n| Trigger | `group` on nav item |\n| Dropdown | `invisible group-hover:visible opacity-0 group-hover:opacity-100 transition-all absolute left-0 w-full bg-white shadow-lg border-t` |\n| Inner grid | `grid grid-cols-4 gap-8 max-w-7xl mx-auto p-8` |\n| Column heading | `font-medium text-sm text-gray-900 mb-3` |\n| Column links | `space-y-2 text-sm text-gray-600` |\n| Featured image | `rounded-lg overflow-hidden` in last column |\n\n### Category Previews and Breadcrumbs\n\n| Element | Classes |\n|---------|---------|\n| Category card | `group relative rounded-xl overflow-hidden` |\n| Category image | `aspect-[4/3] w-full object-cover transition-transform group-hover:scale-105` |\n| Category overlay | `absolute inset-0 bg-gradient-to-t from-black/60 to-transparent` |\n| Category label | `absolute bottom-4 left-4 text-lg font-semibold text-white` |\n| Breadcrumb nav | `flex items-center gap-2 text-sm text-gray-500` |\n| Breadcrumb separator | `size-4 text-gray-400` (chevron icon) |\n| Breadcrumb current | `text-gray-900 font-medium` (last item, no link) |\n\n---\n\n## 9. Accessibility for Ecommerce\n\n| Element | Requirement | Implementation |\n|---------|-------------|----------------|\n| Product image | Descriptive alt text | `alt=\"Red leather crossbody bag\"` not `alt=\"product\"` |\n| Decorative image | Skip for screen readers | `alt=\"\"` and `aria-hidden=\"true\"` |\n| Sale price | Announce was/now | `aria-label=\"Sale price $49.99, originally $99.99\"` on container |\n| Cart update | Announce change | `aria-live=\"polite\"` region for \"Item added\" / \"Cart updated\" messages |\n| Cart count badge | Announce count | `aria-label=\"Cart, 3 items\"` on cart button |\n| Quantity selector | Label buttons | `aria-label=\"Decrease quantity\"` / `aria-label=\"Increase quantity\"` |\n| Star rating | Text alternative | `aria-label=\"4 out of 5 stars\"` on rating container |\n| Filter change | Announce results | `aria-live=\"polite\"` on product count (\"128 results\") |\n| Form errors | Link to field | `aria-describedby=\"email-error\"` on input, matching `id` on error text |\n| Checkout steps | Current step | `aria-current=\"step\"` on active step indicator |\n| Remove from cart | Confirm action | Identify item in label: `aria-label=\"Remove Red Bag from cart\"` |\n| Sort dropdown | Label purpose | `aria-label=\"Sort products by\"` on select element |\n| Color swatch | Name the color | `aria-label=\"Color: Navy Blue\"` on swatch button |\n| Dialog filters | Trap focus | `role=\"dialog\"` + `aria-modal=\"true\"` + focus trap on mobile filter panel |\n\n---\n\n## Common Mistakes\n\n| Mistake | Fix |\n|---------|-----|\n| Fixed pixel image heights | Use `aspect-*` utilities with `object-cover` for responsive images |\n| Cart with no empty state | Always handle zero items with illustration and CTA |\n| Price without `whitespace-nowrap` | Currency and amount should not wrap to separate lines |\n| Filter panel always visible on mobile | Hide with `hidden lg:block`, use dialog for mobile |\n| No loading state during cart updates | Show `opacity-50 pointer-events-none` or skeleton on async actions |\n| Checkout form in single column | Use `grid grid-cols-2 gap-4` for name, city/zip, expiry/CVC pairs |\n| Status badges with only color | Add text labels; color alone fails WCAG |\n| Missing `aria-live` on cart | Cart count and summary changes must announce to screen readers |\n| Mega menu not keyboard-navigable | Ensure focus management and Escape key closes the menu |\n| Discount badge over product text | Position badge on image (`absolute top-2 left-2`), not over card text |\n\n## MCP Component Library\n\nThe `frontend-components` MCP server provides ecommerce-related components:\n\n- **HyperUI** (`hyperui`): Product cards, product collections, pricing tables, forms, badges, stats\n- **DaisyUI** (`daisyui`): Card, badge, stat, table, modal, rating, countdown class references\n- **FlyonUI** (`flyonui`): Card, badge, stat, table CSS components + datatable JS plugin\n\n**Ecommerce search:** `search_components(query: \"product\", framework: \"hyperui\")` or `search_components(query: \"pricing\")` for pricing components across all libraries.\n"},"lastSynced":"2026-03-08T02:11:55.481Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing streamlined ecommerce UI development with Tailwind CSS.","zh":"非常适合需要使用Tailwind CSS进行电子商务UI开发的前端代理。","ja":"Tailwind CSSを使用した電子商取引UI開発を必要とするフロントエンドエージェントに最適です。","ko":"Tailwind CSS를 사용하여 전자상거래 UI 개발을简化해야 하는 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan un desarrollo de interfaz de usuario de comercio electrónico optimizado con Tailwind CSS.","fr":"Parfait pour les agents Frontend qui ont besoin d''un développement d''interface utilisateur de commerce électronique rationalisé avec Tailwind CSS.","de":"Perfekt für Frontend-Agenten, die eine optimierte Entwicklung von E-Commerce-Benutzeroberflächen mit Tailwind CSS benötigen.","pt":"Perfeito para Agentes Frontend que precisam de desenvolvimento de UI de ecommerce simplificado com Tailwind CSS.","ru":"Идеально подходит для агентов Frontend, которым необходим упрощенный разработка UI для электронной коммерции с помощью Tailwind CSS.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يحتاج إلى تطوير واجهة المستخدم للتجارة الإلكترونية المبسطة مع Tailwind CSS."},"recommendation":{"en":"Empowers agents to rapidly design and deploy ecommerce applications with pre-designed UI patterns for product display, cart, checkout, and store navigation using Tailwind CSS classes like `aspect-[3/4]` and `rounded-lg border bg-white shadow-sm`.","zh":"赋予代理快速设计和部署电子商务应用程序的能力，使用Tailwind CSS类似`aspect-[3/4]`和`rounded-lg border bg-white shadow-sm`的预设计UI模式进行产品显示、购物车、结账和商店导航。","ja":"エージェントが、`aspect-[3/4]`や`rounded-lg border bg-white shadow-sm`などのTailwind CSSクラスを使用したプレデザインのUIパターンで、製品表示、カート、チェックアウト、ストアナビゲーションを行う電子商取引アプリケーションを迅速に設計してデプロイできるようにします。","ko":"에이전트가 `aspect-[3/4]`와 `rounded-lg border bg-white shadow-sm` 같은 Tailwind CSS 클래스를 사용하여 미리設計된 UI 패턴으로 제품 표시, 카트, 체크아웃, 스토어 탐색을 수행하는 전자상거래 애플리케이션을 빠르게 설계 및 배포할 수 있도록 합니다.","es":"Habilita a los agentes a diseñar y implementar rápidamente aplicaciones de comercio electrónico con patrones de interfaz de usuario pre diseñados para la visualización de productos, carrito, pago y navegación de la tienda utilizando clases de Tailwind CSS como `aspect-[3/4]` y `rounded-lg border bg-white shadow-sm`.","fr":"Permet aux agents de concevoir et de déployer rapidement des applications de commerce électronique avec des modèles d''interface utilisateur préconçus pour l''affichage de produits, le panier, la caisse et la navigation du magasin en utilisant des classes Tailwind CSS comme `aspect-[3/4]` et `rounded-lg border bg-white shadow-sm`.","de":"Ermöglicht es Agenten, E-Commerce-Anwendungen mit vorgefertigten Benutzeroberflächen-Mustern für die Anzeige von Produkten, Warenkorb, Checkout und Store-Navigation unter Verwendung von Tailwind-CSS-Klassen wie `aspect-[3/4]` und `rounded-lg border bg-white shadow-sm` schnell zu entwerfen und bereitzustellen.","pt":"Habilita os agentes a projetar e implantar rapidamente aplicações de ecommerce com padrões de UI pré-projetados para exibição de produtos, carrinho, checkout e navegação de loja usando classes Tailwind CSS como `aspect-[3/4]` e `rounded-lg border bg-white shadow-sm`.","ru":"Позволяет агентам быстро проектировать и развертывать электронные коммерческие приложения с предварительно разработанными шаблонами UI для отображения продуктов, корзины, оформления заказа и навигации по магазину, используя классы Tailwind CSS, такие как `aspect-[3/4]` и `rounded-lg border bg-white shadow-sm`.","ar":"يتمكن العميل من تصميم وتوزيع تطبيقات التجارة الإلكترونية بسرعة باستخدام أنماط واجهة المستخدم المسبقة التصميم لعرض المنتجات و车तम وعمليات الدفع وتحديد موقع المتجر باستخدام فصول Tailwind CSS مثل `aspect-[3/4]` و `rounded-lg border bg-white shadow-sm`."},"useCases":{"en":["Generating responsive product grid layouts","Customizing cart and checkout interfaces with Tailwind CSS utility classes","Implementing store navigation patterns with pre-designed UI components"],"zh":["生成响应式产品网格布局","使用Tailwind CSS实用程序类自定义购物车和结账界面","使用预设计UI组件实现商店导航模式"],"ja":["レスポンシブ製品グリッドレイアウトを生成する","Tailwind CSSユーティリティクラスを使用してカートとチェックアウトインターフェイスをカスタマイズする","プレデザインのUIコンポーネントを使用してストアナビゲーションパターンを実装する"],"ko":["반응형 제품 그리드 레이아웃 생성","Tailwind CSS 유틸리티 클래스를 사용하여 카트 및 체크아웃 인터페이스 사용자 지정","미리 설계된 UI 구성 요소를 사용하여 스토어 탐색 패턴 구현"],"es":["Generación de diseños de cuadrícula de productos responsivos","Personalización de interfaces de carrito y pago con clases de utilidad de Tailwind CSS","Implementación de patrones de navegación de la tienda con componentes de interfaz de usuario pre diseñados"],"fr":["Génération de mises en page de grille de produits responsives","Personnalisation des interfaces de panier et de caisse avec des classes d''utilité de Tailwind CSS","Mise en œuvre de modèles de navigation du magasin avec des composants d''interface utilisateur préconçus"],"de":["Erzeugung responsiver Produkt-Raster-Layouts","Anpassung von Warenkorb- und Checkout-Schnittstellen mit Tailwind-CSS-Utility-Klassen","Implementierung von Store-Navigationsmustern mit vorgefertigten Benutzeroberflächen-Komponenten"],"pt":["Geração de layouts de grade de produtos responsivos","Personalização de interfaces de carrinho e checkout com classes de utilidade Tailwind CSS","Implementação de padrões de navegação de loja com componentes de UI pré-projetados"],"ru":["Генерация адаптивных макетов сетки продуктов","Настройка интерфейсов корзины и оформления заказа с помощью классов утилиты Tailwind CSS","Реализация шаблонов навигации по магазину с предварительно разработанными компонентами UI"],"ar":["генерация تخطيطات شبكية للمنتجات المستجيبة","تخصيص واجهات عربة التسوق وعمليات الدفع باستخدام فصول أداةTailwind CSS","تنفيذ أنماط تحديد موقع المتجر مع مكونات واجهة المستخدم المسبقة التصميم"]},"limitations":{"en":["Requires knowledge of Tailwind CSS and its utility-first approach","Limited to ecommerce applications","Tailwind CSS version compatibility required"],"zh":["需要了解Tailwind CSS及其实用优先方法","仅限电子商务应用程序","需要Tailwind CSS版本兼容性"],"ja":["Tailwind CSSとそのユーティリティファーストアプローチの知識が必要","電子商取引アプリケーションに限定","Tailwind CSSバージョンの互換性が必要"],"ko":["Tailwind CSS 및 그 유틸리티 우선 접근 방식에 대한 지식이 필요","전자상거래 애플리케이션에만 제한","Tailwind CSS 버전 호환성이 필요"],"es":["Requiere conocimiento de Tailwind CSS y su enfoque de utilidad primero","Limitado a aplicaciones de comercio electrónico","Se requiere compatibilidad con la versión de Tailwind CSS"],"fr":["Nécessite une connaissance de Tailwind CSS et de son approche utilitaire en premier","Limité aux applications de commerce électronique","La compatibilité avec la version de Tailwind CSS est requise"],"de":["Benötigt Kenntnisse von Tailwind CSS und seinem utility-first-Ansatz","Begrenzt auf E-Commerce-Anwendungen","Tailwind-CSS-Version-Kompatibilität ist erforderlich"],"pt":["Exige conhecimento de Tailwind CSS e sua abordagem baseada em utilidade","Limitado a aplicações de ecommerce","Requer compatibilidade de versão do Tailwind CSS"],"ru":["Требует знания Tailwind CSS и его подхода, основанного на утилитах","Ограничен электронными коммерческими приложениями","Требует совместимости версий Tailwind CSS"],"ar":["يتطلب معرفة Tailwind CSS ومنهجها القائم على الأداة","محدود لتطبيقات التجارة الإلكترونية","يتطلب توافق إصدار Tailwind CSS"]},"version":4},"contentHash":"00538517542f9fc0beeebd82def7d078d5a10ad7d1141d1fd10f57df20a2163f","qualityScore":39}');
