INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CodeStorm-Hub/stormcomui/tailwind-ecommerce', 'tailwind-ecommerce', 'CodeStorm-Hub', 'stormcomui', 'community', 'tailwind-ecommerce CodeStorm-Hub stormcomui community tailwind-ecommerce provides pre-designed UI patterns for ecommerce applications, including product display, cart, checkout, and store navigation. It benefits developers and designers building online stores. Tailwind Ecommerce 是一个使用 Tailwind CSS 构建电商 UI 的解决方案，提供产品展示、购物车、结账、订单和商店导航等功能 Tailwind Ecommerce は、AIエージェントを使用して電商 UI を作成するソリューションです。製品表示、ショッピングカート、チェックアウト、オーダー、ストアナビゲーションなどの機能を提供します Tailwind Ecommerce는 Tailwind CSS로 이커머스 UI를 구축하는 솔루션입니다. 제품 표시, 쇼핑 카트, 체크 아웃, 주문, 스토어 네비게이션 등의 기능을 제공합니다 Tailwind Ecommerce ofrece patrones de UI para comercio electrónico con Tailwind CSS, incluyendo tarjetas de producto y carrito Tailwind Ecommerce propose des modèles d''UI pour le commerce électronique avec Tailwind CSS, y compris des cartes de produit et panier Tailwind Ecommerce bietet UI-Muster für E-Commerce mit Tailwind CSS, einschließlich Produktkarten und Warenkorb O Tailwind Ecommerce é uma coleção de padrões de interface de usuário para comércio eletrônico, incluindo exibição de produtos, carrinho, checkout e navegação de loja ИИ Агенты Tailwind Ecommerce - это коллекция шаблонов интерфейса пользователя для электронной коммерции, включая отображение продуктов, корзину, оформление заказа и навигацию по магазину أدوات ذكاء الأعمال.tailwind-ecommerce هي مجموعة من أنماط واجهة المستخدم للتجارة الإلكترونية، بما في ذلك عرض المنتجات و سلة التسوق و الدفع و التنقل في المتجر how to use tailwind-ecommerce tailwind-ecommerce setup guide tailwind-ecommerce vs bootstrap tailwind-ecommerce install what is tailwind-ecommerce tailwind-ecommerce alternative tailwind-ecommerce tutorial tailwind-ecommerce documentation tailwind-ecommerce examples Tailwind Ecommerce Tailwind CSS 电商 UI 产品展示 购物车 结账 订单 商店导航 AIエージェント Generates product display patterns using aspect-ratio classes (e.g., `aspect-[3/4]`) and text styling Supports card variants with key classes like `rounded-lg`, `border`, and `bg-white` for customizable product listings Includes horizontal card layout using `flex` for responsive and adaptable product displays Provides patterns for cart, checkout, orders, and store navigation using Tailwind CSS utility classes Enables customization of product listings with price, rating, and badge elements tailwind-ecommerce is a set of reusable UI components and patterns built with Tailwind CSS, designed to streamline ecommerce development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RamboRogers/cyber-inference/run-thor', 'community', 'RamboRogers', 'cyber-inference', 'RamboRogers/cyber-inference', 'run-thor', 0, 0, 39, '2026-03-08T01:57:15.588Z', '2026-03-08T02:11:58.371Z', '7fc61fe5b2a40c54879d5f161638fc8c35015242978dc4bd1acf530d54db165a', '{"id":"RamboRogers/cyber-inference/run-thor","name":"run-thor","description":{"en":"run-thor is a web GUI management tool for running OpenAI-compatible inference servers, providing automatic model management and dynamic resource allocation for edge deployment. It benefits developers and testers working with AI models.","zh":"Run-Thor 是 Cyber-Inference 的一部分，用于在 Thor GPU 服务器上部署和测试。它提供了自动模型管理和动态资源分配","ja":"Run-Thor は Cyber-Inference の一部で、Thor GPU サーバーでデプロイしてテストするために使用されます。自動モデル管理と動的リソース割り当てを提供します","ko":"Run-Thor는 Cyber-Inference의 일부입니다. Thor GPU 서버에서 배포하고 테스트하는 데 사용되며 자동 모델 관리 및 동적 리소스 할당을 제공합니다","es":"run-thor es una herramienta de administración de GUI web para servidores de inferencia compatibles con OpenAI, con características como administración de modelos automáticos y asignación de recursos dinámicos","fr":"run-thor est un outil de gestion GUI web pour les serveurs d''inférence compatibles OpenAI, doté de fonctionnalités telles que la gestion automatique de modèles et l''allocation de ressources dynamiques","de":"run-thor ist ein Web-GUI-Verwaltungstool für OpenAI-kompatible Inferenzserver mit Funktionen wie automatischer Modellverwaltung und dynamischer Ressourcenzuweisung","pt":"O run-thor é uma ferramenta de gerenciamento de inferência de IA que fornece alocação de recursos dinâmicos e uma interface temática cyberpunk","ru":"Run-thor - это инструмент ИИ Агентов для инференции, который предоставляет динамическое распределение ресурсов и красивый интерфейс в стиле киберпанк","ar":"run-thor هو أداة إدارة الاستدلال الاصطناعي التي توفر تخصيص الموارد الديناميكي وواجهة مستخدم темاتية كيبيربانك"},"seo":{"title":{"en":"run-thor: Deployment Setup Guide | AI Agent Skill","zh":"Run-Thor 设置指南：Cyber-Inference 的 GPU 部署","ja":"Run-Thor セットアップガイド：Cyber-Inference の GPU デプロイ","ko":"Run-Thor 설정 가이드: Cyber-Inference의 GPU 배포","es":"Guía de configuración de run-thor para agentes de IA","fr":"Guide de configuration de run-thor pour les outils d''IA","de":"Einrichtungsleitfaden für run-thor: KI-Agenten-Tool","pt":"Guia de Configuração do run-thor: Ferramenta de Inferênci...","ru":"Настройка run-thor: Инструмент ИИ Агентов для Инференции","ar":"دليل إعداد run-thor: أداة الاستدلال الاصطناعي"},"description":{"en":"Discover how to deploy and test run-thor on Thor, the GPU lab server, and unlock its cyberpunk-themed interface for edge deployment - get started now!","zh":"学习如何在 Thor GPU 服务器上部署和测试 Cyber-Inference，实现自动模型管理和动态资源分配","ja":"Thor GPU サーバーで Cyber-Inference をデプロイしてテストする方法を学び、自動モデル管理と動的リソース割り当てを実現します","ko":"Thor GPU 서버에서 Cyber-Inference를 배포하고 테스트하는 방법을 배우고 자동 모델 관리 및 동적 리소스 할당을 구현하세요","es":"Aprende a configurar run-thor para despliegues de bordes con servidor de inferencia compatible con OpenAI y administración de modelos automáticos","fr":"Découvrez comment configurer run-thor pour des déploiements d''edge avec serveur d''inférence compatible OpenAI et gestion de modèles automatique","de":"Erfahren Sie, wie Sie run-thor für Edge-Deployments mit OpenAI-kompatiblen Inferenzservern und automatischer Modellverwaltung konfigurieren","pt":"Aprenda a configurar o run-thor, uma ferramenta de gerenciamento de inferência de IA compatível com OpenAI, com recursos de alocação de recursos dinâmicos","ru":"Узнайте, как настроить run-thor, инструмент ИИ Агентов для инференции, совместимый с OpenAI, с функциями динамического распределения ресурсов","ar":"تعرف على كيفية إعداد run-thor، أداة إدارة الاستدلال الاصطناعي المتوافق مع OpenAI، مع ميزات تخصيص الموارد الديناميكي"},"definition":{"en":"run-thor is a cyber-inference tool built on llama.cpp, designed for managing and deploying OpenAI-compatible inference servers with a unique cyberpunk-themed interface.","zh":"Run-Thor 是一种用于在 Thor GPU 服务器上部署和测试 Cyber-Inference 的工具","ja":"Run-Thor は、Thor GPU サーバーで Cyber-Inference をデプロイしてテストするためのツールです","ko":"Run-Thor는 Thor GPU 서버에서 Cyber-Inference를 배포하고 테스트하는 데 사용되는 도구입니다","es":"run-thor es un agente de IA que proporciona una interfaz de usuario web para administrar servidores de inferencia compatibles con OpenAI","fr":"run-thor est un outil d''IA qui offre une interface utilisateur web pour gérer les serveurs d''inférence compatibles OpenAI","de":"run-thor ist ein KI-Agent, der eine Web-Benutzeroberfläche zur Verwaltung von OpenAI-kompatiblen Inferenzservern bietet","pt":"O run-thor é uma ferramenta de inferência de IA que executa servidores de inferência compatíveis com OpenAI","ru":"Run-thor - это инструмент ИИ Агентов, который запускает серверы инференции, совместимые с OpenAI","ar":"run-thor هو أداة استدلال اصطناعي تنفذ خواديم الاستدلال المتوافقة مع OpenAI"},"features":{"en":["Provides automatic model management for OpenAI-compatible inference servers","Supports dynamic resource allocation for efficient edge deployment","Offers a cyberpunk-themed interface for user-friendly interaction","Accessible via SSH for secure remote access","Hosts production-like test environment on Thor, the GPU lab server","Utilizes llama.cpp for building and managing inference servers"],"zh":["自动模型管理","动态资源分配","Cyber-Inference 的 GPU 部署","SSH 连接到 Thor 服务器","支持 llama.cpp"],"ja":["自動モデル管理","動的リソース割り当て","Cyber-Inference の GPU デプロイ","SSH 接続を Thor サーバー","llama.cpp をサポート"],"ko":["자동 모델 관리","동적 리소스 할당","Cyber-Inference의 GPU 배포","SSH 연결을 Thor 서버","llama.cpp 지원"],"es":["Administración de modelos automáticos","Asignación de recursos dinámicos","Interfaz de usuario web con tema ciberpunk","Compatibilidad con servidores de inferencia OpenAI","Despliegue de bordes","Acceso via SSH"],"fr":["Gestion automatique de modèles","Allocation de ressources dynamiques","Interface utilisateur web avec thème cyberpunk","Compatibilité avec les serveurs d''inférence OpenAI","Déploiement d''edge","Accès via SSH"],"de":["Automatisierte Modellverwaltung","Dynamische Ressourcenzuweisung","Web-Benutzeroberfläche mit Cyberpunk-Design","Kompatibilität mit OpenAI-kompatiblen Inferenzservern","Edge-Deployment","Zugriff via SSH"],"pt":["Gerenciamento de modelo automático","Alocação de recursos dinâmicos","Interface temática cyberpunk","Compatibilidade com OpenAI","Implementação em llama.cpp","Dependência de SSH para acesso"],"ru":["Автоматическое управление моделью","Динамическое распределение ресурсов","Интерфейс в стиле киберпанк","Совместимость с OpenAI","Реализация на основе llama.cpp","Зависимость от SSH для доступа"],"ar":["إدارة الطراز التلقائي","تخصيص الموارد الديناميكي","واجهة مستخدم темاتية كيبيربانك","التوافق مع OpenAI","تنفيذ على أساس llama.cpp","اعتماد على SSH للوصول"]},"keywords":{"en":["how to use run-thor","run-thor setup guide","run-thor alternative","run-thor vs llama.cpp","run-thor install","what is run-thor","run-thor deployment","run-thor testing","run-thor GPU lab server"],"zh":["AI 工具","GPU 部署","自动模型管理","动态资源分配","Cyber-Inference","llama.cpp","Thor 服务器","SSH 连接"],"ja":["AI エージェント","GPU デプロイ","自動モデル管理","動的リソース割り当て","Cyber-Inference","llama.cpp","Thor サーバー","SSH 接続"],"ko":["AI 에이전트","GPU 배포","자동 모델 관리","동적 리소스 할당","Cyber-Inference","llama.cpp","Thor 서버","SSH 연결"],"es":["agentes de IA","herramientas de IA","servidores de inferencia OpenAI","administración de modelos","asignación de recursos","despliegue de bordes","acceso via SSH","run-thor"],"fr":["outils d''IA","agents d''IA","serveurs d''inférence OpenAI","gestion de modèles","allocation de ressources","déploiement d''edge","accès via SSH","run-thor"],"de":["KI-Agenten","KI-Tools","OpenAI-kompatible Inferenzserver","Modellverwaltung","Ressourcenzuweisung","Edge-Deployment","Zugriff via SSH","run-thor"],"pt":["run-thor","ferramenta de inferência de IA","OpenAI","llama.cpp","gerenciamento de modelo"," alocação de recursos dinâmicos","interface cyberpunk","SSH","servidores de inferência","desenvolvimento de IA"],"ru":["run-thor","инструмент ИИ Агентов","OpenAI","llama.cpp","управление моделью","динамическое распределение ресурсов","интерфейс киберпанк","SSH","серверы инференции","разработка ИИ"],"ar":["run-thor","أداة استدلال اصطناعي","OpenAI","llama.cpp","إدارة الطراز","تخصيص الموارد الديناميكي","واجهة مستخدم كيبيربانك","SSH","خواديم الاستدلال","تطوير الاستدلال الاصطناعي"]}},"owner":"RamboRogers","repo":"cyber-inference","repoPath":"RamboRogers/cyber-inference","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.588Z","topics":[],"category":"community","skillMd":{"name":"run-thor","description":"Deploy and test cyber-inference on the Thor lab server. Use when the user wants to test on Thor, deploy to Thor, run on Thor, verify the server, or mentions thor.lab.","bodyPreview":"# Deploy & Test on Thor\n\nThor is the GPU lab server used for integration testing of cyber-inference. It is accessible via SSH and hosts the production-like test environment.\n\n## Connection Details\n\n| Field | Value |\n|-------|-------|\n| Host | `thor.lab` |\n| User | `matt` |\n| SSH | `ssh matt@thor.lab` |\n| Project path | `/home/matt/Local/cyber-inference` |\n| Server URL | `http://thor.lab:8337` |\n\n## Deploy Workflow\n\nFollow these steps in order. Each depends on the previous.\n\n### 1. Commit & Push","body":"# Deploy & Test on Thor\n\nThor is the GPU lab server used for integration testing of cyber-inference. It is accessible via SSH and hosts the production-like test environment.\n\n## Connection Details\n\n| Field | Value |\n|-------|-------|\n| Host | `thor.lab` |\n| User | `matt` |\n| SSH | `ssh matt@thor.lab` |\n| Project path | `/home/matt/Local/cyber-inference` |\n| Server URL | `http://thor.lab:8337` |\n\n## Deploy Workflow\n\nFollow these steps in order. Each depends on the previous.\n\n### 1. Commit & Push (local machine)\n\n```bash\ngit add -A && git commit -m \"<message>\" && git push\n```\n\n### 2. Pull on Thor (remote)\n\n```bash\nssh matt@thor.lab \"cd /home/matt/Local/cyber-inference && git pull\"\n```\n\n### 3. Start the Server (remote)\n\nThe server runs via `start.sh` which handles `uv sync` and auto-restart.\n\n```bash\n# Interactive (see logs live) - use for debugging\nssh -t matt@thor.lab \"cd /home/matt/Local/cyber-inference && ./start.sh\"\n\n# Background (detached) - use for long-running tests\nssh matt@thor.lab \"cd /home/matt/Local/cyber-inference && nohup ./start.sh > /tmp/cyber-inference.log 2>&1 &\"\n```\n\nCUDA PyTorch wheels are verified automatically when NVIDIA hardware is detected.\n\n### 4. Verify the Server\n\n```bash\n# Health check\ncurl -s http://thor.lab:8337/health\n\n# List models\ncurl -s http://thor.lab:8337/v1/models | python3 -m json.tool\n\n# System status\ncurl -s http://thor.lab:8337/admin/status | python3 -m json.tool\n\n```\n\nThe web GUI is available at: `http://thor.lab:8337`\n\n### 5. Test Inference\n\n```bash\n# Chat completion\ncurl -s http://thor.lab:8337/v1/chat/completions \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\"model\": \"<model_name>\", \"messages\": [{\"role\": \"user\", \"content\": \"Hello\"}]}'' \\\n  | python3 -m json.tool\n\n# Embeddings\ncurl -s http://thor.lab:8337/v1/embeddings \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\"model\": \"<model_name>\", \"input\": \"test text\"}'' \\\n  | python3 -m json.tool\n```\n\n## Quick One-Liner Deploy\n\nPull latest and restart in one command:\n\n```bash\nssh -t matt@thor.lab \"cd /home/matt/Local/cyber-inference && git pull && ./start.sh\"\n```\n\n## Troubleshooting\n\n- **Server won''t start**: Check logs with `ssh matt@thor.lab \"tail -50 /tmp/cyber-inference.log\"`\n- **Port in use**: Kill existing process with `ssh matt@thor.lab \"pkill -f ''cyber-inference serve''\"`\n- **Check running processes**: `ssh matt@thor.lab \"ps aux | grep cyber-inference\"`\n- **GPU/CUDA issues**: `ssh matt@thor.lab \"nvidia-smi\"`\n"},"lastSynced":"2026-03-08T02:11:58.371Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing automated model management and dynamic resource allocation for edge deployment on OpenAI-compatible inference servers.","zh":"适用于需要自动化模型管理和动态资源分配的AI代理，用于在兼容OpenAI的边缘部署推理服务器上进行部署。","ja":"OpenAIと互換性のあるエッジデプロイのインフラサーバー上で自動化されたモデル管理と動的リソース割り当てが必要なAIエージェントに適しています。","ko":"OpenAI와 호환되는 에지 배포 인프라 서버에서 자동화된 모델 관리 및 동적 리소스 할당이 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para Agentes de IA que necesitan una gestión de modelos automatizada y una asignación de recursos dinámica para la implementación en servidores de inferencia compatibles con OpenAI.","fr":"Parfait pour les agents IA nécessitant une gestion de modèles automatisée et une allocation de ressources dynamique pour le déploiement sur des serveurs d''inférence compatibles OpenAI.","de":"Perfekt für KI-Agenten, die eine automatisierte Modellverwaltung und eine dynamische Ressourcenzuweisung für die Bereitstellung auf OpenAI-kompatiblen Inferenzservern benötigen.","pt":"Perfeito para Agentes de IA que necessitam de gerenciamento de modelo automatizado e alocação de recursos dinâmica para implantação de borda em servidores de inferência compatíveis com a OpenAI.","ru":"Идеально для агентов ИИ, которым необходим автоматизированный управление моделями и динамическое распределение ресурсов для развертывания на краю на серверах вывода, совместимых с OpenAI.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يحتاج إلى إدارة نموذج آلية وتخصيص مورد ديناميكي لتثبيت الحواف على خواديم الاستدلال المتوافقة مع OpenAI."},"recommendation":{"en":"Empowers agents to manage OpenAI models with automatic deployment and resource allocation via SSH and HTTP protocols, streamlining integration testing on GPU lab servers like Thor.","zh":"赋予代理管理OpenAI模型的能力，通过SSH和HTTP协议实现自动化部署和资源分配，简化了在Thor等GPU实验室服务器上的集成测试。","ja":"エージェントにOpenAIモデルを管理する能力を与え、SSHおよびHTTPプロトコル経由で自動デプロイおよびリソース割り当てを実行し、ThorなどのGPUラボサーバーでの統合テストを簡素化します。","ko":"에이전트가 OpenAI 모델을 관리할 수 있는 능력을 부여하여 SSH 및 HTTP 프로토콜을 통해 자동화된 배포 및 리소스 할당을 수행하고, Thor와 같은 GPU 실험실 서버上的 통합 테스트를 간소화합니다.","es":"Habilita a los agentes a gestionar modelos de OpenAI con una implementación automática y una asignación de recursos a través de los protocolos SSH y HTTP, lo que simplifica las pruebas de integración en servidores de laboratorio GPU como Thor.","fr":"Permet aux agents de gérer les modèles OpenAI avec un déploiement automatique et une allocation de ressources via les protocoles SSH et HTTP, ce qui simplifie les tests d''intégration sur les serveurs de laboratoire GPU comme Thor.","de":"Ermächtigt Agenten, OpenAI-Modelle mit automatischer Bereitstellung und Ressourcenzuweisung über SSH- und HTTP-Protokolle zu verwalten, wodurch die Integrationstests auf GPU-Laborservern wie Thor vereinfacht werden.","pt":"Habilita agentes a gerenciar modelos OpenAI com implantação automática e alocação de recursos por meio dos protocolos SSH e HTTP, simplificando a integração de testes em servidores de laboratório GPU, como o Thor.","ru":"Наделяет агентов возможностью управлять моделями OpenAI с автоматическим развертыванием и распределением ресурсов через протоколы SSH и HTTP, упрощая интеграционное тестирование на серверах лаборатории GPU, таких как Thor.","ar":"يمنح الوكلاء إدارة نماذج OpenAI مع التثبيت الآلي وتخصيص الموارد عبر بروتوكولات SSH و HTTP، وبذلك يبسط اختبار التكامل على خواديم مختبرات GPU مثل Thor."},"useCases":{"en":["Deploying and testing AI models on edge devices","Automating model updates and rollbacks on Thor","Debugging cyber-inference integration tests"],"zh":["在边缘设备上部署和测试AI模型","在Thor上自动化模型更新和回滚","调试网络推理集成测试"],"ja":["エッジデバイスでのAIモデルのデプロイとテスト","Thorでの自動モデル更新とロールバック","サイバープッシュ理論の統合テストのデバッグ"],"ko":["에지 디바이스에서 AI 모델을 배포하고 테스트하는 것","Thor에서 자동 모델 업데이트 및 롤백","사이버 추론 통합 테스트를 디버깅"],"es":["Implementar y probar modelos de IA en dispositivos de borde","Automatizar actualizaciones de modelos y reversión en Thor","Depurar pruebas de integración de inferencia cibernética"],"fr":["Déployer et tester des modèles d''IA sur des appareils de bord","Automatiser les mises à jour de modèles et les réversions sur Thor","Déboguer les tests d''intégration d''inférence cybernétique"],"de":["Bereitstellen und testen von KI-Modellen auf Edge-Geräten","Automatisieren von Modell-Updates und -Rückgängigkeiten auf Thor","Fehlerbehebung bei Integrationstests zur cybernetischen Inferenz"],"pt":["Implantação e teste de modelos de IA em dispositivos de borda","Automatização de atualizações e reverter modelo no Thor","Depuração de testes de integração de inferência cibernética"],"ru":["Развертывание и тестирование моделей ИИ на устройстве края","Автоматизация обновления и откат моделей на Thor","Отладка интеграционных тестов кибер-вывода"],"ar":["تثبيت واختبار نماذج الذكاء الاصطناعي على أجهزة الحواف","أتمتة تحديثات النماذج والتراجع عنها على Thor","تصحيح أخطاء اختبارات التكامل للاستدلال السيبراني"]},"limitations":{"en":["Requires SSH access to thor.lab","Limited to OpenAI-compatible models","Dependent on GPU lab server availability"],"zh":["需要thor.lab的SSH访问权限","仅限于兼容OpenAI的模型","依赖于GPU实验室服务器的可用性"],"ja":["thor.labへのSSHアクセスが必要","OpenAIと互換性のあるモデルに限られる","GPUラボサーバーの可用性に依存する"],"ko":["thor.lab에 대한 SSH 액세스가 필요함","OpenAI와 호환되는 모델에만 제한됨","GPU 실험실 서버의 가용성에 의존"],"es":["Requiere acceso SSH a thor.lab","Limitado a modelos compatibles con OpenAI","Dependiente de la disponibilidad del servidor de laboratorio GPU"],"fr":["Requiert un accès SSH à thor.lab","Limité aux modèles compatibles OpenAI","Dépend de la disponibilité du serveur de laboratoire GPU"],"de":["Erfordert SSH-Zugriff auf thor.lab","Begrenzt auf OpenAI-kompatible Modelle","Abhängig von der Verfügbarkeit des GPU-Laborservers"],"pt":["Requer acesso SSH ao thor.lab","Limitado a modelos compatíveis com a OpenAI","Dependente da disponibilidade do servidor de laboratório GPU"],"ru":["Требуется доступ SSH к thor.lab","Ограничен моделями, совместимыми с OpenAI","Зависит от доступности сервера лаборатории GPU"],"ar":["يتطلب الوصول إلى SSH إلى thor.lab","محدود بنماذج OpenAI المتوافقة","يعتمد على توافر خادم مختبرات GPU"]},"version":4},"contentHash":"7fc61fe5b2a40c54879d5f161638fc8c35015242978dc4bd1acf530d54db165a","qualityScore":39}');
