INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('RamboRogers/cyber-inference/run-thor', 'run-thor', 'RamboRogers', 'cyber-inference', 'community', 'run-thor RamboRogers cyber-inference community run-thor is a web GUI management tool for running OpenAI-compatible inference servers, providing automatic model management and dynamic resource allocation for edge deployment. It benefits developers and testers working with AI models. Run-Thor 是 Cyber-Inference 的一部分，用于在 Thor GPU 服务器上部署和测试。它提供了自动模型管理和动态资源分配 Run-Thor は Cyber-Inference の一部で、Thor GPU サーバーでデプロイしてテストするために使用されます。自動モデル管理と動的リソース割り当てを提供します Run-Thor는 Cyber-Inference의 일부입니다. Thor GPU 서버에서 배포하고 테스트하는 데 사용되며 자동 모델 관리 및 동적 리소스 할당을 제공합니다 run-thor es una herramienta de administración de GUI web para servidores de inferencia compatibles con OpenAI, con características como administración de modelos automáticos y asignación de recursos dinámicos run-thor est un outil de gestion GUI web pour les serveurs d''inférence compatibles OpenAI, doté de fonctionnalités telles que la gestion automatique de modèles et l''allocation de ressources dynamiques run-thor ist ein Web-GUI-Verwaltungstool für OpenAI-kompatible Inferenzserver mit Funktionen wie automatischer Modellverwaltung und dynamischer Ressourcenzuweisung O run-thor é uma ferramenta de gerenciamento de inferência de IA que fornece alocação de recursos dinâmicos e uma interface temática cyberpunk Run-thor - это инструмент ИИ Агентов для инференции, который предоставляет динамическое распределение ресурсов и красивый интерфейс в стиле киберпанк run-thor هو أداة إدارة الاستدلال الاصطناعي التي توفر تخصيص الموارد الديناميكي وواجهة مستخدم темاتية كيبيربانك how to use run-thor run-thor setup guide run-thor alternative run-thor vs llama.cpp run-thor install what is run-thor run-thor deployment run-thor testing run-thor GPU lab server AI 工具 GPU 部署 自动模型管理 动态资源分配 Cyber-Inference llama.cpp Thor 服务器 SSH 连接 Provides automatic model management for OpenAI-compatible inference servers Supports dynamic resource allocation for efficient edge deployment Offers a cyberpunk-themed interface for user-friendly interaction Accessible via SSH for secure remote access Hosts production-like test environment on Thor, the GPU lab server Utilizes llama.cpp for building and managing inference servers run-thor is a cyber-inference tool built on llama.cpp, designed for managing and deploying OpenAI-compatible inference servers with a unique cyberpunk-themed interface.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('entazis/product-reviews/pull-request', 'community', 'entazis', 'product-reviews', 'entazis/product-reviews', 'pull-request', 0, 0, 39, '2026-03-08T01:57:15.589Z', '2026-03-08T02:12:00.244Z', 'a17832f353f6dbc8cbbc521a4475efabb12b61cbc1ad63cc3d7392f8199c9af4', '{"id":"entazis/product-reviews/pull-request","name":"pull-request","description":{"en":"The pull-request skill handles product reviews with a system that enforces a pre-flight checklist, ensuring code quality and security. It benefits developers by automating testing and review processes.","zh":"Pull Request是一种代码审查系统，确保代码格式化、行为变化测试和秘密保护","ja":"Pull Requestはコードレビューシステムで、コードのフォーマット、テスト、シークレットの保護を担う","ko":"Pull Request는 코드 리뷰 시스템으로 코드 형식화, 행동 변경 테스트 및 비밀 보호를 담당합니다","es":"El sistema de pull-request permite una revisión y validación eficaces de los cambios de código antes de su implementación","fr":"Le système de pull-request permet une révision et une validation efficaces des modifications de code avant leur mise en œuvre","de":"Das pull-request-System ermöglicht eine effektive Überprüfung und Validierung von Code-Änderungen vor ihrer Implementierung","pt":"O pull request é um sistema para lidar com revisões de produtos, garantindo que o código seja formatado e testado","ru":"Pull request - это система для обработки обзоров продуктов, обеспечивающая форматирование и тестирование кода для ИИ Агентов","ar":"طلب السحب هو نظام للتعامل مع المراجعات المنتجات، ويضمن تنسيق الشفرة واختبارها"},"seo":{"title":{"en":"pull-request: Pre-flight Checklist Setup Guide | AI Agent...","zh":"Pull Request 代码审查最佳实践","ja":"Pull Request Setup Guide for AIエージェント","ko":"Pull Request 코드 리뷰 가이드","es":"Guía de configuración de pull-request para herramientas d...","fr":"Guide de configuration de pull-request pour les outils de...","de":"Einrichtungsleitfaden für pull-request bei Produktbewertu...","pt":"Guia de Configuração de Pull Request para Desenvolvedores","ru":"Настройка Pull Request: Руководство для Разработчиков ИИ ...","ar":"دليل إعداد طلبات السحب لل개발ين"},"description":{"en":"Streamline your code review process with pull-request. Learn how to implement a pre-flight checklist and ensure seamless product review handling. Get started...","zh":"了解Pull Request的预检清单，确保代码格式化、行为变化测试和秘密保护","ja":"Pull Requestのベストプラクティスを学び、コードのフォーマット、テスト、シークレットの保護を確実に行う","ko":"Pull Request의 사전 체크리스트를 확인하고 코드 형식화, 행동 변경 테스트 및 비밀 보호를 확인하십시오","es":"Aprende a configurar pull-request para sistemas de revisión de productos con nuestra guía paso a paso","fr":"Découvrez comment configurer pull-request pour les systèmes de révision de produits avec notre guide étape par étape","de":"Erfahren Sie, wie Sie pull-request für Produktbewertungssysteme mit unserem Schritt-für-Schritt-Leitfaden konfigurieren","pt":"Aprenda a configurar pull requests com foco em escopo, formatação de código e testes de comportamento","ru":"Узнайте, как настроить pull request с учетом фокуса на объеме, форматировании кода и тестировании поведения для ИИ Агентов","ar":"تعلم كيفية ضبط طلبات السحب مع التركيز على النطاق وتدوين الشفرة واختبار السلوك"},"definition":{"en":"pull-request is a system for handling product reviews that enforces a pre-flight checklist, including code formatting with gofmt and goimports, and testing behavior changes.","zh":"Pull Request是一种代码审查系统，用于检查代码格式、行为变化和秘密保护","ja":"Pull Requestはコードレビューシステムで、コードのフォーマット、テスト、シークレットの保護を定義する","ko":"Pull Request는 코드 리뷰 시스템으로 코드 형식화, 행동 변경 및 비밀 보호를 정의합니다","es":"Un pull-request es una solicitud de revisión de cambios de código en un sistema de control de versiones","fr":"Un pull-request est une demande de révision de modifications de code dans un système de contrôle de version","de":"Ein pull-request ist eine Anfrage zur Überprüfung von Code-Änderungen in einem Versionskontrollsystem","pt":"Pull request é um sistema de revisão de código que garante a qualidade e a consistência do código","ru":"Pull request - это система обзора кода, обеспечивающая качество и последовательность кода для ИИ Агентов","ar":"طلب السحب هو نظام لمراجعة الشفرة الذي يضمن جودة وثبات الشفرة"},"features":{"en":["Enforces scope focus with no unrelated refactors","Automates code formatting using gofmt and goimports","Prevents secrets from being checked in, including env files and credentials","Ensures behavior changes are tested with targeted tests and full suite when appropriate","Supports review mutations with aggregates updating in the same DB transaction and outbox events emission"],"zh":["代码格式化（gofmt、goimports）","行为变化测试","秘密保护（env文件、凭据、令牌）","数据库事务更新","出箱事件发出"],"ja":["コードのフォーマット（gofmt、goimports）","動作変更のテスト","シークレットの保護（envファイル、クレデンシャル、トークン）","データベーストランザクションの更新","アウトボックスイベントの発行"],"ko":["코드 형식화（gofmt、goimports）","행동 변경 테스트","비밀 보호（env 파일、자격 증명、토큰）","데이터베이스 트랜잭션 업데이트","아웃박스 이벤트 발송"],"es":["Revisión de código con formato de código gofmt y goimports","Detección de secretos y credenciales en el código","Pruebas de comportamiento y cambios de código","Actualizaciones de agregados en la misma transacción de base de datos","Emisión de eventos de outbox cuando corresponda"],"fr":["Révision de code avec formatage de code gofmt et goimports","Détection de secrets et de credenciales dans le code","Tests de comportement et de modifications de code","Mises à jour d''agrégats dans la même transaction de base de données","Émission d''événements de outbox lorsque cela est pertinent"],"de":["Code-Überprüfung mit Code-Formatierung gofmt und goimports","Erkennung von Geheimnissen und Anmeldeinformationen im Code","Tests von Verhaltensänderungen und Code-Änderungen","Aktualisierungen von Aggregaten in der gleichen Datenbanktransaktion","Ausgabe von Outbox-Ereignissen wenn relevant"],"pt":["Verificação de escopo focado","Formatação de código com gofmt e goimports","Testes de comportamento para garantir a qualidade do código","Prevenção de vazamento de segredos","Atualização de agregados em transações de banco de dados","Emissão de eventos de outbox"],"ru":["Проверка фокуса на объеме","Форматирование кода с помощью gofmt и goimports","Тестирование поведения для обеспечения качества кода","Предотвращение утечки секретов","Обновление агрегатов в транзакциях базы данных","Выдача событий outbox для ИИ Агентов"],"ar":["فحص نطاق محدد","تنسيق الشفرة باستخدام gofmt و goimports","اختبار السلوك لضمان جودة الشفرة","منع تسريب الأسرار","تحديث المجموعات في معاملات قواعد البيانات","إصدار أحداث المجموعة الخارجية"]},"keywords":{"en":["how to use pull-request","pull-request setup guide","what is pull-request","pull-request alternative","pull-request vs git request","pull-request install","pull-request pre-flight checklist","pull-request gofmt","pull-request goimports"],"zh":["Pull Request","代码审查","代码格式化","行为变化测试","秘密保护","AI工具","代码review"],"ja":["Pull Request","コードレビュー","コードのフォーマット","動作変更のテスト","シークレットの保護","AIエージェント","コードテスト"],"ko":["Pull Request","코드 리뷰","코드 형식화","행동 변경 테스트","비밀 보호","AIツール","코드 테스트"],"es":["pull-request","herramientas de revisión de productos","sistemas de control de versiones","código gofmt","código goimports","pruebas de comportamiento","actualizaciones de agregados","emisión de eventos de outbox"],"fr":["pull-request","outils de révision de produits","systèmes de contrôle de version","code gofmt","code goimports","tests de comportement","mises à jour d''agrégats","émission d''événements de outbox"],"de":["pull-request","Produktbewertungstools","Versionskontrollsysteme","Code-Formatierung gofmt","Code-Formatierung goimports","Verhaltensänderungstests","Aggregat-Aktualisierungen","Outbox-Ereignis-Ausgabe"],"pt":["pull request","revisão de código","desenvolvimento de software","qualidade de código","gofmt","goimports","testes de comportamento","segurança de código"],"ru":["pull request","обзор кода","разработка программного обеспечения","качество кода","gofmt","goimports","тестирование поведения","безопасность кода","ИИ Агенты"],"ar":["طلب السحب","مراجعة الشفرة","تطوير البرمجيات","جودة الشفرة","gofmt","goimports","اختبار السلوك","أمان الشفرة","أدوات الذكاء الاصطناعي"]}},"owner":"entazis","repo":"product-reviews","repoPath":"entazis/product-reviews","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.589Z","topics":[],"category":"community","skillMd":{"name":"pull-request","description":"Prepare a high-quality pull request for this repository: keep diffs small, ensure gofmt/goimports, run appropriate tests, and write a clear summary + test plan. Use when the user asks to open a PR, prepare changes for review, or improve PR descriptions.","bodyPreview":"# Pull Request\n\n## Pre-flight checklist\n\n- [ ] Scope is focused; no unrelated refactors.\n- [ ] Code is formatted (`gofmt`, `goimports`).\n- [ ] No secrets checked in (env files, credentials, tokens).\n- [ ] Behavior changes are tested (at least targeted tests; full suite when appropriate).\n- [ ] For review mutations: aggregates update in the same DB transaction and outbox events are emitted (if relevant).\n- [ ] Product responses still do **not** include reviews (if touching product endpoints).\n\n##","body":"# Pull Request\n\n## Pre-flight checklist\n\n- [ ] Scope is focused; no unrelated refactors.\n- [ ] Code is formatted (`gofmt`, `goimports`).\n- [ ] No secrets checked in (env files, credentials, tokens).\n- [ ] Behavior changes are tested (at least targeted tests; full suite when appropriate).\n- [ ] For review mutations: aggregates update in the same DB transaction and outbox events are emitted (if relevant).\n- [ ] Product responses still do **not** include reviews (if touching product endpoints).\n\n## Testing guidance\n\nDefault (unit tests, containerized toolchain):\n\n```bash\ndocker run --rm -v \"$PWD\":/src -w /src golang:1.25.6-alpine sh -c \"go test ./...\"\n```\n\nOptional integration concurrency test (when relevant):\n\n```bash\nRUN_INTEGRATION=1 docker run --rm -v \"$PWD\":/src -w /src golang:1.25.6-alpine sh -c \"go test ./... -run TestConcurrentReviewCreates_UpdateAggregates\"\n```\n\n## PR description template\n\nUse this structure:\n\n```markdown\n## Summary\n- <What changed and why>\n- <Any user-facing/API impact>\n\n## Test plan\n- [ ] `go test ./...` (or targeted packages)\n- [ ] Manual check: <endpoint / scenario> (if applicable)\n- [ ] Integration test (if applicable)\n\n## Notes\n- <Risks, migrations, rollout considerations>\n```\n\n## Review-ready final pass\n\n1. Re-read the diff like a reviewer.\n2. Ensure errors are handled and logs are not leaking sensitive info.\n3. Ensure docs/config are updated if behavior or env vars changed.\n"},"lastSynced":"2026-03-08T02:12:00.244Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring automated testing and validation of pull requests with pre-flight checklists.","zh":"适用于需要自动测试和验证拉取请求的代码审查代理，具有预飞检查清单。","ja":"コードレビューエージェントがプルリクエストの自動テストと検証を必要とする場合に最適です。事前フライトチェックリストを使用します。","ko":"코드 리뷰 에이전트가 자동화된 테스트와 확인을 필요한 경우에 적합합니다. 사전 비행 체크리스트를 사용합니다.","es":"Ideal para agentes de revisión de código que requieren pruebas y validación automatizadas de solicitudes de incorporación con listas de verificación previas al vuelo.","fr":"Idéal pour les agents de revue de code nécessitant des tests et une validation automatisés des demandes d''intégration avec des listes de vérification pré-vol.","de":"Ideal für Code-Review-Agents, die automatisierte Tests und Validierung von Pull-Requests mit Vorflug-Checklisten benötigen.","pt":"Ideal para Agentes de Revisão de Código que exigem testes e validação automatizados de solicitações de pull com listas de verificação pré-voo.","ru":"Идеально для агентов по проверке кода, требующих автоматизированного тестирования и проверки запросов на включение с предварительными контрольными списками.","ar":"مثالي لعميل استعراض الشفرة الذي يتطلب اختبارات وتنقيح تلقائي لطلبات الجذب مع قوائم تفحص ما قبل الطيران."},"recommendation":{"en":"Empowers agents to enforce code quality and security standards using gofmt and goimports for formatting, and automates testing of behavior changes with targeted tests, while ensuring no secrets are checked in and product responses do not include reviews.","zh":"赋予代理执行代码质量和安全标准的能力，使用gofmt和goimports进行格式化，并使用有针对性的测试自动化行为更改的测试，同时确保没有秘密被检查并且产品响应不包括审查。","ja":"gofmtとgoimportsを使用してフォーマットし、ターゲットテストを使用して動作の変更をテストすることで、エージェントがコードの品質とセキュリティの基準を強制することを可能にします。製品のレスポンスにレビューが含まれないことを確認します。","ko":"gofmt와 goimports를 사용하여 형식을 지정하고, 대상 테스트를 사용하여 동작의 변경을 테스트함으로써, 에이전트가 코드 품질과 보안 표준을 강제할 수 있도록 합니다. sản phẩm 응답에 리뷰가 포함되지 않는 것을 확인합니다.","es":"Habilita a los agentes a hacer cumplir los estándares de calidad y seguridad del código utilizando gofmt y goimports para el formato, y automatiza las pruebas de cambios de comportamiento con pruebas dirigidas, al mismo tiempo que garantiza que no se verifiquen secretos y las respuestas del producto no incluyen reseñas.","fr":"Permet aux agents d''appliquer les normes de qualité et de sécurité du code en utilisant gofmt et goimports pour le formatage, et automatise les tests de changements de comportement avec des tests ciblés, tout en s''assurant que les secrets ne sont pas vérifiés et que les réponses des produits n''incluent pas d''avis.","de":"Ermächtigt die Agenten, die Qualitäts- und Sicherheitsstandards des Codes mit gofmt und goimports für das Formatieren durchzusetzen und automatisiert das Testen von Verhaltensänderungen mit gezielten Tests, während gleichzeitig sichergestellt wird, dass keine Geheimnisse überprüft werden und die Produktantworten keine Bewertungen enthalten.","pt":"Habilita os agentes a impor padrões de qualidade e segurança de código usando gofmt e goimports para formatação, e automatiza os testes de alterações de comportamento com testes direcionados, garantindo que nenhum segredo seja verificado e as respostas do produto não incluam revisões.","ru":"Наделяет агентов возможностью обеспечивать стандарты качества и безопасности кода с помощью gofmt и goimports для форматирования, и автоматизирует тестирование изменений поведения с помощью целевых тестов, гарантируя, что ни один секрет не будет проверен и ответы продукта не будут включать обзоры.","ar":"يمنح الوكيل القدرة على فرض معايير جودة وأمان الشفرة باستخدام gofmt و goimports لتنسيق ، وتحسين اختبارات التغييرات السلوكية مع اختبارات موجهة ، مع ضمان عدم التحقق من أي سر والاستجابات المنتج لا تشمل الاستعراضات."},"useCases":{"en":["Automating code reviews with pre-flight checklists","Validating code formatting with gofmt and goimports","Testing behavior changes with targeted tests and full suites"],"zh":["使用预飞检查清单自动化代码审查","使用gofmt和goimports验证代码格式","使用有针对性的测试和全套测试测试行为更改"],"ja":["事前フライトチェックリストを使用してコードレビューを自動化する","gofmtとgoimportsを使用してコードのフォーマットを検証する","ターゲットテストとフルスイートを使用して動作の変更をテストする"],"ko":["사전 비행 체크리스트를 사용하여 코드 리뷰를 자동화하는 것","gofmt와 goimports를 사용하여 코드 형식을 확인하는 것","대상 테스트와 전체 테스트를 사용하여 동작의 변경을 테스트하는 것"],"es":["Automatizar las revisiones de código con listas de verificación previas al vuelo","Validar el formato de código con gofmt y goimports","Probar los cambios de comportamiento con pruebas dirigidas y suites completas"],"fr":["Automatiser les revues de code avec des listes de vérification pré-vol","Valider le formatage de code avec gofmt et goimports","Tester les changements de comportement avec des tests ciblés et des suites complètes"],"de":["Automatisieren von Code-Reviews mit Vorflug-Checklisten","Validieren des Code-Formats mit gofmt und goimports","Testen von Verhaltensänderungen mit gezielten Tests und vollständigen Suites"],"pt":["Automatizar revisões de código com listas de verificação pré-voo","Validar formatação de código com gofmt e goimports","Testar alterações de comportamento com testes direcionados e suites completas"],"ru":["Автоматизация проверки кода с предварительными контрольными списками","Проверка форматирования кода с помощью gofmt и goimports","Тестирование изменений поведения с помощью целевых тестов и полных наборов"],"ar":["تحسين استعراض الشفرة تلقائيًا مع قوائم تفحص ما قبل الطيران","تحقق من تنسيق الشفرة باستخدام gofmt و goimports","اختبار التغييرات السلوكية مع الاختبارات الموجهة والمجموعات الكاملة"]},"limitations":{"en":["Requires Go environment for formatting and testing","Limited to code reviews with specific pre-flight checklist requirements"],"zh":["需要Go环境进行格式化和测试","仅限于具有特定预飞检查清单要求的代码审查"],"ja":["フォーマットとテストのためにGo環境が必要","特定の事前フライトチェックリスト要件を持つコードレビューのみに限定"],"ko":["형식 지정 및 테스트를 위한 Go 환경이 필요","특정 사전 비행 체크리스트 요구 사항을 가진 코드 리뷰에만 제한"],"es":["Requiere un entorno Go para el formato y las pruebas","Limitado a revisiones de código con requisitos de lista de verificación previa al vuelo específicos"],"fr":["Nécessite un environnement Go pour le formatage et les tests","Limité aux revues de code avec des exigences de liste de vérification pré-vol spécifiques"],"de":["Benötigt eine Go-Umgebung für Formatierung und Tests","Begrenzt auf Code-Reviews mit spezifischen Vorflug-Checklistenanforderungen"],"pt":["Exige ambiente Go para formatação e teste","Limitado a revisões de código com requisitos específicos de lista de verificação pré-voo"],"ru":["Требует среды Go для форматирования и тестирования","Ограничен проверками кода с конкретными требованиями предварительного контрольного списка"],"ar":["يتطلب بيئة Go لتنسيق واختبار","محدود بالاستعراضات الشفرة مع متطلبات محددة لقائمة تفحص ما قبل الطيران"]},"version":4},"contentHash":"a17832f353f6dbc8cbbc521a4475efabb12b61cbc1ad63cc3d7392f8199c9af4","qualityScore":39}');
