INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wangfh5/WfhZoteroTools/playwright-cli', 'playwright-cli', 'wangfh5', 'WfhZoteroTools', 'community', 'playwright-cli wangfh5 WfhZoteroTools community playwright-cli is a browser automation tool that allows developers to automate browser interactions. It benefits developers who need to automate web page interactions for testing or scraping purposes. playwright-cli是一种命令行工具，用于浏览器自动化，支持快速打开浏览器、导航和交互 playwright-cliは、ブラウザ自動化に使用されるコマンドラインツールで、ブラウザの開閉やナビゲーションをサポート playwright-cli는 브라우저 자동화를 위한 명령행 도구로, 빠른 브라우저 열기 및 탐색을 지원 Playwright-cli es una herramienta de automatización de navegador que permite abrir y navegar por páginas web, interactuar con elementos y capturar pantallas Playwright-cli est un outil d''automatisation de navigateur qui permet d''ouvrir et de naviguer dans des pages web, d''interagir avec des éléments et de capturer des écrans Playwright-cli ist ein Tool zur Automatisierung von Browsern, das das Öffnen und Navigieren von Webseiten, die Interaktion mit Elementen und die Aufnahme von Bildschirmen ermöglicht O playwright-cli é uma ferramenta de automação de navegadores que permite abrir e navegar em páginas da web, interagir com elas e capturar telas Playwright-cli - это инструмент для автоматизации браузеров, который позволяет открывать и навигировать по веб-страницам, взаимодействовать с ними и делать снимки экрана playwright-cli هو أداة لآلة автоматизации المتصفحات التي تسمح بفتح وتنقل صفحات الويب والتفاعل معها وتسجيل الشاشة how to use playwright-cli playwright-cli alternative playwright-cli setup guide browser automation with playwright-cli playwright-cli vs puppeteer playwright-cli install what is playwright-cli playwright-cli documentation playwright-cli tutorial playwright-cli 浏览器自动化 命令行工具 快速打开浏览器 导航和交互 截图 AIエージェント 自动化测试 Opens new browser instances using the `open` command Navigates to specific web pages using the `goto` command Interacts with web pages using refs from snapshots, such as clicking elements Takes screenshots of web pages using the `screenshot` command Closes browser instances using the `close` command Supports typing and pressing keys using the `type` and `press` commands playwright-cli is a command-line interface for automating browser interactions, allowing developers to open, navigate, and interact with web pages using commands like open, goto, and click.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vimalkodoth/fastapi-cursor-starterkit/fastapi-best-practices', 'community', 'vimalkodoth', 'fastapi-cursor-starterkit', 'vimalkodoth/fastapi-cursor-starterkit', 'fastapi-best-practices', 0, 0, 39, '2026-03-08T01:57:15.590Z', '2026-03-08T02:12:01.215Z', '84de07efcba56c9deffc519c852b8ca68c4d29e926c4cb2c418831a7ee3e20e6', '{"id":"vimalkodoth/fastapi-cursor-starterkit/fastapi-best-practices","name":"fastapi-best-practices","description":{"en":"The fastapi-best-practices skill provides a production-ready backend template for AI teams, featuring a layered architecture and built-in observability. It benefits developers looking to create efficient and scalable APIs.","zh":"FastAPI Cursor Starter Kit提供了生产级后端模板，采用API-only、分层架构，集成了Celery+RabbitMQ RPC和PostgreSQL+Alembic","ja":"FastAPI Cursor Starter Kitはプロダクションレベルのバックエンドテンプレートを提供し、API-only、階層化アーキテクチャ、Celery+RabbitMQ RPC、PostgreSQL+Alembicを採用","ko":"FastAPI Cursor Starter Kit는 프로덕션급 백엔드 템플릿을 제공하며 API-only, 계층 구조, Celery+RabbitMQ RPC 및 PostgreSQL+Alembic를 채택","es":"FastAPI con mejores prácticas para desarrollo de backend de Agentes de IA, con características como Celery, RabbitMQ y PostgreSQL","fr":"FastAPI avec les meilleures pratiques pour le développement de backend d''Outils d''IA, avec des fonctionnalités comme Celery, RabbitMQ et PostgreSQL","de":"FastAPI mit Best Practices für die Entwicklung von Backend-KI-Tools, mit Funktionen wie Celery, RabbitMQ und PostgreSQL","pt":"O FastAPI é um framework para desenvolver APIs de alta performance, com suporte a Celery, RabbitMQ e PostgreSQL","ru":"FastAPI - это фреймворк для разработки высокопроизводительных API, с поддержкой Celery, RabbitMQ и PostgreSQL","ar":"FastAPI هو إطار لتطوير واجهات برمجة التطبيقات عالية الأداء، مع دعم Celery و RabbitMQ و PostgreSQL"},"seo":{"title":{"en":"fastapi-best-practices: Production-Ready Backend Setup Gu...","zh":"FastAPI 最佳实践设置指南 - AIエージェント开发","ja":"FastAPI ベストプラクティスセットアップガイド - AIエージェント開発","ko":"FastAPI 최적화 설정 가이드 - AI 에이전트 개발","es":"Guía de configuración de FastAPI con mejores prácticas pa...","fr":"Guide de configuration de FastAPI avec les meilleures pra...","de":"Einrichtungsleitfaden für FastAPI mit Best Practices für ...","pt":"FastAPI Best Practices: Guia de Configuração para Desenvo...","ru":"Лучшие практики FastAPI: Настройка для разработчиков ИИ А...","ar":"أفضل الممارسات ل FastAPI: دليل الإعداد للمطورين"},"description":{"en":"Unlock efficient API development with fastapi-best-practices. Learn how to set up a production-ready backend with Celery, RabbitMQ, and PostgreSQL. Get start...","zh":"使用FastAPI Cursor Starter Kit构建生产级后端，实现API-only、分层架构、Celery+RabbitMQ RPC和PostgreSQL+Alembic","ja":"FastAPI Cursor Starter Kitを使用してプロダクションレベルのバックエンドを構築し、API-only、階層化アーキテクチャ、Celery+RabbitMQ RPC、PostgreSQL+Alembicを実現","ko":"FastAPI Cursor Starter Kit를 사용하여 프로덕션급 백엔드를 구축하고 API-only, 계층 구조, Celery+RabbitMQ RPC 및 PostgreSQL+Alembic를 구현","es":"Aprende a configurar FastAPI con las mejores prácticas para desarrollo de backend de Agentes de IA, incluyendo Celery, RabbitMQ y PostgreSQL","fr":"Découvrez comment configurer FastAPI avec les meilleures pratiques pour le développement de backend d''Outils d''IA, y compris Celery, RabbitMQ et PostgreSQL","de":"Erfahren Sie, wie Sie FastAPI mit Best Practices für die Entwicklung von Backend-KI-Tools konfigurieren, einschließlich Celery, RabbitMQ und PostgreSQL","pt":"Aprenda a configurar o FastAPI com as melhores práticas para desenvolvedores, incluindo Celery, RabbitMQ e PostgreSQL","ru":"Узнайте, как настроить FastAPI с лучшими практиками для разработчиков ИИ Агентов, включая Celery, RabbitMQ и PostgreSQL","ar":"تعلم كيفية تكوين FastAPI بأفضل الممارسات للمطورين، بما في ذلك Celery و RabbitMQ و PostgreSQL"},"definition":{"en":"fastapi-best-practices is a set of standards and templates for building production-ready FastAPI applications with a layered architecture, Celery, RabbitMQ, and PostgreSQL.","zh":"FastAPI最佳实践是指使用FastAPI构建后端应用的标准和指南","ja":"FastAPIベストプラクティスとは、FastAPIを使用してバックエンドアプリケーションを構築するための規範とガイドライン","ko":"FastAPI 최적화는 FastAPI를 사용하여 백엔드 애플리케이션을 구축하는 표준 및 가이드를 의미","es":"FastAPI con mejores prácticas es un conjunto de reglas y patrones para desarrollar aplicaciones de backend de Agentes de IA de manera eficiente","fr":"FastAPI avec les meilleures pratiques est un ensemble de règles et de modèles pour développer des applications de backend d''Outils d''IA de manière efficace","de":"FastAPI mit Best Practices ist eine Sammlung von Regeln und Mustern für die effiziente Entwicklung von Backend-Anwendungen für KI-Tools","pt":"FastAPI é um framework Python para desenvolver APIs de alta performance","ru":"FastAPI - это фреймворк Python для разработки высокопроизводительных API","ar":"FastAPI هو إطار برمجي Python لتطوير واجهات برمجة التطبيقات عالية الأداء"},"features":{"en":["Layered architecture with endpoints, services, and repositories","Built-in observability with metrics and idempotency","Support for Celery and RabbitMQ RPC","PostgreSQL database with Alembic migration tool","Automated code formatting with Black and mypy","Pre-commit hooks for code quality assurance"],"zh":["API-only架构","分层架构（端点、服务、存储库）","Celery+RabbitMQ RPC集成","PostgreSQL+Alembic数据库支持","内置观察性和质量检查（指标、幂等性、Black、mypy、pre-commit）"],"ja":["API-onlyアーキテクチャ","階層化アーキテクチャ（エンドポイント、サービス、リポジトリ）","Celery+RabbitMQ RPCの統合","PostgreSQL+Alembicデータベースのサポート","ビルトインの観測性と品質チェック（メトリクス、イデンプォテント、Black、mypy、pre-commit）"],"ko":["API-only 아키텍처","계층 구조（엔드포인트, 서비스, 저장소）","Celery+RabbitMQ RPC 통합","PostgreSQL+Alembic 데이터베이스 지원","내장 관측성 및 품질 확인（메트릭, 멱등성, Black, mypy, pre-commit）"],"es":["Arquitectura en capas con endpoints, servicios y repositorios","Integración con Celery y RabbitMQ para RPC","Base de datos PostgreSQL con Alembic para migraciones","Observabilidad y calidad integradas con métricas e idempotencia","Soporte para Black, mypy y pre-commit para asegurar la calidad del código"],"fr":["Architecture en couches avec des points de terminaison, des services et des référentiels","Intégration avec Celery et RabbitMQ pour RPC","Base de données PostgreSQL avec Alembic pour les migrations","Observabilité et qualité intégrées avec des métriques et de l''idempotence","Prise en charge de Black, mypy et pre-commit pour assurer la qualité du code"],"de":["Schichtenarchitektur mit Endpunkten, Diensten und Repositorien","Integration mit Celery und RabbitMQ für RPC","Datenbank PostgreSQL mit Alembic für Migrationen","Integrierte Observierbarkeit und Qualität mit Metriken und Idempotenz","Unterstützung für Black, mypy und pre-commit zur Sicherstellung der Codequalität"],"pt":["Suporte a Celery e RabbitMQ para processamento assíncrono","Integração com PostgreSQL para armazenamento de dados","Suporte a Alembic para migração de esquemas de banco de dados","Observabilidade e qualidade com métricas e idempotência","Suporte a Black e mypy para formatação e verificação de código"],"ru":["Поддержка Celery и RabbitMQ для асинхронной обработки","Интеграция с PostgreSQL для хранения данных","Поддержка Alembic для миграции схем баз данных","Наблюдаемость и качество с метриками и идемпотентностью","Поддержка Black и mypy для форматирования и проверки кода"],"ar":["دعم Celery و RabbitMQ لمعالجة غير متزامنة","التكامل مع PostgreSQL لتخزين البيانات","دعم Alembic لتحديث مخططات قواعد البيانات","ملاحظة الجودة مع المعايير والتعاقب","دعم Black و mypy لتنسيق ومراجعة الشفرة"]},"keywords":{"en":["fastapi-best-practices setup guide","fastapi production-ready backend","celery and rabbitmq rpc","postgresql and alembic migration","fastapi-best-practices vs flask","how to use fastapi-best-practices","fastapi-best-practices alternative","fastapi-best-practices install","fastapi-best-practices tutorial","fastapi best practices for ai teams"],"zh":["FastAPI最佳实践","AIエージェント开发","API-only架构","分层架构","Celery+RabbitMQ RPC","PostgreSQL+Alembic","观察性和质量检查"],"ja":["FastAPIベストプラクティス","AIエージェント開発","API-onlyアーキテクチャ","階層化アーキテクチャ","Celery+RabbitMQ RPC","PostgreSQL+Alembic","観測性と品質チェック"],"ko":["FastAPI 최적화","AI 에이전트 개발","API-only 아키텍처","계층 구조","Celery+RabbitMQ RPC","PostgreSQL+Alembic","관측성 및 품질 확인"],"es":["FastAPI","Agentes de IA","desarrollo de backend","mejores prácticas","Celery","RabbitMQ","PostgreSQL","Alembic","observabilidad","calidad del código"],"fr":["FastAPI","Outils d''IA","développement de backend","meilleures pratiques","Celery","RabbitMQ","PostgreSQL","Alembic","observabilité","qualité du code"],"de":["FastAPI","KI-Tools","Backend-Entwicklung","Best Practices","Celery","RabbitMQ","PostgreSQL","Alembic","Beobachtbarkeit","Codequalität"],"pt":["FastAPI","desenvolvimento de APIs","Celery","RabbitMQ","PostgreSQL","Alembic","observabilidade","qualidade de código","desenvolvedores Python"],"ru":["FastAPI","разработка API","Celery","RabbitMQ","PostgreSQL","Alembic","наблюдаемость","качество кода","разработчики Python","ИИ Агенты"],"ar":["FastAPI","تطوير واجهات برمجة التطبيقات","Celery","RabbitMQ","PostgreSQL","Alembic","ملاحظة الجودة","جودة الشفرة","مطورو Python","أدوات الذكاء الاصطناعي"]}},"owner":"vimalkodoth","repo":"fastapi-cursor-starterkit","repoPath":"vimalkodoth/fastapi-cursor-starterkit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.590Z","topics":[],"category":"community","skillMd":{"name":"fastapi-best-practices","description":"FastAPI standards and best practices for this project. Use when adding or changing API routes, services, dependencies, or middleware so the team follows the same patterns and conventions.","bodyPreview":"## In this repository\n\n- **Scope:** FastAPI app lives in `backend/`. Python also in `services/`; same style applies. After edits run **`make format`** and **`make lint`** from repo root.\n- **Rules:** `.cursor/rules/fastapi-python-best-practices.md`, `.cursor/rules/fastapi-patterns.md`, `.cursor/rules/standards.md`, `.cursor/rules/project.md`.\n- Full context: `.cursor/skills/README.md`.\n\n---\n\n# FastAPI best practices (team standards)\n\nStandards derived from this project’s implementation. Follow t","body":"## In this repository\n\n- **Scope:** FastAPI app lives in `backend/`. Python also in `services/`; same style applies. After edits run **`make format`** and **`make lint`** from repo root.\n- **Rules:** `.cursor/rules/fastapi-python-best-practices.md`, `.cursor/rules/fastapi-patterns.md`, `.cursor/rules/standards.md`, `.cursor/rules/project.md`.\n- Full context: `.cursor/skills/README.md`.\n\n---\n\n# FastAPI best practices (team standards)\n\nStandards derived from this project’s implementation. Follow these so the codebase stays consistent and maintainable.\n\n## 1. Project structure and layers\n\n- **Endpoints (controllers):** `backend/app/api/v1/endpoints/` — one file per domain (e.g. `data.py`, `database.py`, `metrics.py`). Only HTTP concerns: parse request, call service/repo via `Depends`, return response or raise `HTTPException`. Use **command** service for write operations (POST/PUT/PATCH/DELETE) and **query** service for read operations (GET). See `.cursor/rules/cqrs.md`.\n- **Business logic:** `backend/app/services/` — use **command** services for writes and **query** services for reads (CQRS). Services receive repositories via constructor; use `AsyncSession` for DB when in the API path. No raw request/response objects.\n- **Data access:** `backend/app/repositories/` — use **write** repositories (create/update/delete) and **read** repositories (get/list) per domain. Repositories receive `AsyncSession`; perform queries and commits. No business rules.\n- **Shared dependencies:** `backend/app/api/v1/deps.py` — define `get_*` functions that return service or repository instances (injecting `get_async_session`). Use these in route handlers via `Depends(...)`.\n- **Models:** `backend/app/models/database.py` (SQLModel table models), `backend/app/models/schemas.py` (Pydantic request/response). DB name is **fastapi_db**.\n\n**Do not:** Put SQL or business logic in endpoint files; put HTTP logic in services or repositories.\n\n## 2. Routers and API design\n\n- Use **APIRouter** with a **prefix** and **tags** for OpenAPI grouping:\n  ```python\n  router = APIRouter(prefix=\"/data\", tags=[\"data\"])\n  ```\n- Mount routers in `backend/app/api/v1/__init__.py` on the v1 router (`prefix=\"/api/v1\"`).\n- Prefer **explicit `response_model`** and **status_code** on route decorators:\n  ```python\n  @router.post(\"/process\", response_model=TaskResult, status_code=200)\n  async def process_data(request: DataRequest, service: DataService = Depends(get_data_service)) -> TaskResult:\n  ```\n- Use **async def** for handlers that do I/O (DB, external calls). Use **def** only for handlers that do no I/O (e.g. simple metrics that read in-memory state).\n- Document with short **docstrings** on each route; they appear in OpenAPI.\n\n## 3. Dependencies (Depends)\n\n- **Session:** Use `get_async_session` from `app.core.database` for any route or dependency that touches the DB. Never create a raw engine or session in an endpoint.\n- **Services and repositories:** Define factory functions in `app.api.v1.deps` that depend on `get_async_session` and return a service or repository instance. Use them in endpoints via `Depends(get_data_service)`, `Depends(get_task_repository)`, etc.\n\nExample (from `deps.py`):\n\n```python\ndef get_data_service(session: AsyncSession = Depends(get_async_session)) -> DataService:\n    \"\"\"Dependency that returns a DataService instance (async session).\"\"\"\n    return DataService(session)\n```\n\n- In endpoints, inject the **service** (or repository when the endpoint only needs data access) and call methods; do not instantiate services or repos inside the route.\n\n## 4. Request and response models\n\n- **Request bodies:** Use Pydantic models from `app.models.schemas` (e.g. `DataRequest`). Declare them as the route parameter; FastAPI validates and parses.\n- **Responses:** Use Pydantic response models (e.g. `TaskResult`, `RecordResponse`, `TaskLogResponse`) and set `response_model=` on the decorator. **Never** return a SQLModel/ORM instance directly; map to a schema and return that (e.g. `RecordResponse.model_validate(r)` or `RecordResponse(**record)`).\n- Prefer **model_validate(orm_instance)** (Pydantic v2) when building response models from ORM objects.\n\n## 5. Async in the request path\n\n- Use **async def** for route handlers that perform I/O (DB, HTTP, etc.). Use **AsyncSession** and async repository methods so the event loop is not blocked.\n- If you must call a **blocking** operation (e.g. sync RabbitMQ RPC), run it in a thread pool with **`await asyncio.to_thread(blocking_func, ...)`** and keep the rest of the flow async (e.g. DB write). See `DataService.process_data_sync_and_save` in `app.services.data_service`.\n- Sync engine/session are only for **Celery tasks** and **startup** (e.g. `init_db`). Do not use them in request handlers.\n\n## 6. Error handling\n\n- **API boundary:** Use **HTTPException** with the appropriate status code (400, 404, 503, etc.) and a clear `detail`. Do not let uncaught exceptions bubble to the client without mapping.\n- **Services/repositories:** Raise domain-friendly exceptions or return `None`/result; let the **endpoint** translate to HTTP (e.g. `if not record: raise HTTPException(status_code=404, detail=\"Record not found\")`).\n- **External calls:** When a dependency (e.g. `call_service_via_rabbitmq`) raises `ValueError`, catch it in the endpoint and map to `HTTPException(status_code=503, detail=str(e))` (or another suitable code).\n- Handle errors and edge cases **first** (early returns, guard clauses); keep the happy path last. See `.cursor/rules/error-handling.md`.\n\n## 7. Middleware and app setup\n\n- **CORS:** Configure in `main.py` (e.g. `CORSMiddleware`). Keep origins/methods/headers explicit for production.\n- **Idempotency:** Optional `Idempotency-Key` header on POST endpoints that support it; implemented in middleware (`IdempotencyMiddleware`). Do not duplicate idempotency logic in services. Paths are listed in the middleware (e.g. `/api/v1/data/process`, `/api/v1/data/process-async`).\n- **Startup:** For simple one-off init (e.g. `init_db()`), `@app.on_event(\"startup\")` is acceptable. For multi-step startup/shutdown, prefer a **lifespan** context manager.\n\n## 8. Database (PostgreSQL, SQLModel, Alembic)\n\n- **In routes:** Always use **async** session via `get_async_session` and pass it to services/repositories. Use connection pooling (already configured in `app.core.database`).\n- **Repositories:** Accept `AsyncSession` in the constructor; use `await session.commit()`, `await session.refresh(record)` after writes; use `select(Model).where(...)` and `await session.execute()` / `session.get()` for reads. Avoid N+1; batch or eager load when needed.\n- **Migrations:** Add or change models in `app.models.database`; then from `backend/` run `alembic revision --autogenerate -m \"description\"` and `alembic upgrade head`. Do not change the database name from **fastapi_db**.\n\n## 9. Naming and style\n\n- **Files and modules:** Lowercase with underscores (e.g. `data_service.py`, `task_repository.py`, `data.py` for the data router).\n- **Routers:** Name the router variable `router`. Group related routes in one file (e.g. all `/data/*` in `data.py`).\n- **Schemas:** Clear names for request (e.g. `DataRequest`) and response (e.g. `TaskResult`, `RecordResponse`). Use type hints and optional fields where appropriate.\n- **Docstrings:** Short module docstring and route docstrings so OpenAPI and readers understand purpose. Document parameters and return values in Pydantic models if non-obvious.\n\n## 10. Team checklist (before merging)\n\n- [ ] New routes live under `backend/app/api/v1/endpoints/` and are mounted in `api/v1/__init__.py`.\n- [ ] Handlers use `Depends(get_async_session)` or `Depends(get_*_service)` / `Depends(get_*_repository)` from `deps.py`; no ad-hoc session or service creation in routes.\n- [ ] Request/response use Pydantic models from `schemas.py`; responses use `response_model=` and never return raw ORM instances.\n- [ ] I/O in the request path is **async** (AsyncSession, async repo methods); any blocking call is wrapped in `asyncio.to_thread`.\n- [ ] Errors are mapped to **HTTPException** in endpoints; services/repos do not raise HTTP-specific errors.\n- [ ] New or changed DB models have an Alembic migration; DB name remains **fastapi_db**.\n- [ ] `make format` and `make lint` have been run from repo root and pass.\n\n## Quick reference (this project)\n\n| Concern | Where / how |\n|--------|-------------|\n| Add route | `backend/app/api/v1/endpoints/<domain>.py` + include in `api/v1/__init__.py` |\n| Add dependency | `backend/app/api/v1/deps.py` (e.g. `get_*_service`, `get_*_repository`) |\n| Request/response models | `backend/app/models/schemas.py` |\n| DB models | `backend/app/models/database.py` + Alembic migration |\n| Business logic | `backend/app/services/` (accept session/repos in constructor) |\n| Data access | `backend/app/repositories/` (accept AsyncSession) |\n| Blocking in request path | `await asyncio.to_thread(sync_func, ...)` then continue async |\n| Idempotency | Middleware; add path to `IDEMPOTENT_PATHS` if needed |\n\nFor more detail, see `.cursor/rules/fastapi-python-best-practices.md` and `.cursor/rules/standards.md`.\n"},"lastSynced":"2026-03-08T02:12:01.215Z","agentAnalysis":{"suitability":{"en":"Perfect for Python-based AI Agents needing efficient and scalable API development with FastAPI","zh":"非常适合需要高效和可扩展API开发的基于Python的AI代理，使用FastAPI","ja":"PythonベースのAIエージェントが効率的でスケーラブルなAPI開発を必要とする場合に最適です。FastAPIを使用します","ko":"파이썬 기반의 AI 에이전트가 효율적이고 확장 가능한 API 개발을 필요로 할 때 적합합니다. FastAPI를 사용합니다","es":"Perfecto para agentes de IA basados en Python que necesitan un desarrollo de API eficiente y escalable con FastAPI","fr":"Parfait pour les agents d''IA basés sur Python nécessitant un développement d''API efficace et évolutif avec FastAPI","de":"Perfekt für Python-basierte KI-Agents, die eine effiziente und skalierbare API-Entwicklung mit FastAPI benötigen","pt":"Perfeito para Agentes de IA baseados em Python que necessitam de desenvolvimento de API eficiente e escalável com FastAPI","ru":"Идеально подходит для агентов ИИ на основе Python, которым необходим эффективный и масштабируемый разработка API с FastAPI","ar":"مثالي لعميل الذكاء الاصطناعي القائم على بايثون الذي يحتاج إلى تطوير واجهة برمجة التطبيقات الكفء والموسع مع FastAPI"},"recommendation":{"en":"Empowers agents to create production-ready backend templates with a layered architecture and built-in observability, utilizing Python and adhering to FastAPI best practices and standards","zh":"赋予代理创建生产就绪的后端模板的能力，具有分层架构和内置的可观察性，利用Python并遵循FastAPI的最佳实践和标准","ja":"エージェントがプロダクションレディのバックエンドテンプレートを作成できるようにし、分層アーキテクチャとビルトインの可観測性を提供し、Pythonを利用し、FastAPIのベストプラクティスと規格に従う","ko":"에이전트가 프로덕션 준비 백엔드 템플릿을 생성할 수 있도록 하며, 계층화된 아키텍처와 내장된 관찰 가능성을 제공하고, 파이썬을 사용하며, FastAPI의 최고의 관행과 표준을 따름","es":"Habilita a los agentes a crear plantillas de backend de producción con una arquitectura en capas y observabilidad integrada, utilizando Python y siguiendo las mejores prácticas y estándares de FastAPI","fr":"Permet aux agents de créer des modèles de backend prêts pour la production avec une architecture en couches et une observabilité intégrée, en utilisant Python et en suivant les meilleures pratiques et les normes de FastAPI","de":"Ermächtigt Agents, produktionsreife Backend-Vorlagen mit einer geschichteten Architektur und integrierter Observierbarkeit zu erstellen, indem Python verwendet und die FastAPI-Best-Practices und -Standards eingehalten werden","pt":"Habilita os agentes a criar modelos de backend prontos para produção com arquitetura em camadas e observabilidade incorporada, utilizando Python e seguindo as melhores práticas e padrões do FastAPI","ru":"Наделяет агентов возможностью создавать шаблоны бэкенда, готовые 