INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vimalkodoth/fastapi-cursor-starterkit/fastapi-best-practices', 'fastapi-best-practices', 'vimalkodoth', 'fastapi-cursor-starterkit', 'community', 'fastapi-best-practices vimalkodoth fastapi-cursor-starterkit community The fastapi-best-practices skill provides a production-ready backend template for AI teams, featuring a layered architecture and built-in observability. It benefits developers looking to create efficient and scalable APIs. FastAPI Cursor Starter Kit提供了生产级后端模板，采用API-only、分层架构，集成了Celery+RabbitMQ RPC和PostgreSQL+Alembic FastAPI Cursor Starter Kitはプロダクションレベルのバックエンドテンプレートを提供し、API-only、階層化アーキテクチャ、Celery+RabbitMQ RPC、PostgreSQL+Alembicを採用 FastAPI Cursor Starter Kit는 프로덕션급 백엔드 템플릿을 제공하며 API-only, 계층 구조, Celery+RabbitMQ RPC 및 PostgreSQL+Alembic를 채택 FastAPI con mejores prácticas para desarrollo de backend de Agentes de IA, con características como Celery, RabbitMQ y PostgreSQL FastAPI avec les meilleures pratiques pour le développement de backend d''Outils d''IA, avec des fonctionnalités comme Celery, RabbitMQ et PostgreSQL FastAPI mit Best Practices für die Entwicklung von Backend-KI-Tools, mit Funktionen wie Celery, RabbitMQ und PostgreSQL O FastAPI é um framework para desenvolver APIs de alta performance, com suporte a Celery, RabbitMQ e PostgreSQL FastAPI - это фреймворк для разработки высокопроизводительных API, с поддержкой Celery, RabbitMQ и PostgreSQL FastAPI هو إطار لتطوير واجهات برمجة التطبيقات عالية الأداء، مع دعم Celery و RabbitMQ و PostgreSQL fastapi-best-practices setup guide fastapi production-ready backend celery and rabbitmq rpc postgresql and alembic migration fastapi-best-practices vs flask how to use fastapi-best-practices fastapi-best-practices alternative fastapi-best-practices install fastapi-best-practices tutorial fastapi best practices for ai teams FastAPI最佳实践 AIエージェント开发 API-only架构 分层架构 Celery+RabbitMQ RPC PostgreSQL+Alembic 观察性和质量检查 Layered architecture with endpoints, services, and repositories Built-in observability with metrics and idempotency Support for Celery and RabbitMQ RPC PostgreSQL database with Alembic migration tool Automated code formatting with Black and mypy Pre-commit hooks for code quality assurance fastapi-best-practices is a set of standards and templates for building production-ready FastAPI applications with a layered architecture, Celery, RabbitMQ, and PostgreSQL.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ShinChven/comfydl-sources/comfydl-source-manager', 'community', 'ShinChven', 'comfydl-sources', 'ShinChven/comfydl-sources', 'comfydl-source-manager', 0, 0, 39, '2026-03-08T01:57:15.594Z', '2026-03-08T02:12:04.629Z', 'c95129e2d7b7c0e6ad39f4ae1be90d7d428d1248f73caa91f1839088537f1136', '{"id":"ShinChven/comfydl-sources/comfydl-source-manager","name":"comfydl-source-manager","description":{"en":"The comfydl-source-manager skill facilitates the creation and management of default model sources for comfydl, benefiting AI agent developers. It guides the workflow of identifying models, creating YAML files, and validating their schema.","zh":"ComfyDL Source Manager 是一个指导创建和管理默认模型源的工具，支持 HuggingFace 和 Civitai 等平台","ja":"ComfyDL Source Manager は、デフォルトモデルソースの作成と管理を支援するツールで、HuggingFace や Civitai などのプラットフォームをサポートしています","ko":"ComfyDL Source Manager는 기본 모델 소스의 생성 및 관리를 지원하는 도구로 HuggingFace 및 Civitaiなどの 플랫폼을 지원합니다","es":"El comfydl-source-manager es una habilidad que facilita la creación y gestión de fuentes de modelos predeterminadas para comfydl.","fr":"Le comfydl-source-manager est une compétence qui facilite la création et la gestion de sources de modèles par défaut pour comfydl.","de":"Der comfydl-source-manager ist eine Fähigkeit, die die Erstellung und Verwaltung von vorkonfigurierten Modellquellen für comfydl erleichtert.","pt":"O ComfyDL Source Manager é uma ferramenta para criar e gerenciar fontes de modelos padrão. Ele permite a criação de arquivos YAML e a validação de esquemas.","ru":"ComfyDL Source Manager - это инструмент для создания и управления источниками моделей по умолчанию. Он позволяет создавать файлы YAML и проверять схемы.","ar":"ComfyDL Source Manager هو أداة لإنشاء وإدارة مصادر النماذج الافتراضية. يسمح بإنشاء ملفات YAML و التحقق من مخططات البيانات"},"seo":{"title":{"en":"comfydl-source-manager: YAML Workflow Management for AI A...","zh":"ComfyDL Source Manager 设置指南 - AI工具","ja":"ComfyDL Source Manager セットアップガイド - AIエージェント","ko":"ComfyDL Source Manager 설정 가이드 - AI 에이전트","es":"Guía de configuración de comfydl-source-manager para AI A...","fr":"Guide de mise en place de comfydl-source-manager pour les...","de":"Einrichtungsleitfaden für comfydl-source-manager als KI-Tool","pt":"Guia de Configuração do ComfyDL Source Manager","ru":"Настройка ComfyDL Source Manager: ИИ Агенты","ar":"دليل إعداد ComfyDL Source Manager للوكلاء الذكية"},"description":{"en":"Discover how to streamline model source management with comfydl-source-manager. Learn to create and validate YAML files for seamless AI agent integration.","zh":"了解 ComfyDL Source Manager 的工作流程和 YAML 模式，轻松管理默认模型源","ja":"ComfyDL Source Manager のワークフローと YAML スキーマを学び、デフォルトモデルソースを効率的に管理する","ko":"ComfyDL Source Manager의 워크플로우와 YAML 스키마를 배우고 기본 모델 소스를 효율적으로 관리하세요","es":"Aprende a crear y gestionar fuentes de modelos predeterminadas con comfydl-source-manager para mejorar tus proyectos de IA","fr":"Découvrez comment créer et gérer des sources de modèles par défaut avec comfydl-source-manager pour améliorer vos projets d''IA","de":"Erfahren Sie, wie Sie vorkonfigurierte Modellquellen mit comfydl-source-manager erstellen und verwalten, um Ihre KI-Projekte zu verbessern","pt":"Aprenda a criar e gerenciar fontes de modelos padrão com o ComfyDL Source Manager, incluindo YAML e download de URLs","ru":"Узнайте, как создавать и управлять источниками моделей по умолчанию с помощью ComfyDL Source Manager, включая YAML и загрузку URL","ar":"اكتشف كيفية إنشاء وإدارة مصادر النماذج الافتراضية باستخدام ComfyDL Source Manager، بما في ذلك YAML وتنزيل URLs"},"definition":{"en":"comfydl-source-manager is a skill that guides the creation and management of default model sources bundled with comfydl, utilizing YAML files and a specific schema for validation.","zh":"ComfyDL Source Manager 是一个 AI 工具，用于管理默认模型源","ja":"ComfyDL Source Manager は、デフ