INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('m1nuzz/batrust/Cargo Startup Validation', 'Cargo Startup Validation', 'm1nuzz', 'batrust', 'community', 'Cargo Startup Validation m1nuzz batrust community Cargo Startup Validation helps developers validate that cargo run starts successfully without runtime errors for long-running applications. It benefits developers working on daemons, tray apps, and servers. Cargo 启动验证是一个用于验证长期运行应用程序可靠性的过程，包括运行单元测试、检查编译和验证二进制启动 Cargo スタートアップ検証は、長期実行アプリケーションの信頼性を検証するプロセスです Cargo 시작 유효성 검사는 長期 실행 애플리케이션의 신뢰성을 검증하는 프로세스입니다 Cargo Startup Validation es una herramienta que valida que las aplicaciones de ejecución prolongada se inicien correctamente sin errores en tiempo de ejecución. Utiliza comandos como `cargo test` y `cargo check` para garantizar la estabilidad de tus aplicaciones Cargo Startup Validation est un outil qui valide que les applications à exécution prolongée se lancent correctement sans erreurs à l''exécution. Il utilise des commandes comme `cargo test` et `cargo check` pour garantir la stabilité de vos applications Cargo Startup Validation ist ein Tool, das überprüft, ob Langzeit-Anwendungen korrekt starten, ohne Laufzeitfehler. Es verwendet Befehle wie `cargo test` und `cargo check`, um die Stabilität Ihrer Anwendungen zu gewährleisten O Cargo Startup Validation é uma técnica para validar a inicialização de aplicativos de longa execução Валидация Запуска Cargo - это техника для проверки запуска долгоживущих приложений التحقق من صحة تشغيل الحمولة هو تقنية للتحقق من تشغيل البرامج الطويلة how to use Cargo Startup Validation what is Cargo Startup Validation Cargo Startup Validation setup guide Cargo Startup Validation alternative Cargo Startup Validation vs other validation tools install Cargo Startup Validation Cargo Startup Validation for long-running applications Cargo 启动验证 AIエージェント 长期运行应用程序 单元测试 编译检查 二进制启动验证 Windows 平台 Cargo 应用程序 应用程序可靠性 Runs unit tests using cargo test --quiet command Checks compilation using cargo check --quiet command Validates binary startup for long-running applications on Windows using Start-Process PowerShell command Supports critical validation for daemons, tray apps, and servers Executes cargo run commands directly in the console for validation Cargo Startup Validation is a validation process that checks the successful startup of cargo run commands for long-running applications, ensuring error-free execution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Sigumaa/calt/gh-workflow', 'community', 'Sigumaa', 'calt', 'Sigumaa/calt', 'gh-workflow', 0, 0, 39, '2026-03-08T01:57:15.623Z', '2026-03-08T02:13:31.542Z', 'd2df486097c5150b19edf1488fde04cb21d7a7efc497b3fdff7b72db7f9752df', '{"id":"Sigumaa/calt/gh-workflow","name":"gh-workflow","description":{"en":"The gh-workflow skill is designed for Sigumaa/calt GitHub Actions workflow operations, enabling users to confirm, monitor, and re-run workflows. It supports workflow and run listings, log checks, and re-run/cancel operations.","zh":"gh-workflow AI 工具是用于 GitHub Actions 的运用操作，支持 workflow 和 run 的确认、监视、重运行和日志检查。","ja":"gh-workflow AI エージェントは、GitHub Actions の運用操作に限定して使用するスキルです。ワークフローとランの確認、監視、再実行、ログ確認をサポートします。","ko":"gh-workflow AI 도구는 GitHub Actions의 운용操作을 위한 도구로, 워크플로우와 런의 확인, 모니터링, 재실행, 로그 확인을 지원합니다.","es":"gh-workflow es una habilidad para automatizar tareas en GitHub con GitHub Actions y CLI, incluyendo la confirmación de flujos de trabajo y la gestión de ejecuciones.","fr":"gh-workflow est une compétence pour automatiser des tâches sur GitHub avec GitHub Actions et CLI, notamment la confirmation de flux de travail et la gestion d''exécutions.","de":"gh-workflow ist eine Fähigkeit zur Automatisierung von Aufgaben in GitHub mit GitHub Actions und CLI, einschließlich der Bestätigung von Workflows und der Verwaltung von Ausführungen.","pt":"O gh-workflow é uma habilidade que permite a automação de tarefas no GitHub, incluindo a confirmação e monitoramento de fluxos de trabalho e execuções.","ru":"gh-workflow - это навык, который позволяет автоматизировать задачи в GitHub, включая проверку и мониторинг рабочих процессов и запусков.","ar":"gh-workflow هو مهارة تسمح بالآليّة في منصة GitHub، بما في ذلك التحقق والمراقبة من سير العمل والتشغيل"},"seo":{"title":{"en":"gh-workflow: GitHub Actions Workflow Management | AI Agen...","zh":"GitHub 工作流 Setup 指南 - gh-workflow AI 工具","ja":"GitHub Workflow 運用スキル - gh-workflow AI エージェントのベストプラクティス","ko":"GitHub 워크플ロー 설정 가이드 - gh-workflow AI 도구","es":"Guía de Configuración de gh-workflow para GitHub Actions","fr":"Guide de Configuration de gh-workflow pour GitHub Actions","de":"Einrichtungsleitfaden für gh-workflow mit GitHub Actions","pt":"Guia de Configuração do gh-workflow para GitHub Actions","ru":"Настройка gh-workflow для GitHub Actions: Лучшие Практики","ar":"دليل إعداد gh-workflow لعمليات GitHub"},"description":{"en":"Streamline your GitHub workflow operations with the gh-workflow skill. Learn how to confirm, monitor, and re-run workflows with ease. Get started now!","zh":"了解 gh-workflow AI 工具的功能和特点，实现 GitHub 工作流的自动化和优化。","ja":"gh-workflow AI エージェントの機能と特徴をご紹介。GitHub Workflow の自動化と最適化を実現します。","ko":"gh-workflow AI 도구의 기능과 특징을 알아보세요. GitHub 워크플러의 자동화와 최적화를 실현합니다.","es":"Aprende a configurar y utilizar gh-workflow para automatizar tareas en GitHub con GitHub Actions y CLI","fr":"Découvrez comment configurer et utiliser gh-workflow pour automatiser des tâches sur GitHub avec GitHub Actions et CLI","de":"Erfahren Sie, wie Sie gh-workflow für die Automatisierung von Aufgaben in GitHub mit GitHub Actions und CLI konfigurieren und verwenden","pt":"Aprenda a configurar e otimizar o gh-workflow para automação de tarefas no GitHub com nossa guia passo a passo","ru":"Узнайте, как настроить и оптимизировать gh-workflow для автоматизации задач в GitHub с нашей пошаговой инструкцией","ar":"تعلم كيفية إعداد وتحسين gh-workflow لآليّة المهام على منصة GitHub باستخدام دليلنا الخطوة بخطوة"},"definition":{"en":"gh-workflow is a skill for managing GitHub Actions workflows, specifically designed for Sigumaa/calt repository operations.","zh":"gh-workflow AI 工具是 GitHub Actions 的运用操作工具，用于自动化和优化工作流程。","ja":"gh-workflow AI エージェントは、GitHub Actions の運用操作に限定して使用するスキルです。","ko":"gh-workflow AI 도구는 GitHub Actions의 운용操作을 위한 도구로, 워크플로우를 자동화하고 최적화합니다.","es":"gh-workflow es una herramienta de automatización para GitHub que utiliza GitHub Actions y CLI para gestionar flujos de trabajo y ejecuciones.","fr":"gh-workflow est un outil d''automatisation pour GitHub qui utilise GitHub Actions et CLI pour gérer des flux de travail et des exécutions.","de":"gh-workflow ist ein Automatisierungstool für GitHub, das GitHub Actions und CLI verwendet, um Workflows und Ausführungen zu verwalten.","pt":"O gh-workflow é uma habilidade de automação de tarefas que opera com comandos gh workflow e gh run no GitHub.","ru":"gh-workflow - это навык автоматизации задач, который работает с командами gh workflow и gh run в GitHub.","ar":"gh-workflow هو مهارة آليّة للمهام التي تعمل مع أوامر gh workflow و gh run على منصة GitHub"},"features":{"en":["Confirms and monitors GitHub Actions workflows using `gh workflow` and `gh run` commands","Supports re-running and canceling workflows with specific run IDs","Provides log checks for failed runs","Restricts operations to the Sigumaa/calt repository","Automatically delegates non-supported operations to other workflows"],"zh":["支持 workflow 和 run 的确认和监视","实现 workflow 和 run 的重运行和取消","支持日志检查和确认","限定于 Sigumaa/calt 仓库的操作","使用 gh workflow 和 gh run 命令"],"ja":["ワークフローとランの確認と監視をサポート","ワークフローとランの再実行と取消を実現","ログ確認と確認をサポート","Sigumaa/calt リポジトリの操作に限定","gh workflow と gh run コマンドを使用"],"ko":["워크플로우와 런의 확인과 모니터링을 지원","워크플로우와 런의 재실행과 취소를 실현","로그 확인과 확인을 지원","Sigumaa/calt 저장소의 운영에限定","gh workflow와 gh run 명령어를 사용"],"es":["Confirmación de flujos de trabajo y ejecuciones","Gestión de ejecuciones con gh run","Reejecución y cancelación de ejecuciones","Verificación de logs de ejecuciones fallidas","Compatibilidad con GitHub Actions y CLI"],"fr":["Confirmation de flux de travail et d''exécutions","Gestion d''exécutions avec gh run","Réexécution et annulation d''exécutions","Vérification des logs d''exécutions échouées","Compatibilité avec GitHub Actions et CLI"],"de":["Bestätigung von Workflows und Ausführungen","Verwaltung von Ausführungen mit gh run","Neue Ausführung und Abbruch von Ausführungen","Überprüfung von Log-Ausgaben fehlgeschlagener Ausführungen","Kompatibilität mit GitHub Actions und CLI"],"pt":["Confirmação e monitoramento de fluxos de trabalho","Verificação de logs de execuções falhas","Reexecução e cancelamento de execuções","Suporte a comandos gh workflow e gh run"],"ru":["Проверка и мониторинг рабочих процессов","Просмотр журналов неудачных запусков","Перезапуск и отмена запусков","Поддержка команд gh workflow и gh run"],"ar":["التحقق والمراقبة من سير العمل","عرض سجلات التشغيل الفاشلة","إعادة التشغيل وإلغاء التشغيل","دعم أوامر gh workflow و gh run"]},"keywords":{"en":["how to use gh-workflow","gh-workflow setup guide","github actions workflow management","gh-workflow vs github actions","gh-workflow install","what is gh-workflow","gh-workflow alternative","github workflow automation","gh-workflow tutorial"],"zh":["GitHub 工作流","gh-workflow AI 工具","GitHub Actions","工作流自动化","运用操作","Sigumaa/calt","gh workflow","gh run"],"ja":["GitHub Workflow","gh-workflow AI エージェント","GitHub Actions","ワークフロー自動化","運用操作","Sigumaa/calt","gh workflow","gh run"],"ko":["GitHub 워크플로","gh-workflow AI 도구","GitHub Actions","워크플로우 자동화","운용 운영","Sigumaa/calt","gh workflow","gh run"],"es":["gh-workflow","GitHub Actions","CLI","automatización de tareas","gestión de flujos de trabajo","gestión de ejecuciones","GitHub","desarrollo de software","herramientas de automatización"],"fr":["gh-workflow","GitHub Actions","CLI","automatisation de tâches","gestion de flux de travail","gestion d''exécutions","GitHub","développement de logiciels","outils d''automatisation"],"de":["gh-workflow","GitHub Actions","CLI","Automatisierung von Aufgaben","Verwaltung von Workflows","Verwaltung von Ausführungen","GitHub","Softwareentwicklung","Automatisierungstools"],"pt":["gh workflow","github actions","automação de tarefas","fluxos de trabalho","execuções","logs de execuções","reexecução","cancelamento"],"ru":["gh workflow","github actions","автоматизация задач","рабочие процессы","запуски","журналы запусков","перезапуск","отмена"],"ar":["gh workflow","github actions","آليّة المهام","سير العمل","التشغيل","سجلات التشغيل","إعادة التشغيل","إلغاء"]}},"owner":"Sigumaa","repo":"calt","repoPath":"Sigumaa/calt","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.623Z","topics":[],"category":"community","skillMd":{"name":"gh-workflow","description":"Sigumaa/calt リポジトリで GitHub Actions のワークフロー実行状況を `gh workflow` と `gh run` で確認・再実行・監視する運用スキル。CI失敗の原因切り分け、対象ジョブ再実行、実行ログ取得、push直後の最新run監視（`gh run list --limit 1` → `gh run watch RUN_ID --exit-status`）を行う依頼で使用する。典型要求は「workflow一覧を見たい」「runを再実行したい」「失敗ジョブのログを確認したい」。`Sigumaa/calt` 以外のリポジトリ操作、`gh` 未認証環境での実操作、ワークフロー以外の実装作業には使用しない。","bodyPreview":"# GitHub Workflow 運用スキル（Sigumaa/calt 限定）\n\n## Overview\n- この skill は `Sigumaa/calt` の GitHub Actions 運用操作に限定して使う。\n- 対応範囲は `gh workflow` と `gh run` を使う確認・監視・再実行・ログ確認である。\n- `--repo` で他リポジトリを指定する操作は禁止する。\n\n## ワークフロー判定\n- 次の依頼なら発火して処理する。\n  - workflow 一覧や run 一覧を確認したい\n  - 失敗 run のログを見たい\n  - 対象 run を rerun / cancel したい\n- 次の依頼は発火せず他手順へ委譲する。\n  - `Sigumaa/calt` 以外の repository 操作\n  - `.github/workflows/*.yml` の実装変更\n  - `gh secret` や `gh variable` の管理\n- 次の依頼は発火し、短い確認質問を返して判定する。\n  - 対象 run_id / workflow 名が未指定","body":"# GitHub Workflow 運用スキル（Sigumaa/calt 限定）\n\n## Overview\n- この skill は `Sigumaa/calt` の GitHub Actions 運用操作に限定して使う。\n- 対応範囲は `gh workflow` と `gh run` を使う確認・監視・再実行・ログ確認である。\n- `--repo` で他リポジトリを指定する操作は禁止する。\n\n## ワークフロー判定\n- 次の依頼なら発火して処理する。\n  - workflow 一覧や run 一覧を確認したい\n  - 失敗 run のログを見たい\n  - 対象 run を rerun / cancel したい\n- 次の依頼は発火せず他手順へ委譲する。\n  - `Sigumaa/calt` 以外の repository 操作\n  - `.github/workflows/*.yml` の実装変更\n  - `gh secret` や `gh variable` の管理\n- 次の依頼は発火し、短い確認質問を返して判定する。\n  - 対象 run_id / workflow 名が未指定\n  - 認証状態が不明\n\n## 実行手順\n1. 対象リポジトリの固定\n```bash\ngh repo view --json nameWithOwner -q .nameWithOwner\n```\n- 結果が `Sigumaa/calt` 以外なら停止し、対象外として返答する。\n\n2. 認証前提の確認\n```bash\ngh auth status\n```\n- `github.com` で有効なログインがない場合は実操作を中止する。\n- 必要時の案内コマンド:\n```bash\ngh auth login --web --hostname github.com --git-protocol https\n```\n\n3. workflow 定義の確認（`gh workflow`）\n```bash\ngh workflow list\ngh workflow view \"<workflow-name-or-id>\"\n```\n\n4. run 状態の確認（`gh run`）\n```bash\ngh run list --limit 20\ngh run view <run-id>\ngh run view <run-id> --log-failed\n```\n\n5. run の操作（必要時のみ）\n```bash\ngh run rerun <run-id>\ngh run rerun <run-id> --failed\ngh run cancel <run-id>\ngh workflow run \"<workflow-name-or-id>\" --ref \"<branch>\"\n```\n- `gh workflow run` は対象 workflow と `--ref` を明示できる場合のみ実施する。\n\n6. 補助情報の取得（必要時のみ）\n```bash\ngh run view <run-id> --job <job-id> --log\ngh run download <run-id> --dir ./artifacts/<run-id>\n```\n\n7. push直後の最新run監視（必要時のみ）\n```bash\ngh run list --limit 1\ngh run watch <run-id> --exit-status\n```\n- `<run-id>` は `gh run list --limit 1` の出力にある最新 run の ID を指定する。\n\n## 禁止事項\n- `Sigumaa/calt` 以外の repository に対する `gh workflow` / `gh run` 操作。\n- `gh ... --repo <other-owner/other-repo>` の使用。\n- 認証未完了のまま rerun / cancel / workflow dispatch を実行すること。\n- `gh api` を使った直接的な workflow 実行状態改変。\n- ワークフロー運用を超える実装変更（コード編集、CI設計変更、権限設定変更）。\n\n## 品質チェック\n- 実行前に `gh repo view` と `gh auth status` の結果を確認する。\n- 実行後は `workflow名/run_id/実行コマンド/結果` を短く記録する。\n- トリガーテストは `references/trigger-test-log.md` に追記する。\n- skill更新後は次を実行して検証する。\n```bash\nuv run --with pyyaml python /home/shiyui/.codex/skills/.system/skill-creator/scripts/quick_validate.py .codex/skills/gh-workflow\n```\n- `description` を変更した場合は差分影響を記録する。\n\n## 返答方針\n- 返答は日本語で、実行した `gh workflow` / `gh run` コマンドを順序どおりに示す。\n- 失敗時は失敗コマンド、原因、次の最小手順（例: 認証、対象指定）を分けて示す。\n- 対象外依頼は「`Sigumaa/calt` 限定のため非対応」と明示して停止する。\n"},"lastSynced":"2026-03-08T02:13:31.542Z","agentAnalysis":{"suitability":{"en":"Perfect for GitHub Actions Agents needing automated workflow management and monitoring capabilities.","zh":"适用于需要自动化工作流管理和监控功能的 GitHub Actions 代理。","ja":"GitHub Actions エージェントが自動化されたワークフロー管理と監視機能を必要とする場合に最適です。","ko":"자동화된 워크플ロー 관리 및 모니터링 기능이 필요한 GitHub Actions 에이전트에 적합합니다.","es":"Perfecto para agentes de GitHub Actions que necesitan capacidades de gestión y monitorización de flujos de trabajo automatizados.","fr":"Parfait pour les agents GitHub Actions ayant besoin de capacités de gestion et de surveillance de flux de travail automatisées.","de":"Perfekt für GitHub Actions Agents, die automatisierte Workflow-Verwaltungs- und Überwachungsfunktionen benötigen.","pt":"Perfeito para Agentes do GitHub Actions que necessitam de gerenciamento e monitoramento de fluxos de trabalho automatizados.","ru":"Идеально подходит для агентов GitHub Actions, которым необходимы автоматизированные возможности управления и мониторинга рабочих процессов.","ar":"مثالي للوكلاء الذين يحتاجون إلى إدارة ومراقبة سير العمل الآلية"},"recommendation":{"en":"Empowers agents to confirm, monitor, and re-run GitHub Actions workflows using gh workflow and gh run commands, supporting workflow and run listings, log checks, and re-run/cancel operations.","zh":"赋予代理确认、监控和重新运行 GitHub Actions 工作流的能力，使用 gh workflow 和 gh run 命令，支持工作流和运行列表、日志检查和重新运行/取消操作。","ja":"エージェントに、gh workflow および gh run コマンドを使用して GitHub Actions ワークフローを確認、監視、および再実行する機能を提供します。ワークフローおよび実行のリスト、ログの確認、および再実行/キャンセル操作をサポートします。","ko":"에이전트가 gh workflow 및 gh run 명령을 사용하여 GitHub Actions 워크플ロー 확인, 모니터링 및 재실행을 가능하게 하며, 워크플로 및 실행 목록, 로그 확인 및 재실행/취소操作을 지원합니다.","es":"Habilita a los agentes a confirmar, monitorear y volver a ejecutar flujos de trabajo de GitHub Actions utilizando los comandos gh workflow y gh run, y soporta listados de flujos de trabajo y ejecuciones, verificación de registros y operaciones de reejecución/cancelación.","fr":"Permet aux agents de confirmer, de surveiller et de réexécuter les flux de travail GitHub Actions en utilisant les commandes gh workflow et gh run, et prend en charge les listes de flux de travail et d''exécution, les vérifications de journaux et les opérations de réexécution/annulation.","de":"Ermächtigt die Agenten, GitHub Actions-Workflows mit den Befehlen gh workflow und gh run zu bestätigen, zu überwachen und erneut auszuführen, und unterstützt Workflow- und Laufverzeichnisse, Protokollprüfungen und Neu- bzw. Abbruchoperationen.","pt":"Habilita os agentes a confirmar, monitorar e reexecutar fluxos de trabalho do GitHub Actions usando comandos gh workflow e gh run, suportando listagens de fluxos de trabalho e execuções, verificações de logs e operações de reexecução/cancelamento.","ru":"Наделяет агентов возможностью подтверждать, отслеживать и повторно запускать рабочие процессы GitHub Actions с помощью команд gh workflow и gh run, поддерживая списки рабочих процессов и запусков, проверку журналов и операции повторного запуска/отмены.","ar":"يمنح الوكلاء القدرة على تأكيد ومراقبة وإعادة تشغيل سير العمل باستخدام أوامر gh workflow و gh run، مع دعم قوائم سير العمل والتشغيل، وفحص السجلات، وعمليات إعادة التشغيل والإلغاء."},"useCases":{"en":["Monitoring failed GitHub Actions runs and retrieving logs for debugging","Re-running cancelled or failed workflows to ensure continuous integration","Listing and managing GitHub Actions workflows and runs for repository maintenance"],"zh":["监控失败的 GitHub Actions 运行并检索日志进行调试","重新运行取消或失败的工作流以确保持续集成","列出和管理 GitHub Actions 工作流和运行以进行存储库维护"],"ja":["失敗した GitHub Actions 実行を監視し、ログを取得してデバッグを行う","キャンセルまたは失敗したワークフローを再実行して継続的インテグレーションを確保する","GitHub Actions ワークフローおよび実行をリストし、管理してリポジトリのメンテナンスを行う"],"ko":["실패한 GitHub Actions 실행을 모니터링하고 로그를 가져와 디버깅을 수행하는 것","취소되거나 실패한 워크플로를 재실행하여 지속적인 통합을 보장하는 것","GitHub Actions 워크플로 및 실행을 나열하고 관리하여 리포지토리 유지 보수를 수행하는 것"],"es":["Monitorear ejecuciones fallidas de GitHub Actions y recuperar registros para depuración","Volver a ejecutar flujos de trabajo cancelados o fallidos para garantizar la integración continua","Listar y gestionar flujos de trabajo y ejecuciones de GitHub Actions para el mantenimiento del repositorio"],"fr":["Surveiller les exécutions having échoué de GitHub Actions et récupérer les journaux pour le débogage","Réexécuter les flux de travail annulés ou ayant échoué pour