INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Sigumaa/calt/gh-workflow', 'gh-workflow', 'Sigumaa', 'calt', 'community', 'gh-workflow Sigumaa calt community The gh-workflow skill is designed for Sigumaa/calt GitHub Actions workflow operations, enabling users to confirm, monitor, and re-run workflows. It supports workflow and run listings, log checks, and re-run/cancel operations. gh-workflow AI 工具是用于 GitHub Actions 的运用操作，支持 workflow 和 run 的确认、监视、重运行和日志检查。 gh-workflow AI エージェントは、GitHub Actions の運用操作に限定して使用するスキルです。ワークフローとランの確認、監視、再実行、ログ確認をサポートします。 gh-workflow AI 도구는 GitHub Actions의 운용操作을 위한 도구로, 워크플로우와 런의 확인, 모니터링, 재실행, 로그 확인을 지원합니다. gh-workflow es una habilidad para automatizar tareas en GitHub con GitHub Actions y CLI, incluyendo la confirmación de flujos de trabajo y la gestión de ejecuciones. gh-workflow est une compétence pour automatiser des tâches sur GitHub avec GitHub Actions et CLI, notamment la confirmation de flux de travail et la gestion d''exécutions. gh-workflow ist eine Fähigkeit zur Automatisierung von Aufgaben in GitHub mit GitHub Actions und CLI, einschließlich der Bestätigung von Workflows und der Verwaltung von Ausführungen. O gh-workflow é uma habilidade que permite a automação de tarefas no GitHub, incluindo a confirmação e monitoramento de fluxos de trabalho e execuções. gh-workflow - это навык, который позволяет автоматизировать задачи в GitHub, включая проверку и мониторинг рабочих процессов и запусков. gh-workflow هو مهارة تسمح بالآليّة في منصة GitHub، بما في ذلك التحقق والمراقبة من سير العمل والتشغيل how to use gh-workflow gh-workflow setup guide github actions workflow management gh-workflow vs github actions gh-workflow install what is gh-workflow gh-workflow alternative github workflow automation gh-workflow tutorial GitHub 工作流 gh-workflow AI 工具 GitHub Actions 工作流自动化 运用操作 Sigumaa/calt gh workflow gh run Confirms and monitors GitHub Actions workflows using `gh workflow` and `gh run` commands Supports re-running and canceling workflows with specific run IDs Provides log checks for failed runs Restricts operations to the Sigumaa/calt repository Automatically delegates non-supported operations to other workflows gh-workflow is a skill for managing GitHub Actions workflows, specifically designed for Sigumaa/calt repository operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('elaraai/east-plugin/east', 'community', 'elaraai', 'east-plugin', 'elaraai/east-plugin', 'east', 0, 0, 39, '2026-03-08T01:57:15.638Z', '2026-03-08T02:13:38.203Z', '4e773a26382d23a4b7eb7a12fb89e7e5948f93726ec278d27e060c9db5b37708', '{"id":"elaraai/east-plugin/east","name":"east","description":{"en":"East is a programming language that allows developers to write programs using a fluent API and compile to portable IR, benefiting AI agent development. It provides a statically typed, expression-based language embedded in TypeScript.","zh":"East 是一种静态类型的表达式编程语言，嵌入在 TypeScript 中。它提供了流畅的 API 和可移植的 IR 编译","ja":"East は静的型付けの式ベースプログラミング言語で、TypeScript に埋め込まれています。フルーント API とポータブル IR コンパイルを提供します","ko":"East는 정적 타이핑의 표현식 프로그래밍 언어로, TypeScript에埋め込여 있습니다. 유연한 API와 이식 가능한 IR 컴파일을 제공합니다","es":"East es un lenguaje de programación estáticamente tipado y basado en expresiones que se puede utilizar para escribir programas con una API fluida y compilar a IR portátil","fr":"East est un langage de programmation à typage statique et basé sur des expressions qui peut être utilisé pour écrire des programmes avec une API fluide et compiler vers IR portable","de":"East ist eine statisch typisierte und auf Ausdrücken basierende Programmiersprache, die verwendet werden kann, um Programme mit einer flüssigen API zu schreiben und auf portables IR zu kompilieren","pt":"O East é uma linguagem de programação estática e baseada em expressões, que permite escrever programas usando uma API fluente e compilar para IR portátil","ru":"East - это статически типизированный язык программирования, позволяющий писать программы с помощью fluent API и компилировать в портативный IR","ar":"إيست هي لغة برمجة ثابتة و基于 التعبيرات، التي تسمح بكتابة البرامج باستخدام واجهة برمجة تطبيق fluente وتنفيذها إلى IR محمول"},"seo":{"title":{"en":"East: Embedded Programming Language Setup Guide | AI Agen...","zh":"East 编程语言设置指南","ja":"East プログラミング言語のベストプラクティス","ko":"East 프로그래밍 언어 시작하기","es":"Guía de configuración de East: Lenguaje de programación e...","fr":"Guide de démarrage rapide d''East: Langage de programmatio...","de":"East-Setup-Anleitung: Statisch typisierter Programmierspr...","pt":"East: Guia de Configuração para Desenvolvedores","ru":"ИИ Агенты: East - Руководство по Настройке","ar":"إيست: دليل إعداد الوكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how to harness the power of East, a statically typed language embedded in TypeScript, and unlock its potential for AI agents - get started today!","zh":"了解 East 编程语言的特点和用途，包括静态类型、表达式和 TypeScript 集成","ja":"East プログラミング言語の特徴と用途を学びましょう。静的型付け、式ベース、TypeScript との統合など","ko":"East 프로그래밍 언어의 특징과 용도를 알아보세요. 정적 타이핑, 표현식 및 TypeScript 통합 등","es":"Aprende a utilizar East, un lenguaje de programación estáticamente tipado y basado en expresiones, para escribir programas con una API fluida y compilar a IR...","fr":"Découvrez comment utiliser East, un langage de programmation à typage statique et basé sur des expressions, pour écrire des programmes avec une API fluide et...","de":"Erfahren Sie, wie Sie East verwenden können, eine statisch typisierte und auf Ausdrücken basierende Programmiersprache, um Programme mit einer flüssigen API ...","pt":"Aprenda a configurar o East, uma linguagem de programação estática e baseada em expressões, e descubra suas funcionalidades","ru":"Узнайте, как настроить East, статически типизированный язык программирования, и откройте для себя его возможности","ar":"تعرف على كيفية إعداد إيست، لغة برمجة ثابتة و基于 التعبيرات، واكتشف ميزاتها"},"definition":{"en":"East is a statically typed, expression-based programming language embedded in TypeScript, designed for compiling to portable IR.","zh":"East 是一种编程语言，提供静态类型、表达式和 TypeScript 集成","ja":"East はプログラミング言語で、静的型付け、式ベース、TypeScript 統合を提供します","ko":"East는 프로그래밍 언어로, 정적 타이핑, 표현식 및 TypeScript 통합을 제공합니다","es":"East es un lenguaje de programación estáticamente tipado y basado en expresiones que se integra en TypeScript","fr":"East est un langage de programmation à typage statique et basé sur des expressions qui s''intègre dans TypeScript","de":"East ist eine statisch typisierte und auf Ausdrücken basierende Programmiersprache, die in TypeScript integriert ist","pt":"O que é East? Uma linguagem de programação estática e baseada em expressões, integrada ao TypeScript","ru":"Что такое East? Статически типизированный язык программирования, встроенный в TypeScript","ar":"ما هي إيست؟ لغة برمجة ثابتة و基于 التعبيرات، متكاملة مع TypeScript"},"features":{"en":["Imports types and helpers directly from @elaraai/east","Defines platform functions using East.platform","Supports implementation of functions using console.log","Compiles to portable IR for cross-platform compatibility","Utilizes a fluent API for program development","Includes types such as IntegerType, StringType, ArrayType, and NullType"],"zh":["静态类型检查","表达式编程","TypeScript 集成","流畅的 API","可移植的 IR 编译"],"ja":["静的型付け","式ベースプログラミング","TypeScript 統合","フルーント API","ポータブル IR コンパイル"],"ko":["정적 타이핑","표현식 프로그래밍","TypeScript 통합","유연한 API","이식 가능한 IR 컴파일"],"es":["Tipado estático para una mayor seguridad y eficiencia","API fluida para escribir programas de manera intuitiva","Compilación a IR portátil para una mayor flexibilidad","Integración con TypeScript para una mayor compatibilidad","Definición de funciones de plataforma personalizadas","Uso de tipos de datos como IntegerType, StringType y ArrayType"],"fr":["Typage statique pour une plus grande sécurité et efficacité","API fluide pour écrire des programmes de manière intuitive","Compilation vers IR portable pour une plus grande flexibilité","Intégration avec TypeScript pour une plus grande compatibilité","Définition de fonctions de plateforme personnalisées","Utilisation de types de données tels que IntegerType, StringType et ArrayType"],"de":["Statisches Typsystem für eine höhere Sicherheit und Effizienz","Flüssige API für die intuitive Erstellung von Programmen","Kompilierung auf portables IR für eine höhere Flexibilität","Integration mit TypeScript für eine höhere Kompatibilität","Definition von benutzerdefinierten Plattformfunktionen","Verwendung von Datentypen wie IntegerType, StringType und ArrayType"],"pt":["Linguagem de programação estática e baseada em expressões","API fluente para escrever programas","Compilação para IR portátil","Integração com TypeScript","Tipos de dados estáticos, como IntegerType e StringType"],"ru":["Статически типизированный язык программирования","Fluent API для написания программ","Компиляция в портативный IR","Интеграция с TypeScript","Статические типы данных, такие как IntegerType и StringType"],"ar":["لغة برمجة ثابتة و基于 التعبيرات","واجهة برمجة تطبيق fluente لكتابة البرامج","تنفيذ إلى IR محمول","التكامل مع TypeScript","أنواع بيانات ثابتة، مثل IntegerType و StringType"]},"keywords":{"en":["how to use east","east alternative","east setup guide","what is east language","east vs typescript","east install","east programming language","east ai agent skill","east embedded language"],"zh":["East 编程语言","静态类型检查","表达式编程","TypeScript 集成","AI 编程工具","AIエージェント"],"ja":["East プログラミング言語","静的型付け","式ベースプログラミング","TypeScript 統合","AI プログラミングツール","AIエージェント"],"ko":["East 프로그래밍 언어","정적 타이핑","표현식 프로그래밍","TypeScript 통합","AI 프로그래밍 도구","AI 에이전트"],"es":["east lenguaje de programación","programación estáticamente tipada","api fluida","compilación a ir portátil","integración con typescript","agentes de ia","herramientas de ia","desarrollo de software","programación de expresiones"],"fr":["langage de programmation east","programmation à typage statique","api fluide","compilation vers ir portable","intégration avec typescript","agents de ia","outils de ia","développement de logiciels","programmation d''expressions"],"de":["east programmiersprache","statisch typisierte programmierung","flüssige api","kompilierung auf portables ir","integration mit typescript","künstliche intelligenz agenten","künstliche intelligenz tools","softwareentwicklung","ausdrucksprogrammierung"],"pt":["east linguagem de programação","configuração east","desenvolvimento east","tipos de dados estáticos","api fluente","compilação ir portátil","typescript","desenvolvedores east","guia de configuração east"],"ru":["east язык программирования","настройка east","разработка east","статические типы данных","fluent api","компиляция в портативный ir","typescript","разработчики east","руководство по настройке east"],"ar":["إيست لغة برمجة","إعداد إيست","تنمية إيست","أنواع بيانات ثابتة","واجهة برمجة تطبيق fluente","تنفيذ إلى ir محمول","typescript","مطورو إيست","دليل إعداد إيست"]}},"owner":"elaraai","repo":"east-plugin","repoPath":"elaraai/east-plugin","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.638Z","topics":[],"category":"community","skillMd":{"name":"east","description":"East programming language - a statically typed, expression-based language embedded in TypeScript. Use when writing East programs with @elaraai/east. Triggers for: (1) Writing East functions with East.function() or East.asyncFunction(), (2) Defining types (IntegerType, StringType, ArrayType, StructType, VariantType, etc.), (3) Using platform functions with East.platform() or East.asyncPlatform(), (4) Compiling East programs with East.compile(), (5) Working with East expressions (arithmetic, collections, control flow), (6) Serializing East IR with .toIR() and EastIR.fromJSON(), (7) Standard library operations (formatting, rounding, generation).","bodyPreview":"# East Language\n\nA statically typed, expression-based programming language embedded in TypeScript. Write programs using a fluent API, compile to portable IR.\n\n## Quick Start\n\n```typescript\n// Types and helpers are direct imports (NOT East.IntegerType)\nimport { East, IntegerType, StringType, ArrayType, NullType } from \"@elaraai/east\";\n\n// 1. Define platform functions (East.platform)\nconst log = East.platform(\"log\", [StringType], NullType);\nconst platform = [log.implement(console.log)];\n\n// 2. Def","body":"# East Language\n\nA statically typed, expression-based programming language embedded in TypeScript. Write programs using a fluent API, compile to portable IR.\n\n## Quick Start\n\n```typescript\n// Types and helpers are direct imports (NOT East.IntegerType)\nimport { East, IntegerType, StringType, ArrayType, NullType } from \"@elaraai/east\";\n\n// 1. Define platform functions (East.platform)\nconst log = East.platform(\"log\", [StringType], NullType);\nconst platform = [log.implement(console.log)];\n\n// 2. Define East function (East.function)\nconst sumArray = East.function([ArrayType(IntegerType)], IntegerType, ($, arr) => {\n    const total = $.let(arr.sum());\n    $(log(East.str`Sum: ${total}`));\n    $.return(total);\n});\n\n// 3. Compile and execute (East.compile)\nconst compiled = East.compile(sumArray, platform);\ncompiled([1n, 2n, 3n]);  // logs \"Sum: 6\", returns 6n\n```\n\n## Decision Tree: What Do You Need?\n\n```\nTask → What do you need?\n    │\n    ├─ Create East Expressions (East.*)\n    │   ├─ From TypeScript value → East.value(tsValue) or East.value(tsValue, Type)\n    │   ├─ String interpolation → East.str`Hello ${name}!`\n    │   └─ Inside function body → $.let(value), $.const(value)\n    │\n    ├─ Define a Type (import from package, NOT East.*)\n    │   ├─ Primitive → IntegerType, FloatType, StringType, BooleanType, DateTimeType, BlobType, NullType\n    │   ├─ Collection → ArrayType(T), SetType(K), DictType(K, V), RefType(T)\n    │   ├─ Compound → StructType({...}), VariantType({...}), RecursiveType(...)\n    │   ├─ Function → FunctionType<I, O>, AsyncFunctionType<I, O>\n    │   └─ Patch → PatchType(T) (compute patch type for any East type)\n    │\n    ├─ Create TypeScript Values for East Types\n    │   ├─ NullType → null\n    │   ├─ BooleanType → true, false\n    │   ├─ IntegerType → 42n (bigint literal)\n    │   ├─ FloatType → 3.14 (number literal)\n    │   ├─ StringType → \"hello\"\n    │   ├─ DateTimeType → new Date(\"2025-01-01T00:00:00Z\")\n    │   ├─ BlobType → new Uint8Array([...])\n    │   ├─ ArrayType(T) → [1n, 2n, 3n]\n    │   ├─ SetType(K) → new Set([1n, 2n, 3n])\n    │   ├─ DictType(K, V) → new Map([[\"a\", 1n], [\"b\", 2n]])\n    │   ├─ StructType({...}) → { field1: value1, field2: value2 }\n    │   ├─ VariantType({...}) (use helpers from package)\n    │   │   ├─ Option type → some(value), none  ← preferred for Option/Maybe\n    │   │   └─ Other variants → variant(\"caseName\", value)\n    │   └─ RefType(T) (use helper from package) → ref(value)\n    │\n    ├─ Write a Function (East.*)\n    │   ├─ Synchronous → East.function([inputs], output, ($, ...args) => { ... })\n    │   └─ Asynchronous → East.asyncFunction([inputs], output, ($, ...args) => { ... })\n    │\n    ├─ Compile and Execute (East.*)\n    │   ├─ Sync function → East.compile(fn, platform)\n    │   └─ Async function → East.compileAsync(fn, platform)\n    │\n    ├─ Use Platform Effects (East.*)\n    │   ├─ Sync effect → East.platform(\"name\", [inputs], output).implement(fn)\n    │   └─ Async effect → East.asyncPlatform(\"name\", [inputs], output).implement(fn)\n    │\n    ├─ Block Operations ($)\n    │   ├─ Variables → $.let(value), $.const(value), $.assign(var, value)\n    │   ├─ Execute → $(expr), $.return(value), $.error(message)\n    │   ├─ Control Flow → $.if(...), $.while(...), $.for(...), $.match(...)\n    │   └─ Error Handling → $.try(...).catch(...).finally(...)\n    │\n    ├─ Expression Operations\n    │   ├─ Boolean\n    │   │   ├─ Logic → .and($=>), .or($=>), .not(), .ifElse($=>,$=>)\n    │   │   ├─ Bitwise → .bitAnd(), .bitOr(), .bitXor()\n    │   │   └─ Compare → .equals()/.equal()/.eq(), .notEquals()/.notEqual()/.ne()\n    │   ├─ Integer\n    │   │   ├─ Math → .add()/.plus(), .subtract()/.sub()/.minus(), .multiply()/.mul()/.times(), .divide()/.div(), .remainder()/.mod()/.rem()/.modulo(), .pow(), .abs(), .sign(), .negate(), .log()\n    │   │   ├─ Convert → .toFloat()\n    │   │   └─ Compare → .equals()/.equal()/.eq(), .notEquals()/.notEqual()/.ne(), .lessThan()/.less()/.lt(), .greaterThan()/.greater()/.gt(), .lessThanOrEqual()/.lessEqual()/.lte()/.le(), .greaterThanOrEqual()/.greaterEqual()/.gte()/.ge()\n    │   ├─ Float\n    │   │   ├─ Math → .add()/.plus(), .subtract()/.sub()/.minus(), .multiply()/.mul()/.times(), .divide()/.div(), .remainder()/.mod()/.rem()/.modulo(), .pow(), .abs(), .sign(), .negate()\n    │   │   ├─ Advanced → .sqrt(), .exp(), .log(), .sin(), .cos(), .tan()\n    │   │   ├─ Convert → .toInteger()\n    │   │   └─ Compare → .equals()/.equal()/.eq(), .notEquals()/.notEqual()/.ne(), .lessThan()/.less()/.lt(), .greaterThan()/.greater()/.gt(), .lessThanOrEqual()/.lessEqual()/.lte()/.le(), .greaterThanOrEqual()/.greaterEqual()/.gte()/.ge()\n    │   ├─ String\n    │   │   ├─ Transform → .concat(), .repeat(), .substring(), .upperCase(), .lowerCase(), .trim(), .trimStart(), .trimEnd()\n    │   │   ├─ Replace → .replace(), .replaceAll(), .split()\n    │   │   ├─ Query → .length(), .startsWith(), .endsWith(), .contains(), .indexOf(), .charAt()\n    │   │   ├─ Parse → .parse(), .parseJson()\n    │   │   ├─ Encode → .encodeUtf8(), .encodeUtf16()\n    │   │   └─ Compare → .equals()/.equal()/.eq(), .notEquals()/.notEqual()/.ne(), .lessThan()/.less()/.lt(), .greaterThan()/.greater()/.gt(), .lessThanOrEqual()/.lessEqual()/.lte()/.le(), .greaterThanOrEqual()/.greaterEqual()/.gte()/.ge()\n    │   ├─ DateTime\n    │   │   ├─ Components → .getYear(), .getMonth(), .getDayOfMonth(), .getDayOfWeek(), .getHour(), .getMinute(), .getSecond(), .getMillisecond()\n    │   │   ├─ Arithmetic → .addDays(), .subtractDays(), .addHours(), .subtractHours(), .addMinutes(), .addSeconds(), .addMilliseconds(), .addWeeks()\n    │   │   ├─ Duration → .durationDays(), .durationHours(), .durationMinutes(), .durationSeconds(), .durationMilliseconds(), .durationWeeks()\n    │   │   ├─ Convert → .toEpochMilliseconds(), .printFormatted()\n    │   │   └─ Compare → .equals()/.equal()/.eq(), .notEquals()/.notEqual()/.ne(), .lessThan()/.less()/.lt(), .greaterThan()/.greater()/.gt(), .lessThanOrEqual()/.lessEqual()/.lte()/.le(), .greaterThanOrEqual()/.greaterEqual()/.gte()/.ge()\n    │   ├─ Blob\n    │   │   ├─ Read → .size(), .getUint8()\n    │   │   ├─ Decode → .decodeUtf8(), .decodeUtf16(), .decodeBeast(), .decodeCsv()\n    │   │   └─ Compare → .equals()/.equal()/.eq(), .notEquals()/.notEqual()/.ne()\n    │   ├─ Array\n    │   │   ├─ Read → .size(), .length(), .has(), .get(), .at(), .tryGet(), .getKeys()\n    │   │   ├─ Mutate → .update(), .pushLast(), .popLast(), .pushFirst(), .popFirst(), .append(), .prepend(), .clear(), .sortInPlace(), .reverseInPlace()\n    │   │   ├─ Transform → .copy(), .slice(), .concat(), .sort(), .reverse(), .map(), .filter(), .filterMap(), .flatMap()\n    │   │   ├─ Search → .findFirst(), .findAll(), .firstMap(), .isSorted()\n    │   │   ├─ Reduce → .reduce(), .every(), .some(), .sum(), .mean(), .maximum(), .minimum(), .findMaximum(), .findMinimum()\n    │   │   ├─ Convert → .stringJoin(), .toSet(), .toDict(), .flattenToSet(), .flattenToDict(), .encodeCsv()\n    │   │   ├─ Group → .groupReduce(), .groupSize(), .groupSum(), .groupMean(), .groupMinimum(), .groupMaximum(), .groupToArrays(), .groupToSets(), .groupToDicts(), .groupEvery(), .groupSome()\n    │   │   └─ Compare → .equals()/.equal()/.eq(), .notEquals()/.notEqual()/.ne()\n    │   ├─ Set\n    │   │   ├─ Read → .size(), .has()\n    │   │   ├─ Mutate → .insert(), .tryInsert(), .delete(), .tryDelete(), .clear(), .unionInPlace()\n    │   │   ├─ Set Ops → .copy(), .union(), .intersection(), .difference(), .symmetricDifference(), .isSubsetOf(), .isSupersetOf(), .isDisjointFrom()\n    │   │   ├─ Transform → .filter(), .filterMap(), .map(), .forEach(), .firstMap()\n    │   │   ├─ Reduce → .reduce(), .every(), .some(), .sum(), .mean()\n    │   │   ├─ Convert → .toArray(), .toSet(), .toDict(), .flattenToArray(), .flattenToSet(), .flattenToDict()\n    │   │   ├─ Group → .groupReduce(), .groupSize(), .groupSum(), .groupMean(), .groupToArrays(), .groupToSets(), .groupToDicts(), .groupEvery(), .groupSome()\n    │   │   └─ Compare → .equals()/.equal()/.eq(), .notEquals()/.notEqual()/.ne()\n    │   ├─ Dict\n    │   │   ├─ Read → .size(), .has(), .get(), .tryGet(), .keys(), .getKeys()\n    │   │   ├─ Mutate → .insert(), .insertOrUpdate(), .update(), .merge(), .getOrInsert(), .delete(), .tryDelete(), .pop(), .swap(), .clear(), .unionInPlace()\n    │   │   ├─ Transform → .copy(), .map(), .filter(), .filterMap(), .forEach(), .firstMap()\n    │   │   ├─ Reduce → .reduce(), .every(), .some(), .sum(), .mean()\n    │   │   ├─ Convert → .toArray(), .toSet(), .toDict(), .flattenToArray(), .flattenToSet(), .flattenToDict()\n    │   │   ├─ Group → .groupReduce(), .groupSize(), .groupSum(), .groupMean(), .groupToArrays(), .groupToSets(), .groupToDicts(), .groupEvery(), .groupSome()\n    │   │   └─ Compare → .equals()/.equal()/.eq(), .notEquals()/.notEqual()/.ne()\n    │   ├─ Struct → .fieldName (direct property access)\n    │   ├─ Variant → .match(), .unwrap(), .hasTag(), .getTag(), .equals()/.equal()/.eq(), .notEquals()/.notEqual()/.ne()\n    │   └─ Ref → .get(), .update(), .merge()\n    │\n    ├─ Standard Library (East.*)\n    │   ├─ Integer → East.Integer.printCommaSeperated(), .roundNearest(), .printOrdinal()\n    │   ├─ Float → East.Float.roundToDecimals(), .printCurrency(), .printCompact()\n    │   ├─ DateTime → East.DateTime.fromComponents(), .roundDownDay(), .parseFormatted()\n    │   ├─ Array → East.Array.range(), .linspace(), .generate()\n    │   ├─ Set → East.Set.generate()\n    │   ├─ Dict → East.Dict.generate()\n    │   ├─ Blob → East.Blob.encodeBeast(), blob.decodeCsv(), array.encodeCsv()\n    │   └─ String → East.String.printJson(), East.String.printError()\n    │\n    ├─ Comparisons (East.*)\n    │   ├─ Equality → East.equal()/.equals()/.eq(), East.notEqual()/.notEquals()/.ne()\n    │   ├─ Ordering → East.less()/.lessThan()/.lt(), East.greater()/.greaterThan()/.gt()\n    │   ├─ Bounds → East.lessEqual()/.lte()/.le(), East.greaterEqual()/.gte()/.ge()\n    │   ├─ Identity → East.is() (reference equality for mutable types)\n    │   └─ Utilities → East.min(), East.max(), East.clamp()\n    │\n    ├─ Conversion (East.*)\n    │   └─ To string → East.print(expr)\n    │\n    ├─ Patch Operations (East.*)\n    │   ├─ Compute diff → East.diff(before, after) → returns patch\n    │   ├─ Apply patch → East.applyPatch(value, patch) → returns patched value\n    │   ├─ Compose patches → East.composePatch(first, second, type) → returns combined patch\n    │   └─ Invert patch → East.invertPatch(patch, type) → returns undo patch\n    │\n    └─ Serialization\n        ├─ IR → fn.toIR(), ir.toJSON(), EastIR.fromJSON(data).compile(platform)\n        └─ Data → East.Blob.encodeBeast(value, ''v2''), blob.decodeBeast(type, ''v2'')\n```\n\n## Type System Summary\n\n| Type | `ValueTypeOf<Type>` | Mutability |\n|------|---------------------|------------|\n| `NullType` | `null` | Immutable |\n| `BooleanType` | `boolean` | Immutable |\n| `IntegerType` | `bigint` | Immutable |\n| `FloatType` | `number` | Immutable |\n| `StringType` | `string` | Immutable |\n| `DateTimeType` | `Date` | Immutable |\n| `BlobType` | `Uint8Array` | Immutable |\n| `ArrayType<T>` | `ValueTypeOf<T>[]` | **Mutable** |\n| `SetType<K>` | `Set<ValueTypeOf<K>>` | **Mutable** |\n| `DictType<K, V>` | `Map<ValueTypeOf<K>, ValueTypeOf<V>>` | **Mutable** |\n| `RefType<T>` | `ref<ValueTypeOf<T>>` | **Mutable** |\n| `StructType<Fields>` | `{...}` | Immutable |\n| `VariantType<Cases>` | `variant` | Immutable |\n| `FunctionType<I, O>` | Function | Immutable |\n| `PatchType<T>` | `variant` | Immutable |\n\n## Key Patterns\n\n### TypeScript Values vs East Expressions\n\nTypeScript values and East expressions are different. East methods only work on East expressions.\n\n```typescript\n// WRONG - Cannot call East methods on TypeScript values\nconst THRESHOLD = 100n;  // This is a TypeScript bigint\nEast.function([IntegerType], BooleanType, ($, x) => {\n    $.return(x.greaterThan(THRESHOLD));  // ERROR: THRESHOLD has no .greaterThan()\n});\n\n// CORRECT - Wrap TypeScript values with East.value()\nconst THRESHOLD = 100n;\nEast.function([IntegerType], BooleanType, ($, x) => {\n    $.return(x.greaterThan(East.value(THRESHOLD)));  // OK\n});\n\n// ALSO CORRECT - Use $.const() inside the function\nEast.function([IntegerType], BooleanType, ($, x) => {\n    const threshold = $.const(THRESHOLD);  // Creates East expression\n    $.return(x.greaterThan(threshold));    // OK\n});\n```\n\n**Rule**: Function parameters are already East expressions. External TypeScript values must be wrapped with `East.value()` or bound with `$.const()`.\n\n### Creating Variant Values\n```typescript\nimport { variant, some, none, ref } from \"@elaraai/east\";\n\n// Option types - use some() and none helpers (preferred)\nconst hasValue = some(42n);      // { type: \"some\", value: 42n }\nconst noValue = none;            // { type: \"none\", value: null }\n\n// AVOID: variant(\"some\", ...) and variant(\"none\", ...) for Option types\n// const hasValue = variant(\"some\", 42n);  // works but use some() instead\n// const noValue = variant(\"none\", null);  // works but use none instead\n\n// Other variant types - use variant()\nconst success = variant(\"ok\", \"done\");\nconst failure = variant(\"error\", \"failed\");\n\n// Mutable references - use ref()\nconst counter = ref(0n);\n```\n\n### String Interpolation\n```typescript\n// East.str`` creates a StringExpr from a template\n// Only East expressions can be interpolated, NOT plain TypeScript values\n\nconst MY_CONSTANT = 100n;  // TypeScript value\n\nEast.function([IntegerType], StringType, ($, x) => {\n    // CORRECT - x is already an East expression (function parameter)\n    const msg1 = $.let(East.str`Value: ${x}`);\n\n    // CORRECT - wrap TypeScript constant with East.value()\n    const msg2 = $.let(East.str`Threshold: ${East.value(MY_CONSTANT)}`);\n\n    // CORRECT - use $.const() to create East expression first\n    const threshold = $.const(MY_CONSTANT);\n    const msg3 = $.let(East.str`Threshold: ${threshold}`);\n\n    // WRONG - cannot interpolate plain TypeScript values\n    // const msg4 = $.let(East.str`Threshold: ${MY_CONSTANT}`);  // ERROR\n\n    $.return(msg1);\n});\n```\n\n### Error Handling\n```typescript\n$.try($ => {\n    $.assign(result, arr.get(index));\n}).catch(($, message, stack) => {\n    $.assign(result, -1n);\n}).finally($ => {\n    // cleanup\n});\n```\n\n### Platform Function Implementations\n```typescript\n// Platform implementations are raw TypeScript functions that receive East values\n// (bigint for Integer, number for Float, string for String, etc.)\n\n// Sync platform - regular TypeScript function\nconst log = East.platform(\"log\", [StringType], NullType);\nconst timeNs = East.platform(\"time_ns\", [], IntegerType);\n\n// Async platform - async TypeScript function\nconst fetchStatus = East.asyncPlatform(\"fetch_status\", [StringType], StringType);\n\n// Implementations receive/return TypeScript values matching East types\nconst platform = [\n    log.implement(console.log),                          // (msg: string) => void\n    timeNs.implement(() => process.hrtime.bigint()),     // () => bigint\n    fetchStatus.implement(async (url: string) => {       // async function OK\n        const response = await fetch(url);\n        return `${response.status}`;\n    }),\n];\n\n// In East code: NO await needed - async is handled automatically\nconst myFn = East.asyncFunction([StringType], NullType, ($, url) => {\n    const t1 = $.let(timeNs());\n    const status = $.let(fetchStatus(url));  // no await, just call it\n    const t2 = $.let(timeNs());\n    $(log(East.str`Fetched in ${t2.subtract(t1)} ns, status: ${status}`));\n});\n\n// Compile async functions with East.compileAsync\nconst compiled = East.compileAsync(myFn, platform);\nawait compiled(\"https://example.com\");  // await at the outer TypeScript level\n```\n"},"lastSynced":"2026-03-08T02:13:38.203Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing a statically typed, expression-based programming language for compiling to portable IR","zh":"适用于需要静态类型、基于表达式的编程语言以编译到可移植 IR 的 AI 代理","ja":"静的に型付けされた、式ベースのプログラミング言語を使用してポータブル IR にコンパイルする必要がある AI エージェントに適しています","ko":"정적으로 형식화된 표현식 기반 프로그래밍 언어를 사용하여 이식 가능한 IR로 컴파일하는 것이 필요한 AI 에이전트에 적합합니다","es":"Perfecto para agentes de inteligencia artificial que necesitan un lenguaje de programación estáticamente tipado y basado en expresiones para compilar a IR portátil","fr":"Parfait pour les agents d''intelligence artificielle ayant besoin d''un langage de programmation statiquement typé et basé sur des expressions pour compiler en IR portable","de":"Perfekt für KI-Agents, die ein statisch typisiertes, ausdrucksbasiertes Programmiersprache für die Kompilierung in portables IR benötigen","pt":"Perfeito para Agentes de IA que precisam de uma linguagem de programação com tipagem estática, baseada em expressões, para compilar para IR portátil","ru":"Идеально для агентов ИИ, которым требуется статически типизированный, основанный на выражениях язык программирования для компиляции в портативный IR","ar":"مثالي للوكلاء الذكياء الذين يحتاجون إلى لغة برمجة ذات نوع ثابت و基于 التعبير لتعريف إلى IR قابل للنقل"},"recommendation":{"en":"Empowers agents to write programs using a fluent API and compile to portable IR, leveraging TypeScript and providing a robust development environment with libraries like @elaraai/east, supporting types such as IntegerType, StringType, ArrayType, and NullType","zh":"赋予代理使用流畅的 API 编写程序并编译到可移植 IR 的能力，利用 TypeScript 并提供一个强大的开发环境，包括类似 @elaraai/east 的库，支持诸如 IntegerType、StringType、ArrayType 和 NullType 之类的类型","ja":"エージェントが流畅な API を使用してプログラムを記述し、ポータブル IR にコンパイルする機能を提供します。TypeScript を活用し、@elaraai/east などのライブラリを備えた堅牢な開発環境を提供し、IntegerType、StringType、ArrayType、NullType などの型をサポートします","ko":"에이전트가 유연한 API를 사용하여 프로그램을 작성하고 이식 가능한 IR로 컴파일 할 수 있는 기능을 제공합니다. TypeScript를 활용하고 @elaraai/east와 같은 라이브러리를 갖춘 강력한 개발 환경을 제공하며 IntegerType, StringType, ArrayType, NullType와 같은 유형을 지원합니다","es":"Habilita a los agentes a escribir programas utilizando una API fluida y compilar a IR portátil, aprovechando TypeScript y proporcionando un entorno de desarrollo robusto con bibliotecas como @elaraai/east, que admite tipos como IntegerType, StringType, ArrayType y NullType","fr":"Permet aux agents d''écrire des programmes en utilisant une API fluide et de compiler en IR portable, en exploitant TypeScript et en fournissant un environnement de développement robuste avec des bibliothèques comme @elaraai/east, prenant en charge des types tels que IntegerType, StringType, ArrayType et NullType","de":"Ermöglicht es Agenten, Programme mit einer flüssigen API zu schreiben und in portables IR zu kompilieren, indem es TypeScript nutzt und eine robuste Entwicklungsumgebung mit Bibliotheken wie @elaraai/east bietet, die Typen wie IntegerType, StringType, ArrayType und NullType unterstützt","pt":"Habilita os agentes a escrever programas usando uma API fluente e compilar para IR portátil, aproveitando o TypeScript e fornecendo um ambiente de desenvolvimento robusto com bibliotecas como @elaraai/east, suportando tipos como IntegerType, StringType, ArrayType e NullType","ru":"Наделяет агентов возможностью писать программы с помощью плавного API и компилировать в портативный IR, используя TypeScript и предоставляя надежную среду разработки с библиотеками seperti @elaraai/east, поддерживающими типы như IntegerType, StringType, ArrayType и NullType","ar":"تمكّن الوكلاء من كتابة البرامج باستخدام واجهة برمجة تطبيقات سهلة الاستخدام وتجميعها إلى IR قابل للنقل، واستخدام TypeScript وتوفير بيئة تطوير قوية مع مكتبات مثل @elaraai/east، ودعم أنواع مثل IntegerType و StringType و ArrayType و NullType"},"useCases":{"en":["Defining platform functions with East.platform","Implementing logging functionality with console.log","Compiling programs to portable IR for cross-platform compatibility"],"zh":["使用 East.platform 定义平台函数","使用 console.log 实现日志功能","编译程序到可移植 IR 以实现跨平台兼容性"],"ja":["East.platform を使用してプラットフォーム関数を定義する","console.log を使用してログ機能を実装する","プログラムをポータブル IR にコンパイルしてクロスプラットフォーム互換性を実現する"],"ko":["East.platform을 사용하여 플랫폼 함수를 정의하는 것","console.log를 사용하여 로깅 기능을 구현하는 것","프로그램을 이식 가능한 IR로 컴파일하여 크로스 플랫폼 호환성을 실현하는 것"],"es":["Definir funciones de plataforma con East.platform","Implementar funcionalidad de registro con console.log","Compilar programas a IR portátil para la compatibilidad entre plataformas"],"fr":["Définir des fonctions de plate-forme avec East.platform","Mettre en œuvre la fonctionnalité de journalisation avec console.log","Compiler des programmes en IR portable pour la compatibilité multiplateforme"],"de":["Plattformfunktionen mit East.platform definieren","Protokollfunktion mit console.log implementieren","Programme in portables IR kompilieren für die Kompatibilität zwischen Plattformen"],"pt":["Definir funções de plataforma com East.platform","Implementar funcionalidade de logging com console.log","Compilar programas para IR portátil para compatibilidade entre plataformas"],"ru":["Определение функций платформы с помощью East.platform","Реализация функциональности логирования с помощью console.log","Компиляция программ в портативный IR для совместимости между платформами"],"ar":["تحديد وظائف المنصة باستخدام East.platform","تنفيذ وظيفة تسجيل باستخدام console.log","تجميع البرامج إلى IR قابل للنقل من أجل التوافق بين المنصات"]},"limitations":{"en":["Requires TypeScript environment","Dependent on @elaraai/east library"],"zh":["需要 TypeScript 环境","依赖于 @elaraai/east 库"],"ja":["TypeScript 環境が必要","@elaraai/east ライブラリに依存する"],"ko":["TypeScript 환경이 필요합니다","@elaraai/east 라이브러리에 의존합니다"],"es":["Requiere entorno de TypeScript","Dependiente de la biblioteca @elaraai/east"],"fr":["Nécessite un environnement TypeScript","Dépend de la bibliothèque @elaraai/east"],"de":["Benötigt eine TypeScript-Umgebung","Abhängig von der Bibliothek @elaraai/east"],"pt":["Requer ambiente TypeScript","Dependente da biblioteca @elaraai/east"],"ru":["Требует среды TypeScript","Зависит от библиотеки @elaraai/east"],"ar":["يتطلب بيئة TypeScript","يعتمد على مكتبة @elaraai/east"]},"version":4},"contentHash":"4e773a26382d23a4b7eb7a12fb89e7e5948f93726ec278d27e060c9db5b37708","qualityScore":39}');
