INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('elaraai/east-plugin/east', 'east', 'elaraai', 'east-plugin', 'community', 'east elaraai east-plugin community East is a programming language that allows developers to write programs using a fluent API and compile to portable IR, benefiting AI agent development. It provides a statically typed, expression-based language embedded in TypeScript. East 是一种静态类型的表达式编程语言，嵌入在 TypeScript 中。它提供了流畅的 API 和可移植的 IR 编译 East は静的型付けの式ベースプログラミング言語で、TypeScript に埋め込まれています。フルーント API とポータブル IR コンパイルを提供します East는 정적 타이핑의 표현식 프로그래밍 언어로, TypeScript에埋め込여 있습니다. 유연한 API와 이식 가능한 IR 컴파일을 제공합니다 East es un lenguaje de programación estáticamente tipado y basado en expresiones que se puede utilizar para escribir programas con una API fluida y compilar a IR portátil East est un langage de programmation à typage statique et basé sur des expressions qui peut être utilisé pour écrire des programmes avec une API fluide et compiler vers IR portable East ist eine statisch typisierte und auf Ausdrücken basierende Programmiersprache, die verwendet werden kann, um Programme mit einer flüssigen API zu schreiben und auf portables IR zu kompilieren O East é uma linguagem de programação estática e baseada em expressões, que permite escrever programas usando uma API fluente e compilar para IR portátil East - это статически типизированный язык программирования, позволяющий писать программы с помощью fluent API и компилировать в портативный IR إيست هي لغة برمجة ثابتة و基于 التعبيرات، التي تسمح بكتابة البرامج باستخدام واجهة برمجة تطبيق fluente وتنفيذها إلى IR محمول how to use east east alternative east setup guide what is east language east vs typescript east install east programming language east ai agent skill east embedded language East 编程语言 静态类型检查 表达式编程 TypeScript 集成 AI 编程工具 AIエージェント Imports types and helpers directly from @elaraai/east Defines platform functions using East.platform Supports implementation of functions using console.log Compiles to portable IR for cross-platform compatibility Utilizes a fluent API for program development Includes types such as IntegerType, StringType, ArrayType, and NullType East is a statically typed, expression-based programming language embedded in TypeScript, designed for compiling to portable IR.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tatargabor/wt-tools/wt', 'community', 'tatargabor', 'wt-tools', 'tatargabor/wt-tools', 'wt', 0, 0, 39, '2026-03-08T01:57:15.642Z', '2026-03-08T02:13:42.303Z', '078c4a34e01d5e8b6528ba72b209378725704b840dcc50e4c81877a3e761380a', '{"id":"tatargabor/wt-tools/wt","name":"wt","description":{"en":"wt worktree management tool for parallel AI development and multi-project workflows, supporting git worktrees and human-AI collaboration","zh":"wt工作树管理工具，用于并行AI开发和多项目工作流。支持git工作树和人工智能协作","ja":"wtワークツリーマネージメントツールは、並行AI開発とマルチプロジェクトワークフローをサポート。gitワークツリーと人工知能コラボレーションに対応","ko":"wt 작업 트리 관리 도구는 병렬 AI 개발 및 다중 프로젝트 워크 플로우를 지원하며 git 작업 트리 및 인간-인공지능 협력을 제공","es":"wt es una herramienta para gestionar contexto, enfoque y trabajo paralelo en el desarrollo de agentes de inteligencia artificial, diseñada para flujos de trabajo de múltiples proyectos y tareas de larga duración","fr":"wt est un outil pour gérer le contexte, la focalisation et le travail parallèle dans le développement d''agents d''intelligence artificielle, conçu pour les flux de travail de plusieurs projets et les tâches de longue durée","de":"wt ist ein Tool für die Verwaltung von Kontext, Fokus und paralleler Arbeit in der Entwicklung von KI-Agents, entwickelt für Mehrprojekt-Workflows und langlaufende Aufgaben","pt":"O wt é uma ferramenta de gerenciamento de contexto para desenvolvimento de agentes de IA, projetada para fluxos de trabalho multi-projeto e colaboração humano-IA.","ru":"wt - это инструмент для управления контекстом и фокусом в разработке ИИ Агентов, предназначенный для много-проектных рабочих процессов и сотрудничества человека и ИИ.","ar":"wt هي أداة لإدارة السياق والتركيز في تطوير العوامل الذكية، مصممة للتدفقات العملية متعددة المشاريع والتعاون بين البشر والذكاء الاصطناعي."},"seo":{"title":{"en":"wt Worktree Management Setup Guide","zh":"wt 工作树管理指南","ja":"wt ワークツリー管理セットアップガイド","ko":"wt 작업 트리 관리 설정 가이드","es":"wt: Guía de configuración para gestión de contexto y enfo...","fr":"wt: Guide de configuration pour la gestion du contexte et...","de":"wt: Einrichtungsleitfaden für Kontext- und Fokuserfassung...","pt":"Guia de Configuração do wt: Ferramentas de Gerenciamento ...","ru":"Настройка wt: Инструменты для управления контекстом и фок...","ar":"دليل إعداد wt: أدوات لإدارة السياق والتركيز في تطوير العو..."},"description":{"en":"Learn technical details of wt worktree management for parallel AI development and multi-project workflows","zh":"了解wt工作树管理的技术细节，实现并行AI开发和多项目工作流","ja":"wtワークツリーマネージメントの技術詳細を学び、並行AI開発とマルチプロジェクトワークフローを実現","ko":"wt 작업 트리 관리의 기술적 세부 사항을 알아보고 병렬 AI 개발 및 다중 프로젝트 워크 플ロー 구현","es":"Aprende a utilizar wt para gestionar contexto, enfoque y trabajo paralelo en el desarrollo de agentes de inteligencia artificial con herramientas de gestión ...","fr":"Découvrez comment utiliser wt pour gérer le contexte, la focalisation et le travail parallèle dans le développement d''agents d''intelligence artificielle avec...","de":"Erfahren Sie, wie Sie wt verwenden können, um Kontext, Fokus und parallele Arbeit in der Entwicklung von KI-Agents mit Git-Worktree-Management-Tools zu verwa...","pt":"Aprenda a configurar o wt para gerenciar contextos, foco e trabalho paralelo em desenvolvimento assistido por IA. Descubra como otimizar seus fluxos de trabalho","ru":"Узнайте, как настроить wt для управления контекстом, фокусом и параллельной работой в разработке с помощью ИИ Агентов. Оптимизируйте свои рабочие процессы","ar":"تعرف على كيفية إعداد wt لإدارة السياق والتركيز والعمل المتوازي في تطوير الذكاء الاصطناعي. تحسين تدفقات العمل الخاصة بك"},"definition":{"en":"wt worktree management refers to the technique of using git worktrees for parallel AI development and multi-project workflows","zh":"wt工作树管理是指使用git工作树实现并行AI开发和多项目工作流的技术","ja":"wtワークツリーマネージメントとは、gitワークツリーを使用して並行AI開発とマルチプロジェクトワークフローを実現する技術","ko":"wt 작업 트리 관리란 git 작업 트리를 사용하여 병렬 AI 개발 및 다중 프로젝트 워크 플로우를 구현하는 기술","es":"wt es una herramienta de gestión de contexto y enfoque para el desarrollo de agentes de inteligencia artificial","fr":"wt est un outil de gestion de contexte et de focalisation pour le développement d''agents d''intelligence artificielle","de":"wt ist ein Tool für die Kontext- und Fokuserfassung in der Entwicklung von KI-Agents","pt":"wt é uma ferramenta de gerenciamento de contexto para desenvolvimento de agentes de IA","ru":"wt - это инструмент для управления контекстом в разработке ИИ Агентов","ar":"wt هي أداة لإدارة السياق في تطوير العوامل الذكية"},"features":{"en":["git worktree support","parallel AI development","multi-project workflow management","human-AI collaboration","worktree mode detection","branch management"],"zh":["支持git工作树","并行AI开发","多项目工作流管理","人工智能协作","工作树模式检测","分支管理"],"ja":["gitワークツリー対応","並行AI開発","マルチプロジェクトワークフロー管理","人工知能コラボレーション","ワークツリーモード検出","ブランチ管理"],"ko":["git 작업 트리 지원","병렬 AI 개발","다중 프로젝트 워크 플로우 관리","인간-인공지능 협력","작업 트리 모드 감지","브랜치 관리"],"es":["Gestión de worktrees de Git para desarrollo paralelo","Detección de contexto para identificar el modo de operación","Compatibilidad con flujos de trabajo de múltiples proyectos","Soporte para tareas de larga duración","Colaboración humana-AI para desarrollo de agentes de inteligencia artificial"],"fr":["Gestion de worktrees Git pour développement parallèle","Détection de contexte pour identifier le mode d''opération","Compatibilité avec les flux de travail de plusieurs projets","Prise en charge des tâches de longue durée","Collaboration humaine-AI pour le développement d''agents d''intelligence artificielle"],"de":["Verwaltung von Git-Worktrees für parallele Entwicklung","Kontext-Erkennung zur Identifizierung des Betriebsmodus","Kompatibilität mit Mehrprojekt-Workflows","Unterstützung für langlaufende Aufgaben","Zusammenarbeit zwischen Mensch und KI für die Entwicklung von KI-Agents"],"pt":["Gerenciamento de worktrees para desenvolvimento paralelo de agentes de IA","Detecção de contexto para identificar o modo de operação","Suporte a fluxos de trabalho multi-projeto","Colaboração humano-IA para tarefas de longa duração","Integração com git para gerenciar branches e commits"],"ru":["Управление worktrees для параллельной разработки ИИ Агентов","Обнаружение контекста для определения режима работы","Поддержка много-проектных рабочих процессов","Сотрудничество человека и ИИ для долгосрочных задач","Интеграция с git для управления ветками и коммитами"],"ar":["إدارة worktrees لتطوير العوامل الذكية المتوازي","اكتشاف السياق لتحديد وضع التشغيل","دعم التدفقات العملية متعددة المشاريع","التعاون بين البشر والذكاء الاصطناعي ل المهام الطويلة الأمد","التكامل مع git لإدارة الفروع والالتزامات"]},"keywords":{"en":["wt worktree management","AI development tools","git worktree","parallel development","multi-project workflow","human-AI collaboration","worktree mode detection"],"zh":["wt工作树管理","AI开发工具","git工作树","并行开发","多项目工作流","人工智能协作","工作树模式检测"],"ja":["wtワークツリーマネージメント","AIエージェント開発ツール","gitワークツリー","並行開発","マルチプロジェクトワークフロー","人工知能コラボレーション","ワークツリーモード検出"],"ko":["wt 작업 트리 관리","인공지능 개발 도구","git 작업 트리","병렬 개발","다중 프로젝트 워크 플로우","인간-인공지능 협력","작업 트리 모드 감지"],"es":["wt","agentes de inteligencia artificial","desarrollo de agentes de IA","gestión de contexto","enfoque en desarrollo","worktrees de Git","colaboración humana-AI"],"fr":["wt","agents d''intelligence artificielle","développement d''agents d''IA","gestion de contexte","focalisation dans le développement","worktrees Git","collaboration humaine-AI"],"de":["wt","KI-Agents","Entwicklung von KI-Agents","Kontext-Verwaltung","Fokuserfassung in der Entwicklung","Git-Worktrees","Zusammenarbeit zwischen Mensch und KI"],"pt":["wt","ferramentas de gerenciamento de contexto","desenvolvimento de agentes de IA","gerenciamento de worktrees","colaboração humano-IA","git","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["wt","инструменты управления контекстом","разработка ИИ Агентов","управление worktrees","сотрудничество человека и ИИ","git","разработка программного обеспечения","инструменты разработки"],"ar":["wt","أدوات لإدارة السياق","تطوير العوامل الذكية","إدارة worktrees","التعاون بين البشر والذكاء الاصطناعي","git","تطوير البرمجيات","أدوات التطوير"]}},"owner":"tatargabor","repo":"wt-tools","repoPath":"tatargabor/wt-tools","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.642Z","topics":[],"category":"community","skillMd":{"name":"wt","description":"Manage git worktrees for parallel AI agent development. Use this when asked to create, list, open, close, or merge worktrees, or when working with wt-* commands.","bodyPreview":"# Worktree Management Skill\n\nManage git worktrees for parallel AI agent development.\n\n## Context Detection\n\nFirst, detect which mode you''re operating in:\n\n```bash\n# Check if we''re in a worktree (not the main repo)\nif git rev-parse --is-inside-work-tree &>/dev/null; then\n  BRANCH=$(git branch --show-current)\n  if [[ \"$BRANCH\" == change/* ]]; then\n    CHANGE_ID=\"${BRANCH#change/}\"\n    echo \"Running in worktree: $CHANGE_ID\"\n    MODE=\"worktree\"\n  else\n    echo \"Running in main repository\"\n    MODE=\"","body":"# Worktree Management Skill\n\nManage git worktrees for parallel AI agent development.\n\n## Context Detection\n\nFirst, detect which mode you''re operating in:\n\n```bash\n# Check if we''re in a worktree (not the main repo)\nif git rev-parse --is-inside-work-tree &>/dev/null; then\n  BRANCH=$(git branch --show-current)\n  if [[ \"$BRANCH\" == change/* ]]; then\n    CHANGE_ID=\"${BRANCH#change/}\"\n    echo \"Running in worktree: $CHANGE_ID\"\n    MODE=\"worktree\"\n  else\n    echo \"Running in main repository\"\n    MODE=\"main\"\n  fi\nfi\n```\n\n## Central Control Commands\n\nUse these from the main repository to manage worktrees.\n\n### List Worktrees\n\n```bash\nwt-list\n```\n\nList all active worktrees with their change IDs and paths.\n\nTo see remote branches available for checkout:\n```bash\nwt-list --remote\n```\n\n### Create New Worktree\n\n```bash\nwt-new <change-id>\n```\n\nCreates a new worktree at `../<project>-<change-id>/` with branch `change/<change-id>`.\n\nIf the branch exists on remote, it will be checked out and tracked automatically.\n\nTo force create a new branch even if remote exists:\n```bash\nwt-new <change-id> --new\n```\n\n### Open Worktree for Work\n\n```bash\nwt-work <change-id>\n```\n\nOpens the worktree in Zed editor with Claude Code. This launches a new agent session in that worktree context.\n\nTo open in terminal instead:\n```bash\nwt-work <change-id> --terminal\n```\n\n### Close Worktree\n\n```bash\nwt-close <change-id>\n```\n\nRemoves the worktree. Interactive mode asks what to do with the branch:\n1. Keep branch (can reopen later)\n2. Delete local branch only\n3. Delete local and remote branch\n\nNon-interactive options:\n```bash\nwt-close <change-id> --keep-branch      # Keep the branch\nwt-close <change-id> --delete-remote    # Delete both local and remote\n```\n\n### Merge Worktree\n\n```bash\nwt-merge <change-id>\n```\n\nMerges the worktree branch into the target branch (default: main/master).\n\nOptions:\n```bash\nwt-merge <change-id> --target develop   # Merge to specific branch\nwt-merge <change-id> --no-delete        # Keep branch after merge\n```\n\n## Self-Control Commands\n\nUse these from within a worktree to manage your own state.\n\n### Push Current Branch\n\n```bash\ngit push -u origin $(git branch --show-current)\n```\n\nPushes the current branch to remote and sets up tracking.\n\n### Get Current Change ID\n\n```bash\nCHANGE_ID=$(git branch --show-current | sed ''s|change/||'')\necho \"Current change: $CHANGE_ID\"\n```\n\n### Close Own Worktree\n\nFrom within a worktree, you cannot directly close it (the directory is in use). Instead:\n\n1. Commit and push your changes\n2. Exit the agent session\n3. From main repo, run: `wt-close <change-id>`\n\nOr instruct the user:\n```\nTo close this worktree after I exit:\n  cd <main-repo-path>\n  wt-close <change-id>\n```\n\n### Merge Own Work\n\n```bash\nCHANGE_ID=$(git branch --show-current | sed ''s|change/||'')\nwt-merge \"$CHANGE_ID\"\n```\n\nThis will merge your current branch to the target and optionally close the worktree.\n\n## Workflow Examples\n\n### Central Agent: Create and Delegate Work\n\n```bash\n# List current work items\nwt-list\n\n# Create new worktree for a task\nwt-new fix-login-bug\n\n# Open agent in that worktree\nwt-work fix-login-bug\n```\n\n### Worktree Agent: Complete and Hand Off\n\n```bash\n# Check current context\ngit branch --show-current  # -> change/fix-login-bug\n\n# Do work...\n# ...\n\n# Push changes\ngit push -u origin change/fix-login-bug\n\n# Report back to user that work is ready for merge\necho \"Work complete. To merge: wt-merge fix-login-bug\"\n```\n\n### Full Lifecycle\n\n```bash\n# 1. Central agent creates worktree\nwt-new implement-feature\n\n# 2. Central agent opens worktree for work\nwt-work implement-feature\n\n# 3. Worktree agent does the work, pushes\ngit add -A && git commit -m \"Implement feature\"\ngit push -u origin change/implement-feature\n\n# 4. Central agent merges when ready\nwt-merge implement-feature\n\n# 5. Worktree is cleaned up automatically (or use wt-close)\n```\n\n## Project Health Audit\n\n### Scan Project Health\n\n```bash\nwt-audit scan              # Human-readable report\nwt-audit scan --json       # Machine-readable JSON\nwt-audit scan --condensed  # Summary line only\n```\n\nScans 6 project health dimensions:\n- **Claude Code Config** — permissions, hooks, agents, rules\n- **Design Documentation** — docs/design/*.md coverage\n- **OpenSpec Config** — config.yaml context population\n- **Code Quality Signals** — large files, unused code tooling\n- **CLAUDE.md Structure** — conventions, managed sections\n- **Gitignore Coverage** — sensitive file patterns\n\nOutput includes evidence (what exists), delta (✅/⚠️/❌), and guidance (source pointers for what the LLM should READ to create missing content).\n\n### Interactive Remediation\n\nUse `/wt:audit` to scan and interactively address gaps. The skill runs the scan, presents findings, and helps create project-specific content by reading the actual codebase — not templates.\n\n## Orchestration Supervisor\n\n### Sentinel (Agent Mode)\n\nUse `/wt:sentinel` to start and supervise a `wt-orchestrate` run with intelligent monitoring. The agent starts the orchestrator in background, polls state every 15s, and makes decisions on crashes (log diagnosis), checkpoints (auto-approve periodic), and completion (summary report).\n\n```bash\n/wt:sentinel                                    # basic supervision\n/wt:sentinel --spec docs/v5.md --max-parallel 3 # with options\n```\n\n### Sentinel (Bash Fallback)\n\nFor environments without Claude agent access:\n\n```bash\nwt-sentinel                                      # basic crash recovery\nwt-sentinel --spec docs/v5.md --max-parallel 3   # with options\n```\n\nSee `docs/sentinel.md` for full documentation.\n"},"lastSynced":"2026-03-08T02:13:42.303Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor and AutoGPT requiring efficient parallel development and multi-project workflows with git worktree management","zh":"适用于像Cursor和AutoGPT这样的AI代理，需要高效的并行开发和多项目工作流，并使用git worktree管理","ja":"CursorやAutoGPTのようなAIエージェントに適しており、効率的な並行開発と多プロジェクトのワークフローが可能であり、git worktree管理が必要","ko":"Cursor와 AutoGPT 같은 AI 에이전트에 적합하며, 효율적인 병렬 개발과 다중 프로젝트 워크플로가 가능하며 git worktree 관리가 필요","es":"Ideal para agentes de IA como Cursor y AutoGPT que requieren un desarrollo paralelo eficiente y flujos de trabajo multi-proyecto con gestión de git worktree","fr":"Idéal pour les agents IA comme Cursor et AutoGPT nécessitant un développement parallèle efficace et des flux de travail multi-projets avec gestion de git worktree","de":"Ideal für KI-Agents wie Cursor und AutoGPT, die ein effizientes paralleles Entwicklung und Multi-Projekt-Workflows mit git worktree-Verwaltung erfordern","pt":"Ideal para Agentes de IA como Cursor e AutoGPT que exigem desenvolvimento paralelo eficiente e fluxos de trabalho multi-projeto com gerenciamento de git worktree","ru":"Идеально подходит для агентов ИИ, таких как Cursor и AutoGPT, требующих эффективного параллельного развития и рабочих процессов с несколькими проектами с управлением git worktree","ar":"مثالي لعمليات الوكيل الذكي مثل Cursor و AutoGPT التي تتطلب تطويرًا موازِيًا فعالًا وسلاسل عمل متعددة المشاريع مع إدارة git worktree"},"recommendation":{"en":"Empowers agents to manage git worktrees for parallel AI development, supporting human-AI collaboration and leveraging git worktree functionality for streamlined project workflows, including context detection and branch management using git rev-parse and git branch commands","zh":"赋予代理管理git worktrees以进行并行AI开发的能力，支持人机AI协作，并利用git worktree功能实现流畅的项目工作流，包括使用git rev-parse和git branch命令进行上下文检测和分支管理","ja":"エージェントがgit worktreesを管理して並行AI開発を行う能力を提供し、人間とAIのコラボレーションを支援し、git worktreeの機能を利用してプロジェクトのワークフローを最適化し、git rev-parseとgit branchコマンドを使用したコンテキストの検出とブランチ管理","ko":"에이전트가 git worktrees를 관리하여 병렬 AI 개발을 수행할 수 있는 능력을 제공하며, 인간과 AI의 협력을 지원하며, git worktree 기능을 활용하여 프로젝트 워크플로를 최적화하고, git rev-parse와 git branch 명령을 사용한 컨텍스트 감지 및 브랜치 관리","es":"Habilita a los agentes a gestionar git worktrees para el desarrollo de IA paralelo, apoyando la colaboración humano-IA y aprovechando la funcionalidad de git worktree para flujos de trabajo de proyecto optimizados, incluyendo la detección de contexto y la gestión de ramas utilizando los comandos git rev-parse y git branch","fr":"Permet aux agents de gérer les git worktrees pour le développement parallèle de l''IA, en soutenant la collaboration humain-IA et en exploitant la fonctionnalité de git worktree pour des flux de travail de projet rationalisés, y compris la détection de contexte et la gestion de branches à l''aide des commandes git rev-parse et git branch","de":"Ermächtigt Agents, git worktrees für parallele KI-Entwicklung zu verwalten, unterstützt die Mensch-KI-Zusammenarbeit und nutzt die git worktree-Funktionalität für optimierte Projektabläufe, einschließlich Kontexterkennung und Branch-Verwaltung mithilfe der Befehle git rev-parse und git branch","pt":"Habilita os agentes a gerenciar git worktrees para desenvolvimento de IA paralelo, apoiando a colaboração humano-IA e aproveitando a funcionalidade do git worktree para fluxos de trabalho de projeto otimizados, incluindo detecção de contexto e gerenciamento de branch utilizando comandos git rev-parse e git branch","ru":"Наделяет агентов возможностью управлять git worktree для параллельного развития ИИ, поддерживая сотрудничество человека и ИИ и используя функциональность git worktree для оптимизированных рабочих процессов проекта, включая обнаружение контекста и управление ветками с помощью команд git rev-parse и git branch","ar":"تمكّن الوكيل من إدارة git worktrees لتطوير الذكاء الاصطناعي الموازي، ودعم التعاون بين الإنسان والذكاء الاصطناعي واستغلال وظيفة git worktree لتحسين سلاسل عمل المشروع، بما في ذلك اكتشاف السياق وإدارة الفرع باستخدام أوامر git rev-parse و git branch"},"useCases":{"en":["Managing parallel AI model development across multiple worktrees","Streamlining human-AI collaboration with git worktree-based workflows","Detecting and switching between different worktree modes using git commands"],"zh":["跨多个工作树管理并行AI模型开发","使用git worktree基的工作流进行人类和AI的协作","使用git命令检测和切换不同的工作树模式"],"ja":["複数のワークツリーをまたいだ並行AIモデル開発の管理","git worktreeベースのワークフローを使用した人間とAIのコラボレーション","gitコマンドを使用した異なるワークツリーのモードの検出と切り替え"],"ko":["다중 워크트리를 통해 병렬 AI 모델 개발 관리","git worktree 기반 워크플로를 사용한 인간과 AI의 협력","git 명령을 사용한 다양한 워크트리 모드의 감지 및 전환"],"es":["Gestión del desarrollo de modelos de IA paralelos en varios worktrees","Optimización de la colaboración humano-IA con flujos de trabajo basados en git worktree","Detección y conmutación entre diferentes modos de worktree utilizando comandos git"],"fr":["Gestion du développement parallèle de modèles d''IA sur plusieurs worktrees","Optimisation de la collaboration humain-IA avec des flux de travail basés sur git worktree","Détection et commutation entre différents modes de worktree à l''aide de commandes git"],"de":["Verwaltung der parallelen Entwicklung von KI-Modellen in mehreren worktrees","Optimierung der Mensch-KI-Zusammenarbeit mit git worktree-basierten Workflows","Erkennung und Umschaltung zwischen verschiedenen worktree-Modi mithilfe von git-Befehlen"],"pt":["Gerenciamento de desenvolvimento de modelo de IA paralelo em vários worktrees","Otimização da colaboração humano-IA com fluxos de trabalho baseados em git worktree","Detecção e alternância entre diferentes modos de worktree usando comandos git"],"ru":["Управление параллельным развитием модели ИИ на нескольких worktree","Оптимизация сотрудничества человека и ИИ с рабочими процессами на основе git worktree","Обнаружение и переключение между различными режимами worktree с помощью команд git"],"ar":["إدارة تطوير نموذج الذكاء الاصطناعي الموازي عبر عدة worktrees","تحسين تعاون الإنسان والذكاء الاصطناعي بسلاسل عمل مبنية على git worktree","اكتشاف وتغيير بين أوضاع worktree المختلفة باستخدام أوامر git"]},"limitations":{"en":["Requires git installation and configuration","Limited to git worktree functionality"],"zh":["需要git的安装和配置","仅限git worktree的功能"],"ja":["gitのインストールと設定が必要","git worktreeの機能のみに限定"],"ko":["git 설치 및 구성이 필요","git worktree 기능만 사용 가능"],"es":["Requiere instalación y configuración de git","Limitado a la funcionalidad de git worktree"],"fr":["Nécessite l''installation et la configuration de git","Limité à la fonctionnalité de git worktree"],"de":["Benötigt die Installation und Konfiguration von git","Begrenzt auf die Funktionalität von git worktree"],"pt":["Exige instalação e configuração do git","Limitado à funcionalidade do git worktree"],"ru":["Требует установки и настройки git","Ограничен функциональностью git worktree"],"ar":["يتطلب تثبيت وتفكيك git","محدود bằng وظيفة git worktree"]},"version":4},"contentHash":"078c4a34e01d5e8b6528ba72b209378725704b840dcc50e4c81877a3e761380a","qualityScore":39}');
