INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tatargabor/wt-tools/wt', 'wt', 'tatargabor', 'wt-tools', 'community', 'wt tatargabor wt-tools community wt worktree management tool for parallel AI development and multi-project workflows, supporting git worktrees and human-AI collaboration wt工作树管理工具，用于并行AI开发和多项目工作流。支持git工作树和人工智能协作 wtワークツリーマネージメントツールは、並行AI開発とマルチプロジェクトワークフローをサポート。gitワークツリーと人工知能コラボレーションに対応 wt 작업 트리 관리 도구는 병렬 AI 개발 및 다중 프로젝트 워크 플로우를 지원하며 git 작업 트리 및 인간-인공지능 협력을 제공 wt es una herramienta para gestionar contexto, enfoque y trabajo paralelo en el desarrollo de agentes de inteligencia artificial, diseñada para flujos de trabajo de múltiples proyectos y tareas de larga duración wt est un outil pour gérer le contexte, la focalisation et le travail parallèle dans le développement d''agents d''intelligence artificielle, conçu pour les flux de travail de plusieurs projets et les tâches de longue durée wt ist ein Tool für die Verwaltung von Kontext, Fokus und paralleler Arbeit in der Entwicklung von KI-Agents, entwickelt für Mehrprojekt-Workflows und langlaufende Aufgaben O wt é uma ferramenta de gerenciamento de contexto para desenvolvimento de agentes de IA, projetada para fluxos de trabalho multi-projeto e colaboração humano-IA. wt - это инструмент для управления контекстом и фокусом в разработке ИИ Агентов, предназначенный для много-проектных рабочих процессов и сотрудничества человека и ИИ. wt هي أداة لإدارة السياق والتركيز في تطوير العوامل الذكية، مصممة للتدفقات العملية متعددة المشاريع والتعاون بين البشر والذكاء الاصطناعي. wt worktree management AI development tools git worktree parallel development multi-project workflow human-AI collaboration worktree mode detection wt工作树管理 AI开发工具 git工作树 并行开发 多项目工作流 人工智能协作 工作树模式检测 git worktree support parallel AI development multi-project workflow management human-AI collaboration worktree mode detection branch management wt worktree management refers to the technique of using git worktrees for parallel AI development and multi-project workflows');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('valuecodes/Rehoboam-UI/validate-scene-ui', 'community', 'valuecodes', 'Rehoboam-UI', 'valuecodes/Rehoboam-UI', 'validate-scene-ui', 0, 0, 39, '2026-03-08T01:57:15.643Z', '2026-03-08T02:13:43.208Z', '17a14380e33621a283fecb29ffaa2031f294970aab4745cc87c82d53055b9776', '{"id":"valuecodes/Rehoboam-UI/validate-scene-ui","name":"validate-scene-ui","description":{"en":"The validate-scene-ui skill runs screenshot-based visual validation after scene/UI changes, providing objective evidence in the final report. It benefits developers and testers working with the Reheboam AI interface.","zh":"validate-scene-ui是一种视觉验证工具，使用pnpm和screenshot捕获技术，确保UI变化的准确性","ja":"validate-scene-uiは、視覚的な検証を行うツールで、pnpmとscreenshotキャプチャ技術を使用してUIの変更を正確に検証します","ko":"validate-scene-ui는 시각적 검증을 수행하는 도구로, pnpm 및 스크린샷 캡처 기술을 사용하여 UI 변경 사항을 정확하게 검증합니다","es":"Validate-scene-ui es una herramienta para realizar pruebas visuales automatizadas después de cambios en la interfaz de usuario. Utiliza capturas de pantalla para proporcionar evidencia objetiva en informes finales.","fr":"Validate-scene-ui est un outil pour effectuer des tests visuels automatisés après des modifications de l''interface utilisateur. Il utilise des captures d''écran pour fournir des preuves objectives dans les rapports finals.","de":"Validate-scene-ui ist ein Werkzeug für automatisierte visuelle Tests nach Änderungen an der Benutzeroberfläche. Es verwendet Screenshot-Erfassung, um objektive Beweise in den Endberichten bereitzustellen.","pt":"O Validate Scene UI é uma ferramenta que executa validação visual baseada em capturas de tela após alterações de cena/UI","ru":"Validate Scene UI - это инструмент, который выполняет визуальную проверку на основе захвата экрана после изменений сцены/интерфейса","ar":"Validate Scene UI هو أداة تقوم بتشغيل التحقق المرئي المستند إلى لقطات الشاشة بعد التغييرات في المشهد/واجهة المستخدم"},"seo":{"title":{"en":"validate-scene-ui: Visual Validation Setup Guide | AI Age...","zh":"validate-scene-ui Setup Guide - AIエージェント视觉验证","ja":"validate-scene-ui セットアップガイド - AIエージェントによる画面検証","ko":"validate-scene-ui 설정 가이드 - AI 에이전트 시각적 검증","es":"Guía de configuración de validate-scene-ui para pruebas v...","fr":"Guide de mise en place de validate-scene-ui pour la valid...","de":"Einrichtungsleitfaden für validate-scene-ui zur visuellen...","pt":"Guia de Configuração do Validate Scene UI para Ferramenta...","ru":"Настройка Validate Scene UI для ИИ Агентов","ar":"دليل إعداد Validate Scene UI لأدوات الذكاء الاصطناعي"},"description":{"en":"Learn how to run screenshot-based visual validation with validate-scene-ui. Get started with our setup guide and optimize your scene/UI testing workflow today!","zh":"通过validate-scene-ui实现视觉验证，使用pnpm和screenshot捕获技术，确保UI变化的准确性","ja":"validate-scene-uiを使用して視覚的な検証を行い、pnpmとscreenshotキャプチャ技術でUIの変更を正確に検証する","ko":"validate-scene-ui를 사용하여 시각적 검증을 수행하고 pnpm 및 스크린샷 캡처 기술을 사용하여 UI 변경 사항을 정확하게 검증하십시오","es":"Aprende a utilizar validate-scene-ui para realizar pruebas visuales automatizadas y mejorar la calidad de tus aplicaciones","fr":"Découvrez comment utiliser validate-scene-ui pour effectuer des tests visuels automatisés et améliorer la qualité de vos applications","de":"Erfahren Sie, wie Sie validate-scene-ui verwenden können, um automatisierte visuelle Tests durchzuführen und die Qualität Ihrer Anwendungen zu verbessern","pt":"Aprenda a configurar o Validate Scene UI para capturar telas e validar alterações de cena/UI com o Reheboam","ru":"Узнайте, как настроить Validate Scene UI для захвата экрана и проверки изменений сцены/интерфейса с Reheboam","ar":"تعرف على كيفية إعداد Validate Scene UI لالتقاط الشاشة والتحقق من التغييرات في المشهد/واجهة المستخدم مع Reheboam"},"definition":{"en":"validate-scene-ui is a skill that performs visual validation using screenshot captures, providing an objective way to test scene/UI changes in the Reheboam AI interface.","zh":"validate-scene-ui是一种AIエージェント视觉验证工具","ja":"validate-scene-uiはAIエージェントによる画面検証ツールです","ko":"validate-scene-ui는 AI 에이전트 시각적 검증 도구입니다","es":"Validate-scene-ui es una herramienta de prueba visual que utiliza capturas de pantalla para validar cambios en la interfaz de usuario","fr":"Validate-scene-ui est un outil de test visuel qui utilise des captures d''écran pour valider les modifications de l''interface utilisateur","de":"Validate-scene-ui ist ein Werkzeug für visuelle Tests, das Screenshot-Erfassung verwendet, um Änderungen an der Benutzeroberfläche zu überprüfen","pt":"O Validate Scene UI é uma ferramenta de validação de interface de usuário","ru":"Validate Scene UI - это инструмент проверки интерфейса пользователя","ar":"Validate Scene UI هو أداة للتحقق من واجهة المستخدم"},"features":{"en":["Runs screenshot capture using `pnpm --filter rehoboam-ui screenshot:scene` command","Supports options for sampling animation progression, such as `--count` and `--interval-ms`","Allows custom output directory for screenshots using `--output` option","Generates objective evidence in the final report using screenshot captures","Integrates with the Reheboam AI interface for seamless testing"],"zh":["使用pnpm进行screenshot捕获","支持自定义输出路径和文件名","可配置捕获间隔和次数","支持动画进度样本捕获","使用screenshot:scene命令进行视觉验证"],"ja":["pnpmを使用してscreenshotキャプチャを行う","出力パスとファイル名のカスタマイズをサポート","キャプチャ間隔と回数の設定を可能に","アニメーションの進行度サンプルキャプチャをサポート","screenshot:sceneコマンドを使用して視覚的な検証を行う"],"ko":["pnpm을 사용하여 스크린샷 캡처를 수행","출력 경로와 파일 이름을 사용자 정의","캡처 간격과 횟수를 구성","애니메이션 진행도 샘플 캡처 지원","screenshot:scene 명령을 사용하여 시각적 검증을 수행"],"es":["Ejecución de capturas de pantalla con pnpm","Opciones personalizables para la captura de pantalla, como --count y --interval-ms","Salida de capturas de pantalla en formato PNG","Integración con la interfaz de usuario Rehoboam","Informes finales con evidencia objetiva","Soporte para la prueba de progresión de animaciones"],"fr":["Exécution de captures d''écran avec pnpm","Options personnalisables pour la capture d''écran, comme --count et --interval-ms","Sortie de captures d''écran au format PNG","Intégration avec l''interface utilisateur Rehoboam","Rapports finals avec des preuves objectives","Prise en charge de la vérification de la progression des animations"],"de":["Ausführung von Screenshot-Erfassung mit pnpm","Anpassbare Optionen für die Screenshot-Erfassung, wie --count und --interval-ms","Ausgabe von Screenshot-Erfassung im PNG-Format","Integration mit der Benutzeroberfläche Rehoboam","Endberichte mit objektiven Beweisen","Unterstützung für die Überprüfung von Animationsfortschritten"],"pt":["Captura de tela com comando pnpm","Validação visual após alterações de cena/UI","Opções personalizáveis para captura de tela","Saída de captura de tela em formato PNG","Suporte a animação com opção de intervalo"],"ru":["Захват экрана с помощью команды pnpm","Визуальная проверка после изменений сцены/интерфейса","Настраиваемые опции для захвата экрана","Выход захвата экрана в формате PNG","Поддержка анимации с опцией интервала"],"ar":["التقاط الشاشة باستخدام الأمر pnpm","التحقق المرئي بعد التغييرات في المشهد/واجهة المستخدم","خيارات قابلة للتخصيص لالتقاط الشاشة","مخرج التقاط الشاشة بتنسيق PNG","دعم التحريك مع خيار الفاصل الزمني"]},"keywords":{"en":["how to use validate-scene-ui","validate-scene-ui setup guide","visual validation in Reheboam AI","screenshot-based testing with pnpm","validate-scene-ui alternative tools","validate-scene-ui vs other testing frameworks","install validate-scene-ui","validate-scene-ui tutorial","Reheboam AI interface testing"],"zh":["validate-scene-ui","AIエージェント","视觉验证","pnpm","screenshot","UI变化","视觉检验","自动化测试","前端开发"],"ja":["validate-scene-ui","AIエージェント","画面検証","pnpm","screenshot","UIの変更","視覚的な検証","自動テスト","フロントエンド開発"],"ko":["validate-scene-ui","AI 에이전트","시각적 검증","pnpm","스�린샷","UI 변경","시각적 검사","자동화 테스트","프론트엔드 개발"],"es":["herramientas de prueba visual","pruebas automatizadas","validación de interfaz de usuario","capturas de pantalla","pnpm","Rehoboam","informes finales","evidencia objetiva","Agentes de IA para pruebas"],"fr":["outils de test visuel","tests automatisés","validation de l''interface utilisateur","captures d''écran","pnpm","Rehoboam","rapports finals","preuves objectives","Agents IA pour les tests"],"de":["Werkzeuge für visuelle Tests","automatisierte Tests","Überprüfung der Benutzeroberfläche","Screenshot-Erfassung","pnpm","Rehoboam","Endberichte","objektive Beweise","KI-Agenten für Tests"],"pt":["Validate Scene UI","Ferramentas de IA","Captura de tela","Validação visual","Interface de usuário","Reheboam","pnpm","Desenvolvimento de software"],"ru":["Validate Scene UI","ИИ Агенты","Захват экрана","Визуальная проверка","Интерфейс пользователя","Reheboam","pnpm","Разработка программного обеспечения"],"ar":["Validate Scene UI","أدوات الذكاء الاصطناعي","التقاط الشاشة","التحقق المرئي","واجهة المستخدم","Reheboam","pnpm","تطوير البرمجيات"]}},"owner":"valuecodes","repo":"Rehoboam-UI","repoPath":"valuecodes/Rehoboam-UI","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.643Z","topics":[],"category":"community","skillMd":{"name":"validate-scene-ui","description":"Validate Rehoboam scene animation and UI quality with deterministic Playwright screenshots driven by `apps/ui/scripts/screenshot-scene.ts`. Use when changes touch animation timing, Canvas2D rendering, layout/CSS, overlays, timeline sequencing, or any visual behavior that should be confirmed by screenshots.","bodyPreview":"# Validate Scene UI\n\n## Overview\n\nRun screenshot-based visual validation after scene/UI changes and use the captures as objective evidence in the final report.\n\n## Validation Workflow\n\n1. Run screenshot capture.\n\n```bash\npnpm --filter rehoboam-ui screenshot:scene\n```\n\n2. Use options when needed:\n\n- `pnpm --filter rehoboam-ui screenshot:scene --count 3 --interval-ms 1200` to sample animation progression.\n- `pnpm --filter rehoboam-ui screenshot:scene --output .tmp/screenshots/<label>.png` to keep","body":"# Validate Scene UI\n\n## Overview\n\nRun screenshot-based visual validation after scene/UI changes and use the captures as objective evidence in the final report.\n\n## Validation Workflow\n\n1. Run screenshot capture.\n\n```bash\npnpm --filter rehoboam-ui screenshot:scene\n```\n\n2. Use options when needed:\n\n- `pnpm --filter rehoboam-ui screenshot:scene --count 3 --interval-ms 1200` to sample animation progression.\n- `pnpm --filter rehoboam-ui screenshot:scene --output .tmp/screenshots/<label>.png` to keep outputs tied to the task.\n- `pnpm --filter rehoboam-ui screenshot:scene:headed` for local visual debugging.\n\n3. Review both generated images:\n\n- Full page: `<output>.png`\n- Instrument crop: `<output>.instrument.png`\n\n4. Check visual quality:\n\n- Preserve layout alignment and spacing.\n- Avoid clipping, overlap, or unreadable text.\n- Keep ring/sweep/divergence rendering stable and intentional.\n- Confirm callouts/panel positioning remains usable.\n\n5. Report concrete findings with screenshot file paths and whether the scene quality appears acceptable.\n\n## Notes\n\n- The underlying command executes `apps/ui/scripts/screenshot-scene.ts`, which runs Playwright against `http://127.0.0.1:3000` by default, starts the API worker on `http://127.0.0.1:3001/api/events`, and captures deterministic outputs under `apps/ui/.tmp/screenshots/`.\n- Use this skill by default for UI/animation validation unless the user explicitly asks to skip screenshot checks.\n"},"lastSynced":"2026-03-08T02:13:43.208Z","agentAnalysis":{"suitability":{"en":"Perfect for UI Testing Agents needing automated visual validation capabilities after scene/UI changes.","zh":"非常适合需要自动化视觉验证功能的UI测试代理，特别是在场景/UI更改后。","ja":"UIテストエージェントがシーン/UIの変更後に自動化された視覚的なバリデーション機能を必要とする場合に最適です。","ko":"UI 테스트 에이전트가 장면/UI 변경 후 자동화된 시각적 검증 기능을 필요로 할 때 적합합니다.","es":"Perfecto para agentes de prueba de UI que necesitan capacidades de validación visual automatizada después de cambios en la escena/interfaz de usuario.","fr":"Parfait pour les agents de test d''UI nécessitant des capacités de validation visuelle automatisée après des changements de scène/Interface utilisateur.","de":"Perfekt für UI-Testagenten, die automatisierte visuelle Validierungsfunktionen nach Szenen-/Benutzeroberflächenänderungen benötigen.","pt":"Perfeito para Agentes de Teste de UI que necessitam de capacidades de validação visual automatizadas após alterações de cena/UI.","ru":"Идеально подходит для агентов тестирования UI, которым требуются автоматизированные возможности визуальной проверки после изменений сцены/интерфейса.","ar":"مثالي للوكلاء اختبار واجهة المستخدم الذين يحتاجون إلى إمكانيات التحقق البصري الآلي بعد التغييرات في المشهد / واجهة المستخدم."},"recommendation":{"en":"Empowers agents to run screenshot-based visual validation using pnpm commands, providing objective evidence in final reports and supporting options for sampling animation progression and custom output formats like .png.","zh":"赋予代理运行基于截图的视觉验证，使用pnpm命令，提供最终报告中的客观证据，并支持对动画进度的采样和自定义输出格式，如.png。","ja":"エージェントがpnpmコマンドを使用してスクリーンショットベースの視覚的なバリデーションを実行できるようにし、最終報告書に客観的な証拠を提供し、カスタム出力形式（.pngなど）やアニメーションの進捗状況のサンプリングオプションをサポートします。","ko":"에이전트가 pnpm 명령을 사용하여 스크린샷 기반의 시각적 검증을 실행할 수 있도록 하며, 최종 보고서에 객관적인 증거를 제공하며, 사용자 지정 출력 형식(.png 등) 및 애니메이션 진행의 샘플링 옵션을 지원합니다.","es":"Habilita a los agentes a ejecutar una validación visual basada en capturas de pantalla utilizando comandos pnpm, proporcionando evidencia objetiva en informes finales y admitiendo opciones para la progresión de la animación de muestreo y formatos de salida personalizados como .png.","fr":"Permet aux agents d''exécuter une validation visuelle basée sur des captures d''écran en utilisant des commandes pnpm, fournissant des preuves objectives dans les rapports finals et prenant en charge les options pour la progression de l''animation d''échantillonnage et les formats de sortie personnalisés comme .png.","de":"Ermächtigt Agenten, eine screenshot-basierte visuelle Validierung mithilfe von pnpm-Befehlen durchzuführen, wodurch objektive Beweise in den Endberichten bereitgestellt und Optionen für die Animationsfortschrittsstichproben und benutzerdefinierte Ausgabeformate wie .png unterstützt werden.","pt":"Habilita os agentes a executar validação visual baseada em capturas de tela usando comandos pnpm, fornecendo evidências objetivas em relatórios finais e suportando opções para amostragem da progressão da animação e formatos de saída personalizados como .png.","ru":"Наделяет агентов возможностью запускать проверку визуальной достоверности на основе скриншотов с помощью команд pnpm, предоставляя объективные доказательства в итоговых отчетах и поддерживая опции для выборки прогресса анимации и пользовательских форматов вывода, таких как .png.","ar":"يمنح الوكلاء khảية تشغيل التحقق البصري القائم على لقطات الشاشة باستخدام أوامر pnpm، مما يوفر أدلة موضوعية في التقارير النهائية ودعم خيارات لتحديث تقدم Animation وتنسيقات الإخراج المخصصة مثل .png."},"useCases":{"en":["Automating visual validation after UI updates","Generating objective evidence for scene/UI changes","Debugging animation progression with customizable intervals"],"zh":["自动化UI更新后的视觉验证","为场景/UI更改生成客观证据","使用可自定义间隔调试动画进度"],"ja":["UIの更新後に視覚的なバリデーションを自動化する","シーン/UIの変更に対する客観的な証拠を生成する","カスタム間隔でアニメーションの進捗状況をデバッグする"],"ko":["UI 업데이트 후 시각적 검증을 자동화하는 것","장면/UI 변경에 대한 객관적인 증거를 생성하는 것","사용자 지정 간격으로 애니메이션 진행 상황을 디버깅하는 것"],"es":["Automatizar la validación visual después de las actualizaciones de la interfaz de usuario","Generar evidencia objetiva para los cambios de escena/interfaz de usuario","Depurar la progresión de la animación con intervalos personalizables"],"fr":["Automatiser la validation visuelle après les mises à jour de l''interface utilisateur","Générer des preuves objectives pour les changements de scène/interface utilisateur","Déboguer la progression de l''animation avec des intervalles personnalisables"],"de":["Automatisierung der visuellen Validierung nach Benutzeroberflächen-Aktualisierungen","Erzeugen von objektiven Beweisen für Szenen-/Benutzeroberflächen-Änderungen","Fehlerbehebung der Animationsfortschritts mit anpassbaren Intervallen"],"pt":["Automatizar a validação visual após atualizações de UI","Gerar evidências objetivas para alterações de cena/UI","Depurar a progressão da animação com intervalos personalizados"],"ru":["Автоматизировать проверку визуальной достоверности после обновлений интерфейса","Генерировать объективные доказательства для изменений сцены/интерфейса","Отлаживать прогресс анимации с настраиваемыми интервалами"],"ar":["أتمتة التحقق البصري بعد تحديثات واجهة المستخدم","توليد أدلة موضوعية لتحديثات المشهد / واجهة المستخدم","تصحيح أخطاء تقدم Animation مع فترات زمنية مخصصة"]},"limitations":{"en":["Requires pnpm installation","Limited to Reheboam AI interface","Dependent on screenshot capture functionality"],"zh":["需要pnpm安装","仅限于Reheboam AI接口","依赖于截图捕获功能"],"ja":["pnpmのインストールが必要","Reheboam AIインターフェイスに限定される","スクリーンショットのキャプチャ機能に依存する"],"ko":["pnpm 설치가 필요함","Reheboam AI 인터페이스에만 제한됨","스크린샷 캡처 기능에 의존함"],"es":["Requiere la instalación de pnpm","Limitado a la interfaz de Reheboam AI","Dependiente de la funcionalidad de captura de pantalla"],"fr":["Nécessite l''installation de pnpm","Limité à l''interface Reheboam AI","Dépendant de la fonctionnalité de capture d''écran"],"de":["Erfordert die Installation von pnpm","Begrenzt auf die Reheboam-AI-Schnittstelle","Abhängig von der Screenshot-Funktion"],"pt":["Requer instalação do pnpm","Limitado à interface Reheboam AI","Dependente da funcionalidade de captura de tela"],"ru":["Требует установки pnpm","Ограничен интерфейсом Reheboam AI","Зависит от функциональности захвата экрана"],"ar":["يتطلب تثبيت pnpm","محدود لواجهة Reheboam AI","يعتمد على وظيفة التقاط الشاشة"]},"version":4},"contentHash":"17a14380e33621a283fecb29ffaa2031f294970aab4745cc87c82d53055b9776","qualityScore":39}');
