INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('valuecodes/Rehoboam-UI/validate-scene-ui', 'validate-scene-ui', 'valuecodes', 'Rehoboam-UI', 'community', 'validate-scene-ui valuecodes Rehoboam-UI community The validate-scene-ui skill runs screenshot-based visual validation after scene/UI changes, providing objective evidence in the final report. It benefits developers and testers working with the Reheboam AI interface. validate-scene-ui是一种视觉验证工具，使用pnpm和screenshot捕获技术，确保UI变化的准确性 validate-scene-uiは、視覚的な検証を行うツールで、pnpmとscreenshotキャプチャ技術を使用してUIの変更を正確に検証します validate-scene-ui는 시각적 검증을 수행하는 도구로, pnpm 및 스크린샷 캡처 기술을 사용하여 UI 변경 사항을 정확하게 검증합니다 Validate-scene-ui es una herramienta para realizar pruebas visuales automatizadas después de cambios en la interfaz de usuario. Utiliza capturas de pantalla para proporcionar evidencia objetiva en informes finales. Validate-scene-ui est un outil pour effectuer des tests visuels automatisés après des modifications de l''interface utilisateur. Il utilise des captures d''écran pour fournir des preuves objectives dans les rapports finals. Validate-scene-ui ist ein Werkzeug für automatisierte visuelle Tests nach Änderungen an der Benutzeroberfläche. Es verwendet Screenshot-Erfassung, um objektive Beweise in den Endberichten bereitzustellen. O Validate Scene UI é uma ferramenta que executa validação visual baseada em capturas de tela após alterações de cena/UI Validate Scene UI - это инструмент, который выполняет визуальную проверку на основе захвата экрана после изменений сцены/интерфейса Validate Scene UI هو أداة تقوم بتشغيل التحقق المرئي المستند إلى لقطات الشاشة بعد التغييرات في المشهد/واجهة المستخدم how to use validate-scene-ui validate-scene-ui setup guide visual validation in Reheboam AI screenshot-based testing with pnpm validate-scene-ui alternative tools validate-scene-ui vs other testing frameworks install validate-scene-ui validate-scene-ui tutorial Reheboam AI interface testing validate-scene-ui AIエージェント 视觉验证 pnpm screenshot UI变化 视觉检验 自动化测试 前端开发 Runs screenshot capture using `pnpm --filter rehoboam-ui screenshot:scene` command Supports options for sampling animation progression, such as `--count` and `--interval-ms` Allows custom output directory for screenshots using `--output` option Generates objective evidence in the final report using screenshot captures Integrates with the Reheboam AI interface for seamless testing validate-scene-ui is a skill that performs visual validation using screenshot captures, providing an objective way to test scene/UI changes in the Reheboam AI interface.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('NagasakaH/devcontainer/e2e', 'community', 'NagasakaH', 'devcontainer', 'NagasakaH/devcontainer', 'e2e', 0, 0, 39, '2026-03-08T01:57:15.650Z', '2026-03-08T02:13:52.941Z', 'ef4845f61a0f72981cef1b96b8856b8ce2d22e5b7f809a03c0a2bfed89cb2a2b', '{"id":"NagasakaH/devcontainer/e2e","name":"e2e","description":{"en":"The e2e skill generates, maintains, and executes end-to-end tests for various programming languages, including TypeScript, JavaScript, Python, and C#. It benefits developers by automating testing workflows.","zh":"E2E测试生成工具是一种自动化测试工具，支持多种语言，包括TypeScript、JavaScript、Python和C#","ja":"E2Eテスト生成（E2E）は、TypeScript、JavaScript、Python、C#などの言語をサポートする自動テストツールです","ko":"E2E 테스트 생성 도구는 TypeScript, JavaScript, Python, C# 등의 언어를 지원하는 자동 테스트 도구입니다","es":"e2e es una herramienta para la gestión de plantillas de devcontainer, que facilita la creación y mantenimiento de pruebas end-to-end","fr":"e2e est un outil de gestion de modèles de devcontainer, qui facilite la création et la maintenance de tests de bout en bout","de":"e2e ist ein Tool für die Verwaltung von Devcontainer-Vorlagen, das die Erstellung und Wartung von End-to-End-Tests erleichtert","pt":"O agente e2e é uma ferramenta para gerar e manter testes de ponta a ponta em projetos de desenvolvimento. Suporta TypeScript, JavaScript, Python e C#","ru":"ИИ Агент e2e - это инструмент для генерации и поддержки тестирования от начала до конца в проектах разработки. Поддерживает TypeScript, JavaScript, Python и C#","ar":"العامل الذكي e2e هو أداة لتوليد وضبط اختبارات النهاية إلى النهاية في مشاريع التطوير. يدعم لغات TypeScript و JavaScript و Python و C#"},"seo":{"title":{"en":"e2e: End-to-End Testing Setup Guide | AI Agent Skill","zh":"E2E测试生成工具：setup guide","ja":"E2Eテスト生成（E2E）setup guide","ko":"E2E 테스트 생성 도구: 설정 가이드","es":"Guía de configuración de e2e para pruebas end-to-end","fr":"Guide de configuration e2e pour les tests de bout en bout","de":"E2E-Setup-Leitfaden für End-to-End-Tests","pt":"Guia de Configuração e2e para Desenvolvedores","ru":"Настройка ИИ Агента e2e: Руководство для Разработчиков","ar":"دليل تنفيذ وضبط العامل الذكي e2e للافطارين"},"description":{"en":"Discover how to automate end-to-end testing with e2e, supporting languages like TypeScript, JavaScript, Python, and C#. Learn more and get started today!","zh":"使用E2E测试生成工具自动化测试，支持TypeScript、JavaScript、Python和C#等语言","ja":"E2Eテスト生成（E2E）を使用して自動テストを実現し、TypeScript、JavaScript、Python、C#などの言語をサポート","ko":"E2E 테스트 생성 도구를 사용하여 자동 테스트를 구현하고 TypeScript, JavaScript, Python, C# 등의 언어를 지원합니다","es":"Aprende a configurar e2e para tus proyectos de desarrollo con nuestro tutorial detallado","fr":"Découvrez comment configurer e2e pour vos projets de développement avec notre tutoriel détaillé","de":"Erfahren Sie, wie Sie e2e für Ihre Entwicklungsvorhaben mit unserem detaillierten Tutorial konfigurieren","pt":"Aprenda a configurar e utilizar o agente e2e para testes de ponta a ponta em projetos de desenvolvimento com TypeScript, JavaScript, Python e C#","ru":"Узнайте, как настроить и использовать ИИ Агент e2e для тестирования от начала до конца в проектах разработки с TypeScript, JavaScript, Python и C#","ar":"تعلم كيفية تثبيت وتكوين العامل الذكي e2e لأتمتة اختبارات النهاية إلى النهاية في مشاريع التطوير باستخدام TypeScript و JavaScript و Python و C#"},"definition":{"en":"e2e is an end-to-end testing skill that automates test generation, maintenance, and execution for multiple programming languages using frameworks like Playwright and Cypress.","zh":"E2E测试生成工具是一种用于生成和维护端到端测试的工具","ja":"E2Eテスト生成（E2E）は、エンドツーエンドテストを生成・保守するためのツールです","ko":"E2E 테스트 생성 도구는 端到端 테스트를 생성하고 유지하기 위한 도구입니다","es":"e2e es una herramienta de pruebas end-to-end que genera y mantiene pruebas automatizadas","fr":"e2e est un outil de tests de bout en bout qui génère et maintient des tests automatisés","de":"e2e ist ein Tool für End-to-End-Tests, das automatisierte Tests generiert und wartet","pt":"O que é e2e? É uma ferramenta de teste de ponta a ponta para projetos de desenvolvimento","ru":"Что такое e2e? Это инструмент для тестирования от начала до конца для проектов разработки","ar":"ما هو العامل الذكي e2e? هو أداة لاختبارات النهاية إلى النهاية لمشاريع التطوير"},"features":{"en":["Supports end-to-end testing for TypeScript and JavaScript using Playwright and Cypress","Automates testing for Python using Playwright for Python and Selenium","Enables end-to-end testing for C# using Playwright for .NET and Selenium","Automatically detects project language and uses appropriate test frameworks and commands","Provides detailed documentation for test frameworks, including reference/typescript/frameworks.md and reference/python/frameworks.md"],"zh":["支持TypeScript、JavaScript、Python和C#等语言","自动检测项目语言并使用适当的测试框架","支持Playwright、Cypress、Selenium等测试框架","提供详细的测试报告和调试信息","可集成到CI/CD流程中"],"ja":["TypeScript、JavaScript、Python、C#などの言語をサポート","プロジェクトの言語を自動検出し、適切なテストフレームワークを使用","Playwright、Cypress、Seleniumなどのテストフレームワークをサポート","詳細なテストレポートとデバッグ情報を提供","CI/CD流程に統合可能"],"ko":["TypeScript, JavaScript, Python, C# 등의 언어를 지원","프로젝트 언어를 자동으로 감지하여 적절한 테스트 프레임워크를 사용","Playwright, Cypress, Selenium 등의 테스트 프레임워크를 지원","상세한 테스트 보고서와 디버깅 정보를 제공","CI/CD 과정에 통합 가능"],"es":["Soporte para TypeScript, JavaScript, Python y C#","Integración con Playwright, Cypress, Selenium y otros frameworks de pruebas","Detección automática del lenguaje del proyecto","Uso de comandos y frameworks de pruebas adecuados para cada lenguaje","Generación y mantenimiento de pruebas end-to-end","Compatibilidad con devcontainer"],"fr":["Prise en charge de TypeScript, JavaScript, Python et C#","Intégration avec Playwright, Cypress, Selenium et d''autres frameworks de tests","Détection automatique du langage du projet","Utilisation de commandes et de frameworks de tests appropriés pour chaque langage","Génération et maintenance de tests de bout en bout","Compatibilité avec devcontainer"],"de":["Unterstützung für TypeScript, JavaScript, Python und C#","Integration mit Playwright, Cypress, Selenium und anderen Testframeworks","Automatische Spracherkennung des Projekts","Verwendung von Befehlen und Testframeworks, die für jede Sprache geeignet sind","Generierung und Wartung von End-to-End-Tests","Kompatibilität mit devcontainer"],"pt":["Suporte a TypeScript e JavaScript com Playwright e Cypress","Suporte a Python com Playwright e Selenium","Suporte a C# com Playwright e Selenium","Detecção automática da linguagem do projeto","Uso de frameworks de teste adequados para cada linguagem"],"ru":["Поддержка TypeScript и JavaScript с Playwright и Cypress","Поддержка Python с Playwright и Selenium","Поддержка C# с Playwright и Selenium","Автоматическое обнаружение языка проекта","Использование подходящих фреймворков для тестирования для каждого языка"],"ar":["دعم لغات TypeScript و JavaScript مع Playwright و Cypress","دعم لغة Python مع Playwright و Selenium","دعم لغة C# مع Playwright و Selenium","اكتشاف تلقائي للغة المشروع","استخدام إطارات اختبار مناسبة لكل لغة"]},"keywords":{"en":["e2e testing","end-to-end testing setup guide","how to use e2e","e2e vs Cypress","e2e install","e2e alternative","what is e2e","e2e for Python","e2e for JavaScript","e2e setup guide"],"zh":["E2E测试生成工具","自动化测试","TypeScript","JavaScript","Python","C#","Playwright","Cypress","Selenium","CI/CD"],"ja":["E2Eテスト生成（E2E）","自動テスト","TypeScript","JavaScript","Python","C#","Playwright","Cypress","Selenium","CI/CD"],"ko":["E2E 테스트 생성 도구","자동화 테스트","TypeScript","JavaScript","Python","C#","Playwright","Cypress","Selenium","CI/CD"],"es":["e2e testing","pruebas end-to-end","devcontainer","TypeScript","JavaScript","Python","C#","Playwright","Cypress","Selenium"],"fr":["tests de bout en bout","e2e testing","devcontainer","TypeScript","JavaScript","Python","C#","Playwright","Cypress","Selenium"],"de":["End-to-End-Tests","e2e testing","devcontainer","TypeScript","JavaScript","Python","C#","Playwright","Cypress","Selenium"],"pt":["e2e testing","testes de ponta a ponta","desenvolvimento de software","TypeScript","JavaScript","Python","C#","Playwright","Cypress","Selenium"],"ru":["тестирование e2e","тестирование от начала до конца","разработка программного обеспечения","TypeScript","JavaScript","Python","C#","Playwright","Cypress","Selenium"],"ar":["اختبارات النهاية إلى النهاية","تطوير البرمجيات","TypeScript","JavaScript","Python","C#","Playwright","Cypress","Selenium","ادوات الذكاء الاصطناعي"]}},"owner":"NagasakaH","repo":"devcontainer","repoPath":"NagasakaH/devcontainer","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.650Z","topics":[],"category":"community","skillMd":{"name":"e2e","description":"E2Eテストの生成・実行ガイド。テストジャーニーの作成、テスト実行、スクリーンショット/動画/トレースの取得、アーティファクトのアップロードをサポート。「E2Eテスト」「エンドツーエンドテスト」「Playwrightテスト」「ユーザージャーニーのテスト」などのフレーズで発動。","bodyPreview":"# E2Eテスト生成（E2E）\n\nエンドツーエンドテストを生成・保守・実行するためのガイド。\n\n## 対応言語\n\nこのスキルは以下の言語に対応しています。プロジェクトの言語を自動検出し、適切なテストフレームワークとコマンドを使用します。\n\n| 言語 | E2Eフレームワーク | 詳細 |\n|------|------------------|------|\n| TypeScript/JavaScript | Playwright, Cypress | [reference/typescript/frameworks.md](reference/typescript/frameworks.md) |\n| Python | Playwright for Python, Selenium | [reference/python/frameworks.md](reference/python/frameworks.md) |\n| C# | Playwright for .NET, Selenium | [reference/csharp/frameworks.md](reference/csh","body":"# E2Eテスト生成（E2E）\n\nエンドツーエンドテストを生成・保守・実行するためのガイド。\n\n## 対応言語\n\nこのスキルは以下の言語に対応しています。プロジェクトの言語を自動検出し、適切なテストフレームワークとコマンドを使用します。\n\n| 言語 | E2Eフレームワーク | 詳細 |\n|------|------------------|------|\n| TypeScript/JavaScript | Playwright, Cypress | [reference/typescript/frameworks.md](reference/typescript/frameworks.md) |\n| Python | Playwright for Python, Selenium | [reference/python/frameworks.md](reference/python/frameworks.md) |\n| C# | Playwright for .NET, Selenium | [reference/csharp/frameworks.md](reference/csharp/frameworks.md) |\n\n### 言語自動検出\n\nプロジェクトの言語は以下のファイルの存在で判別します：\n\n| ファイル | 判定される言語 |\n|----------|----------------|\n| `package.json` | TypeScript/JavaScript |\n| `pyproject.toml`, `setup.py`, `requirements.txt` | Python |\n| `*.csproj`, `*.sln` | C# |\n\n`{{language}}` 変数が指定された場合は、その言語の設定を優先します。\n\n## このスキルの目的\n\n1. **テストジャーニーの生成** - ユーザーフローのPlaywrightテストを作成\n2. **E2Eテストの実行** - 複数ブラウザでテストを実行\n3. **アーティファクトの取得** - 失敗時のスクリーンショット、動画、トレースを保存\n4. **結果のアップロード** - HTMLレポートとJUnit XMLを生成\n5. **不安定なテストの検出** - 不安定なテストを特定・隔離\n\n## 使用するタイミング\n\n以下の場合に使用：\n- 重要なユーザージャーニーのテスト（ログイン、決済、購入フロー等）\n- 複数ステップのフローがエンドツーエンドで動作することの検証\n- UIインタラクションとナビゲーションのテスト\n- フロントエンドとバックエンドの統合検証\n- 本番デプロイ前の品質確認\n\n## ワークフロー\n\n### ステップ1: ユーザーフローの分析\n\nリクエストを分析し、テストシナリオを特定する。\n\n- ユーザージャーニーの流れ\n- テストで検証すべき項目\n- 必要なテストケース数\n\n### ステップ2: E2Eテストの生成\n\nPage Object Modelパターンを使用してテストコードを生成する。\n\nテストには以下を含める：\n- ナビゲーション\n- ユーザーアクション\n- アサーション（検証）\n- スクリーンショット取得\n\n### ステップ3: テストの実行\n\n複数ブラウザでテストを実行する。\n\n対象ブラウザ：\n- Chromium（デスクトップChrome）\n- Firefox（デスクトップ）\n- WebKit（デスクトップSafari）\n- Mobile Chrome（オプション）\n\n### ステップ4: 結果の報告\n\nテスト結果とアーティファクトを報告する。\n\n- 成功/失敗の状態\n- 実行時間\n- 生成されたアーティファクト\n- 推奨事項（必要に応じて）\n\n## 言語別テストコード例\n\n以下に各言語でのE2Eテスト例を示します。詳細な情報は各言語のリファレンスを参照してください。\n\n### TypeScript/JavaScript (Playwright)\n\n```typescript\n// tests/e2e/market-search.spec.ts\nimport { test, expect } from ''@playwright/test''\nimport { MarketsPage } from ''../pages/MarketsPage''\n\ntest.describe(''市場検索'', () => {\n  test(''ユーザーは市場を検索してフィルタリングできる'', async ({ page }) => {\n    // 1. ページへ移動\n    const marketsPage = new MarketsPage(page)\n    await marketsPage.goto()\n\n    // 2. 検索を実行\n    await marketsPage.search(''election'')\n\n    // 3. 結果を検証\n    await expect(marketsPage.marketCards).toHaveCount(5)\n  })\n})\n```\n\n**テスト実行:**\n\n```bash\nnpx playwright test\nnpx playwright test --headed  # ブラウザ表示\nnpx playwright show-report    # レポート表示\n```\n\n### Python (Playwright for Python)\n\n```python\n# tests/e2e/test_market_search.py\nfrom playwright.sync_api import Page, expect\nfrom pages.markets_page import MarketsPage\n\nclass TestMarketSearch:\n    def test_user_can_search_and_filter_markets(self, page: Page):\n        # 1. ページへ移動\n        markets_page = MarketsPage(page)\n        markets_page.goto()\n\n        # 2. 検索を実行\n        markets_page.search(''election'')\n\n        # 3. 結果を検証\n        expect(markets_page.market_cards).to_have_count(5)\n```\n\n**テスト実行:**\n\n```bash\npytest tests/e2e/\npytest tests/e2e/ --headed  # ブラウザ表示\n```\n\n### C# (Playwright for .NET)\n\n```csharp\n// Tests/E2E/MarketSearchTests.cs\nusing Microsoft.Playwright;\nusing Xunit;\n\npublic class MarketSearchTests : PlaywrightTest\n{\n    [Fact]\n    public async Task UserCanSearchAndFilterMarkets()\n    {\n        // 1. ページへ移動\n        var marketsPage = new MarketsPage(Page);\n        await marketsPage.GotoAsync();\n\n        // 2. 検索を実行\n        await marketsPage.SearchAsync(\"election\");\n\n        // 3. 結果を検証\n        await Expect(marketsPage.MarketCards).ToHaveCountAsync(5);\n    }\n}\n```\n\n**テスト実行:**\n\n```bash\ndotnet test\ndotnet test --filter \"Category=E2E\"\n```\n\n## テストコードテンプレート（TypeScript）\n\n```typescript\n// tests/e2e/{機能名}/{テスト名}.spec.ts\nimport { test, expect } from ''@playwright/test''\nimport { {ページ名}Page } from ''../../pages/{ページ名}Page''\n\ntest.describe(''{テストスイート名}'', () => {\n  test(''{テストケース名}'', async ({ page }) => {\n    // 1. ページへ移動\n    const targetPage = new {ページ名}Page(page)\n    await targetPage.goto()\n\n    // 2. ページ読み込みを検証\n    await expect(page).toHaveTitle(/{期待するタイトル}/)\n    await expect(page.locator(''h1'')).toContainText(''{期待するテキスト}'')\n\n    // 3. ユーザーアクションを実行\n    await targetPage.{アクションメソッド}(''{入力値}'')\n\n    // 4. APIレスポンスを待機\n    await page.waitForResponse(resp =>\n      resp.url().includes(''{APIエンドポイント}'') && resp.status() === 200\n    )\n\n    // 5. 結果を検証\n    await expect(page.locator(''{セレクタ}'')).toBeVisible()\n\n    // 6. スクリーンショットを取得\n    await page.screenshot({ path: ''artifacts/{スクリーンショット名}.png'' })\n  })\n})\n```\n\n## Page Objectテンプレート\n\n```typescript\n// tests/pages/{ページ名}Page.ts\nimport { Page, Locator } from ''@playwright/test''\n\nexport class {ページ名}Page {\n  readonly page: Page\n  readonly {要素名}: Locator\n\n  constructor(page: Page) {\n    this.page = page\n    this.{要素名} = page.locator(''[data-testid=\"{テストID}\"]'')\n  }\n\n  async goto() {\n    await this.page.goto(''{URL}'')\n  }\n\n  async {アクションメソッド}(input: string) {\n    await this.{要素名}.fill(input)\n    await this.{要素名}.press(''Enter'')\n  }\n}\n```\n\n## テストアーティファクト\n\nテスト実行時に以下のアーティファクトを取得：\n\n**全テストで取得：**\n- HTMLレポート（タイムラインと結果）\n- JUnit XML（CI統合用）\n\n**失敗時のみ取得：**\n- 失敗状態のスクリーンショット\n- テストの動画記録\n- デバッグ用トレースファイル（ステップバイステップ再生）\n- ネットワークログ\n- コンソールログ\n\n## クイックコマンド\n\n### TypeScript/JavaScript (Playwright)\n\n```bash\n# 全E2Eテストを実行\nnpx playwright test\n\n# 特定のテストファイルを実行\nnpx playwright test tests/e2e/market-search.spec.ts\n\n# ヘッドモードで実行（ブラウザを表示）\nnpx playwright test --headed\n\n# デバッグモードで実行\nnpx playwright test --debug\n\n# テストコードを生成\nnpx playwright codegen http://localhost:3000\n\n# レポートを表示\nnpx playwright show-report\n\n# トレースファイルを表示\nnpx playwright show-trace artifacts/trace.zip\n```\n\n### Python (Playwright for Python)\n\n```bash\n# 全E2Eテストを実行\npytest tests/e2e/\n\n# ヘッドモードで実行\npytest tests/e2e/ --headed\n\n# 特定のブラウザで実行\npytest tests/e2e/ --browser chromium\n\n# トレース記録\npytest tests/e2e/ --tracing on\n```\n\n### C# (Playwright for .NET)\n\n```bash\n# 全E2Eテストを実行\ndotnet test --filter \"Category=E2E\"\n\n# 詳細出力\ndotnet test -v detailed\n\n# Playwrightブラウザインストール\npwsh bin/Debug/net8.0/playwright.ps1 install\n```\n\n## 不安定なテストの検出\n\nテストが断続的に失敗する場合：\n\n1. **原因の特定**\n   - タイムアウト問題\n   - レース条件\n   - アニメーションによる要素の非表示\n\n2. **推奨される修正**\n   - 明示的な待機を追加: `await page.waitForSelector(''{セレクタ}'')`\n   - タイムアウトを増加: `{ timeout: 10000 }`\n   - コンポーネント内のレース条件を確認\n   - アニメーションによる要素非表示を検証\n\n3. **隔離の推奨**\n   - 修正まで `test.fixme()` でマーク\n\n## ベストプラクティス\n\n**推奨事項：**\n- Page Object Modelを使用して保守性を向上\n- セレクタには `data-testid` 属性を使用\n- 任意の待ち時間ではなくAPIレスポンスを待機\n- 重要なユーザージャーニーをエンドツーエンドでテスト\n- mainへのマージ前にテストを実行\n- 失敗時はアーティファクトを確認\n\n**避けるべきこと：**\n- 脆いセレクタの使用（CSSクラスは変更される可能性がある）\n- 実装の詳細をテスト\n- 本番環境でテストを実行\n- 不安定なテストを無視\n- 失敗時のアーティファクト確認をスキップ\n- 全てのエッジケースをE2Eでテスト（ユニットテストを使用）\n\n## CI/CD統合\n\n```yaml\n# .github/workflows/e2e.yml\n- name: Install Playwright\n  run: npx playwright install --with-deps\n\n- name: Run E2E tests\n  run: npx playwright test\n\n- name: Upload artifacts\n  if: always()\n  uses: actions/upload-artifact@v3\n  with:\n    name: playwright-report\n    path: playwright-report/\n```\n\n## 重要な注意事項\n\n**本番環境での注意点：**\n- 金銭が関わるE2Eテストはテストネット/ステージング環境のみで実行\n- 本番環境で決済・取引テストを実行しない\n- 金融関連テストには `test.skip(process.env.NODE_ENV === ''production'')` を設定\n- テスト用のウォレット/アカウントのみを使用\n\n## 他のスキルとの連携\n\n- **plan**: テストすべき重要なジャーニーを特定\n- **tdd**: ユニットテスト用（より高速で詳細）\n- **e2e**: 統合テストとユーザージャーニーテスト用\n- **code-review**: テスト品質の検証\n"},"lastSynced":"2026-03-08T02:13:52.941Z","agentAnalysis":{"suitability":{"en":"Perfect for Automated Testing Agents needing end-to-end test generation and execution for TypeScript, JavaScript, Python, and C# projects.","zh":"非常适合需要从头到尾的测试生成和执行的自动化测试代理，支持TypeScript、JavaScript、Python和C#项目。","ja":"TypeScript、JavaScript、Python、C#プロジェクトのエンドツーエンドのテスト生成と実行が必要な自動テストエージェントに最適です。","ko":"TypeScript, JavaScript, Python 및 C# 프로젝트를 위한 자동화된 테스트 에이전트에 적합합니다. 엔드 투 엔드 테스트 생성 및 실행이 필요합니다.","es":"Perfecto para Agentes de Pruebas Automatizadas que necesitan generación y ejecución de pruebas de extremo a extremo para proyectos de TypeScript, JavaScript, Python y C#.","fr":"Parfait pour les Agents de Test Automatisés ayant besoin de génération et d''exécution de tests de bout en bout pour les projets TypeScript, JavaScript, Python et C#.","de":"Perfekt für automatisierte Testagenten, die eine Generierung und Ausführung von End-to-End-Tests für TypeScript-, JavaScript-, Python- und C#-Projekte benötigen.","pt":"Perfeito para Agentes de Testes Automatizados que precisam de geração e execução de testes de ponta a ponta para projetos TypeScript, JavaScript, Python e C#.","ru":"Идеально подходит для Автоматизированных Тестировочных Агентов, которым требуется генерация и выполнение тестов от начала до конца для проектов TypeScript, JavaScript, Python и C#.","ar":"مثالي لعميل اختبار آلي يحتاج إلى генера وتنفيذ اختبار من النهاية إلى النهاية لمشاريع TypeScript و JavaScript و Python و C#."},"recommendation":{"en":"Empowers agents to automate testing workflows using Playwright, Cypress, and Selenium frameworks, supporting languages like TypeScript, JavaScript, Python, and C#, and streamlining development with automated end-to-end testing.","zh":"赋予代理使用Playwright、Cypress和Selenium框架自动化测试工作流的能力，支持TypeScript、JavaScript、Python和C#等语言，并通过自动化的端到端测试简化开发。","ja":"Playwright、Cypress、Seleniumフレームワークを使用して、TypeScript、JavaScript、Python、C#などの言語をサポートし、自動化されたエンドツーエンドテストで開発をストリームライン化するテストワークフローの自動化をエージェントに可能にします。","ko":"Playwright, Cypress 및 Selenium 프레임워크를 사용하여 TypeScript, JavaScript, Python 및 C#와 같은 언어를 지원하고 자동화된 엔드 투 엔드 테스트를 통해 개발을 간소화하여 테스트 워크플로를 자동화할 수 있는 에이전트를赋予합니다.","es":"Habilita a los agentes a automatizar flujos de trabajo de pruebas utilizando los frameworks Playwright, Cypress y Selenium, que admiten lenguajes como TypeScript, JavaScript, Python y C#, y optimizan el desarrollo con pruebas de extremo a extremo automatizadas.","fr":"Permet aux agents d''automatiser les flux de travail de test en utilisant les frameworks Playwright, Cypress et Selenium, qui prennent en charge des langages tels que TypeScript, JavaScript, Python et C#, et rationalisent le développement avec des tests de bout en bout automatisés.","de":"Ermöglicht es den Agenten, Testworkflows mit den Frameworks Playwright, Cypress und Selenium zu automatisieren, die Sprachen wie TypeScript, JavaScript, Python und C# unterstützen und die Entwicklung mit automatisierten End-to-End-Tests optimieren.","pt":"Habilita os agentes a automatizar fluxos de trabalho de teste usando os frameworks Playwright, Cypress e Selenium, dando suporte a linguagens como TypeScript, JavaScript, Python e C#, e agilizando o desenvolvimento com testes de ponta a ponta automatizados.","ru":"Наделяет агентов возможностью автоматизировать рабочие процессы тестирования с помощью фреймворков Playwright, Cypress и Selenium, поддерживая языки seperti TypeScript, JavaScript, Python и C#, и оптимизируя разработку за счет автоматизированного тестирования от начала до конца.","ar":"يمكن العميل من توفير العمليات اليدوية لاختبار البرمجيات باستخدام أطر العمل Playwright و Cypress و Selenium، ودعم اللغات مثل TypeScript و JavaScript و Python و C#، وتحسين التطوير من خلال الاختبارات الآلية من النهاية إلى النهاية."},"useCases":{"en":["Generating end-to-end tests for web applications using Playwright","Automating test execution for Python projects with Selenium","Debugging C# applications using end-to-end testing with Playwright for .NET"],"zh":["使用Playwright为Web应用程序生成端到端测试","使用Selenium为Python项目自动执行测试","使用Playwright for .NET进行C#应用程序的端到端测试调试"],"ja":["Playwrightを使用してWebアプリケーション用のエンドツーエンドテストを生成する","Seleniumを使用してPythonプロジェクトのテストを自動実行する","Playwright for .NETを使用してC#アプリケーションのエンドツーエンドテストをデバッグする"],"ko":["Playwright를 사용하여 웹 애플리케이션을 위한 엔드 투 엔드 테스트를 생성","Selenium을 사용하여 Python 프로젝트의 테스트를 자동으로 실행","Playwright for .NET을 사용하여 C# 애플리케이션의 엔드 투 엔드 테스트를 디버깅"],"es":["Generación de pruebas de extremo a extremo para aplicaciones web con Playwright","Automatización de la ejecución de pruebas para proyectos de Python con Selenium","Depuración de aplicaciones de C# con pruebas de extremo a extremo con Playwright para .NET"],"fr":["Génération de tests de bout en bout pour les applications Web avec Playwright","Automatisation de l''exécution de tests pour les projets Python avec Selenium","Débogage d''applications C# avec des tests de bout en bout avec Playwright pour .NET"],"de":["Generierung von End-to-End-Tests für Webanwendungen mit Playwright","Automatisierung der Testausführung für Python-Projekte mit Selenium","Fehlerbehebung von C#-Anwendungen mit End-to-End-Tests mit Playwright für .NET"],"pt":["Gerar testes de ponta a ponta para aplicações web usando Playwright","Automatizar a execução de testes para projetos Python com Selenium","Depurar aplicações C# usando testes de ponta a ponta com Playwright para .NET"],"ru":["Генерировать тесты от начала до конца для веб-приложений с помощью Playwright","Автоматизировать выполнение тестов для проектов Python с помощью Selenium","Отлаживать приложения C# с помощью тестов от начала до конца с Playwright для .NET"],"ar":["توليد اختبارات من النهاية إلى النهاية لتطبيقات الويب باستخدام Playwright","تأهيل تنفيذ الاختبارات للبرامج التي تستخدم لغة بايثون مع Selenium","تصحيح الأخطاء في تطبيقات C# باستخدام اختبارات من النهاية إلى النهاية مع Playwright من أجل .NET"]},"limitations":{"en":["Requires project language detection","Limited to supported languages and frameworks"],"zh":["需要项目语言检测","仅限支持的语言和框架"],"ja":["プロジェクト言語の検出が必要","サポートされている言語とフレームワークのみ"],"ko":["프로젝트 언어 감지가 필요","지원 언어 및 프레임워크만 해당"],"es":["Requiere detección del lenguaje del proyecto","Limitado a los lenguajes y frameworks admitidos"],"fr":["Nécessite la détection du langage du projet","Limité aux langages et frameworks pris en charge"],"de":["Erfordert die Projektsprachenerkennung","Begrenzt auf unterstützte Sprachen und Frameworks"],"pt":["Requer detecção de linguagem do projeto","Limitado às linguagens e frameworks suportados"],"ru":["Требует обнаружения языка проекта","Ограничен поддерживаемыми языками и фреймворками"],"ar":["يتطلب اكتشاف لغة المشروع","محدود باللغات والأطر الداعمة"]},"version":4},"contentHash":"ef4845f61a0f72981cef1b96b8856b8ce2d22e5b7f809a03c0a2bfed89cb2a2b","qualityScore":39}');
